import React, { Suspense, useEffect } from 'react'
import { HashRouter, Route, Routes } from 'react-router'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { PageSkeleton } from '@/components/PageSkeleton'
import { ToastProvider, useToast } from '@/hooks/useToast'
import { Toaster } from '@/components/ui/Toast'
import { ROUTE_REGISTRY } from '@/config/routes'
import { RouteGuard } from '@/core/routeGuard'
import { initializeApp } from '@/services/system/bootstrapService'
import { getLogger } from '@/lib/logger'
import { ThemeProvider } from '@/core/ThemeProvider'
// 显式 import 智能体系统入口，触发 initAgentSystem() 自动初始化
// （src/agents/index.ts 在模块加载时通过 setTimeout 延迟 100ms 调用 initAgentSystem）
import '@/agents'

if (import.meta.env.DEV) {
  import('@/devtools/testDataFlow')
}

const logger = getLogger()

function AppContent(): React.JSX.Element {
  const { toast } = useToast()

  useEffect(() => {
    initializeApp().catch((err) => {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('IndexedDB init failed', { error: err })
      toast({
        title: '本地数据库初始化失败',
        description: `${message}，请检查浏览器存储权限或刷新页面重试。`,
        variant: 'error',
        duration: 0,
      })
    })
  }, [toast])

  return (
    <Suspense fallback={<PageSkeleton />}>
      <Routes>
        {ROUTE_REGISTRY.map((route) => (
          <Route
            key={route.path}
            path={route.path}
            element={
              <RouteGuard module={route.category}>
                <route.component />
              </RouteGuard>
            }
          />
        ))}
        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </Suspense>
  )
}

function NotFoundPage(): React.JSX.Element {
  return (
    <div className="flex min-h-screen items-center justify-center">
      <div className="text-center">
        <h1 className="text-4xl font-bold">404</h1>
        <p className="text-muted-foreground">页面未找到</p>
      </div>
    </div>
  )
}

export default function App(): React.JSX.Element {
  return (
    <ThemeProvider defaultMode="system">
      <HashRouter>
        <ErrorBoundary>
          <ToastProvider>
            <AppContent />
            <Toaster />
          </ToastProvider>
        </ErrorBoundary>
      </HashRouter>
    </ThemeProvider>
  )
}

/**
 * @module AgentRegistry
 * @lifecycle @Global
 * @description Agent 注册表模块，集中管理 Agent 定义、实例化与生命周期
 */

import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import type { AgentConfig } from './agentRuntime'

const logger = getLogger()

export interface AgentRegistryEntry {
  config: AgentConfig
  registeredAt: number
  instanceCount: number
  tags: string[]
}

export class AgentRegistry {
  private agents = new Map<string, AgentRegistryEntry>()
  private tags = new Map<string, Set<string>>()

  register(config: AgentConfig, tags: string[] = []): void {
    logger.debug(`[AgentRegistry] register() agentId="${config.id}"`)

    if (this.agents.has(config.id)) {
      logger.warn(`[AgentRegistry] Agent "${config.id}" already registered, updating config`)
    }

    this.agents.set(config.id, {
      config,
      registeredAt: Date.now(),
      instanceCount: 0,
      tags,
    })

    for (const tag of tags) {
      if (!this.tags.has(tag)) {
        this.tags.set(tag, new Set())
      }
      this.tags.get(tag)!.add(config.id)
    }

    eventBus.emit('AGENT_REGISTERED', { agentId: config.id, tags })
    logger.info(`[AgentRegistry] Agent "${config.id}" registered with tags: [${tags.join(', ')}]`)
  }

  unregister(agentId: string): boolean {
    logger.debug(`[AgentRegistry] unregister() agentId="${agentId}"`)

    const entry = this.agents.get(agentId)
    if (!entry) {
      logger.warn(`[AgentRegistry] Unregister failed: Agent "${agentId}" not found`)
      return false
    }

    for (const tag of entry.tags) {
      this.tags.get(tag)?.delete(agentId)
      if (this.tags.get(tag)?.size === 0) {
        this.tags.delete(tag)
      }
    }

    this.agents.delete(agentId)
    eventBus.emit('AGENT_UNREGISTERED', { agentId })
    logger.info(`[AgentRegistry] Agent "${agentId}" unregistered`)
    return true
  }

  get(agentId: string): AgentRegistryEntry | undefined {
    return this.agents.get(agentId)
  }

  getAll(): AgentRegistryEntry[] {
    return Array.from(this.agents.values())
  }

  getByTag(tag: string): AgentRegistryEntry[] {
    const ids = this.tags.get(tag)
    if (!ids) return []
    return Array.from(ids).map((id) => this.agents.get(id)!).filter(Boolean)
  }

  has(agentId: string): boolean {
    return this.agents.has(agentId)
  }

  getStats() {
    return {
      total: this.agents.size,
      tags: this.tags.size,
      agentIds: Array.from(this.agents.keys()),
    }
  }

  incrementInstance(agentId: string): void {
    const entry = this.agents.get(agentId)
    if (entry) {
      entry.instanceCount++
    }
  }

  decrementInstance(agentId: string): void {
    const entry = this.agents.get(agentId)
    if (entry && entry.instanceCount > 0) {
      entry.instanceCount--
    }
  }
}

// Singleton
let registryInstance: AgentRegistry | null = null

export function createAgentRegistry(): AgentRegistry {
  if (registryInstance) return registryInstance
  registryInstance = new AgentRegistry()
  return registryInstance
}

export function getAgentRegistry(): AgentRegistry {
  if (!registryInstance) {
    registryInstance = new AgentRegistry()
  }
  return registryInstance
}

export function destroyAgentRegistry(): void {
  registryInstance = null
  logger.info('[AgentRegistry] Instance destroyed')
}

import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'

const logger = getLogger()

export interface AgentConfig {
  id: string
  name: string
  description: string
  defaultTimeout: number
  maxConcurrent: number
  mcpServerName?: string
  defaultToolName?: string
}

export interface AgentTask {
  id: string
  agentId: string
  type: string
  payload: unknown
  timeout: number
  status: 'pending' | 'running' | 'completed' | 'failed' | 'timeout'
  result?: unknown
  error?: string
  createdAt: number
  startedAt?: number
  completedAt?: number
}

export class AgentRuntime {
  private agents = new Map<string, AgentConfig>()
  private tasks = new Map<string, AgentTask>()
  private runningTasks = new Map<string, { controller: AbortController; timeout: ReturnType<typeof setTimeout> }>()

  constructor() {
    logger.info('[AgentRuntime] Initializing...')
  }

  register(config: AgentConfig): void {
    logger.debug(`[AgentRuntime] register() called for agent "${config.id}"`)

    if (this.agents.has(config.id)) {
      logger.warn(`[AgentRuntime] Agent "${config.id}" already registered, overwriting`)
    }

    this.agents.set(config.id, config)
    eventBus.emit('AGENT_REGISTERED', { agentId: config.id })
    logger.info(`[AgentRuntime] Agent "${config.id}" registered (timeout=${config.defaultTimeout}ms, maxConcurrent=${config.maxConcurrent})`)
  }

  async execute(agentId: string, type: string, payload: unknown, timeout?: number): Promise<AgentTask> {
    logger.debug(`[AgentRuntime] execute() called: agentId="${agentId}", type="${type}"`)

    const agent = this.agents.get(agentId)
    if (!agent) {
      logger.error(`[AgentRuntime] Execute failed: Agent not found "${agentId}"`)
      throw new Error(`Agent not found: ${agentId}`)
    }

    const taskId = `${agentId}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
    const effectiveTimeout = timeout ?? agent.defaultTimeout
    const task: AgentTask = {
      id: taskId,
      agentId,
      type,
      payload,
      timeout: effectiveTimeout,
      status: 'pending',
      createdAt: Date.now(),
    }
    this.tasks.set(taskId, task)

    logger.info(`[AgentRuntime] Task created: taskId="${taskId}", agentId="${agentId}", type="${type}", timeout=${effectiveTimeout}ms`)
    eventBus.emit('AGENT_TASK_STARTED', { taskId, agentId, type })

    return new Promise((resolve) => {
      const controller = new AbortController()
      const timeoutId = setTimeout(() => {
        task.status = 'timeout'
        task.error = `Task timeout after ${task.timeout}ms`
        task.completedAt = Date.now()
        this.runningTasks.delete(taskId)
        controller.abort()

        logger.warn(`[AgentRuntime] Task timeout: taskId="${taskId}", agentId="${agentId}", elapsed=${task.timeout}ms`)
        eventBus.emit('AGENT_TASK_TIMEOUT', { taskId, agentId, type })
        resolve(task)
      }, effectiveTimeout)

      task.status = 'running'
      task.startedAt = Date.now()
      this.runningTasks.set(taskId, { controller, timeout: timeoutId })
      logger.debug(`[AgentRuntime] Task started: taskId="${taskId}", timeout=${effectiveTimeout}ms`)

      this.runAgent(agentId, task, controller.signal)
        .then((result) => {
          task.status = 'completed'
          task.result = result
          task.completedAt = Date.now()
          const duration = task.completedAt - (task.startedAt ?? task.createdAt)

          logger.info(`[AgentRuntime] Task completed: taskId="${taskId}", duration=${duration}ms`)
          eventBus.emit('AGENT_TASK_COMPLETED', { taskId, agentId, type, result })
        })
        .catch((error) => {
          task.status = 'failed'
          task.error = error instanceof Error ? error.message : String(error)
          task.completedAt = Date.now()
          const duration = task.completedAt - (task.startedAt ?? task.createdAt)

          logger.error(`[AgentRuntime] Task failed: taskId="${taskId}", duration=${duration}ms, error="${task.error}"`)
          eventBus.emit('AGENT_TASK_FAILED', { taskId, agentId, type, error: task.error })
        })
        .finally(() => {
          clearTimeout(timeoutId)
          this.runningTasks.delete(taskId)
          logger.debug(`[AgentRuntime] Task cleanup: taskId="${taskId}", runningTasks=${this.runningTasks.size}`)
          resolve(task)
        })
    })
  }

  private async runAgent(agentId: string, task: AgentTask, signal: AbortSignal): Promise<unknown> {
    logger.info(`[AgentRuntime] runAgent() executing via MCP: agentId="${agentId}", taskId="${task.id}"`)

    const agent = this.agents.get(agentId)
    if (!agent) throw new Error(`Agent not found: ${agentId}`)

    const { mcpBridge } = await import('@/mcp/bridge')
    const serverName = agent.mcpServerName ?? agentId
    const toolName = agent.defaultToolName ?? task.type
    const result = await mcpBridge.callTool(serverName, toolName, task.payload as Record<string, unknown>)

    if (signal.aborted) {
      logger.debug(`[AgentRuntime] runAgent() aborted: taskId="${task.id}"`)
      throw new Error('Task aborted')
    }

    if (result.isError) {
      const errorText = result.content[0]?.text ?? 'Unknown MCP error'
      logger.error('[AgentRuntime] MCP call failed', { serverName, toolName, error: errorText })
      throw new Error(`MCP call failed: ${errorText}`)
    }

    logger.info(`[AgentRuntime] MCP call completed: ${serverName}.${toolName}`)
    return { success: true, serverName, toolName, result }
  }

  async executeParallel(tasks: Array<{ agentId: string; type: string; payload: unknown; timeout?: number }>): Promise<AgentTask[]> {
    logger.info(`[AgentRuntime] executeParallel() called: ${tasks.length} tasks`)

    const promises = tasks.map((t, index) => {
      logger.debug(`[AgentRuntime] Parallel task #${index}: agentId="${t.agentId}", type="${t.type}"`)
      return this.execute(t.agentId, t.type, t.payload, t.timeout)
    })

    const results = await Promise.all(promises)
    const successCount = results.filter((r) => r.status === 'completed').length
    logger.info(`[AgentRuntime] executeParallel() completed: ${successCount}/${tasks.length} succeeded`)

    return results
  }

  getTask(id: string): AgentTask | undefined {
    const task = this.tasks.get(id)
    if (!task) {
      logger.debug(`[AgentRuntime] getTask() not found: id="${id}"`)
    } else {
      logger.debug(`[AgentRuntime] getTask() found: id="${id}", status="${task.status}"`)
    }
    return task
  }

  listTasks(status?: AgentTask['status']): AgentTask[] {
    const allTasks = Array.from(this.tasks.values())
    const filtered = status ? allTasks.filter((t) => t.status === status) : allTasks
    logger.debug(`[AgentRuntime] listTasks(): status="${status ?? 'all'}", count=${filtered.length}`)
    return filtered
  }

  cancelTask(id: string): boolean {
    logger.debug(`[AgentRuntime] cancelTask() called: id="${id}"`)

    const running = this.runningTasks.get(id)
    if (running) {
      logger.debug(`[AgentRuntime] Cancelling running task: id="${id}"`)
      running.controller.abort()
      clearTimeout(running.timeout)
      this.runningTasks.delete(id)
    }

    const task = this.tasks.get(id)
    if (task) {
      task.status = 'failed'
      task.error = 'Task cancelled'
      task.completedAt = Date.now()

      logger.info(`[AgentRuntime] Task cancelled: id="${id}"`)
      eventBus.emit('AGENT_TASK_CANCELLED', { taskId: id })
      return true
    }

    logger.warn(`[AgentRuntime] cancelTask() failed: task not found "${id}"`)
    return false
  }

  getStats() {
    const stats = {
      totalAgents: this.agents.size,
      pendingTasks: this.listTasks('pending').length,
      runningTasks: this.listTasks('running').length,
      completedTasks: this.listTasks('completed').length,
      failedTasks: this.listTasks('failed').length + this.listTasks('timeout').length,
    }
    logger.debug(`[AgentRuntime] getStats(): ${JSON.stringify(stats)}`)
    return stats
  }
}

export const agentRuntime = new AgentRuntime()

/**
 * @module Agents
 * @lifecycle @Global
 * @description Agent 系统统一入口，整合 Registry/Runtime/HealthMonitor/ConfigManager
 */

import { getLogger } from '@/lib/logger'
import { agentRuntime, type AgentConfig } from './agentRuntime'
import { getAgentRegistry, AgentRegistry } from './agentRegistry'
import { getAgentHealthMonitor, AgentHealthMonitor } from './agentHealthMonitor'
import { getAgentConfigManager } from './agentConfigManager'
import { initAgentSubscriptions } from '@/store/agentStore'

const logger = getLogger()

// 导出所有 Agent 模块
export { agentRuntime, type AgentConfig } from './agentRuntime'
export { getAgentRegistry, createAgentRegistry, type AgentRegistryEntry } from './agentRegistry'
export { getAgentHealthMonitor, createAgentHealthMonitor, type AgentHealthReport, type HealthThresholds } from './agentHealthMonitor'
export { getAgentConfigManager, createAgentConfigManager, type AgentConfigOverride, type AgentConfigSnapshot } from './agentConfigManager'

// ============================================================================
// 预定义 Agent 配置
// ============================================================================

/** V6 自动评分 Agent */
export const AGENT_V6_SCORING: AgentConfig = {
  id: 'v6-scoring-agent',
  name: 'V6 自动评分 Agent',
  description: '执行 V6 九维评分计算，返回评分结果与因子明细',
  defaultTimeout: 30000,
  maxConcurrent: 5,
  mcpServerName: 'scoring:v6',
  defaultToolName: 'score_stock',
}

/** V4 行业评分 Agent */
export const AGENT_V4_INDUSTRIAL: AgentConfig = {
  id: 'v4-industrial-agent',
  name: 'V4 行业评分 Agent',
  description: '执行 V4 行业评分计算，返回行业强弱与板块轮动信号',
  defaultTimeout: 45000,
  maxConcurrent: 3,
  mcpServerName: 'scoring:v6',
  defaultToolName: 'analyze_hot_sector',
}

/** LLM 智能评分 Agent */
export const AGENT_LLM_INTelligent: AgentConfig = {
  id: 'llm-intelligent-agent',
  name: 'LLM 智能评分 Agent',
  description: '调用 LLM API 进行个股深度分析，返回智能评分与投资建议',
  defaultTimeout: 60000,
  maxConcurrent: 2,
  mcpServerName: 'llm',
  defaultToolName: 'chat_completion',
}

/** 数据采集 Agent */
export const AGENT_FETCHER: AgentConfig = {
  id: 'fetcher-agent',
  name: '数据采集 Agent',
  description: '执行股票基础数据/行情数据/财务数据的采集任务',
  defaultTimeout: 15000,
  maxConcurrent: 10,
  mcpServerName: 'fetcher',
  defaultToolName: 'fetch_stock_basic',
}

/** 新闻分析 Agent */
export const AGENT_NEWS_ANALYZER: AgentConfig = {
  id: 'news-analyzer-agent',
  name: '新闻分析 Agent',
  description: '执行新闻情感分析、股票关联提取、热点识别任务',
  defaultTimeout: 20000,
  maxConcurrent: 5,
  mcpServerName: 'news',
  defaultToolName: 'fetch_news',
}

/** 默认 Agent 配置列表 */
export const DEFAULT_AGENTS: AgentConfig[] = [
  AGENT_V6_SCORING,
  AGENT_V4_INDUSTRIAL,
  AGENT_LLM_INTelligent,
  AGENT_FETCHER,
  AGENT_NEWS_ANALYZER,
]

// ============================================================================
// Agent 系统初始化
// ============================================================================

let initialized = false
let cleanup: (() => void) | null = null

/**
 * 初始化 Agent 系统
 * - 注册默认 Agent
 * - 启动健康监控
 * - 初始化 Store 订阅
 */
export function initAgentSystem(): void {
  if (initialized) {
    logger.warn('[AgentSystem] Already initialized')
    return
  }

  logger.info('[AgentSystem] Initializing...')

  const registry = getAgentRegistry()
  const configManager = getAgentConfigManager()
  const healthMonitor = getAgentHealthMonitor()

  // 注册默认 Agent 配置
  for (const config of DEFAULT_AGENTS) {
    const validation = configManager.validateConfig(config)
    if (!validation.valid) {
      logger.error(`[AgentSystem] Invalid config for "${config.id}":`, { errors: validation.errors })
      continue
    }
    configManager.setDefault(config.id, config)
    registry.register(config, ['default', 'system'])
    agentRuntime.register(config)
    logger.info(`[AgentSystem] Agent "${config.id}" registered`)
  }

  // 启动健康监控（30s 检查周期）
  healthMonitor.start(30000)

  // 初始化 Store 订阅
  cleanup = initAgentSubscriptions()

  initialized = true
  logger.info('[AgentSystem] Initialization complete', {
    agents: registry.getStats().total,
    healthMonitor: 'running',
  })
}

/**
 * 关闭 Agent 系统
 * - 停止健康监控
 * - 清理 Store 订阅
 */
export function shutdownAgentSystem(): void {
  if (!initialized) {
    logger.warn('[AgentSystem] Not initialized, skip shutdown')
    return
  }

  logger.info('[AgentSystem] Shutting down...')

  const healthMonitor = getAgentHealthMonitor()
  healthMonitor.stop()

  if (cleanup) {
    cleanup()
    cleanup = null
  }

  initialized = false
  logger.info('[AgentSystem] Shutdown complete')
}

/**
 * 获取 Agent 系统状态
 */
export function getAgentSystemStatus(): {
  initialized: boolean
  runtimeStats: ReturnType<typeof agentRuntime.getStats>
  registryStats: ReturnType<AgentRegistry['getStats']>
  healthReports: ReturnType<AgentHealthMonitor['getAllReports']>
} {
  return {
    initialized,
    runtimeStats: agentRuntime.getStats(),
    registryStats: getAgentRegistry().getStats(),
    healthReports: getAgentHealthMonitor().getAllReports(),
  }
}

// ============================================================================
// 自动初始化（在模块导入时执行）
// ============================================================================

// 在开发环境下，延迟初始化以便日志系统先就绪
if (import.meta.env.DEV) {
  setTimeout(() => {
    initAgentSystem()
  }, 100)
} else {
  // 生产环境立即初始化
  initAgentSystem()
}

/**
 * @module taskQueue
 * @lifecycle @Global
 * @description Agent 任务队列。支持优先级调度、并发控制和状态订阅。
 *
 * @remarks
 * - 优先级：high > normal > low，同优先级内 FIFO
 * - 并发控制：按 agentId 维度限制并发数
 * - 状态变更通过订阅机制通知外部
 *
 * @see src/agents/agentRuntime.ts
 */

import { getLogger } from '@/lib/logger'

const logger = getLogger()

export type TaskPriority = 'high' | 'normal' | 'low'

export interface QueuedTask {
  id: string
  agentId: string
  type: string
  payload: unknown
  timeout: number
  priority: TaskPriority
  status: 'pending' | 'running' | 'completed' | 'failed' | 'timeout' | 'cancelled'
  result?: unknown
  error?: string
  createdAt: number
  startedAt?: number
  completedAt?: number
}

export type TaskQueueListener = (task: QueuedTask) => void

const PRIORITY_ORDER: Record<TaskPriority, number> = {
  high: 0,
  normal: 1,
  low: 2,
}

export class TaskQueue {
  private pending = new Map<string, QueuedTask>()
  private running = new Map<string, QueuedTask>()
  private completed = new Map<string, QueuedTask>()
  private listeners = new Set<TaskQueueListener>()
  private maxConcurrentPerAgent = new Map<string, number>()
  private drainTimers = new Map<string, ReturnType<typeof queueMicrotask> | number>()

  setMaxConcurrent(agentId: string, max: number): void {
    this.maxConcurrentPerAgent.set(agentId, max)
    logger.debug(`[TaskQueue] setMaxConcurrent: agentId="${agentId}", max=${max}`)
  }

  enqueue(task: Omit<QueuedTask, 'status' | 'createdAt'> & { status?: QueuedTask['status']; createdAt?: number }): QueuedTask {
    const fullTask: QueuedTask = {
      status: 'pending',
      createdAt: Date.now(),
      ...task,
    }

    this.pending.set(fullTask.id, fullTask)
    logger.info(`[TaskQueue] Enqueued: taskId="${fullTask.id}", agentId="${fullTask.agentId}", priority="${fullTask.priority}"`)

    this.notify(fullTask)
    this.scheduleDrain(fullTask.agentId)

    return fullTask
  }

  dequeue(agentId: string): QueuedTask | undefined {
    const pendingForAgent = Array.from(this.pending.values())
      .filter((t) => t.agentId === agentId && t.status === 'pending')
      .sort((a, b) => {
        const pa = PRIORITY_ORDER[a.priority]
        const pb = PRIORITY_ORDER[b.priority]
        if (pa !== pb) return pa - pb
        return a.createdAt - b.createdAt
      })

    if (pendingForAgent.length === 0) return undefined

    const task = pendingForAgent[0] as QueuedTask
    this.pending.delete(task.id)
    task.status = 'running'
    task.startedAt = Date.now()
    this.running.set(task.id, task)

    logger.debug(`[TaskQueue] Dequeued: taskId="${task.id}", priority="${task.priority}"`)
    this.notify(task)
    return task
  }

  markCompleted(taskId: string, result: unknown): void {
    const task = this.running.get(taskId)
    if (!task) return

    task.status = 'completed'
    task.result = result
    task.completedAt = Date.now()
    this.running.delete(taskId)
    this.completed.set(taskId, task)

    logger.info(`[TaskQueue] Completed: taskId="${taskId}", agentId="${task.agentId}"`)
    this.notify(task)
    this.scheduleDrain(task.agentId)
  }

  markFailed(taskId: string, error: string): void {
    const task = this.running.get(taskId)
    if (!task) return

    task.status = 'failed'
    task.error = error
    task.completedAt = Date.now()
    this.running.delete(taskId)
    this.completed.set(taskId, task)

    logger.error(`[TaskQueue] Failed: taskId="${taskId}", error="${error}"`)
    this.notify(task)
    this.scheduleDrain(task.agentId)
  }

  markTimeout(taskId: string): void {
    const task = this.running.get(taskId)
    if (!task) return

    task.status = 'timeout'
    task.error = `Task timeout after ${task.timeout}ms`
    task.completedAt = Date.now()
    this.running.delete(taskId)
    this.completed.set(taskId, task)

    logger.warn(`[TaskQueue] Timeout: taskId="${taskId}"`)
    this.notify(task)
    this.scheduleDrain(task.agentId)
  }

  cancel(taskId: string): boolean {
    const pendingTask = this.pending.get(taskId)
    if (pendingTask) {
      pendingTask.status = 'cancelled'
      pendingTask.error = 'Task cancelled'
      pendingTask.completedAt = Date.now()
      this.pending.delete(taskId)
      this.completed.set(taskId, pendingTask)
      logger.info(`[TaskQueue] Cancelled pending task: taskId="${taskId}"`)
      this.notify(pendingTask)
      return true
    }

    const runningTask = this.running.get(taskId)
    if (runningTask) {
      runningTask.status = 'cancelled'
      runningTask.error = 'Task cancelled'
      runningTask.completedAt = Date.now()
      this.running.delete(taskId)
      this.completed.set(taskId, runningTask)
      logger.info(`[TaskQueue] Cancelled running task: taskId="${taskId}"`)
      this.notify(runningTask)
      this.scheduleDrain(runningTask.agentId)
      return true
    }

    return false
  }

  get(taskId: string): QueuedTask | undefined {
    return (
      this.pending.get(taskId) ??
      this.running.get(taskId) ??
      this.completed.get(taskId)
    )
  }

  list(status?: QueuedTask['status']): QueuedTask[] {
    const all = [
      ...this.pending.values(),
      ...this.running.values(),
      ...this.completed.values(),
    ]
    return status ? all.filter((t) => t.status === status) : all
  }

  getRunningCount(agentId: string): number {
    let count = 0
    for (const task of this.running.values()) {
      if (task.agentId === agentId) count++
    }
    return count
  }

  getStats() {
    return {
      pending: this.pending.size,
      running: this.running.size,
      completed: this.completed.size,
      total: this.pending.size + this.running.size + this.completed.size,
    }
  }

  subscribe(listener: TaskQueueListener): () => void {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  private notify(task: QueuedTask): void {
    this.listeners.forEach((l) => {
      try {
        l(task)
      } catch (err) {
        logger.error('[TaskQueue] Listener error', { error: err instanceof Error ? err.message : String(err) })
      }
    })
  }

  private scheduleDrain(agentId: string): void {
    if (this.drainTimers.has(agentId)) return

    const timerId = queueMicrotask(() => {
      this.drainTimers.delete(agentId)
      this.drain(agentId)
    })
    this.drainTimers.set(agentId, timerId as unknown as number)
  }

  private drain(agentId: string): void {
    const maxConcurrent = this.maxConcurrentPerAgent.get(agentId) ?? 1
    const runningCount = this.getRunningCount(agentId)

    if (runningCount >= maxConcurrent) {
      logger.debug(`[TaskQueue] drain skipped: ${runningCount}/${maxConcurrent} running for "${agentId}"`)
      return
    }

    const slots = maxConcurrent - runningCount
    for (let i = 0; i < slots; i++) {
      const task = this.dequeue(agentId)
      if (!task) break
    }
  }
}

export const taskQueue = new TaskQueue()

import React, { Suspense, useEffect, useRef } from 'react'
import { useState } from 'react'
import { useLocation } from 'react-router'
