              />
            </div>
          </div>

          {/* 是否启用模拟交易 */}
          <div className="flex items-center justify-between rounded-md border p-3">
            <Label htmlFor="enablePaperTrading">启用模拟交易</Label>
            <Switch
              id="enablePaperTrading"
              checked={config.enablePaperTrading}
              onChange={(e) => updateField('enablePaperTrading', e.target.checked)}
            />
          </div>
        </CardContent>
      </Card>

      {/* 数据采集配置组 */}
      <Card>
        <CardHeader>
          <CardTitle>数据采集配置</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            {/* 数据刷新间隔 */}
            <div className="space-y-2">
              <Label htmlFor="refreshInterval">数据刷新间隔</Label>
              <Select
                id="refreshInterval"
                value={String(config.refreshInterval)}
                onChange={(e) => updateField('refreshInterval', Number(e.target.value))}
              >
                {REFRESH_INTERVAL_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={String(opt.value)}>
                    {opt.label}
                  </SelectItem>
                ))}
              </Select>
            </div>

            {/* 是否自动刷新 */}
            <div className="flex items-center justify-between rounded-md border p-3 sm:col-span-2">
              <Label htmlFor="autoRefresh">自动刷新数据</Label>
              <Switch
                id="autoRefresh"
                checked={config.autoRefresh}
                onChange={(e) => updateField('autoRefresh', e.target.checked)}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 显示配置组 */}
      <Card>
        <CardHeader>
          <CardTitle>显示配置</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            {/* 主题 */}
            <div className="space-y-2">
              <Label htmlFor="theme">主题</Label>
              <Select
                id="theme"
                value={config.theme}
                onChange={(e) => updateField('theme', e.target.value as AppConfig['theme'])}
              >
                {THEME_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </Select>
            </div>

            {/* 语言 */}
            <div className="space-y-2">
              <Label htmlFor="language">语言</Label>
              <Select
                id="language"
                value={config.language}
                onChange={(e) => updateField('language', e.target.value as AppConfig['language'])}
              >
                {LANGUAGE_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* LLM 模型配置 */}
      <Card>
        <CardHeader>
          <CardTitle>LLM 模型配置</CardTitle>
        </CardHeader>
        <CardContent>
          <LLMConfigWidget
            value={llmConfig}
            onChange={handleLlmConfigChange}
            configReady={llmConfigReady}
            showWarning={!llmConfigReady}
          />
        </CardContent>
      </Card>
    </div>
  )
}

import React, { useState, useMemo, useEffect } from 'react'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Select, SelectItem } from '@/components/ui/Select'
import {
  parseBulkInput,
  importStocks,
  type BulkImportRow,
  type BulkImportResult,
} from '@/services/input/batchImportService'
import { usePoolStore, getAllGroups } from '@/store/poolStore'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

export default function BulkImportPanel(): React.JSX.Element {
  const refresh = usePoolStore((s) => s.refresh)
  const stocks = usePoolStore((s) => s.stocks)
  const allGroups = useMemo(() => getAllGroups(), [stocks])
  const [importText, setImportText] = useState('')
  const [importPreview, setImportPreview] = useState<BulkImportRow[]>([])
  const [importResult, setImportResult] = useState<BulkImportResult | null>(null)
  const [importing, setImporting] = useState(false)
  const [message, setMessage] = useState('')
  const [targetGroup, setTargetGroup] = useState('')

  // 组件初始化：加载股票池数据
  useEffect(() => {
    logger.info('[BulkImportPanel] 组件初始化，加载股票池数据')
    void refresh()
  }, [refresh])

  const handleParseImport = (text: string): void => {
    setImportText(text)
    setImportResult(null)
    setMessage('')
    const rows = parseBulkInput(text)
    setImportPreview(rows)
  }

  const handleConfirmImport = async (): Promise<void> => {
    const rows = importPreview
    if (rows.length === 0) {
      setMessage('未解析到有效股票')
      return
    }

    setImporting(true)
    const result = await importStocks(rows, {
      fetchBasicAfterAdd: false,
      group: targetGroup || undefined,
    })
    setImporting(false)

    if (result.success && result.data) {
      setImportResult(result.data)
      setMessage(
        `批量导入完成：成功 ${result.data.success} 条，失败 ${result.data.failed} 条`,
      )
      await refresh()
    } else {
      setMessage(result.error ?? '批量导入失败')
    }
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle>批量导入候选股票</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <p className="text-sm text-muted-foreground">
            支持粘贴 CSV / 文本，每行格式：代码,名称（如 600519,贵州茅台）
          </p>
          <textarea
            className="min-h-[160px] w-full rounded-md border bg-background p-3 text-sm text-foreground outline-none focus:border-primary"
            placeholder={`600519,贵州茅台\n000001,平安银行\n300750,宁德时代`}
            value={importText}
            onChange={(e) => handleParseImport(e.target.value)}
          />

          <div className="flex flex-wrap items-center gap-2">
            <span className="text-sm text-muted-foreground">目标分组：</span>
            <Select
              className="h-8 w-auto min-w-[140px]"
              value={targetGroup}
              onChange={(e) => setTargetGroup(e.target.value)}
              aria-label="批量导入目标分组"
            >
              <SelectItem value="">默认分组</SelectItem>
              {allGroups.map((g) => (
                <SelectItem key={g} value={g}>
                  {g}
                </SelectItem>
              ))}
            </Select>
          </div>

          {importPreview.length > 0 && (
            <div className="max-h-60 overflow-auto rounded-md border">
              <table className="w-full text-sm">
                <thead className="bg-muted">
                  <tr>
                    <th className="px-3 py-2 text-left">序号</th>
                    <th className="px-3 py-2 text-left">代码</th>
                    <th className="px-3 py-2 text-left">名称</th>
                    <th className="px-3 py-2 text-left">标准化代码</th>
                  </tr>
                </thead>
                <tbody>
                  {importPreview.map((row, idx) => (
                    <tr key={`${row.symbol}-${idx}`} className="border-t">
                      <td className="px-3 py-2">{idx + 1}</td>
                      <td className="px-3 py-2">{row.code}</td>
                      <td className="px-3 py-2">{row.name}</td>
                      <td className="px-3 py-2 font-mono text-xs">{row.symbol}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {importResult && importResult.errors.length > 0 && (
            <div className={`max-h-40 overflow-auto rounded-md border p-3 text-sm ${twBorder('red', 200)} ${twBg('red', 50)} ${twText('red', 700)} dark:${twBorder('red', 900)} dark:${twBg('red', 950)}/30`}>
              <p className={`font-medium ${twText('red', 700)} dark:${twText('red', 400)}`}>失败明细：</p>
              <ul className={`mt-1 list-inside list-disc ${twText('red', 600)} dark:${twText('red', 300)}`}>
                {importResult.errors.map((e, idx) => (
                  <li key={idx}>
                    第 {e.row} 行 {e.raw}: {e.error}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {message && (
            <p className="text-sm text-muted-foreground">{message}</p>
          )}

          <div className="flex justify-end gap-2">
            <Button
              onClick={() => void handleConfirmImport()}
              disabled={importPreview.length === 0 || importing}
            >
              {importing ? '导入中...' : `确认导入 (${importPreview.length})`}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Select, SelectItem } from '@/components/ui/Select'
import {
  getHotSectors,
  getHotSectorByCode,
  addHotSectorStock,
  addHotSectorStocks,
  type HotSector,
} from '@/services/input/hotSectorService'
import { usePoolStore, getAllGroups } from '@/store/poolStore'
import { useToast } from '@/hooks/useToast'
import { getLogger } from '@/lib/logger'
import { COLOR_TOKENS, twText, twBg } from '@/constants/theme.tokens'

const logger = getLogger()

export default function HotSectorPanel(): React.JSX.Element {
  // 从 poolStore 获取状态
  const refresh = usePoolStore((s) => s.refresh)
  const stocks = usePoolStore((s) => s.stocks)
  const allGroups = useMemo(() => getAllGroups(), [stocks])
  
  const [hotSectors] = useState<HotSector[]>(() => getHotSectors())
  const [selectedHotSector, setSelectedHotSector] = useState<string>(
    getHotSectors()[0]?.code ?? '',
  )
  const [targetGroup, setTargetGroup] = useState('')
  const [addingHot, setAddingHot] = useState<Set<string>>(new Set())
  const [addingAll, setAddingAll] = useState(false)
  const [message, setMessage] = useState('')
  const { toast } = useToast()

  const existingSymbols = useMemo(
    () => new Set(stocks.map((s) => s.symbol)),
    [stocks],
  )

  const activeHotSector = useMemo(
    () => getHotSectorByCode(selectedHotSector),
    [selectedHotSector],
  )

  const addOptions = useMemo(
    () => ({ fetchBasicAfterAdd: false, group: targetGroup || undefined }),
    [targetGroup],
  )

  // 组件初始化：加载股票池数据
  useEffect(() => {
    logger.info('[HotSectorPanel] 组件初始化，加载股票池数据')
    void refresh()
  }, [refresh])

  const handleAddHotStock = async (symbolToAdd: string): Promise<void> => {
    if (!activeHotSector) {
      logger.warn('[HotSectorPanel] handleAddHotStock 中断: activeHotSector 为空', { symbol: symbolToAdd })
      return
    }

    const startTime = Date.now()
    logger.info('[HotSectorPanel] handleAddHotStock 开始', {
      symbol: symbolToAdd,
      sectorCode: activeHotSector.code,
      targetGroup: addOptions.group ?? '默认分组'
    })
    
    setAddingHot((prev) => new Set(prev).add(symbolToAdd))
    
    try {
      const result = await addHotSectorStock(
        activeHotSector.code,
        symbolToAdd,
        addOptions,
      )
      
      setAddingHot((prev) => {
        const next = new Set(prev)
        next.delete(symbolToAdd)
        return next
      })

      if (result.success) {
        logger.info('[HotSectorPanel] handleAddHotStock 成功', {
          symbol: symbolToAdd,
          elapsedMs: Date.now() - startTime,
        })
        setMessage(`已将 ${symbolToAdd} 加入候选池`)
        await refresh()
      } else {
        logger.error('[HotSectorPanel] handleAddHotStock 失败', {
          symbol: symbolToAdd,
          error: result.error,
          elapsedMs: Date.now() - startTime,
        })
        setMessage(result.error ?? '加入失败')
      }
    } catch (err) {
      logger.error('[HotSectorPanel] handleAddHotStock 异常', {
        symbol: symbolToAdd,
        error: err instanceof Error ? err.message : String(err),
        elapsedMs: Date.now() - startTime,
      })
      setAddingHot((prev) => {
        const next = new Set(prev)
        next.delete(symbolToAdd)
        return next
      })
      setMessage(err instanceof Error ? err.message : '加入失败')
    }
  }

  const handleAddAllHotStocks = async (): Promise<void> => {
    if (!activeHotSector || addingAll) return
    setAddingAll(true)
    setAddingHot((prev) => {
      const next = new Set(prev)
      activeHotSector.stocks.forEach((s) => next.add(s.symbol))
      return next
    })
    try {
      const result = await addHotSectorStocks(activeHotSector.code, addOptions)
      if (result.success && result.data) {
        toast({
          title: '批量加入完成',
          description: `板块 ${activeHotSector.name}：成功 ${result.data.added.length} 只，失败 ${result.data.failed.length} 只`,
          variant: 'success',
        })
        setMessage(
          `板块 ${activeHotSector.name}：成功加入 ${result.data.added.length} 只，失败 ${result.data.failed.length} 只`,
        )
        await refresh()
      } else {
        toast({ title: '批量加入失败', description: result.error ?? '未知错误', variant: 'error' })
        setMessage(result.error ?? '批量加入失败')
      }
    } finally {
      setAddingAll(false)
      setAddingHot((prev) => {
        const next = new Set(prev)
        activeHotSector.stocks.forEach((s) => next.delete(s.symbol))
        return next
      })
    }
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle>热门板块推荐</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {hotSectors.map((sector) => (
              <button
                key={sector.code}
                onClick={() => setSelectedHotSector(sector.code)}
                className={`rounded-md border p-3 text-left transition-colors ${
                  selectedHotSector === sector.code
                    ? 'border-primary bg-primary/10'
                    : 'hover:bg-accent/50'
                }`}
              >
                <div className="flex items-center justify-between">
                  <span className="font-medium">{sector.name}</span>
                  <Badge
                    className={
                      sector.trend === 'up'
                        ? `${twBg('green', 100)} ${twText('green', 800)}`
                        : sector.trend === 'down'
                          ? `${twBg('red', 100)} ${twText('red', 800)}`
                          : `${twBg('gray', 100)} ${twText('gray', 600)}`
                    }
                  >
                    {sector.score}
                  </Badge>
                </div>
                <div className="mt-1 text-xs text-muted-foreground">
                  动量 {sector.factors.momentum} · 资金 {sector.factors.fundFlow}
                </div>
              </button>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <span className="text-sm text-muted-foreground">目标分组：</span>
            <Select
              className="h-8 w-auto min-w-[140px]"
              value={targetGroup}
              onChange={(e) => setTargetGroup(e.target.value)}
              aria-label="热门板块目标分组"
            >
              <SelectItem value="">默认分组</SelectItem>
              {allGroups.map((g) => (
                <SelectItem key={g} value={g}>
                  {g}
                </SelectItem>
              ))}
            </Select>
          </div>

          {activeHotSector && (
            <div className="rounded-md border">
              <div className="flex items-center justify-between border-b p-3">
                <h4 className="font-medium">{activeHotSector.name} 关联股票</h4>
                <Button size="sm" variant="secondary" onClick={() => void handleAddAllHotStocks()} disabled={addingAll}>
                  {addingAll ? '加入中...' : '全部加入候选池'}
                </Button>
              </div>
              <div className="max-h-96 overflow-auto">
                {activeHotSector.stocks.map((stock) => {
                  const isAdded = existingSymbols.has(stock.symbol)
                  const isAdding = addingHot.has(stock.symbol)
                  return (
                    <div
                      key={stock.symbol}
                      className="flex items-center justify-between border-b p-3 last:border-b-0"
                    >
                      <div>
                        <span className="font-mono text-sm">{stock.symbol}</span>
                        <span className="ml-2 text-sm text-muted-foreground">{stock.name}</span>
                      </div>
                      <Button
                        size="sm"
                        onClick={() => void handleAddHotStock(stock.symbol)}
                        disabled={isAdded || isAdding}
                        variant={isAdded ? 'secondary' : 'primary'}
                      >
                        {isAdded ? '已加入' : isAdding ? '加入中...' : '加入候选池'}
                      </Button>
                    </div>
                  )
                })}
              </div>
            </div>
          )}

          {message && <p className="text-sm text-muted-foreground">{message}</p>}
        </CardContent>
      </Card>
    </div>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Input } from '@/components/ui/Input'
import { Badge } from '@/components/ui/Badge'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/Dialog'
import { Select, SelectItem } from '@/components/ui/Select'
import { addStock } from '@/services/input/inputService'
import {
  checkFetcherHealth,
  refreshSymbolKline,
} from '@/services/fetcher/fetcherService'
import { transitionStock, updateStockGroup } from '@/services/stockpool/stockpoolService'
import { PoolBoard } from '@/components/pool/PoolBoard'
import { usePoolStore, getAllGroups } from '@/store/poolStore'
import { StockSearch } from '@/components/input/StockSearch'
import { RESEARCH_STATUS, type ResearchStatus } from '@/config/dbConfig'
import type { Stock } from '@/data/types'
import type { StockSearchResult } from '@/services/input/inputService'
import type { PoolViewMode } from '@/components/pool/PoolBoard'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

const ALL_GROUPS_VALUE = '__all__'
type QualityFilter = 'all' | 'missingBasic' | 'missingKline' | 'missingFinance'

export default function InputDashboard(): React.JSX.Element {
  const navigate = useNavigate()

  // 从 poolStore 获取状态
  const stocks = usePoolStore((s) => s.stocks)
  const loading = usePoolStore((s) => s.loading)
  const error = usePoolStore((s) => s.error)
  const refresh = usePoolStore((s) => s.refresh)

  // 本地 UI 状态
  const [selectedGroup, setSelectedGroup] = useState('')
  const [symbol, setSymbol] = useState('')
  const [name, setName] = useState('')
  const [group, setGroup] = useState('')
  const [message, setMessage] = useState('')
  const [fetcherOk, setFetcherOk] = useState<boolean | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [searchMode, setSearchMode] = useState<'fill' | 'add'>('fill')
  const [viewMode, setViewMode] = useState<PoolViewMode>('kanban')
  const [qualityFilter, setQualityFilter] = useState<QualityFilter>('all')
  const [selectedSymbols, setSelectedSymbols] = useState<string[]>([])
  const [newGroupDialogOpen, setNewGroupDialogOpen] = useState(false)
  const [newGroupName, setNewGroupName] = useState('')
  const [createdGroups, setCreatedGroups] = useState<string[]>([])

  // 初始化加载
  useEffect(() => {
    logger.info('[InputDashboard] 初始化，加载股票池数据')
    void refresh()
  }, [refresh])

  const allGroups = useMemo(() => getAllGroups(), [stocks])

  const groupOptions = useMemo(
    () => Array.from(new Set([...allGroups, ...createdGroups])).sort(),
    [allGroups, createdGroups],
  )

  const allStocks = stocks

  const filteredStocks = useMemo(() => {
    if (qualityFilter === 'all') return allStocks
    return allStocks.filter((s) => {
      const q = s.dataQuality
      switch (qualityFilter) {
        case 'missingBasic':
          return q?.basic !== true
        case 'missingKline':
          return q?.kline !== true
        case 'missingFinance':
          return q?.finance !== true
        default:
          return true
      }
    })
  }, [allStocks, qualityFilter])

  const handleAdd = async (fetchBasic: boolean, fetchKline: boolean): Promise<void> => {
    if (!symbol || !name) {
      setMessage('请输入代码和名称')
      return
    }

    setSubmitting(true)
    const result = await addStock(
      { symbol, name },
      {
        fetchBasicAfterAdd: fetchBasic,
        fetchKlineAfterAdd: fetchKline,
        group: group || undefined,
      },
    )
    setSubmitting(false)

    if (result.success) {
      setMessage(
        result.error
          ? `已添加 ${result.data?.symbol}，${result.error}`
          : `已添加 ${result.data?.symbol}`,
      )
      setSymbol('')
      setName('')
      setGroup('')
      await refresh()
    } else {
      setMessage(result.error ?? '添加失败')
    }
  }

  const handleRefreshHealth = async (): Promise<void> => {
    setFetcherOk(null)
    const result = await checkFetcherHealth()
    setFetcherOk(result.ok)
    if (!result.ok) {
      setMessage(result.error ?? '数据采集服务异常')
    }
  }

  const handleRefreshKline = async (stock: Stock): Promise<void> => {
    const result = await refreshSymbolKline(stock.symbol)
    if (result.success) {
      setMessage(`已刷新 ${stock.symbol} 行情`)
      await refresh()
    } else {
      setMessage(result.error ?? '刷新行情失败')
    }
  }

  const handleAnalyze = (symbolToAnalyze: string): void => {
    navigate(`/analysis/stock-score/${symbolToAnalyze}`)
  }

  const handleSelectToggle = (targetSymbol: string): void => {
    setSelectedSymbols((prev) =>
      prev.includes(targetSymbol)
        ? prev.filter((s) => s !== targetSymbol)
        : [...prev, targetSymbol],
    )
  }

  const runBulkTransition = async (toStatus: ResearchStatus): Promise<void> => {
    const targets = allStocks.filter((s) => selectedSymbols.includes(s.symbol))
    const results: string[] = []
    for (const stock of targets) {
      const result = await transitionStock(stock.symbol, toStatus)
      if (!result.success) {
        results.push(`${stock.symbol}: ${result.error ?? '失败'}`)
      }
    }
    setSelectedSymbols([])
    await refresh()
    if (results.length > 0) {
      setMessage(`批量流转完成，部分失败：${results.join('；')}`)
    } else {
      setMessage(`已批量流转 ${targets.length} 只标的到 ${toStatus}`)
    }
  }

  const runBulkChangeGroup = async (targetGroup: string): Promise<void> => {
    const targets = allStocks.filter((s) => selectedSymbols.includes(s.symbol))
    const results: string[] = []
    for (const stock of targets) {
      const result = await updateStockGroup(stock.symbol, targetGroup)
      if (!result.success) {
        results.push(`${stock.symbol}: ${result.error ?? '失败'}`)
      }
    }
    setSelectedSymbols([])
    await refresh()
    if (results.length > 0) {
      setMessage(`批量移入分组完成，部分失败：${results.join('；')}`)
    } else {
      setMessage(`已批量移入 ${targets.length} 只标的到 ${targetGroup}`)
    }
  }

  const handleBulkArchive = (): Promise<void> => runBulkTransition(RESEARCH_STATUS.archived)

  const handleTransition = async (symbol: string, toStatus: ResearchStatus): Promise<void> => {
    const result = await transitionStock(symbol, toStatus)
    await refresh()
    if (!result.success) {
