import React, { useState } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Button } from '@/components/ui/Button'
import { PhaseStepper } from './PhaseStepper'
import type { ExecutionPlan, ExecutionPhase, RiskCheckItem } from '@/data/types'
import { ChevronDown, ChevronUp, ShieldAlert, ShieldCheck, Info } from 'lucide-react'
import { COLOR_SHADES, twText, twBg } from '@/constants/theme.tokens'

export interface ExecutionPlanCardProps {
  plan: ExecutionPlan
  onConfirm?: (planId: string) => void
  onExecute?: (planId: string) => void
  onCancel?: (planId: string) => void
  onReview?: (planId: string) => void
}

const PHASE_BADGE_COLORS: Record<ExecutionPhase, string> = {
  plan: `${twBg('blue', 100)} ${twText('blue', 800)}`,
  confirmed: `${twBg('blue', 100)} ${twText('blue', 800)}`,
  pending: `${twBg('yellow', 100)} ${twText('yellow', 800)}`,
  executed: `${twBg('green', 100)} ${twText('green', 800)}`,
  cancelled: `${twBg('red', 100)} ${twText('red', 800)}`,
  reviewed: `${twBg('purple', 100)} ${twText('purple', 800)}`,
}

const PHASE_LABELS: Record<ExecutionPhase, string> = {
  plan: '计划',
  confirmed: '已确认',
  pending: '执行中',
  executed: '已执行',
  cancelled: '已取消',
  reviewed: '已复盘',
}

function formatRelativeTime(timestamp: number): string {
  const diff = Date.now() - timestamp
  const seconds = Math.floor(diff / 1000)
  const minutes = Math.floor(seconds / 60)
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  if (days > 0) return `${days}天前`
  if (hours > 0) return `${hours}小时前`
  if (minutes > 0) return `${minutes}分钟前`
  return '刚刚'
}

function getStepperPhase(plan: ExecutionPlan): ExecutionPhase {
  if (plan.phase !== 'cancelled') return plan.phase
  // 根据时间戳推断取消前最后到达的阶段
  if (plan.executedAt) return 'pending'
  if (plan.confirmedAt) return 'confirmed'
  return 'plan'
}

export function ExecutionPlanCard({
  plan,
  onConfirm,
  onExecute,
  onCancel,
  onReview,
}: ExecutionPlanCardProps): React.JSX.Element {
  const [riskExpanded, setRiskExpanded] = useState(false)

  const directionLabel = plan.direction === 'buy' ? '买入' : '卖出'
  const directionClass =
    plan.direction === 'buy'
      ? `${COLOR_SHADES.green[100]} ${COLOR_SHADES.green[800]}`
      : `${COLOR_SHADES.red[100]} ${COLOR_SHADES.red[800]}`

  const phaseClass = PHASE_BADGE_COLORS[plan.phase]
  const stepperPhase = getStepperPhase(plan)
  const isCancelled = plan.phase === 'cancelled'

  // 操作按钮可见性
  const canConfirm = plan.phase === 'plan' && !!onConfirm
  const canExecute = (plan.phase === 'plan' || plan.phase === 'confirmed') && !!onExecute
  const canCancel =
    (plan.phase === 'plan' || plan.phase === 'confirmed' || plan.phase === 'pending') && !!onCancel
  const canReview =
    (plan.phase === 'executed' || plan.phase === 'cancelled') && !!onReview

  const riskChecks = plan.risk?.checks ?? []

  return (
    <Card className="overflow-hidden">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center gap-2">
            <span className="font-mono font-semibold text-sm">{plan.symbol}</span>
            <Badge className={cn(directionClass)}>{directionLabel}</Badge>
            <Badge className={cn(phaseClass)}>{PHASE_LABELS[plan.phase]}</Badge>
          </div>
          <span className="text-xs text-muted-foreground">
            置信度 {(plan.confidence * 100).toFixed(0)}%
          </span>
        </div>
      </CardHeader>

      <CardContent className="space-y-3 pt-0">
        {/* 状态机步骤条 */}
        <PhaseStepper
          phase={stepperPhase}
          cancelled={isCancelled}
          result={plan.result}
        />

        {/* 详情区 */}
        <div className="grid grid-cols-3 gap-2 text-xs">
          <div className="rounded-md border p-2">
            <p className="text-muted-foreground">数量 / 仓位</p>
            <p className="font-medium">
              {plan.sizing ? `${plan.sizing.quantity}股 / ${(plan.sizing.positionPct * 100).toFixed(1)}%` : '—'}
            </p>
          </div>
          <div className="rounded-md border p-2">
            <p className="text-muted-foreground">风控检查</p>
            <div className="flex items-center gap-1 font-medium">
              {plan.risk ? (
                <>
                  {plan.risk.passed ? (
                    <ShieldCheck className={`h-3.5 w-3.5 ${COLOR_SHADES.green[600]}`} />
                  ) : (
                    <ShieldAlert className={`h-3.5 w-3.5 ${COLOR_SHADES.red[600]}`} />
                  )}
                  <span className={plan.risk.passed ? COLOR_SHADES.green[700] : COLOR_SHADES.red[700]}>
                    {plan.risk.passed ? '通过' : '未通过'}
                  </span>
                  <span className="text-muted-foreground">({plan.risk.checks.length}项)</span>
                </>
              ) : (
                <span>—</span>
              )}
            </div>
          </div>
          <div className="rounded-md border p-2">
            <p className="text-muted-foreground">订单号</p>
            <p className="font-medium truncate">{plan.orderId ?? '—'}</p>
          </div>
        </div>

        {/* 风控明细可展开 */}
        {riskChecks.length > 0 && (
          <div>
            <button
              type="button"
              onClick={() => setRiskExpanded((v) => !v)}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              {riskExpanded ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
              风控明细 ({riskChecks.length}项)
            </button>
            {riskExpanded && (
              <div className="mt-2 space-y-1.5">
                {riskChecks.map((check: RiskCheckItem, idx: number) => (
                  <div
                    key={idx}
                    className={cn(
                      'flex items-start gap-1.5 rounded-md border px-2 py-1.5 text-xs',
                      check.severity === 'blocker' && `${twBg('red', 50)} ${twBg('red', 200)} ${twText('red', 800)}`,
                      check.severity === 'warning' && `${twBg('yellow', 50)} ${twBg('yellow', 200)} ${twText('yellow', 800)}`,
                      check.severity === 'info' && `${twBg('gray', 50)} ${twBg('gray', 200)} ${twText('gray', 700)}`
                    )}
                  >
                    {check.severity === 'blocker' && <ShieldAlert className={`h-3.5 w-3.5 ${COLOR_SHADES.red[600]} mt-0.5 shrink-0`} />}
                    {check.severity === 'warning' && <ShieldCheck className={`h-3.5 w-3.5 ${COLOR_SHADES.yellow[600]} mt-0.5 shrink-0`} />}
                    {check.severity === 'info' && <Info className={`h-3.5 w-3.5 ${COLOR_SHADES.gray[500]} mt-0.5 shrink-0`} />}
                    <div>
                      <span className="font-medium">{check.name}:</span>{' '}
                      <span>{check.message}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* 错误信息 */}
        {plan.errorMessage && (
          <p className={`text-xs ${COLOR_SHADES.red[600]} ${COLOR_SHADES.red[50]} rounded-md px-2 py-1.5 border ${COLOR_SHADES.red[200]}`}>
            {plan.errorMessage}
          </p>
        )}

        {/* 操作按钮 */}
        <div className="flex flex-wrap gap-2">
          {canConfirm && (
            <Button size="sm" onClick={() => onConfirm?.(plan.id)}>
              确认
            </Button>
          )}
          {canExecute && (
            <Button size="sm" onClick={() => onExecute?.(plan.id)}>
              执行
            </Button>
          )}
          {canCancel && (
            <Button variant="danger" size="sm" onClick={() => onCancel?.(plan.id)}>
              取消
            </Button>
          )}
          {canReview && (
            <Button variant="secondary" size="sm" onClick={() => onReview?.(plan.id)}>
              复盘
            </Button>
          )}
        </div>

        {/* 底部时间 */}
        <div className="flex items-center justify-between text-[10px] text-muted-foreground pt-1 border-t">
          <span>创建于 {formatRelativeTime(plan.createdAt)}</span>
          {plan.accountType && (
            <Badge variant="outline" className="text-[10px] px-1.5 py-0">
              {plan.accountType === 'paper' ? '模拟盘' : plan.accountType === 'real' ? '实盘' : plan.accountType}
            </Badge>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import React from 'react'
import { cn } from '@/lib/utils'
import type { ExecutionPhase } from '@/data/types'
import { Loader2 } from 'lucide-react'
import { COLOR_SHADES, twBg, twText, twBorder } from '@/constants/theme.tokens'

export interface PhaseStepperProps {
  phase: ExecutionPhase
  cancelled?: boolean
  result?: 'success' | 'failed' | 'partial'
}

const PHASES: ExecutionPhase[] = ['plan', 'confirmed', 'pending', 'executed', 'cancelled', 'reviewed']

const PHASE_LABELS: Record<ExecutionPhase, string> = {
  plan: '计划',
  confirmed: '确认',
  pending: '执行中',
  executed: '已执行',
  cancelled: '已取消',
  reviewed: '已复盘',
}

const PHASE_COLORS: Record<ExecutionPhase, { bg: string; text: string; border: string }> = {
  plan: { bg: twBg('blue', 500), text: twText('blue', 500), border: twBorder('blue', 500) },
  confirmed: { bg: twBg('blue', 500), text: twText('blue', 500), border: twBorder('blue', 500) },
  pending: { bg: twBg('yellow', 500), text: twText('yellow', 500), border: twBorder('yellow', 500) },
  executed: { bg: twBg('green', 500), text: twText('green', 500), border: twBorder('green', 500) },
  cancelled: { bg: twBg('red', 500), text: twText('red', 500), border: twBorder('red', 500) },
  reviewed: { bg: twBg('purple', 500), text: twText('purple', 500), border: twBorder('purple', 500) },
}

export function PhaseStepper({ phase, cancelled, result }: PhaseStepperProps): React.JSX.Element {
  const currentIndex = PHASES.indexOf(phase)
  const cancelledIndex = PHASES.indexOf('cancelled')

  const isPhaseReached = (index: number): boolean => {
    if (cancelled) {
      // 取消模式下，当前 phase 及之前阶段为已到达，cancelled 本身也为已到达
      if (index === cancelledIndex) return true
      return index <= currentIndex
    }
    return index <= currentIndex
  }

  const isPhaseCurrent = (index: number): boolean => {
    if (cancelled) {
      return PHASES[index] === 'cancelled'
    }
    return index === currentIndex
  }

  const getLineStyle = (index: number): { bg: string; dashed: boolean } => {
    const nextIndex = index + 1
    if (nextIndex >= PHASES.length) return { bg: 'bg-transparent', dashed: false }

    const isNextReached = isPhaseReached(nextIndex)
    const isCurrentReached = isPhaseReached(index)

    // 取消模式下，从当前 phase 到 cancelled 的连线为红色断裂线
    if (cancelled && index === currentIndex && nextIndex === cancelledIndex) {
      return { bg: COLOR_SHADES.red[500], dashed: true }
    }

    // 取消模式下，cancelled 之后的连线灰色
    if (cancelled && index >= cancelledIndex) {
      return { bg: twBg('gray', 200), dashed: false }
    }

    if (isCurrentReached && isNextReached) {
      return { bg: COLOR_SHADES.blue[500], dashed: false }
    }

    return { bg: twBg('gray', 200), dashed: false }
  }

  return (
    <div className="flex items-center justify-between w-full">
      {PHASES.map((p, index) => {
        const reached = isPhaseReached(index)
        const current = isPhaseCurrent(index)
        const colors = PHASE_COLORS[p]!
        const lineStyle = getLineStyle(index)
        const isPendingSpinner = p === 'pending' && current && !cancelled

        return (
          <React.Fragment key={p}>
            {/* 节点 */}
            <div className="flex flex-col items-center gap-1 flex-1">
              <div
                className={cn(
                  'relative flex items-center justify-center rounded-full border-2 transition-colors',
                  'w-6 h-6',
                  reached || current
                    ? `${colors.bg} ${colors.border} text-white`
                    : `${twBg('slate', 50)} ${twBorder('slate', 300)} ${twText('slate', 400)}`,
                  current && !cancelled && 'ring-2 ring-offset-1',
                  current && !cancelled && colors.border.replace('border-', 'ring-')
                )}
              >
                {isPendingSpinner ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : (
                  <span className="text-[10px] font-bold">{index + 1}</span>
                )}

                {/* 结果指示器 */}
                {p === 'executed' && reached && result && (
                  <span
                    className={cn(
                      'absolute -top-1 -right-1 flex h-2.5 w-2.5 rounded-full border border-white',
                      result === 'success' && COLOR_SHADES.green[600],
                      result === 'failed' && COLOR_SHADES.red[600],
                      result === 'partial' && COLOR_SHADES.yellow[600]
                    )}
                  />
                )}
              </div>
              <span
                className={cn(
                  'text-[10px] font-medium whitespace-nowrap',
                  reached || current ? colors.text : twText('gray', 400)
                )}
              >
                {PHASE_LABELS[p]}
              </span>
            </div>

            {/* 连接线 */}
            {index < PHASES.length - 1 && (
              <div className="flex-1 h-0.5 mx-1 relative">
                <div
                  className={cn(
                    'absolute inset-0 rounded-full',
                    lineStyle.bg,
                    lineStyle.dashed && `bg-transparent border-t-2 border-dashed ${COLOR_SHADES.red[500]}`
                  )}
                />
              </div>
            )}
          </React.Fragment>
        )
      })}
    </div>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Button } from '@/components/ui/Button'
import { EmptyState } from '@/components/ui/EmptyState'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs'
import { useExecutionStore, initExecutionStoreSubscriptions } from '@/store/executionStore'
import { ExecutionPlanCard } from '../components/ExecutionPlanCard'
import type { ExecutionPlan } from '@/data/types'
import { RefreshCw } from 'lucide-react'

type FilterTab = 'all' | 'active' | 'completed' | 'cancelled' | 'reviewed'

const TAB_LABELS: Record<FilterTab, string> = {
  all: '全部',
  active: '活跃',
  completed: '已完成',
  cancelled: '已取消',
  reviewed: '已复盘',
}

function isToday(timestamp: number): boolean {
  const d = new Date(timestamp)
  const now = new Date()
  return (
    d.getFullYear() === now.getFullYear() &&
    d.getMonth() === now.getMonth() &&
    d.getDate() === now.getDate()
  )
}

function filterPlans(plans: ExecutionPlan[], tab: FilterTab): ExecutionPlan[] {
  switch (tab) {
    case 'active':
      return plans.filter((p) => p.phase === 'plan' || p.phase === 'confirmed' || p.phase === 'pending')
    case 'completed':
      return plans.filter((p) => p.phase === 'executed')
    case 'cancelled':
      return plans.filter((p) => p.phase === 'cancelled')
    case 'reviewed':
      return plans.filter((p) => p.phase === 'reviewed')
    default:
      return plans
  }
}

export function ExecutionPlanPanel(): React.JSX.Element {
  const [activeTab, setActiveTab] = useState<FilterTab>('all')

  const plans = useExecutionStore((s) => s.plans)
  const activePlans = useExecutionStore((s) => s.activePlans)
  const loading = useExecutionStore((s) => s.loading)
  const isRefreshing = useExecutionStore((s) => s.isRefreshing)
  const refresh = useExecutionStore((s) => s.refresh)
  const confirmPlan = useExecutionStore((s) => s.confirmPlan)
  const executePlan = useExecutionStore((s) => s.executePlan)
  const cancelPlan = useExecutionStore((s) => s.cancelPlan)
  const markReviewed = useExecutionStore((s) => s.markReviewed)

  useEffect(() => {
    const cleanup = initExecutionStoreSubscriptions()
    void refresh()
    return cleanup
  }, [refresh])

  const filteredPlans = useMemo(() => filterPlans(plans, activeTab), [plans, activeTab])

  const stats = useMemo(() => {
    const active = activePlans.length
    const pendingConfirm = plans.filter((p) => p.phase === 'plan').length
    const todayExecuted = plans.filter(
      (p) => p.phase === 'executed' && p.executedAt && isToday(p.executedAt)
    ).length
    return { active, pendingConfirm, todayExecuted }
  }, [plans, activePlans])

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center gap-2">
            <CardTitle>执行计划</CardTitle>
            {activePlans.length > 0 && (
              <Badge variant="default">{activePlans.length}</Badge>
            )}
          </div>
          <Button
            variant="secondary"
            size="sm"
            onClick={() => void refresh()}
            disabled={isRefreshing}
          >
            <RefreshCw className={cn('h-3.5 w-3.5 mr-1', isRefreshing && 'animate-spin')} />
            {isRefreshing ? '刷新中...' : '刷新'}
          </Button>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* 统计栏 */}
        <div className="grid grid-cols-3 gap-2">
          <div className="rounded-md border p-2 text-center">
            <p className="text-xs text-muted-foreground">活跃</p>
            <p className="text-lg font-semibold">{stats.active}</p>
          </div>
          <div className="rounded-md border p-2 text-center">
            <p className="text-xs text-muted-foreground">待确认</p>
            <p className="text-lg font-semibold">{stats.pendingConfirm}</p>
          </div>
          <div className="rounded-md border p-2 text-center">
            <p className="text-xs text-muted-foreground">今日执行</p>
            <p className="text-lg font-semibold">{stats.todayExecuted}</p>
          </div>
        </div>

        {/* 筛选栏 */}
        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as FilterTab)}>
          <TabsList className="w-full">
            {(Object.keys(TAB_LABELS) as FilterTab[]).map((tab) => (
              <TabsTrigger key={tab} value={tab} className="flex-1">
                {TAB_LABELS[tab]}
                <span className="ml-1 text-[10px] text-muted-foreground">
                  ({filterPlans(plans, tab).length})
                </span>
              </TabsTrigger>
            ))}
          </TabsList>

          <TabsContent value={activeTab}>
            {loading ? (
              <div className="space-y-2">
                {Array.from({ length: 3 }).map((_, i) => (
                  <div key={i} className="h-32 rounded-md border bg-muted animate-pulse" />
                ))}
              </div>
            ) : filteredPlans.length === 0 ? (
              <EmptyState
                title="暂无执行计划"
                description="扫描信号后将自动生成"
                className="py-8"
              />
            ) : (
              <div className="grid gap-2">
                {filteredPlans.map((plan) => (
                  <ExecutionPlanCard
                    key={plan.id}
                    plan={plan}
                    onConfirm={confirmPlan}
                    onExecute={executePlan}
                    onCancel={cancelPlan}
                    onReview={markReviewed}
                  />
                ))}
              </div>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router'
import { Settings, RefreshCw, Plus, Target } from 'lucide-react'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { WidgetErrorBoundary } from '@/components/WidgetErrorBoundary'
import { GridLayout } from 'react-grid-layout'
import 'react-grid-layout/css/styles.css'
import 'react-resizable/css/styles.css'
import { widgetRegistry } from '@/cockpit/core/widgetRegistry'
import { widgetEngine } from '@/cockpit/core/widgetEngine'
import { MarketDataProvider, useMarketData } from '@/cockpit/providers/MarketDataProvider'
import { GRID_COLUMNS, GRID_ROW_HEIGHT, GRID_GAP } from '@/constants/cockpit.constants'
import { getLogger } from '@/lib/logger'
import { COLOR_TOKENS } from '@/constants/theme.tokens'
import type { WidgetConfig, MarketData } from '@/types/modules/widget.types'

const logger = getLogger()
const LAYOUT_STORAGE_KEY = 'v9_cockpit_layout'

/** 从 localStorage 恢复布局 */
function loadLayout(): Record<string, { x: number; y: number }> | null {
  try {
    const raw = localStorage.getItem(LAYOUT_STORAGE_KEY)
    return raw ? (JSON.parse(raw) as Record<string, { x: number; y: number }>) : null
  } catch {
    return null
  }
}

/** 持久化布局到 localStorage */
function saveLayout(layout: { i: string; x: number; y: number; w: number; h: number }[]): void {
  try {
    const positions: Record<string, { x: number; y: number }> = {}
    layout.forEach((item) => {
      positions[item.i] = { x: item.x, y: item.y }
    })
    localStorage.setItem(LAYOUT_STORAGE_KEY, JSON.stringify(positions))
  } catch {
    logger.warn('[CockpitShell] Failed to save layout')
  }
}

interface WidgetWrapperProps {
  config: WidgetConfig
  data: MarketData
}

function WidgetWrapper(props: WidgetWrapperProps): React.JSX.Element {
  // P0-2 修复：hooks 必须在所有条件分支之前调用（React Rules of Hooks）
  // 使用可选链安全访问 config，避免 null 解构崩溃
  const config = props?.config ?? null
  const data = props?.data

  const [Component, setComponent] = useState<React.ComponentType<{ config: unknown; data?: MarketData }> | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!config) {
      setLoading(false)
      return
    }
    const mount = async () => {
      try {
        // 使用 widgetEngine 完整生命周期管理
        const success = await widgetEngine.mountInstance(config.instanceId)
        if (success) {
          const component = await widgetEngine.loadComponent(config.widgetId)
          setComponent(component)
          logger.info('[CockpitShell] Widget mounted successfully', { instanceId: config.instanceId, widgetId: config.widgetId })
        } else {
          setError('挂载失败')
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : '加载失败')
        logger.error('[CockpitShell] Widget mount error', { instanceId: config.instanceId, error: err })
      } finally {
        setLoading(false)
      }
    }
    mount()

    // 清理：卸载实例
    return () => {
      widgetEngine.unmountInstance(config.instanceId)
      logger.info('[CockpitShell] Widget unmounted', { instanceId: config.instanceId })
    }
  }, [config?.instanceId, config?.widgetId])

  // P0-2 深度修复：用 SafeWrapper 包裹动态加载的 Widget 组件
  // 防止 widget 组件内部解构 { config } 时收到 null props 导致崩溃
  // 注意：useMemo 必须在所有条件返回之前调用（rules of hooks）
  const SafeComponent = useMemo(() => {
    if (!Component) return null
    const SafeWrapper = (wrapperProps: { config: unknown; data?: MarketData }): React.JSX.Element | null => {
      if (!wrapperProps || !wrapperProps.config) {
        logger.warn('[CockpitShell] SafeWrapper: widget received null props', { widgetId: config?.widgetId })
        return null
      }
      return <Component {...wrapperProps} />
    }
    SafeWrapper.displayName = `Safe(${Component.displayName || Component.name || 'Widget'})`
    return SafeWrapper
  }, [Component, config?.widgetId])

  // 空值守卫：所有 hooks 之后安全返回
  if (!config) {
    logger.warn('[WidgetWrapper] config is null/undefined, rendering fallback')
    return (
      <Card>
        <CardContent className="flex h-full items-center justify-center text-sm" style={{ color: COLOR_TOKENS.textSecondary.hex }}>
          组件配置未就绪
        </CardContent>
      </Card>
    )
  }

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-base">{config.title}</CardTitle>
        </CardHeader>
        <CardContent className="p-8">
          <div className="flex justify-center">
            <RefreshCw className="h-8 w-8 animate-spin text-gray-400" />
          </div>
        </CardContent>
      </Card>
    )
  }

  if (error) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-base">{config.title}</CardTitle>
        </CardHeader>
        <CardContent className="p-8">
          <div className={`text-center ${COLOR_TOKENS.danger.tailwind}`}>
            <p>{error}</p>
            <Button
              variant="outline"
              size="sm"
              onClick={async () => {
                setLoading(true)
                setError(null)
                const success = await widgetEngine.refreshInstance(config.instanceId)
                if (success) {
                  const component = await widgetEngine.loadComponent(config.widgetId)
                  setComponent(component)
                } else {
                  setError('刷新失败')
                }
                setLoading(false)
              }}
              className="mt-2"
            >
              重试
            </Button>
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!SafeComponent) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-base">{config.title}</CardTitle>
        </CardHeader>
        <CardContent className="p-8 text-center text-gray-400">
          组件未找到
        </CardContent>
      </Card>
    )
  }

  // 将统一的 MarketData 注入到每个 Widget 组件
  // 组件既可通过 props.data 获取，也可通过 useMarketData() 消费
  // WidgetErrorBoundary 捕获子组件渲染异常，避免单个 Widget 崩溃影响全局
  return (
    <WidgetErrorBoundary
      widgetId={config.widgetId}
      instanceId={config.instanceId}
      errorTitle={`${config.title} 加载异常`}
    >
      <SafeComponent config={config} data={data} />
    </WidgetErrorBoundary>
  )
}

function CockpitContent(): React.JSX.Element {
  const [instances, setInstances] = useState<WidgetConfig[]>([])
  const [engineStats, setEngineStats] = useState({ cachedComponents: 0 })
  const { data, getTaskStats } = useMarketData()

  useEffect(() => {
    setInstances(widgetRegistry.getAllInstances())
    setEngineStats(widgetEngine.getStats())
    const unsubscribe = widgetRegistry.subscribe(() => {
      setInstances(widgetRegistry.getAllInstances())
      setEngineStats(widgetEngine.getStats())
    })
    return unsubscribe
  }, [])

  const handleLayoutChange = (newLayout: readonly { i: string; x: number; y: number; w: number; h: number }[]) => {
    saveLayout([...newLayout])
    logger.info('[CockpitShell] Layout saved', { items: newLayout.length })
  }

  const layout = (() => {
    const persisted = loadLayout()
    return instances.map((instance) => {
      const saved = persisted?.[instance.instanceId]
      return {
        i: instance.instanceId,
        x: saved?.x ?? instance.position?.x ?? 0,
        y: saved?.y ?? instance.position?.y ?? 0,
        w: instance.size.cols,
        h: instance.size.rows,
        minW: 1,
        minH: 1,
      }
    })
  })()

  const stats = getTaskStats()

  return (
    <div className="min-h-screen bg-background">
      <header className="sticky top-0 z-10 border-b bg-background/95 px-4 py-3 backdrop-blur">
        <div className="mx-auto flex max-w-7xl items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex h-8 w-8 items-center justify-center rounded-md bg-primary/10 text-primary">
              <Target className="h-4 w-4" />
            </div>
            <h1 className="text-lg font-bold">驾驶舱</h1>
            <Badge variant="outline" className="ml-2">
              {instances.length} 个 Widget
            </Badge>
            <Badge variant="secondary" className="text-xs">
              缓存: {engineStats.cachedComponents}
            </Badge>
            <Badge variant="secondary" className="text-xs">
              采集任务: {stats.running}/{stats.total}
            </Badge>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm">
              <Plus className="h-4 w-4 mr-1" />
              添加 Widget
            </Button>
            <Button variant="ghost" size="sm">
              <Settings className="h-4 w-4" />
            </Button>
            <Button variant="secondary" size="sm" asChild>
              <Link to="/">返回首页</Link>
            </Button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl p-4">
        <GridLayout
          className="bg-background"
          layout={layout}
          width={1100}
          gridConfig={{
            cols: GRID_COLUMNS,
            rowHeight: GRID_ROW_HEIGHT,
            margin: [GRID_GAP, GRID_GAP],
            containerPadding: [GRID_GAP, GRID_GAP],
          }}
          dragConfig={{
            enabled: true,
          }}
          resizeConfig={{
            enabled: true,
          }}
          onLayoutChange={handleLayoutChange}
        >
          {instances.map((instance) => (
            <div key={instance.instanceId}>
              <WidgetWrapper config={instance} data={data} />
            </div>
          ))}
        </GridLayout>
      </main>
    </div>
  )
}

export default function CockpitShell(): React.JSX.Element {
  return (
    <MarketDataProvider>
      <CockpitContent />
    </MarketDataProvider>
  )
}

import React from 'react'
import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import { widgetRegistry } from './widgetRegistry'
import { defaultWidgetBuilder } from '../defaultWidgetBuilder'
import type { MarketData } from '@/types/modules/widget.types'

const logger = getLogger()

const componentCache = new Map<string, React.ComponentType<{ config: unknown; data?: MarketData }>>()

export class WidgetEngine {
  constructor() {
    logger.info('[WidgetEngine] Initializing...')
  }

  async loadComponent(widgetId: string): Promise<React.ComponentType<{ config: unknown; data?: MarketData }> | null> {
    const startTs = Date.now()
    logger.debug(`[WidgetEngine] loadComponent() called: widgetId="${widgetId}"`)

    const cached = componentCache.get(widgetId)
    if (cached) {
      logger.debug(`[WidgetEngine] loadComponent() cache hit: widgetId="${widgetId}"`)
      return cached
    }

    const template = widgetRegistry.getTemplate(widgetId)
    if (!template) {
      logger.error(`[WidgetEngine] loadComponent failed: Template "${widgetId}" not found`)
      eventBus.emit('WIDGET_LOAD_ERROR', { widgetId, error: 'Template not found' })
      return null
    }

    try {
      logger.debug(`[WidgetEngine] Loading component module: widgetId="${widgetId}"`)
      const module = await template.component()
      const component = module.default as React.ComponentType<{ config: unknown; data?: MarketData }>

      if (!component) {
        throw new Error(`Widget "${widgetId}" component is empty`)
      }

      // P0-2 全局防御：包裹所有 widget 组件，防止 props 为 null 时解构崩溃
      const SafeWrapper = (props: { config: unknown; data?: MarketData }): React.JSX.Element | null => {
        if (!props || !props.config) {
          logger.warn(`[WidgetEngine] Widget "${widgetId}" received null props, rendering fallback`)
          return null
        }
        return React.createElement(component, props)
      }
      SafeWrapper.displayName = `Safe(${component.displayName || component.name || 'Widget'})`

      componentCache.set(widgetId, SafeWrapper)
      const duration = Date.now() - startTs

      logger.info(`[WidgetEngine] Component loaded: widgetId="${widgetId}", duration=${duration}ms`)
      eventBus.emit('WIDGET_LOAD_SUCCESS', { widgetId })
      return SafeWrapper
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      logger.error(`[WidgetEngine] Failed to load component: widgetId="${widgetId}", error="${errorMsg}"`)
      eventBus.emit('WIDGET_LOAD_ERROR', { widgetId, error: errorMsg })
      throw err
    }
  }

  async mountInstance(instanceId: string): Promise<boolean> {
    const startTs = Date.now()
    logger.debug(`[WidgetEngine] mountInstance() called: instanceId="${instanceId}"`)

    const config = widgetRegistry.getInstance(instanceId)
    if (!config) {
      logger.error(`[WidgetEngine] mountInstance failed: Instance "${instanceId}" not found`)
      return false
    }

    logger.info(`[WidgetEngine] Mounting instance: instanceId="${instanceId}", widgetId="${config.widgetId}"`)
    widgetRegistry.updateRuntimeState(instanceId, { status: 'loading' })
    eventBus.emit('WIDGET_MOUNT_START', { instanceId, widgetId: config.widgetId })

    try {
      await this.loadComponent(config.widgetId)
      widgetRegistry.updateRuntimeState(instanceId, { status: 'ready', lastRefresh: Date.now() })

      const duration = Date.now() - startTs
      logger.info(`[WidgetEngine] Instance mounted: instanceId="${instanceId}", duration=${duration}ms`)
      eventBus.emit('WIDGET_MOUNT_SUCCESS', { instanceId, widgetId: config.widgetId })
      return true
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      const fallbackState = defaultWidgetBuilder.buildFallbackRuntimeState(instanceId, config.widgetId, errorMsg)
      widgetRegistry.updateRuntimeState(instanceId, fallbackState)

      logger.error(`[WidgetEngine] Failed to mount instance: instanceId="${instanceId}", error="${errorMsg}"`)
      eventBus.emit('WIDGET_MOUNT_ERROR', { instanceId, widgetId: config.widgetId, error: errorMsg })
      return false
    }
  }

  unmountInstance(instanceId: string): void {
    logger.debug(`[WidgetEngine] unmountInstance() called: instanceId="${instanceId}"`)

    const config = widgetRegistry.getInstance(instanceId)
    widgetRegistry.updateRuntimeState(instanceId, { status: 'idle' })

    logger.info(`[WidgetEngine] Instance unmounted: instanceId="${instanceId}", widgetId="${config?.widgetId}"`)
    eventBus.emit('WIDGET_UNMOUNT', { instanceId, widgetId: config?.widgetId })
  }

  async refreshInstance(instanceId: string): Promise<boolean> {
    const startTs = Date.now()
    logger.debug(`[WidgetEngine] refreshInstance() called: instanceId="${instanceId}"`)

    const config = widgetRegistry.getInstance(instanceId)
    if (!config) {
      logger.error(`[WidgetEngine] refreshInstance failed: Instance "${instanceId}" not found`)
      return false
    }

    logger.info(`[WidgetEngine] Refreshing instance: instanceId="${instanceId}", widgetId="${config.widgetId}"`)
    widgetRegistry.updateRuntimeState(instanceId, { status: 'loading' })
    eventBus.emit('WIDGET_REFRESH_START', { instanceId, widgetId: config.widgetId })

    try {
      await this.loadComponent(config.widgetId)
      widgetRegistry.updateRuntimeState(instanceId, { status: 'ready', lastRefresh: Date.now() })

      const duration = Date.now() - startTs
      logger.info(`[WidgetEngine] Instance refreshed: instanceId="${instanceId}", duration=${duration}ms`)
      eventBus.emit('WIDGET_REFRESH_SUCCESS', { instanceId, widgetId: config.widgetId })
      return true
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      widgetRegistry.updateRuntimeState(instanceId, { status: 'error', error: errorMsg })

      logger.error(`[WidgetEngine] Failed to refresh instance: instanceId="${instanceId}", error="${errorMsg}"`)
      eventBus.emit('WIDGET_REFRESH_ERROR', { instanceId, widgetId: config.widgetId, error: errorMsg })
      return false
    }
  }

  preloadComponent(widgetId: string): void {
    if (componentCache.has(widgetId)) {
      logger.debug(`[WidgetEngine] preloadComponent() skipped: widgetId="${widgetId}" already cached`)
      return
    }

    logger.debug(`[WidgetEngine] Preloading component: widgetId="${widgetId}"`)
    this.loadComponent(widgetId).catch((err) => {
      logger.warn(`[WidgetEngine] Preload failed: widgetId="${widgetId}"`, { error: err })
    })
  }

  clearCache(widgetId?: string): void {
    if (widgetId) {
      const existed = componentCache.has(widgetId)
      componentCache.delete(widgetId)
      logger.info(`[WidgetEngine] Cache cleared for: widgetId="${widgetId}", existed=${existed}`)
    } else {
      const prevSize = componentCache.size
      componentCache.clear()
      logger.info(`[WidgetEngine] All cache cleared: ${prevSize} components`)
    }
  }

  getStats() {
    const stats = {
      cachedComponents: componentCache.size,
    }
    logger.debug(`[WidgetEngine] getStats(): ${JSON.stringify(stats)}`)
    return stats
  }
}

export const widgetEngine = new WidgetEngine()

import React, { createContext, useContext, useEffect, useRef, useState, useCallback } from 'react'
import { getLogger } from '@/lib/logger'
import type { MarketData, CollectionResultCallback, ChatMessage } from '@/types/modules/widget.types'
import { taskScheduler } from '@/services/data-collector/TaskScheduler'
import { marketDataAdapter } from '@/services/data-collector/MarketDataAdapter'
import { widgetRegistry } from '@/cockpit/core/widgetRegistry'
import { MockStockAnalysisProvider } from '@/services/stock-analysis/mockStockAnalysisProvider'
import { streamingChat } from '@/services/llm/llmGateway'
import type { LlmStreamCallback } from '@/services/llm/llmTypes'
import {
  ACTIVE_DATA_SOURCE,
  DATA_SOURCE_TYPE,
} from '@/constants/cockpit.constants'

const logger = getLogger()

interface MarketDataContextValue {
  data: MarketData
  loadingMap: Record<string, boolean>
  errorMap: Record<string, string | null>
  refreshWidget: (instanceId: string) => void
  getTaskStats: () => { total: number; running: number; error: number }
  /** 发送个股/市场分析聊天消息（新增）
   * @remarks 用户主动触发的对话行为，不走轮询 TaskScheduler，直接调用对应 Collector
   */
  sendChatMessage: (target: string, question: string) => Promise<ChatMessage>
}

const MarketDataContext = createContext<MarketDataContextValue | null>(null)

interface MarketDataProviderProps {
  children: React.ReactNode
}

export function MarketDataProvider({ children }: MarketDataProviderProps): React.JSX.Element {
  const [data, setData] = useState<MarketData>(() => marketDataAdapter.merge())
  const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({})
  const [errorMap, setErrorMap] = useState<Record<string, string | null>>({})

  const taskMapRef = useRef<Record<string, string>>({})
  const isMountedRef = useRef(false)
  const subscribeRef = useRef<(() => void) | null>(null)

  const handleCollectionResult: CollectionResultCallback = useCallback((taskId, rawData, error) => {
    if (!isMountedRef.current) return

    if (error) {
      const instanceId = Object.entries(taskMapRef.current).find(([, tid]) => tid === taskId)?.[0]
      if (instanceId) {
        setErrorMap((prev) => ({ ...prev, [instanceId]: error.message }))
        setLoadingMap((prev) => ({ ...prev, [instanceId]: false }))
      }
      return
    }

    if (rawData) {
      const instanceId = Object.entries(taskMapRef.current).find(([, tid]) => tid === taskId)?.[0]
      if (instanceId) {
        setErrorMap((prev) => ({ ...prev, [instanceId]: null }))
        setLoadingMap((prev) => ({ ...prev, [instanceId]: false }))
      }

      const adapted = marketDataAdapter.adapt(rawData)
      setData((prev) => marketDataAdapter.merge(prev, adapted))
    }
  }, [])

  useEffect(() => {
    isMountedRef.current = true
    logger.info('[MarketDataProvider] 初始化数据采集...')

    subscribeRef.current = taskScheduler.subscribe(handleCollectionResult)

    const instances = widgetRegistry.getAllInstances()
    logger.info(`[MarketDataProvider] 发现 ${instances.length} 个 Widget 实例`)

    instances.forEach((instance) => {
      const { instanceId, widgetId, dataSource } = instance

      if (!dataSource || !dataSource.enabled) {
        logger.warn(`[MarketDataProvider] Widget ${instanceId} 未配置数据源，跳过`)
        return
      }

      if (taskMapRef.current[instanceId]) {
        logger.warn(`[MarketDataProvider] Widget ${instanceId} 已有采集任务，跳过重复注册`)
        return
      }

      setLoadingMap((prev) => ({ ...prev, [instanceId]: true }))

      const taskId = taskScheduler.registerTask(widgetId, instanceId, dataSource)
      taskMapRef.current[instanceId] = taskId
      taskScheduler.startTask(taskId)
    })

    return () => {
      logger.info('[MarketDataProvider] 组件卸载，清理数据采集任务...')
      isMountedRef.current = false

      if (subscribeRef.current) {
        subscribeRef.current()
        subscribeRef.current = null
      }

      Object.values(taskMapRef.current).forEach((taskId) => {
        taskScheduler.unregisterTask(taskId)
      })
      taskMapRef.current = {}
    }
  }, [handleCollectionResult])

  const refreshWidget = useCallback((instanceId: string) => {
    const taskId = taskMapRef.current[instanceId]
    if (!taskId) {
      logger.warn(`[MarketDataProvider] 未找到实例 ${instanceId} 对应的任务`)
      return
    }

    setLoadingMap((prev) => ({ ...prev, [instanceId]: true }))
    setErrorMap((prev) => ({ ...prev, [instanceId]: null }))

    taskScheduler.stopTask(taskId)
    taskScheduler.startTask(taskId)

    logger.info(`[MarketDataProvider] 手动刷新: ${instanceId}`)
  }, [])

  const getTaskStats = useCallback(() => {
    const tasks = taskScheduler.getAllTasks()
    return {
      total: tasks.length,
      running: tasks.filter((t) => t.status === 'running').length,
      error: tasks.filter((t) => t.status === 'error').length,
    }
  }, [])

  /**
   * 发送聊天消息
   * @description Mock 模式直接调用 MockStockAnalysisProvider；REST 模式使用 SSE 流式 LLM 推理接口
   * @remarks 这是用户主动触发的行为，不经过 TaskScheduler 轮询，返回的 ChatMessage 由 Widget 自行追加到本地会话
   */
  const sendChatMessage = useCallback(async (target: string, question: string): Promise<ChatMessage> => {
    logger.info(`[MarketDataProvider] 发送聊天消息: target=${target}`)

    if (ACTIVE_DATA_SOURCE === DATA_SOURCE_TYPE.MOCK) {
      return MockStockAnalysisProvider.sendChatMessage(target, question)
    }

    const messages = [
      { role: 'system' as const, content: `你是一位专业的股票分析助手，正在分析标的：${target}。请提供详细、专业的分析。` },
      { role: 'user' as const, content: question },
    ]

    let fullContent = ''
    const startTime = Date.now()

    const chunkCallback: LlmStreamCallback = (chunk) => {
      if (!chunk.isDone) {
        fullContent += chunk.content
        logger.debug('[MarketDataProvider] LLM stream chunk received', { length: chunk.content.length, total: fullContent.length })
      }
    }

    try {
      await streamingChat(messages, chunkCallback)
      logger.info('[MarketDataProvider] LLM streaming chat completed', { contentLength: fullContent.length, duration: Date.now() - startTime })
    } catch (err) {
      logger.error('[MarketDataProvider] LLM streaming chat failed', { error: err instanceof Error ? err.message : String(err) })
      throw err
    }

    return {
      id: `assistant_${Date.now()}`,
      role: 'assistant',
      content: fullContent,
      timestamp: Date.now(),
    }
  }, [])

  const value: MarketDataContextValue = {
    data,
    loadingMap,
    errorMap,
    refreshWidget,
    getTaskStats,
    sendChatMessage,
  }

  return <MarketDataContext.Provider value={value}>{children}</MarketDataContext.Provider>
}

// eslint-disable-next-line react-refresh/only-export-components
export function useMarketData(): MarketDataContextValue {
  const context = useContext(MarketDataContext)
  if (!context) {
    throw new Error('useMarketData 必须在 MarketDataProvider 内部使用')
  }
  return context
}

// eslint-disable-next-line react-refresh/only-export-components
export function useOptionalMarketData(): MarketDataContextValue | undefined {
  return useContext(MarketDataContext) ?? undefined
}

import React, { useEffect, useState } from 'react'
import { ArrowUpCircle, ArrowDownCircle } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
