  const sentimentTrend = useAnalysisNewsStore((s) => s.sentimentTrend)
  const stockOptions = useAnalysisNewsStore((s) => s.sentimentStockOptions)
  const industryOptions = useAnalysisNewsStore((s) => s.sentimentIndustryOptions)
  const computeSentimentTrend = useAnalysisNewsStore((s) => s.computeSentimentTrend)

  const [dimension, setDimension] = useState<SentimentTrendDimension>('global')
  const [value, setValue] = useState<string>('')

  // 当 articles/dimension/value 变化时，通过 Store action 重新计算
  useEffect(() => {
    logger.info('[NewsSentimentTrend] 触发情感趋势计算', { dimension, value, articleCount: articles.length })
    computeSentimentTrend(dimension, value || undefined)
  }, [articles, dimension, value, computeSentimentTrend])

  // 构建趋势数据（从 Store 读取，若尚未计算则使用空数据）
  const trend = useMemo(() => sentimentTrend ?? {
    dimension,
    value: value ?? '',
    data: [],
    summary: { totalArticles: 0, positiveCount: 0, negativeCount: 0, neutralCount: 0, avgDailyArticles: 0 },
  }, [sentimentTrend, dimension, value])

  const handleDimensionChange = useCallback((event: React.ChangeEvent<HTMLSelectElement>) => {
    const next = event.target.value as SentimentTrendDimension
    setDimension(next)
    setValue('')
  }, [])

  const handleValueChange = useCallback((event: React.ChangeEvent<HTMLSelectElement>) => {
    setValue(event.target.value)
  }, [])

  const isEmpty = !loading && articles.length === 0

  return (
    <Card>
      <CardHeader>
        <CardTitle>情感趋势</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center gap-3">
          <div className="space-y-1">
            <label htmlFor="sentiment-dimension" className="text-sm font-medium">
              维度
            </label>
            <Select
              id="sentiment-dimension"
              value={dimension}
              onChange={handleDimensionChange}
            >
              {DIMENSION_OPTIONS.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </Select>
          </div>

          {dimension !== 'global' && (
            <div className="space-y-1">
              <label htmlFor="sentiment-value" className="text-sm font-medium">
                {dimension === 'stock' ? '股票代码' : '行业分类'}
              </label>
              <Select
                id="sentiment-value"
                value={value}
                onChange={handleValueChange}
              >
                <SelectItem value="">请选择</SelectItem>
                {(dimension === 'stock' ? stockOptions : industryOptions).map((opt) => (
                  <SelectItem key={opt} value={opt}>
                    {opt}
                  </SelectItem>
                ))}
              </Select>
            </div>
          )}

          <div className="ml-auto flex gap-4 text-sm">
            <span className={newsColors.positive.text}>正面 {trend.summary.positiveCount} 条</span>
            <span className={newsColors.negative.text}>负面 {trend.summary.negativeCount} 条</span>
            <span className={newsColors.neutral.text}>中性 {trend.summary.neutralCount} 条</span>
          </div>
        </div>

        <DataState<typeof trend>
          isLoading={loading}
          isError={error !== null}
          isEmpty={isEmpty || trend.data.length === 0}
          data={trend}
          errorProps={{ error: error ?? '' }}
          emptyProps={{
            title: '暂无趋势数据',
            description: '当前筛选条件下没有足够资讯生成情感趋势',
          }}
        >
          <BarChart
            data={trend.data as unknown as Array<Record<string, unknown>>}
            xKey="date"
            bars={SENTIMENT_BAR_CONFIG}
            height={320}
          />
        </DataState>

        {trend.summary.totalArticles > 0 && (
          <div className="grid grid-cols-2 gap-4 text-sm text-muted-foreground sm:grid-cols-4">
            <div>总资讯数 <span className="font-medium text-foreground">{trend.summary.totalArticles}</span></div>
            <div>平均每日 <span className="font-medium text-foreground">{trend.summary.avgDailyArticles.toFixed(1)}</span></div>
            <div>正面占比 <span className={`font-medium ${newsColors.positive.text}`}>{formatRatio(trend.summary.positiveCount / trend.summary.totalArticles)}</span></div>
            <div>负面占比 <span className={`font-medium ${newsColors.negative.text}`}>{formatRatio(trend.summary.negativeCount / trend.summary.totalArticles)}</span></div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

export default NewsSentimentTrend

/**
 * IntelligentScoreExplanation - 智能评分解释可视化（DA-003）
 *
 * 展示智能评分结果：维度雷达图、关键因子高亮、可折叠的思维链。
 * LLM 原始输出统一经 sanitizeLlmOutput 净化后渲染。
 */

import { memo, useMemo, useState } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Button } from '@/components/ui/Button'
import { DataState } from '@/components/ui/DataState'
import { ScoreRadar } from '@/components/chart/ScoreRadar'
import { sanitizeLlmOutput } from '@/utils/xssSanitizer'
import type { IntelligentScore } from '@/data/types'
import {
  INTELLIGENT_SCORE_EXPLANATION_CONFIG,
  INTELLIGENT_SCORE_EXPLANATION_LABELS,
} from '@/constants/score.constants'
import { CHART_PALETTE } from '@/constants/theme.tokens'

export interface IntelligentScoreExplanationProps {
  result?: IntelligentScore
  loading?: boolean
  error?: string | null
  className?: string
}

const SCORE_SCALE_MAX = 5

export function buildRadarData(result: IntelligentScore) {
  return result.dimensionScores
    .filter((dim) => typeof dim.score === 'number' && Number.isFinite(dim.score))
    .slice(0, INTELLIGENT_SCORE_EXPLANATION_CONFIG.maxRadarDimensions)
    .map((dim) => ({
      dimension: dim.name,
      score: dim.score as number,
      fullMark: SCORE_SCALE_MAX,
    }))
}

export function buildKeyFactors(result: IntelligentScore) {
  const valid = result.dimensionScores.filter(
    (dim) => typeof dim.score === 'number' && Number.isFinite(dim.score),
  )
  const sorted = valid.slice().sort((a, b) => (b.score as number) - (a.score as number))
  return sorted.slice(0, INTELLIGENT_SCORE_EXPLANATION_CONFIG.topFactorCount)
}

export const IntelligentScoreExplanation = memo(function IntelligentScoreExplanation({
  result,
  loading,
  error,
  className,
}: IntelligentScoreExplanationProps) {
  const [showChain, setShowChain] = useState(!INTELLIGENT_SCORE_EXPLANATION_CONFIG.chainCollapsed)

  const radarData = useMemo(() => (result ? buildRadarData(result) : []), [result])
  const keyFactors = useMemo(() => (result ? buildKeyFactors(result) : []), [result])
  const sanitizedChain = useMemo(() => {
    if (!result) return ''
    return sanitizeLlmOutput(result.modelResponse ?? result.basis ?? '')
  }, [result])

  const isEmpty = !loading && !error && !result

  return (
    <Card className={cn('overflow-hidden', className)}>
      <CardHeader className="pb-2">
        <CardTitle className="text-base font-semibold">
          {INTELLIGENT_SCORE_EXPLANATION_LABELS.title}
        </CardTitle>
      </CardHeader>
      <CardContent className="pt-0">
        <DataState
          isLoading={loading ?? false}
          isError={!!error}
          isEmpty={isEmpty}
          data={result}
          loadingProps={{ message: '加载中...' }}
          errorProps={{ error: error ?? '加载失败', showErrorDetail: true }}
          emptyProps={{
            title: INTELLIGENT_SCORE_EXPLANATION_LABELS.emptyTitle,
            description: INTELLIGENT_SCORE_EXPLANATION_LABELS.emptyDescription,
          }}
        >
          {result && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <div>
                  <p className="mb-2 text-sm font-medium text-muted-foreground">
                    {INTELLIGENT_SCORE_EXPLANATION_LABELS.radarTitle}
                  </p>
                  <ScoreRadar
                    data={radarData}
                    height={240}
                    colors={{ fill: CHART_PALETTE.series1, stroke: CHART_PALETTE.series1 }}
                  />
                </div>
                <div>
                  <p className="mb-2 text-sm font-medium text-muted-foreground">
                    {INTELLIGENT_SCORE_EXPLANATION_LABELS.keyFactorsTitle}
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {keyFactors.map((factor) => {
                      const score = factor.score as number
                      const isHighlight = score >= INTELLIGENT_SCORE_EXPLANATION_CONFIG.highlightThreshold
                      return (
                        <Badge
                          key={factor.name}
                          variant={isHighlight ? 'success' : 'outline'}
                          className="text-xs"
                        >
                          {factor.name}: {score.toFixed(1)}
                        </Badge>
                      )
                    })}
                    {keyFactors.length === 0 && (
                      <span className="text-sm text-muted-foreground">暂无有效维度得分</span>
                    )}
                  </div>
                </div>
              </div>

              {sanitizedChain && (
                <div className="rounded-md border p-3">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setShowChain((prev) => !prev)}
                    aria-expanded={showChain}
                  >
                    {showChain
                      ? INTELLIGENT_SCORE_EXPLANATION_LABELS.collapseChain
                      : INTELLIGENT_SCORE_EXPLANATION_LABELS.expandChain}
                  </Button>
                  {showChain && (
                    <pre className="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">
                      {sanitizedChain}
                    </pre>
                  )}
                </div>
              )}
            </div>
          )}
        </DataState>
      </CardContent>
    </Card>
  )
})

