import {
  forwardRef,
  memo,
  useEffect,
  useRef,
  type ComponentPropsWithoutRef,
  type RefObject,
} from 'react'
import { createChart, CandlestickSeries, type IChartApi, type ISeriesApi, type CandlestickData, type Time } from 'lightweight-charts'
import { CHART_PALETTE } from '@/constants/theme.tokens'

export interface CandlestickChartData {
  time: string
  open: number
  high: number
  low: number
  close: number
  volume?: number
}

export interface CandlestickChartProps extends ComponentPropsWithoutRef<'div'> {
  data: CandlestickChartData[]
  height?: number
  upColor?: string
  downColor?: string
}

const CandlestickChart = forwardRef<HTMLDivElement, CandlestickChartProps>(
  ({ data, height = 400, upColor, downColor, ...divProps }, ref) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const chartRef = useRef<IChartApi | null>(null)
    const seriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null)

    // 涨跌色默认值
    const positiveColor = upColor ?? CHART_PALETTE.upColor
    const negativeColor = downColor ?? CHART_PALETTE.downColor

    useEffect(() => {
      if (!containerRef.current) return

      // 创建图表
      const chart = createChart(containerRef.current, {
        height,
        layout: {
          background: { color: 'transparent' },
          textColor: CHART_PALETTE.axis,
        },
        grid: {
          vertLines: { color: CHART_PALETTE.gridLight },
          horzLines: { color: CHART_PALETTE.gridLight },
        },
        crosshair: {
          mode: 1,
          vertLine: {
            color: CHART_PALETTE.accent,
            width: 1,
            style: 2,
          },
          horzLine: {
            color: CHART_PALETTE.accent,
            width: 1,
            style: 2,
          },
        },
        rightPriceScale: {
          borderColor: CHART_PALETTE.gridLight,
        },
        timeScale: {
          borderColor: CHART_PALETTE.gridLight,
          timeVisible: true,
        },
      })

      // 添加 K 线系列
      const series = chart.addSeries(CandlestickSeries, {
        upColor: positiveColor,
        downColor: negativeColor,
        borderUpColor: positiveColor,
        borderDownColor: negativeColor,
        wickUpColor: positiveColor,
        wickDownColor: negativeColor,
      })

      // 格式化数据
      const formattedData: CandlestickData<Time>[] = data.map((item) => ({
        time: item.time as Time,
        open: item.open,
        high: item.high,
        low: item.low,
        close: item.close,
      }))

      series.setData(formattedData)

      // 适应窗口
      chart.timeScale().fitContent()

      chartRef.current = chart
      seriesRef.current = series

      // 清理
      return () => {
        chart.remove()
        chartRef.current = null
        seriesRef.current = null
      }
    }, [data, height, positiveColor, negativeColor])

    // 转发 ref
    if (ref) {
      if (typeof ref === 'function') {
        ref(containerRef.current)
      } else {
        ;(ref as RefObject<HTMLDivElement | null>).current = containerRef.current
      }
    }

    return (
      <div ref={containerRef} style={{ height }} {...divProps} />
    )
  }
)

CandlestickChart.displayName = 'CandlestickChart'

// 同时导出 named + default
const CandlestickChartMemo = memo(CandlestickChart)
CandlestickChartMemo.displayName = 'CandlestickChart'
export const CandlestickSeriesChart = CandlestickChartMemo
export { CandlestickSeriesChart as CandlestickChart }
export default CandlestickChartMemo

import {
  forwardRef,
  memo,
  type ComponentPropsWithoutRef,
} from 'react'
import { CHART_PALETTE } from '@/constants/theme.tokens'

export interface FactorHeatmapData {
  name: string
  value: number
  category?: string
}

export interface FactorHeatmapProps extends ComponentPropsWithoutRef<'div'> {
  data: FactorHeatmapData[]
  minValue?: number
  maxValue?: number
  height?: number
}

const FactorHeatmap = forwardRef<HTMLDivElement, FactorHeatmapProps>(
  ({ data, minValue = -1, maxValue = 1, height = 200, ...divProps }, ref) => {
    // 计算列数（根据数据量动态调整）
    const colCount = Math.min(Math.ceil(Math.sqrt(data.length)), 6)

    // 将值映射到颜色渐变：低(-1) -> 中(0) -> 高(1)
    // 颜色端点全部来自 CHART_PALETTE，禁止硬编码
    const valueToColor = (value: number): string => {
      const normalized = (value - minValue) / (maxValue - minValue)

      const parseRgb = (hex: string): [number, number, number] => {
        const n = Number.parseInt(hex.replace('#', ''), 16)
        return [(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff]
      }

      const low = parseRgb(CHART_PALETTE.factorHeatmapLow)
      const mid = parseRgb(CHART_PALETTE.factorHeatmapMid)
      const high = parseRgb(CHART_PALETTE.factorHeatmapHigh)

      if (normalized <= 0.5) {
        const ratio = normalized * 2
        const r = Math.round(low[0] + (mid[0] - low[0]) * ratio)
        const g = Math.round(low[1] + (mid[1] - low[1]) * ratio)
        const b = Math.round(low[2] + (mid[2] - low[2]) * ratio)
        return `rgb(${r}, ${g}, ${b})`
      } else {
        const ratio = (normalized - 0.5) * 2
        const r = Math.round(mid[0] + (high[0] - mid[0]) * ratio)
        const g = Math.round(mid[1] + (high[1] - mid[1]) * ratio)
        const b = Math.round(mid[2] + (high[2] - mid[2]) * ratio)
        return `rgb(${r}, ${g}, ${b})`
      }
    }

    // 根据类别分组
    const categories = [...new Set(data.map((item) => item.category ?? '默认'))]
    const groupedData = categories.map((category) => ({
      category,
      items: data.filter((item) => (item.category ?? '默认') === category),
    }))

    return (
      <div ref={ref} {...divProps}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', height }}>
          {groupedData.map((group) => (
            <div key={group.category}>
              {categories.length > 1 && (
                <div
                  style={{
                    fontSize: '12px',
                    color: CHART_PALETTE.axis,
                    marginBottom: '6px',
                    fontWeight: 500,
                  }}
                >
                  {group.category}
                </div>
              )}
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: `repeat(${colCount}, 1fr)`,
                  gap: '4px',
                }}
              >
                {group.items.map((item, index) => (
                  <div
                    key={`${item.name}-${index}`}
                    style={{
                      backgroundColor: valueToColor(item.value),
                      borderRadius: '6px',
                      padding: '8px 6px',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      minHeight: '60px',
                      color: CHART_PALETTE.tooltipBg,
                      fontSize: '11px',
                    }}
                  >
                    <span
                      style={{
                        fontWeight: 600,
                        marginBottom: '2px',
                        textAlign: 'center',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        maxWidth: '100%',
                      }}
                      title={item.name}
                    >
                      {item.name}
                    </span>
                    <span
                      style={{
                        fontFamily: 'JetBrains Mono, monospace',
                        fontSize: '12px',
                        fontWeight: 500,
                      }}
                    >
                      {item.value.toFixed(2)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }
)

FactorHeatmap.displayName = 'FactorHeatmap'

// 同时导出 named + default
const FactorHeatmapMemo = memo(FactorHeatmap)
FactorHeatmapMemo.displayName = 'FactorHeatmap'
export const FactorHeatmapChart = FactorHeatmapMemo
export { FactorHeatmapChart as FactorHeatmap }
export default FactorHeatmapMemo

