import type { NewsArticle } from '@/data/types'
import { Badge } from '@/components/ui/Badge'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { twBg } from '@/constants/theme.tokens'

export interface NewsCardProps {
  article: NewsArticle
  onClick?: () => void
}

const SENTIMENT_CONFIG: Record<
  NewsArticle['sentiment'],
  { label: string; variant: 'default' | 'secondary' | 'outline' | 'destructive'; className: string }
> = {
  positive: { label: '正面', variant: 'default', className: `${twBg('emerald', 500)} text-white hover:${twBg('emerald', 500)}/80` },
  negative: { label: '负面', variant: 'destructive', className: '' },
  neutral: { label: '中性', variant: 'secondary', className: `${twBg('slate', 500)} text-white hover:${twBg('slate', 500)}/80` },
}

export function NewsCard({ article, onClick }: NewsCardProps): React.JSX.Element {
  const sentiment = SENTIMENT_CONFIG[article.sentiment]
  const summary = article.content.length > 120 ? `${article.content.slice(0, 120)}...` : article.content

  return (
    <Card
      className="cursor-pointer transition-shadow hover:shadow-md"
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          onClick?.()
        }
      }}
    >
      <CardHeader className="pb-3">
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline">{article.category}</Badge>
          <Badge variant={sentiment.variant} className={sentiment.className}>
            {sentiment.label}
          </Badge>
        </div>
        <CardTitle className="text-base leading-snug hover:text-primary" onClick={onClick}>
          {article.title}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        <p className="text-sm text-muted-foreground overflow-hidden text-ellipsis" style={{ display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical' as const }}>{summary}</p>
        {article.relatedStocks.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {article.relatedStocks.map((symbol) => (
              <Badge key={symbol} variant="secondary" className="text-xs">
                {symbol}
              </Badge>
            ))}
          </div>
        )}
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <span>{article.source}</span>
          <span>{new Date(article.publishTime).toLocaleString('zh-CN')}</span>
        </div>
      </CardContent>
    </Card>
  )
}

/**
 * LLM 配置组件（可复用）
 *
 * 支持模型预设快速选择 + 自定义配置。
 * 可折叠，支持受控模式。
 * 显示模型信息（上下文窗口、价格）。
 *
 * 使用示例：
 *   <LLMConfigWidget
 *     value={llmConfig}
 *     onChange={setLlmConfig}
 *     configReady={configReady}
 *     className="..."
 *   />
 */

import { useState, useMemo, memo } from 'react'
import { LLM_MODEL_PRESETS, getPresetById, inferPresetId, DEFAULT_LLM_BASE_URL, type PartialLlmConfig } from '@/config/llmConfig'
import { Input } from '@/components/ui/Input'
import {
  isValidLlmBaseURL,
  isValidLlmApiKey,
  isValidLlmModel,
} from '@/utils/dataValidation'

interface Props {
  /** 当前 LLM 配置 */
  value: PartialLlmConfig
  /** 配置变更回调 */
  onChange: (config: PartialLlmConfig) => void
  /** 配置是否可用（baseURL + apiKey 非空） */
  configReady: boolean
  /** 是否显示配置不可用提示 */
  showWarning?: boolean
  /** 额外 className */
  className?: string
}

/** 校验单个字段并返回错误提示（无错返回空串） */
function validateField(field: 'baseURL' | 'apiKey' | 'model', value: string): string {
  const trimmed = value.trim()
  if (!trimmed) return '' // 非空校验由 configReady 负责
  switch (field) {
    case 'baseURL':
      return isValidLlmBaseURL(trimmed) ? '' : 'URL 格式非法，仅允许 http:// 或 https://'
    case 'apiKey':
      return isValidLlmApiKey(trimmed) ? '' : 'API Key 仅允许字母、数字、._-/，长度 8-256'
    case 'model':
      return isValidLlmModel(trimmed) ? '' : '模型名仅允许字母、数字、._-/:，长度 1-128'
    default:
      return ''
  }
}

export const LLMConfigWidget = memo(function LLMConfigWidget({
  value,
  onChange,
  configReady,
  showWarning = true,
  className,
}: Props): React.JSX.Element {
  const [expanded, setExpanded] = useState(false)

  // 根据 baseURL 推断当前预设
  const currentPresetId = inferPresetId(value.baseURL ?? '')

  // 获取当前预设及其模型信息
  const currentPreset = useMemo(() => getPresetById(currentPresetId), [currentPresetId])
  const modelOptions = currentPreset?.models ?? []

  // 输入校验错误信息（仅展示用户已输入字段的错误）
  const baseURLError = value.baseURL ? validateField('baseURL', value.baseURL) : ''
  const apiKeyError = value.apiKey ? validateField('apiKey', value.apiKey) : ''
  const modelError = value.model ? validateField('model', value.model) : ''

  // 格式化上下文窗口
  const contextStr = useMemo(() => {
    if (!currentPreset?.contextWindow) return null
    const w = currentPreset.contextWindow
    if (w >= 1_000_000) return `${(w / 1_000_000).toFixed(0)}M`
    if (w >= 1_000) return `${(w / 1_000).toFixed(0)}K`
    return String(w)
  }, [currentPreset])

  // 价格信息
  const priceInfo = useMemo(() => {
    if (!currentPreset?.inputPrice) return null
    return `${currentPreset.inputPrice}/${currentPreset.outputPrice}`
  }, [currentPreset])

  function handlePresetChange(presetId: string) {
    const preset = getPresetById(presetId)
    if (preset) {
      onChange({
        baseURL: preset.baseURL,
        model: preset.defaultModel,
        apiKey: '', // 需要用户填写
      })
    }
  }

  return (
    <div className={`space-y-2 ${className ?? ''}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <label className="text-sm font-medium">大模型配置</label>
          {/* 状态指示 */}
          {configReady && value.model && (
            <span className="inline-flex items-center rounded-full bg-primary/10 px-2 py-0.5 text-xs text-primary">
              {value.model}
            </span>
          )}
        </div>
        <button
          type="button"
          className="text-xs text-muted-foreground hover:text-foreground"
          onClick={() => setExpanded((prev) => !prev)}
        >
          {expanded ? '收起' : '展开'}
        </button>
      </div>

      {expanded && (
        <div className="space-y-3 rounded-md border p-3">
          {/* 预设选择 */}
          <div className="space-y-1">
            <label className="text-xs text-muted-foreground">模型预设</label>
            <select
              className="flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 text-sm"
              value={currentPresetId}
              onChange={(e) => handlePresetChange(e.target.value)}
            >
              {LLM_MODEL_PRESETS.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name}{p.provider ? ` (${p.provider})` : ''}
                </option>
              ))}
            </select>
          </div>

          {/* Base URL */}
          <div className="space-y-1">
            <label className="text-xs text-muted-foreground">Base URL</label>
            <Input
              placeholder={DEFAULT_LLM_BASE_URL}
              value={value.baseURL ?? ''}
              onChange={(e) => onChange({ ...value, baseURL: e.target.value })}
              aria-invalid={!!baseURLError}
            />
            {baseURLError && (
              <p className="text-xs text-destructive">{baseURLError}</p>
            )}
          </div>

          {/* API Key */}
          <div className="space-y-1">
            <label className="text-xs text-muted-foreground">API Key</label>
            <Input
              type="password"
              placeholder="sk-..."
              value={value.apiKey ?? ''}
              onChange={(e) => onChange({ ...value, apiKey: e.target.value })}
              aria-invalid={!!apiKeyError}
            />
            {apiKeyError && (
              <p className="text-xs text-destructive">{apiKeyError}</p>
            )}
          </div>

          {/* Model 选择 */}
          {modelOptions.length > 0 ? (
            <div className="space-y-1">
              <label className="text-xs text-muted-foreground">模型</label>
              <select
                className="flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 text-sm"
                value={modelOptions.includes(value.model ?? '') ? value.model : ''}
                onChange={(e) => onChange({ ...value, model: e.target.value })}
              >
                <option value="" disabled>
                  -- 请选择模型 --
                </option>
                {modelOptions.map((m) => (
                  <option key={m} value={m}>{m}</option>
                ))}
              </select>
              {/* 自定义模型输入（当选择了"请选择模型"或不在列表中时显示） */}
              {!modelOptions.includes(value.model ?? '') && (
                <Input
                  placeholder="或输入自定义模型 ID"
                  value={value.model ?? ''}
                  onChange={(e) => onChange({ ...value, model: e.target.value })}
                  aria-invalid={!!modelError}
                />
              )}
              {modelError && (
                <p className="text-xs text-destructive">{modelError}</p>
              )}
            </div>
          ) : (
            <div className="space-y-1">
              <label className="text-xs text-muted-foreground">模型</label>
              <Input
                placeholder="如 deepseek-v4-flash"
                value={value.model ?? ''}
                onChange={(e) => onChange({ ...value, model: e.target.value })}
                aria-invalid={!!modelError}
              />
              {modelError && (
                <p className="text-xs text-destructive">{modelError}</p>
              )}
            </div>
          )}

          {/* 模型信息摘要 */}
          {currentPreset && (
            <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground">
              {contextStr && <span>上下文: {contextStr} tokens</span>}
              {priceInfo && <span>价格: ${priceInfo} /M tokens</span>}
              <span>供应商: {currentPreset.provider}</span>
            </div>
          )}

          <p className="text-xs text-muted-foreground">
            支持 OpenAI 兼容接口（/v1/chat/completions）。推荐 DeepSeek V4 / Kimi K2.7 / 通义千问 Qwen3.6 / 硅基流动。
          </p>
        </div>
      )}

      {showWarning && !configReady && (
        <p className="text-xs text-destructive">LLM 未配置，请填写 Base URL 与 API Key</p>
      )}
    </div>
  )
})

import { twText } from '@/constants/theme.tokens'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import type { StrategySnapshot } from '@/data/types'

export interface ChangeLogPanelProps {
  snapshot: StrategySnapshot
}

export function ChangeLogPanel({ snapshot }: ChangeLogPanelProps): React.JSX.Element {
  const changeLog = snapshot.changeFromPrev

  if (!changeLog) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-base">变更记录</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground">无变更记录</p>
        </CardContent>
      </Card>
    )
  }

  const renderSymbolList = (title: string, symbols: string[], variant: 'default' | 'secondary' | 'outline' | 'destructive') => (
    <div className="space-y-1">
      <h4 className="text-sm font-medium">{title}</h4>
      {symbols.length === 0 ? (
        <p className="text-xs text-muted-foreground">无</p>
      ) : (
        <div className="flex flex-wrap gap-1">
          {symbols.map((symbol) => (
            <Badge key={symbol} variant={variant} className="text-xs">
              {symbol}
            </Badge>
          ))}
        </div>
      )}
    </div>
  )

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="text-base">变更记录</CardTitle>
          <Badge variant="outline">总计 {changeLog.totalChange > 0 ? `+${changeLog.totalChange}` : changeLog.totalChange}</Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {renderSymbolList('核心稀缺 - 新增', changeLog.coreChange.added, 'default')}
        {renderSymbolList('核心稀缺 - 移除', changeLog.coreChange.removed, 'destructive')}
        {renderSymbolList('热点动量 - 新增', changeLog.hotChange.added, 'default')}
        {renderSymbolList('热点动量 - 移除', changeLog.hotChange.removed, 'destructive')}
        {renderSymbolList('价值洼地 - 新增', changeLog.valueChange.added, 'default')}
        {renderSymbolList('价值洼地 - 移除', changeLog.valueChange.removed, 'destructive')}

        <div className="space-y-1">
          <h4 className="text-sm font-medium">评分变化</h4>
          {(changeLog.scoreChanges?.length ?? 0) === 0 ? (
            <p className="text-xs text-muted-foreground">无显著变化</p>
          ) : (
            <ul className="space-y-1">
              {changeLog.scoreChanges?.map((change) => (
                <li key={change.symbol} className="flex items-center justify-between text-sm">
                  <span>
                    {change.symbol} {change.name}
                  </span>
                  <span className={change.delta >= 0 ? twText('emerald', 600) : twText('red', 600)}>
                    {change.delta >= 0 ? '+' : ''}
                    {change.delta.toFixed(2)}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { cn } from '@/lib/utils'
import type { StrategyGroupItem } from '@/services/trading/strategySnapshotService'

export interface StrategyGroupCardProps {
  title: string
  items: StrategyGroupItem[]
  color: string
}

export function StrategyGroupCard({ title, items, color }: StrategyGroupCardProps): React.JSX.Element {
  const count = items.length
  const composites = items.map((item) => item.composite)
  const avgComposite = count > 0 ? Math.round((composites.reduce((a, b) => a + b, 0) / count) * 100) / 100 : 0
  const maxComposite = count > 0 ? Math.max(...composites) : 0

  return (
    <Card className="flex h-full flex-col">
      <CardHeader className="pb-3">
        <div className="flex items-center gap-2">
          <div className={cn('h-3 w-3 rounded-full', color)} data-testid="group-color-dot" />
          <CardTitle className="text-base">{title}</CardTitle>
          <Badge variant="secondary" className="ml-auto">
            {count} 只
          </Badge>
        </div>
        <div className="flex gap-4 text-sm text-muted-foreground">
          <span>均分 {avgComposite.toFixed(2)}</span>
          <span>最高 {maxComposite.toFixed(2)}</span>
        </div>
      </CardHeader>
      <CardContent className="flex-1 overflow-auto">
        {items.length === 0 ? (
          <p className="text-sm text-muted-foreground">暂无标的</p>
        ) : (
          <ul className="space-y-2">
            {items.map((item) => (
              <li
                key={item.symbol}
                className="rounded-md border p-2 text-sm"
                title={item.reasons[0] ?? ''}
              >
                <div className="flex items-center justify-between">
                  <span className="font-medium">
                    {item.symbol} {item.name}
                  </span>
                  <span className="text-muted-foreground">{item.composite.toFixed(2)}</span>
                </div>
                {item.reasons[0] && (
                  <p className="mt-1 line-clamp-2 text-xs text-muted-foreground">
                    {item.reasons[0]}
                  </p>
                )}
              </li>
            ))}
          </ul>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * @module EngineStatusCard
 * @description 引擎状态监控卡片。
 *   - 读取 engineStore（started / startedAt / stats / layerStatuses / healthSummary）
 *   - 读取 systemMonitorStore（refreshSnapshot / isLoading）
 *   - 展示引擎运行状态、DataFlow 连接、Agent 运行时统计与 V6 引擎层权重
 */

import React, { useEffect, useState, memo } from 'react'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Progress } from '@/components/ui/Progress'
import { useEngineStore } from '@/store/engineStore'
import { useSystemMonitorStore } from '@/store/systemMonitorStore'
import {
  HEALTH_STATUS,
  HEALTH_STATUS_MAP,
  V6_ENGINE_LAYERS,
  type HealthStatus,
} from '@/constants/health.constants'
import { COLOR_TOKENS } from '@/constants/theme.tokens'
import { getLogger } from '@/lib/logger'
import { cn } from '@/lib/utils'

const logger = getLogger()

// ============================================================
// 常量（零硬编码锚点）
// ============================================================

/** 本地运行时长刷新间隔（毫秒） */
const REFRESH_INTERVAL_MS = 1000
/** 顶部统计卡片网格列数 */
const STAT_GRID_COLS = 4
/** Agent 运行时统计网格列数 */
const AGENT_STAT_COLS = 4
/** 权重进度条最大值（百分比制） */
const WEIGHT_PROGRESS_MAX = 100
/** 毫秒与秒换算因子 */
const MS_PER_SECOND = 1000
/** 每分钟秒数 */
const SECONDS_PER_MINUTE = 60
/** 每小时秒数 */
const SECONDS_PER_HOUR = 3600

/** 统计卡片通用样式（边框/背景引用主题令牌，避免硬编码颜色类） */
const STAT_CARD_CLASS = cn(
  'rounded-lg border p-3',
  COLOR_TOKENS.border.tailwind,
  COLOR_TOKENS.bgSlate50.tailwind,
)

/** 网格列模板（基于常量动态生成，避免 Tailwind 动态类名失效） */
const STAT_GRID_STYLE: React.CSSProperties = {
  gridTemplateColumns: `repeat(${STAT_GRID_COLS}, minmax(0, 1fr))`,
}
const AGENT_GRID_STYLE: React.CSSProperties = {
  gridTemplateColumns: `repeat(${AGENT_STAT_COLS}, minmax(0, 1fr))`,
}

// ============================================================
// 纯函数工具
// ============================================================

/**
 * 将 healthSummary.overallStatus（小写）映射为 HEALTH_STATUS 常量（大写）
 * 以便复用 HEALTH_STATUS_MAP 的语义化颜色与标签
 */
function mapOverallStatus(status: string | undefined): HealthStatus {
  switch (status) {
    case 'healthy':
      return HEALTH_STATUS.HEALTHY
    case 'warning':
      return HEALTH_STATUS.WARNING
    case 'critical':
      return HEALTH_STATUS.CRITICAL
    case 'unknown':
      return HEALTH_STATUS.UNKNOWN
    default:
      return HEALTH_STATUS.UNKNOWN
  }
}

/** 将运行时长格式化为 "Xh Ym Zs" */
function formatUptime(started: boolean, startedAt: number, now: number): string {
  if (!started || !startedAt) return '0h 0m 0s'
  const totalSeconds = Math.max(0, Math.floor((now - startedAt) / MS_PER_SECOND))
  const hours = Math.floor(totalSeconds / SECONDS_PER_HOUR)
  const minutes = Math.floor((totalSeconds % SECONDS_PER_HOUR) / SECONDS_PER_MINUTE)
  const seconds = totalSeconds % SECONDS_PER_MINUTE
  return `${hours}h ${minutes}m ${seconds}s`
}

// ============================================================
// 组件
// ============================================================

function EngineStatusCard(): React.JSX.Element {
  const started = useEngineStore((s) => s.started)
  const startedAt = useEngineStore((s) => s.startedAt)
  const stats = useEngineStore((s) => s.stats)
  const layerStatuses = useEngineStore((s) => s.layerStatuses)
  const healthSummary = useEngineStore((s) => s.healthSummary)

  const refreshSnapshot = useSystemMonitorStore((s) => s.refreshSnapshot)
  const systemMonitorIsLoading = useSystemMonitorStore((s) => s.isLoading)

  // 本地时钟：每秒触发一次重绘以刷新运行时长
  const [now, setNow] = useState<number>(() => Date.now())

  // 挂载时拉取一次系统监控快照 + 启动本地运行时长定时器
  useEffect(() => {
    logger.info('[EngineStatusCard] mounted, refreshing system snapshot')
    void refreshSnapshot()

    const timer = setInterval(() => {
      setNow(Date.now())
    }, REFRESH_INTERVAL_MS)

    return () => {
      clearInterval(timer)
      logger.info('[EngineStatusCard] unmounted, timer cleared')
    }
  }, [refreshSnapshot])

  const overallStatus = mapOverallStatus(healthSummary?.overallStatus)
  const statusMeta = HEALTH_STATUS_MAP[overallStatus]
  const uptime = formatUptime(started, startedAt ?? 0, now)

  // 加载态：系统监控正在加载且尚无健康摘要数据时展示占位文本
  const showLoading = systemMonitorIsLoading && !healthSummary

  return (
    <Card>
      <CardHeader className="flex-row items-center justify-between space-y-0">
        <CardTitle className="text-base">引擎状态监控</CardTitle>
        <Badge
          variant="outline"
          className={cn('border-transparent font-semibold text-white', statusMeta.bgClass)}
        >
          {overallStatus}
        </Badge>
      </CardHeader>

      <CardContent className="space-y-4">
        {showLoading ? (
          <p className="text-sm text-muted-foreground">加载中...</p>
        ) : (
          <>
            {/* 顶部统计卡片 */}
            <div className="grid gap-3" style={STAT_GRID_STYLE}>
              {/* 引擎状态 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">引擎状态</p>
                <div className="mt-1 flex items-center gap-1.5">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{
                      backgroundColor: started
                        ? COLOR_TOKENS.success.hex
                        : COLOR_TOKENS.danger.hex,
                    }}
                  />
                  <span
                    className="text-sm font-medium"
                    style={{
                      color: started ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex,
                    }}
                  >
                    {started ? '运行中' : '已停止'}
                  </span>
                </div>
              </div>

              {/* 运行时长 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">运行时长</p>
                <p className="mt-1 text-sm font-medium tabular-nums">{uptime}</p>
              </div>

              {/* 数据流 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">数据流</p>
                <div className="mt-1">
                  <Badge variant={stats.dataflow.connected ? 'success' : 'outline'}>
                    {stats.dataflow.connected ? '已连接' : '未连接'}
                  </Badge>
                </div>
              </div>

              {/* 活跃通道 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">活跃通道</p>
                <p className="mt-1 text-sm font-medium tabular-nums">
                  {stats.dataflow.channels}
                </p>
              </div>
            </div>

            {/* 智能体运行时统计 */}
            <div>
              <p className="mb-2 text-xs font-medium text-muted-foreground">智能体运行时</p>
              <div className="grid gap-3" style={AGENT_GRID_STYLE}>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">智能体总数</p>
                  <p className="mt-1 text-sm font-medium tabular-nums">
                    {stats.agents.totalAgents}
                  </p>
                </div>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">运行中</p>
                  <p
                    className="mt-1 text-sm font-medium tabular-nums"
                    style={{ color: COLOR_TOKENS.info.hex }}
                  >
                    {stats.agents.runningTasks}
                  </p>
                </div>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">已完成</p>
                  <p
                    className="mt-1 text-sm font-medium tabular-nums"
                    style={{ color: COLOR_TOKENS.success.hex }}
                  >
                    {stats.agents.completedTasks}
                  </p>
                </div>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">失败</p>
                  <p
                    className="mt-1 text-sm font-medium tabular-nums"
                    style={
                      stats.agents.failedTasks > 0
                        ? { color: COLOR_TOKENS.danger.hex }
                        : undefined
                    }
                  >
                    {stats.agents.failedTasks}
                  </p>
                </div>
              </div>
            </div>

            {/* V6 引擎层 */}
            <div>
              <p className="mb-2 text-xs font-medium text-muted-foreground">
                V6 引擎层（共 {V6_ENGINE_LAYERS.length} 层）
              </p>
              <div className="space-y-2">
                {Object.values(layerStatuses).map((layer) => {
                  const weightPercent = layer.weight * WEIGHT_PROGRESS_MAX
                  const isActive = layer.executionCount > 0
                  return (
                    <div
                      key={layer.layerId}
                      className={cn('rounded-lg border p-3', COLOR_TOKENS.border.tailwind)}
                    >
                      <div className="mb-1.5 flex items-center justify-between gap-2">
                        <div className="min-w-0">
                          <p className="truncate text-sm font-medium">{layer.layerName}</p>
                          <p className="text-xs text-muted-foreground">ID: {layer.layerId}</p>
                        </div>
                        <div className="flex flex-shrink-0 items-center gap-1.5">
                          {layer.deterministic ? (
                            <Badge
                              variant="outline"
                              className={cn(
                                'border-transparent text-white',
                                COLOR_TOKENS.success.bgClass,
                              )}
                            >
                              确定性
                            </Badge>
                          ) : layer.llmEnhanceable ? (
                            <Badge
                              variant="outline"
                              className={cn(
                                'border-transparent text-white',
                                COLOR_TOKENS.purple.bgClass,
                              )}
                            >
                              大模型增强
                            </Badge>
                          ) : null}
                          <Badge variant={isActive ? 'success' : 'secondary'}>
                            {isActive ? '活跃' : '空闲'}
                          </Badge>
                        </div>
                      </div>
                      <Progress
                        value={weightPercent}
                        max={WEIGHT_PROGRESS_MAX}
                        showMax={false}
                        label={`权重 ${weightPercent.toFixed(0)}%`}
                      />
                    </div>
                  )
                })}
              </div>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  )
}

EngineStatusCard.displayName = 'EngineStatusCard'

export default memo(EngineStatusCard)

/**
 * @module LogStreamPanel
 * @description 实时监控日志流面板。
 *
 * 职责：
 *   - 订阅 MonitorLogService，实时展示 引擎/Agent/系统/DataFlow 日志
 *   - 按级别（info/warn/error/critical）与来源（engine/agent/system/dataflow）过滤
 *   - 支持暂停/恢复自动刷新、清空日志
 *   - 新日志到达时自动滚动到底部（暂停时保持当前视图）
 *
 * 遵循 AGENTS.md 契约：
 *   - 组件层仅依赖 store/services，不直接调用 dataLayer 或 db
 *   - 禁止使用 any
 *   - 核心分支含 logger.info
 *   - 所有 useEffect cleanup 显式声明
 */

import React, { useEffect, useRef, useState, memo } from 'react'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Button } from '@/components/ui/Button'
import {
  getMonitorLogService,
  type MonitorLogFilter,
  type MonitorLogLevel,
  type MonitorLogSource,
} from '@/services/system/monitorLogService'
import { useSystemMonitorStore } from '@/store/systemMonitorStore'
import { COLOR_TOKENS, twText, twBg } from '@/constants/theme.tokens'
import { MONITOR_INTERVALS } from '@/constants/health.constants'
import { getLogger } from '@/lib/logger'
import { cn } from '@/lib/utils'

// ============================================================
// 常量（零魔法数字）
// ============================================================

/** 日志列表最大高度（px） */
const MAX_HEIGHT_PX = 400
/** 默认最大日志条数 */
const DEFAULT_MAX_ENTRIES = 50
/** 时间戳补零长度（HH/MM/SS） */
const TIMESTAMP_PAD_START = 2
/** 毫秒补零长度（mmm） */
const MS_PAD_START = 3

// ============================================================
// 类型定义
// ============================================================

/** 级别过滤值（含 "全部"） */
type FilterLevel = MonitorLogLevel | 'all'
/** 来源过滤值（含 "全部"） */
type FilterSource = MonitorLogSource | 'all'

interface LogStreamPanelProps {
  /** 最大展示日志条数，默认 50 */
  maxEntries?: number
}

// ============================================================
// 显示映射
// ============================================================

/** 级别过滤器选项 */
const LEVEL_FILTER_OPTIONS: ReadonlyArray<{ value: FilterLevel; label: string }> = [
  { value: 'all', label: '全部' },
  { value: 'info', label: '信息' },
  { value: 'warn', label: '警告' },
  { value: 'error', label: '错误' },
  { value: 'critical', label: '严重' },
]

/** 来源过滤器选项 */
const SOURCE_FILTER_OPTIONS: ReadonlyArray<{ value: FilterSource; label: string }> = [
  { value: 'all', label: '全部' },
  { value: 'engine', label: '引擎' },
  { value: 'agent', label: '智能体' },
  { value: 'system', label: '系统' },
  { value: 'dataflow', label: '数据流' },
]

/** 日志级别显示映射 */
const LEVEL_DISPLAY: Record<
  MonitorLogLevel,
  { label: string; color: string; bgClass: string }
> = {
  info: { label: '信息', color: COLOR_TOKENS.info.hex, bgClass: `${twBg('blue', 100)} ${twText('blue', 700)}` },
  warn: { label: '警告', color: COLOR_TOKENS.warning.hex, bgClass: `${twBg('amber', 100)} ${twText('amber', 700)}` },
  error: { label: '错误', color: COLOR_TOKENS.danger.hex, bgClass: `${twBg('red', 100)} ${twText('red', 700)}` },
  critical: { label: '严重', color: COLOR_TOKENS.danger.hex, bgClass: `${twBg('red', 200)} ${twText('red', 800)} font-bold` },
}

/** 日志来源显示映射 */
const SOURCE_DISPLAY: Record<MonitorLogSource, { label: string; bgClass: string }> = {
  engine: { label: '引擎', bgClass: `${twBg('indigo', 100)} ${twText('indigo', 700)}` },
  agent: { label: '智能体', bgClass: `${twBg('purple', 100)} ${twText('purple', 700)}` },
  system: { label: '系统', bgClass: `${twBg('teal', 100)} ${twText('teal', 700)}` },
  dataflow: { label: '数据流', bgClass: `${twBg('cyan', 100)} ${twText('cyan', 700)}` },
}

const logger = getLogger()

// ============================================================
// 工具函数
// ============================================================

/**
 * 格式化时间戳为 HH:MM:SS.mmm
 * 使用 Date 方法（getHours/getMinutes/getSeconds/getMilliseconds）
 */
function formatTimestamp(timestamp: number): string {
  const date = new Date(timestamp)
  const hh = String(date.getHours()).padStart(TIMESTAMP_PAD_START, '0')
  const mm = String(date.getMinutes()).padStart(TIMESTAMP_PAD_START, '0')
  const ss = String(date.getSeconds()).padStart(TIMESTAMP_PAD_START, '0')
  const ms = String(date.getMilliseconds()).padStart(MS_PAD_START, '0')
  return `${hh}:${mm}:${ss}.${ms}`
}

// ============================================================
// 组件
// ============================================================

function LogStreamPanelBase({
  maxEntries = DEFAULT_MAX_ENTRIES,
}: LogStreamPanelProps): React.JSX.Element {
  const monitorLogs = useSystemMonitorStore((s) => s.monitorLogs)
  const fetchMonitorLogs = useSystemMonitorStore((s) => s.fetchMonitorLogs)
  const clearMonitorLogs = useSystemMonitorStore((s) => s.clearMonitorLogs)

  const [filterLevel, setFilterLevel] = useState<FilterLevel>('all')
  const [filterSource, setFilterSource] = useState<FilterSource>('all')
  const [isPaused, setIsPaused] = useState<boolean>(false)
  const logContainerRef = useRef<HTMLDivElement>(null)

  // 订阅 + 轮询：挂载时获取初始日志、订阅变更、启动轮询；暂停时停止轮询
  useEffect(() => {
    const fetchFilteredLogs = (): void => {
      const filter: MonitorLogFilter = {
        level: filterLevel === 'all' ? undefined : filterLevel,
        source: filterSource === 'all' ? undefined : filterSource,
        limit: maxEntries,
      }
      fetchMonitorLogs(filter)
    }

    // 获取初始日志
    fetchFilteredLogs()
    logger.info('[LogStreamPanel] initialized', {
      filterLevel,
      filterSource,
      maxEntries,
      isPaused,
    })

    // 订阅日志变更通知（仅用于触发刷新，数据通过 Store 获取）
    const service = getMonitorLogService()
    const unsubscribe = service.subscribe(() => {
      if (!isPaused) {
        fetchFilteredLogs()
      }
    })

    // 轮询定时器（暂停时不启动）
    let timer: ReturnType<typeof setInterval> | null = null
    if (!isPaused) {
      timer = setInterval(() => {
        fetchFilteredLogs()
      }, MONITOR_INTERVALS.LOG_STREAM)
    }

    // 清理：取消订阅并清除定时器
    return () => {
      unsubscribe()
      if (timer !== null) {
        clearInterval(timer)
      }
    }
  }, [filterLevel, filterSource, isPaused, maxEntries, fetchMonitorLogs])

  // 自动滚动到底部（暂停时保持当前视图）
  useEffect(() => {
    if (isPaused) return
    const container = logContainerRef.current
    if (container) {
      container.scrollTop = container.scrollHeight
    }
  }, [monitorLogs, isPaused])

  // 暂停/恢复切换
  const handleTogglePause = (): void => {
    setIsPaused((prev) => {
      logger.info('[LogStreamPanel] pause toggled', { next: !prev })
      return !prev
    })
  }

  // 清空日志
  const handleClear = (): void => {
    clearMonitorLogs()
    logger.info('[LogStreamPanel] clearLogs() triggered')
  }

  return (
    <Card className="w-full">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle>监控日志流</CardTitle>
          <Badge variant="secondary">{monitorLogs.length} 条</Badge>
        </div>

        <div className="mt-3 flex flex-wrap items-center gap-3">
          {/* 级别过滤 */}
          <div className="flex items-center gap-1.5">
            <span className="text-xs text-muted-foreground">级别</span>
            {LEVEL_FILTER_OPTIONS.map((opt) => (
              <Button
                key={opt.value}
                variant={filterLevel === opt.value ? 'primary' : 'outline'}
                size="sm"
                onClick={() => setFilterLevel(opt.value)}
              >
                {opt.label}
              </Button>
            ))}
          </div>

          {/* 来源过滤 */}
          <div className="flex items-center gap-1.5">
            <span className="text-xs text-muted-foreground">来源</span>
            {SOURCE_FILTER_OPTIONS.map((opt) => (
              <Button
                key={opt.value}
                variant={filterSource === opt.value ? 'primary' : 'outline'}
                size="sm"
                onClick={() => setFilterSource(opt.value)}
              >
                {opt.label}
              </Button>
            ))}
          </div>

          {/* 操作按钮 */}
          <div className="ml-auto flex items-center gap-2">
            <Button
              variant={isPaused ? 'success' : 'outline'}
              size="sm"
              onClick={handleTogglePause}
            >
              {isPaused ? '恢复' : '暂停'}
            </Button>
            <Button variant="ghost" size="sm" onClick={handleClear}>
              清空
            </Button>
          </div>
        </div>
      </CardHeader>

      <CardContent>
        <div
          ref={logContainerRef}
          className={`overflow-y-auto rounded-md border border-border ${twBg('slate', 50)}/50 p-2`}
          style={{ maxHeight: `${MAX_HEIGHT_PX}px` }}
        >
          {monitorLogs.length === 0 ? (
            <div className="flex h-32 items-center justify-center text-sm text-muted-foreground">
              暂无日志
            </div>
          ) : (
            <div className="space-y-1">
              {monitorLogs.map((entry) => {
                const levelMeta = LEVEL_DISPLAY[entry.level]
                const sourceMeta = SOURCE_DISPLAY[entry.source]
                return (
                  <div
                    key={entry.id}
                    className="flex items-start gap-2 rounded px-2 py-1 font-mono text-xs hover:bg-accent/40"
                  >
                    <span className="shrink-0 text-muted-foreground">
                      {formatTimestamp(entry.timestamp)}
                    </span>
                    <Badge
                      variant="default"
                      className={cn('shrink-0', levelMeta.bgClass)}
                    >
                      <span
                        className="inline-block h-1.5 w-1.5 rounded-full"
                        style={{ backgroundColor: levelMeta.color }}
                      />
                      {levelMeta.label}
                    </Badge>
                    <Badge
                      variant="default"
                      className={cn('shrink-0', sourceMeta.bgClass)}
                    >
                      {sourceMeta.label}
                    </Badge>
                    <span className={`break-all ${twText('slate', 700)}`}>{entry.message}</span>
                  </div>
                )
              })}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

const LogStreamPanel = memo(LogStreamPanelBase)
LogStreamPanel.displayName = 'LogStreamPanel'

export default LogStreamPanel

import React, { useCallback, useState } from 'react'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs'
import {
  parseV6Export,
  transformV6ToV9,
  importToV9,
  generateMigrationReport,
  runV6Migration,
  type V6ExportShape,
  type V9ImportShape,
  type MigrationReport,
} from '@/services/system/v6MigrationService'
import { exportAll } from '@/services/system/systemService'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

interface BackupSnapshot {
  data: Record<string, unknown[]>
  createdAt: number
  stores: number
  totalRecords: number
}

export default function MigrationPanel(): React.JSX.Element {
  const [rawJson, setRawJson] = useState<unknown>(null)
  const [v6Export, setV6Export] = useState<V6ExportShape | null>(null)
  const [transformed, setTransformed] = useState<V9ImportShape | null>(null)
  const [report, setReport] = useState<MigrationReport | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [overwrite, setOverwrite] = useState(false)
  const [activeTab, setActiveTab] = useState('upload')
  // 备份快照:覆盖式导入前自动备份,导入失败时可用于回滚
  const [backup, setBackup] = useState<BackupSnapshot | null>(null)
  const [rollbackStatus, setRollbackStatus] = useState<'idle' | 'rolling' | 'done' | 'failed'>('idle')

  const handleFile = useCallback((file: File) => {
    logger.info('[MigrationPanel] handleFile/start', {
      fileName: file.name,
      fileSize: file.size,
      fileType: file.type,
      timestamp: Date.now(),
    })
    setError('')
    setReport(null)
    const reader = new FileReader()
    reader.onload = (e) => {
      try {
        const raw = e.target?.result
        const text = typeof raw === 'string' ? raw : ''
        const parsed = JSON.parse(text)
        setRawJson(parsed)
        const v6 = parseV6Export(parsed)
        setV6Export(v6)
        const v9 = transformV6ToV9(v6)
        setTransformed(v9)
        setActiveTab('preview')
        logger.info('[MigrationPanel] 文件解析成功', {
          fileName: file.name,
          v6Stocks: v6.stocks?.length ?? 0,
          v6Orders: v6.orders?.length ?? 0,
          v9Stocks: v9.stocks.length,
          v9Scores: v9.v6Scores.length,
        })
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        setError(`解析失败：${message}`)
        setV6Export(null)
        setTransformed(null)
        logger.error('[MigrationPanel] 文件解析失败', {
          fileName: file.name,
          error: message,
          stack: err instanceof Error ? err.stack : undefined,
          timestamp: Date.now(),
        })
      }
    }
    reader.onerror = () => {
      setError('读取文件失败')
      logger.error('[MigrationPanel] 文件读取失败', {
        fileName: file.name,
        fileSize: file.size,
        error: 'FileReader.onerror triggered',
      })
    }
    reader.readAsText(file)
  }, [])

  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault()
      const file = e.dataTransfer.files[0]
      if (file) void handleFile(file)
    },
    [handleFile],
  )

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (file) void handleFile(file)
    },
    [handleFile],
  )

  const handleImport = useCallback(async () => {
    if (!transformed) return
    logger.info('[MigrationPanel] handleImport/start', {
      overwrite,
      hasTransformed: transformed !== null,
      stocksCount: transformed.stocks.length,
      timestamp: Date.now(),
    })

    // 覆盖式导入:必须先备份 + 二次确认,确保数据可回滚
    let backupSnapshot: BackupSnapshot | null = null
    if (overwrite) {
      logger.info('[MigrationPanel] overwrite=true,触发二次确认对话框')
      const confirmed = window.confirm(
        '⚠️ 警告:覆盖式导入将删除现有数据!\n\n' +
        '系统将在导入前自动备份当前数据。\n' +
        '如导入失败,可使用「回滚到备份」按钮恢复。\n\n' +
        '确定继续执行覆盖式导入?'
      )
      if (!confirmed) {
        logger.info('[MigrationPanel] 用户取消覆盖式导入')
        return
      }
      logger.info('[MigrationPanel] 用户确认覆盖式导入,开始备份')

      // 导入前备份当前数据
      try {
        logger.info('[MigrationPanel] exportAll/start')
        const backupResult = await exportAll()
        logger.info('[MigrationPanel] exportAll/response', {
          success: backupResult.success,
          hasData: !!backupResult.data,
          error: backupResult.error,
        })
        if (backupResult.success && backupResult.data) {
          const backupData = backupResult.data
          const stores = Object.keys(backupData)
          const totalRecords = stores.reduce(
            (sum, store) => sum + (backupData[store]?.length ?? 0),
            0,
          )
          backupSnapshot = {
            data: backupData,
            createdAt: Date.now(),
            stores: stores.length,
            totalRecords,
          }
          setBackup(backupSnapshot)
          logger.info('[MigrationPanel] 备份完成', {
            stores: stores.length,
            totalRecords,
            storeNames: stores,
          })
        } else {
          const backupError = backupResult.error ?? '未知错误'
          setError(`备份失败,已中止导入(防止数据丢失):${backupError}`)
          logger.error('[MigrationPanel] 备份失败,中止导入', {
            error: backupError,
            timestamp: Date.now(),
          })
          return
        }
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        setError(`备份异常,已中止导入:${message}`)
        logger.error('[MigrationPanel] 备份异常', {
          error: message,
          stack: err instanceof Error ? err.stack : undefined,
        })
        return
      }
    } else {
      logger.info('[MigrationPanel] overwrite=false,跳过备份直接导入')
    }

    setLoading(true)
    setError('')
    logger.info('[MigrationPanel] importToV9/start', {
      overwrite,
      stocksCount: transformed.stocks.length,
      hasBackup: backupSnapshot !== null,
    })
    try {
      const result = await importToV9(transformed, { overwriteExisting: overwrite })
      setReport(result)
      setActiveTab('report')
      logger.info('[MigrationPanel] 导入完成', {
        overwrite,
        importedRecords: result.summary.importedRecords,
        skippedRecords: result.summary.skippedRecords,
        failedRecords: result.summary.failedRecords,
        totalStores: result.summary.totalStores,
        backupCreated: backupSnapshot !== null,
        timestamp: Date.now(),
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      setError(`导入失败:${message}`)
      logger.error('[MigrationPanel] 导入失败', {
        error: message,
        stack: err instanceof Error ? err.stack : undefined,
        hasBackup: backupSnapshot !== null,
        overwrite,
        timestamp: Date.now(),
      })
    } finally {
      setLoading(false)
    }
  }, [transformed, overwrite])

  // 回滚:从备份恢复(下载备份文件 + 提示用户手动恢复)
  const handleDownloadBackup = useCallback(() => {
    if (!backup) return
    logger.info('[MigrationPanel] handleDownloadBackup/start', {
      stores: backup.stores,
      totalRecords: backup.totalRecords,
      createdAt: backup.createdAt,
    })
    const json = JSON.stringify(backup.data, null, 2)
    const blob = new Blob([json], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `v9-backup-${new Date(backup.createdAt).toISOString().replace(/[:.]/g, '-')}.json`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
    logger.info('[MigrationPanel] 备份已下载', {
      stores: backup.stores,
      totalRecords: backup.totalRecords,
      filename: a.download,
      blobSize: blob.size,
    })
  }, [backup])

  // 回滚:清空当前数据并提示用户重新上传备份(因 systemService 未提供 restoreFromBackup 接口)
  const handleRollback = useCallback(async () => {
    if (!backup) return
    logger.warn('[MigrationPanel] handleRollback/start', {
      backupCreatedAt: backup.createdAt,
      backupStores: backup.stores,
      backupTotalRecords: backup.totalRecords,
      timestamp: Date.now(),
    })
    setRollbackStatus('rolling')
    logger.info('[MigrationPanel] 触发备份下载以供手动恢复')
    // 触发备份下载
    handleDownloadBackup()
    setRollbackStatus('done')
    logger.info('[MigrationPanel] handleRollback/complete', {
      rollbackStatus: 'done',
      message: '已下载备份文件,等待用户手动恢复',
    })
    setError(
      `已下载备份文件(共 ${backup.stores} 个 store,${backup.totalRecords} 条记录)。\n` +
      '请使用「上传」功能导入此备份文件以恢复数据。\n' +
      '注意:恢复前请先在总控舱点击「重置数据」清空当前状态。'
    )
  }, [backup, handleDownloadBackup])

  const handleRunMigration = useCallback(async () => {
    if (!rawJson) return
    logger.info('[MigrationPanel] handleRunMigration/start', {
      hasRawJson: rawJson !== null,
      overwrite,
      timestamp: Date.now(),
    })
    setLoading(true)
    setError('')
    try {
      const result = await runV6Migration(rawJson, { overwriteExisting: overwrite })
      logger.info('[MigrationPanel] runV6Migration/response', {
        success: result.success,
        hasData: !!result.data,
        error: result.error,
      })
      if (result.success && result.data) {
        setReport(result.data)
        setActiveTab('report')
        logger.info('[MigrationPanel] 快速迁移完成', {
          overwrite,
          importedRecords: result.data.summary.importedRecords,
          skippedRecords: result.data.summary.skippedRecords,
          failedRecords: result.data.summary.failedRecords,
          totalStores: result.data.summary.totalStores,
          timestamp: Date.now(),
        })
      } else {
        const migrationError = result.error ?? '迁移失败'
        setError(migrationError)
        logger.warn('[MigrationPanel] 快速迁移失败响应', {
          error: migrationError,
          overwrite,
        })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      setError(`迁移失败：${message}`)
      logger.error('[MigrationPanel] 快速迁移异常', {
        error: message,
        stack: err instanceof Error ? err.stack : undefined,
        overwrite,
        timestamp: Date.now(),
      })
    } finally {
      setLoading(false)
    }
  }, [rawJson, overwrite])

  const v6Overview = v6Export
    ? [
        { key: 'stocks', label: '股票', count: v6Export.stocks?.length ?? 0 },
        { key: 'daily_quotes', label: '行情', count: v6Export.daily_quotes?.length ?? 0 },
        { key: 'v6_scores', label: 'V6评分', count: v6Export.v6_scores?.length ?? 0 },
        { key: 'orders', label: '订单', count: v6Export.orders?.length ?? 0 },
        { key: 'sector_scores', label: '板块评分', count: v6Export.sector_scores?.length ?? 0 },
        { key: 'rotation_scores', label: '轮动评分', count: v6Export.rotation_scores?.length ?? 0 },
        { key: 'score_docs', label: '评分文档', count: v6Export.score_docs?.length ?? 0 },
        { key: 'strategy_snapshots', label: '策略快照', count: v6Export.strategy_snapshots?.length ?? 0 },
        { key: 'local_docs', label: '本地文档', count: v6Export.local_docs?.length ?? 0 },
        { key: 'news', label: '资讯', count: v6Export.news?.length ?? 0 },
        { key: 'news_stock_map', label: '资讯关联', count: v6Export.news_stock_map?.length ?? 0 },
        { key: 'sentiment_cache', label: '情感缓存', count: v6Export.sentiment_cache?.length ?? 0 },
      ]
    : []

  const v9Overview = transformed
    ? [
        { key: 'stocks', label: '股票', count: transformed.stocks.length },
        { key: 'daily_quotes', label: '聚合行情', count: transformed.dailyQuotes.length },
        { key: 'v6_scores', label: 'V6评分', count: transformed.v6Scores.length },
        { key: 'score_docs', label: '评分文档', count: transformed.scoreDocs.length + transformed.scoreDocsFromScores.length },
        { key: 'orders', label: '订单', count: transformed.orders.length },
        { key: 'sector_scores', label: '板块评分', count: transformed.sectorScores.length },
        { key: 'rotation_scores', label: '轮动评分', count: transformed.rotationScores.length },
        { key: 'strategy_snapshots', label: '策略快照', count: transformed.strategySnapshots.length },
        { key: 'local_docs', label: '本地文档', count: transformed.localDocs.length },
        { key: 'news', label: '资讯', count: transformed.news.length },
        { key: 'news_stock_map', label: '资讯关联', count: transformed.newsStockMaps.length },
        { key: 'sentiment_cache', label: '情感缓存', count: transformed.sentimentCache.length },
      ]
    : []

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>V6 Pro → V9 数据迁移</CardTitle>
        <CardDescription>
          上传 V6 Pro 的 JSON 全量导出文件，预览并导入到 V9。
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList>
            <TabsTrigger value="upload">上传</TabsTrigger>
            <TabsTrigger value="preview" disabled={!transformed}>预览</TabsTrigger>
            <TabsTrigger value="report" disabled={!report}>报告</TabsTrigger>
          </TabsList>

          <TabsContent value="upload" className="space-y-4">
            <div
              onDrop={handleDrop}
              onDragOver={(e) => e.preventDefault()}
              className="rounded-lg border-2 border-dashed border-muted-foreground/25 p-8 text-center hover:border-muted-foreground/50"
            >
              <p className="text-sm text-muted-foreground">拖拽 JSON 文件到此处，或点击选择</p>
              <input
                type="file"
                accept="application/json"
                aria-label="上传 V6 导出 JSON"
                onChange={handleInputChange}
                className="mt-4 block w-full text-sm text-muted-foreground file:mr-4 file:rounded-md file:border-0 file:bg-secondary file:px-4 file:py-2 file:text-sm file:font-medium"
              />
            </div>
            {error && (
              <div className="rounded-md border border-destructive/50 bg-destructive/10 p-3 text-sm text-destructive">
                {error}
              </div>
            )}
          </TabsContent>

          <TabsContent value="preview" className="space-y-4">
            {transformed && (
              <>
                <div className="flex items-center gap-4">
                  <label className="flex items-center gap-2 text-sm">
                    <input
                      type="checkbox"
                      checked={overwrite}
                      onChange={(e) => setOverwrite(e.target.checked)}
                      className="h-4 w-4"
                    />
                    覆盖已存在数据
                  </label>
                </div>

                <div className="grid gap-4 md:grid-cols-2">
                  <div>
                    <h4 className="mb-2 text-sm font-medium">V6 源数据概览</h4>
                    <div className="grid grid-cols-2 gap-2">
                      {v6Overview.map((item) => (
                        <div key={item.key} className="rounded-md border p-2 text-center">
                          <p className="text-lg font-bold">{item.count}</p>
                          <Badge variant="outline">{item.label}</Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div>
                    <h4 className="mb-2 text-sm font-medium">V9 转换后概览</h4>
                    <div className="grid grid-cols-2 gap-2">
                      {v9Overview.map((item) => (
                        <div key={item.key} className="rounded-md border p-2 text-center">
                          <p className="text-lg font-bold">{item.count}</p>
                          <Badge variant="outline">{item.label}</Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="flex gap-2">
                  <Button onClick={handleImport} disabled={loading}>
                    {loading ? '导入中...' : '执行导入'}
                  </Button>
                  <Button variant="outline" onClick={handleRunMigration} disabled={loading}>
                    一键迁移（解析+导入）
                  </Button>
                </div>

                {/* 备份状态提示:覆盖式导入前已自动备份 */}
                {backup && (
                  <div className="rounded-md border border-success/40 bg-success/5 p-3 text-sm">
                    <p className="font-medium">已自动备份当前数据</p>
                    <p className="mt-1 text-muted-foreground">
                      备份时间:{new Date(backup.createdAt).toLocaleString('zh-CN')} ·
                      共 {backup.stores} 个存储区 / {backup.totalRecords} 条记录
                    </p>
                    <div className="mt-2 flex gap-2">
                      <Button variant="outline" size="sm" onClick={handleDownloadBackup}>
                        下载备份文件
                      </Button>
                    </div>
                  </div>
                )}
              </>
            )}
            {error && (
              <div className="space-y-2">
                <div className="rounded-md border border-destructive/50 bg-destructive/10 p-3 text-sm text-destructive whitespace-pre-line">
                  {error}
                </div>
                {/* 回滚按钮:导入失败且有备份时显示 */}
                {backup && rollbackStatus !== 'done' && (
                  <div className="flex gap-2">
                    <Button
                      variant="danger"
                      size="sm"
                      onClick={handleRollback}
                      disabled={rollbackStatus === 'rolling'}
                    >
                      {rollbackStatus === 'rolling' ? '回滚中...' : '回滚到备份'}
                    </Button>
                  </div>
                )}
              </div>
            )}
          </TabsContent>

          <TabsContent value="report" className="space-y-4">
            {report && (
              <>
                <div className="grid grid-cols-4 gap-2">
                  <div className="rounded-md border p-2 text-center">
                    <p className="text-lg font-bold">{report.summary.totalStores}</p>
                    <Badge variant="outline">存储区</Badge>
                  </div>
                  <div className="rounded-md border p-2 text-center">
                    <p className="text-lg font-bold">{report.summary.importedRecords}</p>
                    <Badge variant="outline">成功</Badge>
                  </div>
                  <div className="rounded-md border p-2 text-center">
                    <p className="text-lg font-bold">{report.summary.skippedRecords}</p>
                    <Badge variant="outline">跳过</Badge>
                  </div>
                  <div className="rounded-md border p-2 text-center">
                    <p className="text-lg font-bold">{report.summary.failedRecords}</p>
                    <Badge variant="outline">失败</Badge>
                  </div>
                </div>
                <pre className="max-h-96 overflow-auto rounded-md bg-muted p-4 text-xs">
                  {generateMigrationReport(report)}
                </pre>
                <Button variant="outline" onClick={() => { setRawJson(null); setV6Export(null); setTransformed(null); setReport(null); setActiveTab('upload') }}>
                  重新上传
                </Button>
              </>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

/**
 * @file Alert.tsx
 * @description 警告提示组件
 * @module components/ui/Alert
 *
 * 功能特性：
 * - 多种变体：default / destructive / success / warning / info
 * - 支持标题和描述
 * - 可选关闭按钮
 * - 完整的 ARIA 属性
 * - 适配 V9 样式系统
 *
 * @author V9 Component Library Team
 * @version V9
 */

import { type ReactNode, memo } from 'react'
import { cn } from '@/lib/utils'
import { getLogger } from '@/lib/logger'
import { THEME_TOKENS, COLOR_TOKENS, COLOR_SHADES } from '@/constants/theme.tokens'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

export type AlertVariant = 'default' | 'destructive' | 'success' | 'warning' | 'info'

export interface AlertProps extends React.HTMLAttributes<HTMLDivElement> {
  /** 变体样式 */
  variant?: AlertVariant
  /** 是否可关闭 */
  closable?: boolean
  /** 关闭回调 */
  onClose?: () => void
  /** 图标 */
  icon?: ReactNode
}

export type AlertTitleProps = React.HTMLAttributes<HTMLHeadingElement>

export type AlertDescriptionProps = React.HTMLAttributes<HTMLParagraphElement>

// ============================================================
// 变体样式配置（使用 Design Tokens）
// ============================================================

const VARIANT_STYLES: Record<AlertVariant, {
  container: string
  icon: string
}> = {
  default: {
    container: `${COLOR_TOKENS.bgMuted.tailwind}/50 ${COLOR_SHADES.slate[300]}/20`,
    icon: COLOR_TOKENS.textMuted.tailwind,
  },
  destructive: {
    container: `${COLOR_TOKENS.danger.bgClass}/10 ${COLOR_SHADES.red[300]}/30`,
    icon: COLOR_TOKENS.danger.tailwind,
  },
  success: {
    container: `${COLOR_TOKENS.success.bgClass}/10 ${COLOR_SHADES.green[300]}/30`,
    icon: COLOR_TOKENS.success.tailwind,
  },
  warning: {
    container: `${COLOR_TOKENS.warning.bgClass}/10 ${COLOR_SHADES.amber[300]}/30`,
    icon: COLOR_TOKENS.warning.tailwind,
  },
  info: {
    container: `${COLOR_TOKENS.info.bgClass}/10 ${COLOR_SHADES.blue[300]}/30`,
    icon: COLOR_TOKENS.info.tailwind,
  },
}

// ============================================================
// 默认图标（使用 Design Tokens）
// ============================================================

const DefaultIcons: Record<AlertVariant, ReactNode> = {
  default: (
    <svg className={THEME_TOKENS.iconSizes.md} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10" />
      <line x1="12" y1="16" x2="12" y2="12" />
      <line x1="12" y1="8" x2="12.01" y2="8" />
    </svg>
  ),
  destructive: (
    <svg className={THEME_TOKENS.iconSizes.md} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10" />
      <line x1="15" y1="9" x2="9" y2="15" />
      <line x1="9" y1="9" x2="15" y2="15" />
    </svg>
  ),
  success: (
    <svg className={THEME_TOKENS.iconSizes.md} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
      <polyline points="22 4 12 14.01 9 11.01" />
    </svg>
  ),
  warning: (
    <svg className={THEME_TOKENS.iconSizes.md} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z" />
      <line x1="12" y1="9" x2="12" y2="13" />
      <line x1="12" y1="17" x2="12.01" y2="17" />
    </svg>
  ),
