import { forwardRef, memo, useCallback, useMemo } from 'react'
import { cn } from '@/lib/utils'

function toDateString(value: string | Date | undefined): string {
  if (!value) return ''
  if (value instanceof Date) {
    const year = value.getFullYear()
    const month = String(value.getMonth() + 1).padStart(2, '0')
    const day = String(value.getDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
  }
  return value
}

export interface DatePickerProps {
  value?: string | Date
  onChange?: (value: string) => void
  min?: string | Date
  max?: string | Date
  placeholder?: string
  disabled?: boolean
  className?: string
}

export const DatePicker = memo(forwardRef<HTMLInputElement, DatePickerProps>(
  ({ value, onChange, min, max, placeholder, disabled, className }, ref) => {
    const dateValue = useMemo(() => toDateString(value), [value])
    const minDate = useMemo(() => toDateString(min), [min])
    const maxDate = useMemo(() => toDateString(max), [max])

    const handleChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        onChange?.(e.target.value)
      },
      [onChange],
    )

    return (
      <input
        ref={ref}
        type="date"
        value={dateValue}
        onChange={handleChange}
        min={minDate || undefined}
        max={maxDate || undefined}
        placeholder={placeholder}
        disabled={disabled}
        className={cn(
          'flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background',
          'file:border-0 file:bg-transparent file:text-sm file:font-medium',
          'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
          'disabled:cursor-not-allowed disabled:opacity-50',
          className,
        )}
      />
    )
  },
))
DatePicker.displayName = 'DatePicker'

import { type ButtonHTMLAttributes, type DialogHTMLAttributes, forwardRef, useEffect, useRef } from 'react'
import { cn } from '@/lib/utils'
import { X } from 'lucide-react'

export interface DialogProps extends DialogHTMLAttributes<HTMLDialogElement> {
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

export const Dialog = forwardRef<HTMLDialogElement, DialogProps>(
  ({ className, open, onOpenChange, children, ...props }, ref) => {
    const internalRef = useRef<HTMLDialogElement>(null)
    const dialogRef = (ref as React.RefObject<HTMLDialogElement>) || internalRef

    useEffect(() => {
      const dialog = dialogRef.current
      if (!dialog) return
      if (open && !dialog.open) {
        dialog.showModal()
      } else if (!open && dialog.open) {
        dialog.close()
      }
    }, [open, dialogRef])

    useEffect(() => {
      const dialog = dialogRef.current
      if (!dialog) return
      const handleClose = () => onOpenChange?.(false)
      dialog.addEventListener('close', handleClose)
      return () => dialog.removeEventListener('close', handleClose)
    }, [onOpenChange, dialogRef])

    return (
      <dialog
        ref={dialogRef}
        className={cn(
          'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
          'm-0 max-h-[85vh] w-full max-w-lg rounded-lg border bg-background p-0 shadow-lg backdrop:bg-black/50',
          'open:animate-in open:fade-in-0 open:zoom-in-95',
          className,
        )}
        {...props}
      >
        {children}
      </dialog>
    )
  },
)
Dialog.displayName = 'Dialog'

