export const ErrorState = memo(function ErrorState({
  error,
  onRetry,
  variant = 'card',
  title,
  showErrorDetail = false,
  errorCode,
  className,
}: ErrorStateProps) {
  const errorInfo = getErrorInfo(error, errorCode)

  // 使用 useCallback 包装 onRetry，避免不必要的重渲染
