      )}
      {variant === 'card' && (
        <ErrorCard
          error={error}
          errorInfo={errorInfo}
          title={title}
          onRetry={onRetry ? handleRetry : undefined}
          showErrorDetail={showErrorDetail}
        />
      )}
      {variant === 'fullscreen' && (
        <ErrorFullscreen
          error={error}
          errorInfo={errorInfo}
          title={title}
          onRetry={onRetry ? handleRetry : undefined}
          showErrorDetail={showErrorDetail}
        />
      )}
