/**
 * LoadingState 组件 - 全局加载状态展示
 *
 * 支持三种展示模式：
 * - skeleton: 骨架屏模式，适合内容加载
 * - spinner: 旋转图标模式，适合快速加载
 * - progress: 进度条模式，适合文件上传/下载等场景
 *
 * @module components/ui/LoadingState
 */

import { memo } from 'react'
import { Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'

// ============================================================
// Props 定义
// ============================================================

export interface LoadingStateProps {
  /** 展示模式 */
  variant?: 'skeleton' | 'spinner' | 'progress'
  /** 骨架屏行数（仅 skeleton 模式） */
  rows?: number
  /** 骨架屏高度（仅 skeleton 模式） */
  height?: number
  /** 加载文案 */
  message?: string
  /** 进度百分比 0-100（仅 progress 模式） */
  progress?: number
  /** 自定义图标（仅 spinner 模式） */
  icon?: React.ReactNode
  /** 额外 className */
  className?: string
}

// ============================================================
// 骨架屏行组件
// ============================================================

interface SkeletonRowProps {
  height?: number
  isLast?: boolean
}

function SkeletonRow({ height = 16, isLast = false }: SkeletonRowProps) {
  return (
    <div
      className={cn(
        'h-4 rounded bg-muted animate-pulse',
        !isLast && 'mb-3'
      )}
      style={{ width: isLast ? '60%' : '100%', height }}
    />
  )
}

// ============================================================
// Skeleton 模式
// ============================================================

interface LoadingSkeletonProps {
  rows?: number
  height?: number
  message?: string
  className?: string
}

function LoadingSkeleton({ rows = 5, height, message, className }: LoadingSkeletonProps) {
  return (
    <div className={cn('space-y-4 p-6', className)}>
      {message && (
        <p className="text-sm text-muted-foreground text-center">{message}</p>
      )}
      <div className="space-y-2">
        {Array.from({ length: rows }).map((_, i) => (
          <SkeletonRow
            key={i}
            height={height}
            isLast={i === rows - 1}
          />
        ))}
      </div>
    </div>
  )
}

// ============================================================
// Spinner 模式
// ============================================================

interface LoadingSpinnerProps {
  message?: string
  icon?: React.ReactNode
  className?: string
}

function LoadingSpinner({ message, icon }: LoadingSpinnerProps) {
  return (
    <div className="flex flex-col items-center justify-center gap-4 p-8">
      {icon ?? (
        <Loader2 className="h-10 w-10 text-muted-foreground animate-spin" />
      )}
      {message && (
        <p className="text-sm text-muted-foreground">{message}</p>
      )}
    </div>
  )
}

// ============================================================
// Progress 模式
// ============================================================

interface LoadingProgressProps {
  progress?: number
  message?: string
  className?: string
}

function LoadingProgress({ progress = 0, message, className }: LoadingProgressProps) {
  const clampedProgress = Math.min(100, Math.max(0, progress))

  return (
    <div className={cn('space-y-3 p-6', className)}>
      {message && (
        <div className="flex justify-between items-center text-sm">
          <span className="text-muted-foreground">{message}</span>
          <span className="font-medium">{clampedProgress}%</span>
        </div>
      )}
      <div className="w-full h-2 bg-muted rounded-full overflow-hidden">
        <div
          className="h-full bg-primary transition-all duration-300 ease-out rounded-full"
          style={{ width: `${clampedProgress}%` }}
        />
      </div>
    </div>
  )
}

// ============================================================
// 主组件
// ============================================================

export const LoadingState = memo(function LoadingState({
  variant = 'spinner',
  rows = 5,
  height,
  message,
  progress,
  icon,
  className,
}: LoadingStateProps) {
  return (
    <div className={cn('w-full', className)}>
      {variant === 'skeleton' && (
        <LoadingSkeleton rows={rows} height={height} message={message} className={className} />
      )}
      {variant === 'spinner' && (
        <LoadingSpinner message={message} icon={icon} />
      )}
      {variant === 'progress' && (
        <LoadingProgress progress={progress} message={message} />
      )}
    </div>
  )
})

export default LoadingState

import { createContext, forwardRef, memo, useContext, useMemo, useState, type HTMLAttributes, type LiHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'
import { ChevronDown } from 'lucide-react'

interface MenuContextValue {
  selectedKeys: string[]
  mode: 'horizontal' | 'vertical'
  onSelect: (key: string) => void
}

const MenuContext = createContext<MenuContextValue | null>(null)

function useMenu() {
  const ctx = useContext(MenuContext)
  if (!ctx) throw new Error('Menu components must be used within <Menu>')
  return ctx
}

export interface MenuProps extends Omit<HTMLAttributes<HTMLUListElement>, 'onSelect'> {
  selectedKeys?: string[]
  defaultSelectedKeys?: string[]
  mode?: 'horizontal' | 'vertical'
  onSelect?: (key: string) => void
}

export const Menu = memo(forwardRef<HTMLUListElement, MenuProps>(
  ({ selectedKeys, defaultSelectedKeys, mode = 'vertical', onSelect, className, children, ...props }, ref) => {
    const [internalKeys, setInternalKeys] = useState<string[]>(defaultSelectedKeys ?? [])
    const isControlled = selectedKeys !== undefined
    const activeKeys = isControlled ? selectedKeys : internalKeys

    const context = useMemo<MenuContextValue>(
      () => ({
        selectedKeys: activeKeys,
        mode,
        onSelect: (key: string) => {
          onSelect?.(key)
          if (!isControlled) setInternalKeys([key])
        },
      }),
      [activeKeys, mode, onSelect, isControlled],
    )

    return (
      <MenuContext.Provider value={context}>
        <ul
          ref={ref}
          role="menu"
          className={cn(
            'flex list-none p-0 m-0',
            mode === 'horizontal' ? 'flex-row items-center gap-1' : 'flex-col gap-1',
            className,
          )}
          {...props}
        >
          {children}
        </ul>
      </MenuContext.Provider>
    )
  },
))
Menu.displayName = 'Menu'

export interface MenuItemProps extends LiHTMLAttributes<HTMLLIElement> {
  key: string
  icon?: React.ReactNode
  disabled?: boolean
  onClick?: React.MouseEventHandler<HTMLLIElement>
}

export const MenuItem = memo(forwardRef<HTMLLIElement, MenuItemProps>(
  ({ className, icon, disabled, children, onClick, key: itemKey, ...props }, ref) => {
    const { selectedKeys, onSelect } = useMenu()
    const isSelected = selectedKeys.includes(itemKey)

    const handleClick = (e: React.MouseEvent<HTMLLIElement>) => {
      if (disabled) return
      onClick?.(e)
      onSelect(itemKey)
    }

    return (
      <li
        ref={ref}
        role="menuitem"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled}
        onClick={handleClick}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            handleClick(e as never)
          }
        }}
        className={cn(
          'flex cursor-pointer select-none items-center gap-2 rounded-md px-3 py-2 text-sm outline-none transition-colors',
          'hover:bg-accent hover:text-accent-foreground',
          'focus-visible:bg-accent focus-visible:text-accent-foreground',
          isSelected && 'bg-accent text-accent-foreground',
          disabled && 'pointer-events-none opacity-50',
          className,
        )}
        {...props}
      >
        {icon && <span className="flex h-4 w-4 items-center justify-center">{icon}</span>}
        {children}
      </li>
    )
  },
))
MenuItem.displayName = 'MenuItem'

export interface SubMenuProps {
  key: string
  title: React.ReactNode
  icon?: React.ReactNode
  disabled?: boolean
  children?: React.ReactNode
  className?: string
}

export const SubMenu = memo(forwardRef<HTMLLIElement, SubMenuProps>(
  ({ className, title, icon, disabled, children }, ref) => {
    const [open, setOpen] = useState(false)
    const { mode } = useMenu()

    const isHorizontal = mode === 'horizontal'

    return (
      <li
        ref={ref}
        role="menuitem"
        className={cn('relative', className)}
        onMouseEnter={() => isHorizontal && !disabled && setOpen(true)}
        onMouseLeave={() => isHorizontal && !disabled && setOpen(false)}
      >
        <button
          type="button"
          disabled={disabled}
          onClick={() => !isHorizontal && !disabled && setOpen(!open)}
          className={cn(
            'flex w-full cursor-pointer select-none items-center gap-2 rounded-md px-3 py-2 text-sm outline-none transition-colors',
            'hover:bg-accent hover:text-accent-foreground',
            'focus-visible:bg-accent focus-visible:text-accent-foreground',
            disabled && 'pointer-events-none opacity-50',
          )}
          aria-expanded={open}
        >
          {icon && <span className="flex h-4 w-4 items-center justify-center">{icon}</span>}
          <span className="flex-1 text-left">{title}</span>
          <ChevronDown
            className={cn(
              'h-4 w-4 transition-transform duration-200',
              open && 'rotate-180',
            )}
          />
        </button>
        {open && (
          <ul
            role="menu"
            className={cn(
              'min-w-[8rem] overflow-hidden rounded-md border bg-popover p-1 text-popover-foreground shadow-md',
              isHorizontal ? 'absolute left-0 top-full z-50 mt-1' : 'ml-4 mt-1',
            )}
          >
            {children}
          </ul>
        )}
      </li>
    )
  },
))
SubMenu.displayName = 'SubMenu'

import { forwardRef, memo, useCallback, useMemo } from 'react'
import { cn } from '@/lib/utils'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export interface PaginationProps {
  total: number
  pageSize?: number
  current?: number
  onChange?: (page: number) => void
  className?: string
}

function generatePages(current: number, totalPages: number): (number | 'ellipsis-start' | 'ellipsis-end')[] {
  if (totalPages <= 7) {
    return Array.from({ length: totalPages }, (_, i) => i + 1)
  }

  const pages: (number | 'ellipsis-start' | 'ellipsis-end')[] = []

  pages.push(1)

  if (current <= 3) {
    for (let i = 2; i <= 5; i++) pages.push(i)
    pages.push('ellipsis-end')
  } else if (current >= totalPages - 2) {
    pages.push('ellipsis-start')
    for (let i = totalPages - 4; i < totalPages; i++) pages.push(i)
  } else {
    pages.push('ellipsis-start')
    pages.push(current - 1, current, current + 1)
    pages.push('ellipsis-end')
  }

  pages.push(totalPages)

  return pages
}

export const Pagination = memo(forwardRef<HTMLDivElement, PaginationProps>(
  ({ total, pageSize = 10, current = 1, onChange, className }, ref) => {
    const totalPages = useMemo(() => Math.max(1, Math.ceil(total / pageSize)), [total, pageSize])

    const safeCurrent = useMemo(() => {
      if (current < 1) return 1
      if (current > totalPages) return totalPages
      return current
    }, [current, totalPages])

    const pages = useMemo(() => generatePages(safeCurrent, totalPages), [safeCurrent, totalPages])

    const handlePageChange = useCallback(
      (page: number) => {
        if (page < 1 || page > totalPages || page === safeCurrent) return
        onChange?.(page)
      },
      [totalPages, safeCurrent, onChange],
    )

    if (total === 0) return null

    return (
      <nav ref={ref} role="navigation" aria-label="pagination" className={cn('flex items-center gap-1', className)}>
        <button
          type="button"
          disabled={safeCurrent <= 1}
          onClick={() => handlePageChange(safeCurrent - 1)}
          className={cn(
            'inline-flex h-9 w-9 items-center justify-center rounded-md text-sm',
            'hover:bg-accent hover:text-accent-foreground',
            'disabled:pointer-events-none disabled:opacity-50',
          )}
          aria-label="上一页"
        >
          <ChevronLeft className="h-4 w-4" />
        </button>

        {pages.map((page, index) => {
          if (page === 'ellipsis-start' || page === 'ellipsis-end') {
            return (
              <span
                key={`ellipsis-${index}`}
                className="flex h-9 w-9 items-center justify-center text-sm text-muted-foreground"
                aria-hidden="true"
              >
                ...
              </span>
            )
          }

          const isActive = page === safeCurrent
          return (
            <button
              key={page}
              type="button"
              disabled={isActive}
              onClick={() => handlePageChange(page)}
              className={cn(
                'inline-flex h-9 w-9 items-center justify-center rounded-md text-sm',
                'hover:bg-accent hover:text-accent-foreground',
                isActive && 'bg-primary text-primary-foreground hover:bg-primary/90',
                'disabled:pointer-events-none',
              )}
              aria-current={isActive ? 'page' : undefined}
              aria-label={`第 ${page} 页`}
            >
              {page}
            </button>
          )
        })}

        <button
          type="button"
          disabled={safeCurrent >= totalPages}
          onClick={() => handlePageChange(safeCurrent + 1)}
          className={cn(
            'inline-flex h-9 w-9 items-center justify-center rounded-md text-sm',
            'hover:bg-accent hover:text-accent-foreground',
            'disabled:pointer-events-none disabled:opacity-50',
          )}
          aria-label="下一页"
        >
          <ChevronRight className="h-4 w-4" />
        </button>

        <span className="ml-2 text-sm text-muted-foreground">
          共 {total} 条
        </span>
      </nav>
    )
  },
))
Pagination.displayName = 'Pagination'

import { type HTMLAttributes, type ReactNode, forwardRef, memo, useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

export type PopoverPlacement = 'top' | 'bottom' | 'left' | 'right'
export type PopoverTrigger = 'click' | 'hover' | 'focus'

export interface PopoverProps extends Omit<HTMLAttributes<HTMLDivElement>, 'content'> {
  /** 触发方式 */
  trigger?: PopoverTrigger
  /** 浮层内容 */
  content: ReactNode
  /** 浮层位置 */
  placement?: PopoverPlacement
  /** 触发元素 */
  children: ReactNode
  /** 是否默刻显示 */
  defaultOpen?: boolean
}

const placementClasses: Record<PopoverPlacement, string> = {
  top: 'bottom-full mb-2 left-1/2 -translate-x-1/2',
  bottom: 'top-full mt-2 left-1/2 -translate-x-1/2',
  left: 'right-full mr-2 top-1/2 -translate-y-1/2',
  right: 'left-full ml-2 top-1/2 -translate-y-1/2',
}

export const Popover = memo(forwardRef<HTMLDivElement, PopoverProps>(
  ({
    className,
    trigger = 'click',
    content,
    placement = 'bottom',
    children,
    defaultOpen = false,
    ...props
  }, ref) => {
    const [isOpen, setIsOpen] = useState(defaultOpen)
    const popoverRef = useRef<HTMLDivElement>(null)
    const triggerRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
      if (!isOpen) return

      const handleClickOutside = (event: MouseEvent) => {
        if (
          popoverRef.current &&
          !popoverRef.current.contains(event.target as Node) &&
          !triggerRef.current?.contains(event.target as Node)
        ) {
          setIsOpen(false)
        }
      }

      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }, [isOpen])

    const handleTrigger = () => {
      setIsOpen((prev) => !prev)
    }

    const handleMouseEnter = () => {
      if (trigger === 'hover') setIsOpen(true)
    }

    const handleMouseLeave = () => {
      if (trigger === 'hover') setIsOpen(false)
    }

    const handleFocus = () => {
      if (trigger === 'focus') setIsOpen(true)
    }

    const handleBlur = () => {
      if (trigger === 'focus') setIsOpen(false)
    }

    return (
      <div
        ref={ref}
        className={cn('relative inline-block', className)}
        {...props}
      >
        <div
          ref={triggerRef}
          onClick={trigger === 'click' ? handleTrigger : undefined}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          onFocus={handleFocus}
          onBlur={handleBlur}
        >
          {children}
        </div>
        {isOpen && (
          <div
            ref={popoverRef}
            className={cn(
              'absolute z-50 min-w-[200px] rounded-md border bg-popover p-4 text-popover-foreground shadow-md',
              'animate-in fade-in-0 zoom-in-95',
              placementClasses[placement],
            )}
            style={{ transformOrigin: 'center' }}
          >
            {content}
          </div>
        )}
      </div>
    )
  },
))

Popover.displayName = 'Popover'

