  summary: string
}

/** 全部外部 API 配置健康报告 */
export interface ApiHealthReport {
  /** 检查时间（ISO 8601） */
  checkedAt: string
  /** 各供应商健康状态 */
  providers: ApiConfigHealthStatus[]
  /** 已配置（完整）的供应商数量 */
  configuredCount: number
  /** 供应商总数 */
  totalCount: number
  /** 是否全部就绪 */
  allConfigured: boolean
}

/**
 * 获取所有外部 API 供应商的配置健康状态。
 *
 * **设计原则**：
 * - 仅检查配置完整性（baseURL、apiKey、timeout 等是否设置），不发起网络请求
 * - 覆盖 4 个外部 API：AkShare（fetcher）、REST Collector、WebSocket Collector、LLM
 * - 返回结构化报告，方便前端展示或日志记录
 */
export function getApiHealthStatus(): ApiHealthReport {
  const providers: ApiConfigHealthStatus[] = []

  // 1. AkShare 数据采集服务
  const akshareConfig = getDefaultFetcherServiceConfig()
  const akshareChecks = [
    {
      field: 'baseURL',
      value: akshareConfig.baseURL,
      ok: !!akshareConfig.baseURL && akshareConfig.baseURL !== 'http://localhost:8000',
      hint: 'VITE_AKSHARE_BASE_URL — 应指向远程 AkShare 服务（非 localhost）',
    },
    {
      field: 'timeoutMs',
      value: String(akshareConfig.timeoutMs),
      ok: akshareConfig.timeoutMs > 0,
      hint: '请求超时时间（ms），默认 30000',
    },
    {
      field: 'retries',
      value: String(akshareConfig.retries),
      ok: akshareConfig.retries >= 0,
      hint: '失败重试次数，默认 3',
    },
  ]
  providers.push({
    id: 'akshare',
    name: 'AkShare 数据采集',
    configured: akshareChecks.every(c => c.ok),
    checks: akshareChecks,
    summary: akshareChecks.every(c => c.ok)
      ? 'AkShare 服务配置完整'
      : 'AkShare 服务配置不完整，baseURL 仍指向 localhost 或未设置',
  })

  // 2. REST Collector（行情 REST API）
  const restBaseUrl = import.meta.env.VITE_API_BASE_URL || '/api'
  const restChecks = [
    {
      field: 'baseURL',
      value: restBaseUrl,
      ok: !!restBaseUrl && restBaseUrl !== '/api',
      hint: 'VITE_API_BASE_URL — REST 行情数据服务地址',
    },
  ]
  providers.push({
    id: 'rest_collector',
    name: 'REST 行情采集',
    configured: restChecks.every(c => c.ok),
    checks: restChecks,
    summary: restChecks.every(c => c.ok)
      ? 'REST 行情服务配置完整'
      : 'REST 行情服务使用默认 /api（可能为 mock 模式）',
  })

  // 3. WebSocket Collector（实时行情推送）
  const wsUrl = import.meta.env.VITE_WS_URL || 'ws://localhost:8080/ws'
  const wsChecks = [
    {
      field: 'wsUrl',
      value: wsUrl,
      ok: !!wsUrl && !wsUrl.includes('localhost'),
      hint: 'VITE_WS_URL — WebSocket 实时行情推送地址',
    },
  ]
  providers.push({
    id: 'websocket_collector',
    name: 'WebSocket 实时行情',
    configured: wsChecks.every(c => c.ok),
    checks: wsChecks,
    summary: wsChecks.every(c => c.ok)
      ? 'WebSocket 实时行情服务配置完整'
      : 'WebSocket 服务仍指向 localhost 或未配置',
  })

  // 4. LLM 大模型服务
  // P0-01 安全修复：API Key 从加密 localStorage 读取，不再从 VITE_ 环境变量读取
  const llmBaseUrl = import.meta.env.VITE_LLM_BASE_URL ?? ''
  const llmModel = import.meta.env.VITE_LLM_MODEL ?? 'deepseek-chat'
  const llmApiKeyConfigured = isLlmApiKeyConfigured()
  const llmChecks = [
    {
      field: 'baseURL',
      value: llmBaseUrl,
      ok: !!llmBaseUrl,
      hint: 'VITE_LLM_BASE_URL — LLM 服务地址',
    },
    {
      field: 'apiKey',
      value: llmApiKeyConfigured ? '已配置（加密存储）' : '(未配置)',
      ok: llmApiKeyConfigured,
      hint: 'API Key 通过 UI 配置页加密存储于 localStorage，不再使用环境变量',
    },
    {
      field: 'model',
      value: llmModel,
      ok: !!llmModel,
      hint: 'VITE_LLM_MODEL — 模型名称，默认 deepseek-chat',
    },
  ]
  providers.push({
    id: 'llm',
    name: 'LLM 大模型',
    configured: llmChecks.every(c => c.ok),
    checks: llmChecks,
    summary: llmChecks.every(c => c.ok)
      ? 'LLM 服务配置完整'
      : 'LLM 服务配置不完整，缺少 baseURL 或 apiKey',
  })

  const configuredCount = providers.filter(p => p.configured).length
  return {
    checkedAt: new Date().toISOString(),
    providers,
    configuredCount,
    totalCount: providers.length,
    allConfigured: configuredCount === providers.length,
  }
}

import { STOCK_SCORE_FACTORS } from './scoreFactors'
import { defaultStorage } from '@/lib/localStorageManager'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

export interface LlmConfig {
  baseURL: string
  apiKey: string
  model: string
  /** 最大输出 token 数 */
  maxTokens?: number
  /** 采样温度 */
  temperature?: number
  /** 请求超时时间（毫秒） */
  timeout?: number
}

export type PartialLlmConfig = Partial<LlmConfig>

/** 单个因子的 LLM 调用覆盖设置 */
export interface LlmFactorOverride {
  /** 因子唯一标识，与 scoreFactors.ts 中的因子名称对齐 */
  factorId: string
  /** 是否允许该因子调用 LLM */
  useLlm: boolean
}

/**
 * 支持 AI 调用透明度的 LLM 配置。
 * 在 {@link LlmConfig} 基础上增加总开关、透明度面板开关以及因子级覆盖。
 */
export interface LlmTransparencyConfig extends LlmConfig {
  /** 各因子是否调用 LLM 的覆盖配置 */
  factorOverrides?: LlmFactorOverride[]
  /** LLM 总开关 */
  enableLlm: boolean
  /** 是否在前端展示 AI 调用透明度面板 */
  showTransparencyPanel: boolean
}

/**
 * 默认启用 LLM 的因子层级索引。
 * 按 scoreFactors.ts 中 STOCK_SCORE_FACTORS.factors 的顺序依次对应 L0 ~ L8。
 */
const DEFAULT_LLM_ENABLED_LAYER_INDICES = new Set([0, 1, 2, 5, 6])

/**
 * 默认 LLM 因子级覆盖配置。
 * - L0/L1/L2/L5/L6 默认使用 LLM
 * - L3/L4/L7/L8 默认不调用 LLM（由规则引擎自动计算）
 * factorId 从 scoreFactors.ts 中的因子名称推导，禁止硬编码因子名称。
 */
export const DEFAULT_LLM_FACTOR_OVERRIDES: LlmFactorOverride[] = STOCK_SCORE_FACTORS.factors.map(
  (factor, index) => ({
    factorId: factor.name,
    useLlm: DEFAULT_LLM_ENABLED_LAYER_INDICES.has(index),
  }),
)

/** LLM 模型预设 */
export interface LlmPreset {
  id: string
  name: string
  provider: string
  baseURL: string
  defaultModel: string
  models: string[]
  contextWindow?: number
  inputPrice?: string
  outputPrice?: string
}

/** 内置模型预设列表 */
export const LLM_MODEL_PRESETS: LlmPreset[] = [
