/**
 * 路由白名单 —— 从 ROUTE_REGISTRY 自动派生的合法路径前缀集合。
 * 用于 RouteGuard 路径级校验，防止未注册路径绕过舱室入口守卫。
 *
 * 生成规则：提取每个注册路径的首段前缀（如 /analysis/stock-score → analysis）。
 * 新增路由只需在 ROUTE_REGISTRY 注册，白名单自动生效。
 */
export const ROUTE_WHITELIST: ReadonlySet<string> = (() => {
  const prefixes = new Set<string>()
  for (const route of ROUTE_REGISTRY) {
    const segments = route.path.split('/').filter(Boolean)
    if (segments.length > 0 && segments[0]) {
      prefixes.add(segments[0])
    }
  }
  // 根路径 '/' 始终允许
  prefixes.add('/')
  return prefixes
})()

export function getAllPaths(): string[] {
  return ROUTE_REGISTRY.map((r) => r.path)
}

export function hasRoute(path: string): boolean {
  return ROUTE_REGISTRY.some((r) => r.path === path)
}

export function getRoutesByCategory(category: RouteCategory): RouteConfig[] {
  return ROUTE_REGISTRY.filter((r) => r.category === category)
}

export function getCabinPaths(): Record<'input' | 'analysis' | 'trading' | 'output' | 'command', string> {
  return {
    input: '/input',
    analysis: '/analysis',
    trading: '/trading',
    output: '/output',
    command: '/command',
  }
}

/**
 * 安全策略统一配置总线
 *
 * 作为所有安全模块（MCP 门禁、安装审计、CI/CD）的唯一配置源，
 * 消除跨文件硬编码，确保授权规则、日志路径、白名单的一致性。
 *
 * 数据来源：.trae/mcp-whitelist-policy.json
 * 消费者：mcp-confirmation-demo.ts / audit-installations.ps1 / CI policy-verify
 *
 * 遵循 AGENTS.md 第三节"零硬编码"约束：所有阈值、规则从 config 层注入
 */

import * as fs from 'fs'
import * as path from 'path'

// ============================================================
// 类型定义（与 .trae/mcp-whitelist-policy.json schema 对齐）
// ============================================================

export type AuthorizationLevel = 'autoApprove' | 'requireConfirmation' | 'requireAdminApproval'

export interface TrustedMcpServer {
  source: string
  package: string
  trustedReason: string
  allowedTools: string[]
  restrictedTools: string[]
  restrictedReason: string
  networkOrigins: string[]
}

export interface BlockedMcpServer {
  blockedReason: string
}

export interface AuditConfig {
  logEnabled: boolean
  logPath: string
  logFields: string[]
  retentionDays: number
  alertOnFailure: boolean
}

export interface SecurityPolicy {
  policyVersion: string
  policyName: string
  lastUpdated: string
  strategy: string
  scope: string
  trustedMcpServers: Record<string, TrustedMcpServer>
  blockedMcpServers: Record<string, BlockedMcpServer>
  authorizationRules: Record<AuthorizationLevel, string[]>
  audit: AuditConfig
}

