  /** 是否包含行业评分 */
  includeIndustryScore?: boolean
  /** 是否包含交易信号 */
  includeSignals?: boolean
  /** 是否包含关联新闻 */
  includeNews?: boolean
}

/** 综合查询结果 */
export interface QueryBuilderResult {
  /** 股票基础信息 */
  stock?: Stock
  /** K 线行情 */
  quotes?: DailyQuotes
  /** V6 评分 */
  v6Score?: V6Score
  /** 智能评分 */
  intelligentScore?: IntelligentScore
  /** 行业评分 */
  industryScore?: IndustryScore
  /** 交易信号列表 */
  signals?: Signal[]
  /** 关联新闻列表 */
  news?: NewsArticle[]
  /** 查询失败的维度 */
  errors?: string[]
}

type TaskResult = { key: keyof Omit<QueryBuilderResult, 'errors'>; value: unknown }

/**
 * QueryBuilder -- 绕开 Store 综合查询引擎
 *
 * 封装 dataLayer 多个 Store 的并发查询，一次性获取某只股票在
 * 基础信息 / 行情 / V6评分 / 智能评分 / 行业评分 / 交易信号 / 关联新闻
 * 等多个维度的数据，返回统一的 QueryBuilderResult。 */
export class QueryBuilder {
  /**
   * 从 DataLayer 查询多维度的股票数据
   * @param params 查询参数
   * @returns 综合后的 QueryBuilderResult
   */
  async queryStock(params: UnifiedStockQuery): Promise<QueryBuilderResult> {
    const { symbol } = params
    const tasks: Promise<TaskResult>[] = []
    const dimensions: string[] = []
    const errors: string[] = []

    // --- 基础信息 ---
    if (params.includeBasic) {
      dimensions.push('basic')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            const value = await dataLayer.stocks.get(symbol)
            return { key: 'stock', value }
          } catch (err) {
            const msg = `Failed to fetch basic data for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('basic')
            return { key: 'stock', value: undefined }
          }
        })(),
      )
    }

    // --- K 线行情 ---
    if (params.includeQuotes) {
      dimensions.push('quotes')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            const value = await dataLayer.dailyQuotes.get(symbol)
            return { key: 'quotes', value }
          } catch (err) {
            const msg = `Failed to fetch quotes for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('quotes')
            return { key: 'quotes', value: undefined }
          }
        })(),
      )
    }

    // --- V6 评分 ---
    if (params.includeV6Score) {
      dimensions.push('v6Score')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            const value = await dataLayer.v6Scores.get(symbol)
            return { key: 'v6Score', value }
          } catch (err) {
            const msg = `Failed to fetch V6 score for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('v6Score')
            return { key: 'v6Score', value: undefined }
          }
        })(),
      )
    }

    // --- 智能评分 ---
    if (params.includeIntelligentScore) {
      dimensions.push('intelligentScore')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            const value = await dataLayer.intelligentScores.getLatestBySymbol(symbol)
            return { key: 'intelligentScore', value }
          } catch (err) {
            const msg = `Failed to fetch intelligent score for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('intelligentScore')
            return { key: 'intelligentScore', value: undefined }
          }
        })(),
      )
    }

    // --- 行业评分（需要 industryCode） ---
    if (params.includeIndustryScore) {
      dimensions.push('industryScore')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            // 如果 includeBasic 已经开启，basic 任务会并发返回 stock。
            // 这里立即查询 stock 以确保 industryScore 任务自包含。
            const stock = await dataLayer.stocks.get(symbol).catch(() => undefined)
            if (stock?.industryCode) {
              const value = await dataLayer.industryScores.getLatestByCode(stock.industryCode)
              return { key: 'industryScore', value }
            }
            return { key: 'industryScore', value: undefined }
          } catch (err) {
            const msg = `Failed to fetch industry score for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('industryScore')
            return { key: 'industryScore', value: undefined }
          }
        })(),
      )
    }

    // --- 交易信号 ---
    if (params.includeSignals) {
      dimensions.push('signals')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            const value = await dataLayer.signals.listBySymbol(symbol)
            return { key: 'signals', value }
          } catch (err) {
            const msg = `Failed to fetch signals for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('signals')
            return { key: 'signals', value: [] }
          }
        })(),
      )
    }

    // --- 关联新闻（通过 newsStockMap 多对多关联） ---
    if (params.includeNews) {
      dimensions.push('news')
      tasks.push(
        (async (): Promise<TaskResult> => {
          try {
            const mappings = await dataLayer.newsStockMap.listBySymbol(symbol)
            const newsList: NewsArticle[] = []
            // 并行获取所有关联新闻
            const newsResults = await Promise.allSettled(
              mappings.map((m) => dataLayer.news.get(m.newsId)),
            )
            for (const result of newsResults) {
              if (result.status === 'fulfilled' && result.value) {
                newsList.push(result.value)
              }
            }
            return { key: 'news', value: newsList }
          } catch (err) {
            const msg = `Failed to fetch news for ${symbol}: ${String(err)}`
            logger.warn(`[QueryBuilder] ${msg}`)
            errors.push('news')
            return { key: 'news', value: [] }
          }
        })(),
      )
    }

    // 并行执行所有查询
    const results = await Promise.all(tasks)

    // 组装结果
    const data: QueryBuilderResult = {}
    for (const result of results) {
      if (result.value !== undefined && result.value !== null) {
        ;(data as Record<string, unknown>)[result.key] = result.value
      }
    }

    if (errors.length > 0) {
      data.errors = errors
    }

    logger.info(`[QueryBuilder] queryStock: ${symbol}, dimensions=[${dimensions.join(',')}]`)
    return data
  }

  /**
   * 批量查询多只股票的综合数据
   * @param symbols 股票代码列表
   * @param params 查询参数（不含 symbol）
   * @returns Map<symbol, QueryBuilderResult>
   */
  async queryStocksBatch(
    symbols: string[],
    params: Omit<UnifiedStockQuery, 'symbol'>,
  ): Promise<Map<string, QueryBuilderResult>> {
    const results = new Map<string, QueryBuilderResult>()
    // 串行查询避免 IndexedDB 事务竞争
    for (const symbol of symbols) {
      results.set(symbol, await this.queryStock({ ...params, symbol }))
    }
    logger.info(`[QueryBuilder] queryStocksBatch: ${symbols.length} symbols queried`)
    return results
  }
}

/** 全局 QueryBuilder 实例 */
export const queryBuilder = new QueryBuilder()

/**
 * @module DataBridgeAdapter
 * @lifecycle @Global
 * @description DataBridge 扩展适配层，提供面向模块的便捷数据访问接口
 */

import { DataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import type { StandardEnvelope } from '@/core/envelope'
import type { DataBridgeAdapterConfig, DataAction, BridgeQueryOptions, BridgeQueryResult } from '@/types/modules/databridge.types'

const logger = getLogger()

export type { DataBridgeAdapterConfig, DataAction, BridgeQueryOptions, BridgeQueryResult } from '@/types/modules/databridge.types'

export class DataBridgeAdapter {
  private bridge: DataBridge
  private config: DataBridgeAdapterConfig
  private pendingQueries = new Map<string, { resolve: (r: BridgeQueryResult) => void; reject: (e: Error) => void }>()
  private activeSubscriptions: Array<() => void> = []

  constructor(config: DataBridgeAdapterConfig = {}) {
    this.config = {
      enableFallbackQueue: true,
      defaultTimeout: 10000,
      ...config,
    }
    this.bridge = new DataBridge()
    logger.info('[DataBridgeAdapter] Initialized')
  }

  async query<T = unknown>(
    action: DataAction,
    payload: Record<string, unknown> = {},
    options: BridgeQueryOptions = {},
  ): Promise<BridgeQueryResult<T>> {
    const traceId = `bridge-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
    const timeout = options.timeout ?? this.config.defaultTimeout ?? 10000

    logger.info(`[DataBridgeAdapter] query() action="${action}", traceId="${traceId}"`)

    const envelope = EnvelopeFactory.create(
      {
        action: action as unknown as import('@/config/dbConfig').EnvelopeAction,
        source: 'system' as import('@/config/dbConfig').ModuleId,
        target: 'db' as import('@/config/dbConfig').EnvelopeTarget,
        traceId,
      },
      payload,
    )

    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pendingQueries.delete(traceId)
        logger.warn(`[DataBridgeAdapter] Query timeout: action="${action}", traceId="${traceId}"`)
        resolve({
          success: false,
          error: `Query timeout after ${timeout}ms`,
          traceId,
        })
      }, timeout)

      this.pendingQueries.set(traceId, {
        resolve: (result: BridgeQueryResult<unknown>) => {
          clearTimeout(timer)
          this.pendingQueries.delete(traceId)
          resolve(result as BridgeQueryResult<T>)
        },
        reject: (err: Error) => {
          clearTimeout(timer)
          this.pendingQueries.delete(traceId)
          reject(err)
        },
      })

      this.bridge
        .forward(envelope)
        .then(() => {
          logger.debug(`[DataBridgeAdapter] Query forwarded: traceId="${traceId}"`)
          const result: BridgeQueryResult<T> = {
            success: true,
            data: envelope.payload as T,
            traceId,
          }
          this.pendingQueries.get(traceId)?.resolve(result)
        })
        .catch((err) => {
          logger.error(`[DataBridgeAdapter] Query failed: traceId="${traceId}", error="${err.message}"`)
          const result: BridgeQueryResult<T> = {
            success: false,
            error: err.message,
            traceId,
          }
          this.pendingQueries.get(traceId)?.resolve(result)
        })
    })
  }

  subscribe(channel: string, callback: (envelope: StandardEnvelope) => void): () => void {
    logger.debug(`[DataBridgeAdapter] subscribe() channel="${channel}"`)
    const unsubscribe = eventBus.on(channel, callback as (payload: unknown) => void)
    // 追踪活跃订阅，destroy 时统一清理
    this.activeSubscriptions.push(unsubscribe)
    return () => {
      unsubscribe()
      const idx = this.activeSubscriptions.indexOf(unsubscribe)
      if (idx !== -1) this.activeSubscriptions.splice(idx, 1)
    }
  }

  getStats() {
    return {
      pendingQueries: this.pendingQueries.size,
      activeSubscriptions: this.activeSubscriptions.length,
      enableFallbackQueue: this.config.enableFallbackQueue,
    }
  }

  /**
   * 清理所有活跃 EventBus 订阅，防止内存泄漏。
   */
  destroySubscriptions(): void {
    this.activeSubscriptions.forEach((unsub) => unsub())
    this.activeSubscriptions = []
    logger.info('[DataBridgeAdapter] All subscriptions cleaned up')
  }
}

// Singleton
let adapterInstance: DataBridgeAdapter | null = null

export function createDataBridgeAdapter(config?: DataBridgeAdapterConfig): DataBridgeAdapter {
  if (adapterInstance) return adapterInstance
  adapterInstance = new DataBridgeAdapter(config)
  return adapterInstance
}

export function getDataBridgeAdapter(): DataBridgeAdapter {
  if (!adapterInstance) {
    throw new Error('DataBridgeAdapter not initialized. Call createDataBridgeAdapter() first.')
  }
  return adapterInstance
}

export function destroyDataBridgeAdapter(): void {
  if (adapterInstance) {
    adapterInstance.destroySubscriptions()
  }
  adapterInstance = null
  logger.info('[DataBridgeAdapter] Instance destroyed')
}

