import { useState, useEffect } from 'react'

export function useDebounce<T>(value: T, delayMs = 300): T {
  const [debouncedValue, setDebouncedValue] = useState(value)

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value)
    }, delayMs)

    return () => {
      clearTimeout(timer)
    }
  }, [value, delayMs])

  return debouncedValue
}

/**
 * @module useFreshData
 * @description 数据新鲜度自动刷新 Hook。
 *
 * 监听 Store 数据的 lastUpdated 时间戳，
 * 当数据超过 maxStaleMs 时自动触发 refresh。
 * 支持 document.visibilitychange 事件自动检查：
 * 页面重新可见时，检查所有注册的数据源是否过期。
 *
 * 纯 UI 层 Hook，不改变现有 Store 接口。
 *
 * @see src/core/refreshCoordinator.ts -- 跨 Store 刷新协调
 * @see docs/implementation/freshness-alerts.md -- 数据新鲜度告警策略
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

export interface UseFreshDataOptions {
  /** 数据的最后更新时间戳（ms） */
  lastUpdated: number
  /** 最大允许过期时间（ms），超过此值数据被视为过期 */
  maxStaleMs: number
  /** 刷新回调函数 */
  refresh: () => Promise<void>
  /** 是否启用（默认 true） */
  enabled?: boolean
  /** 日志标签，用于调试追踪 */
  label?: string
}

export interface UseFreshDataResult {
  /** 数据是否已过期 */
  isStale: boolean
  /** 距上次更新的秒数 */
  secondsSinceUpdate: number
  /** 强制立即刷新 */
  forceRefresh: () => void
}

// ============================================================
// 全局注册表：收集所有活跃的 useFreshData 实例
// ============================================================

/**
 * visibilitychange 事件处理器注册表。
 * 页面重新可见时，遍历所有注册实例，检查并刷新过期数据。
 */
const visibilityHandlers = new Set<() => void>()
let visibilityListenerAttached = false

/**
 * 添加 visibilitychange 全局监听器（仅首次添加）。
 * 页面重新可见时调用所有注册的检查函数。
 */
function ensureVisibilityListener(): void {
  if (visibilityListenerAttached) return
  visibilityListenerAttached = true

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') return

    logger.info('[useFreshData] 页面重新可见，检查所有数据源新鲜度')
    const handlers = Array.from(visibilityHandlers)
    for (const handler of handlers) {
      try {
        handler()
      } catch (err) {
        logger.error('[useFreshData] visibilitychange handler error', {
          error: err instanceof Error ? err.message : String(err),
        })
      }
    }
  })
}

// ============================================================
// Hook 实现
// ============================================================

/**
 * 数据新鲜度自动刷新 Hook。
 *
 * @param options - 配置选项
 * @returns 新鲜度状态与强制刷新方法
 *
 * @example
 * ```tsx
 * // 在组件中使用
 * const lastUpdated = useOrderStore((s) => s.lastUpdated)
 * const refresh = useOrderStore((s) => s.refresh)
 *
 * const { isStale, secondsSinceUpdate, forceRefresh } = useFreshData({
 *   lastUpdated,
 *   maxStaleMs: 60_000, // 60秒
 *   refresh,
 *   label: 'orderStore',
 * })
 * ```
 */
export function useFreshData(options: UseFreshDataOptions): UseFreshDataResult {
  const { lastUpdated, maxStaleMs, refresh, enabled = true, label = 'unknown' } = options

  const [now, setNow] = useState(() => Date.now())
  const isRefreshingRef = useRef(false)
  const optionsRef = useRef(options)
  optionsRef.current = options

  // 每秒更新当前时间，用于计算 secondsSinceUpdate
  useEffect(() => {
    if (!enabled) return

    const timer = setInterval(() => {
      setNow(Date.now())
    }, 1000)

    return () => clearInterval(timer)
  }, [enabled])

  // 计算是否过期
  const isStale = enabled && lastUpdated > 0 && (now - lastUpdated) > maxStaleMs
  const secondsSinceUpdate = lastUpdated > 0 ? Math.floor((now - lastUpdated) / 1000) : 0

  // 强制刷新
  const forceRefresh = useCallback(() => {
    if (isRefreshingRef.current) {
      logger.debug(`[useFreshData:${label}] forceRefresh skipped: already refreshing`)
      return
    }
    isRefreshingRef.current = true
    logger.info(`[useFreshData:${label}] forceRefresh triggered`)
    refresh().finally(() => {
      isRefreshingRef.current = false
    })
  }, [refresh, label])

  // 自动刷新：检测到过期时自动触发一次
  useEffect(() => {
    if (!enabled || !isStale || isRefreshingRef.current) return

    logger.info(`[useFreshData:${label}] 数据过期，自动刷新`, {
      lastUpdated,
      maxStaleMs,
      secondsSinceUpdate,
    })

    isRefreshingRef.current = true
    refresh().finally(() => {
      isRefreshingRef.current = false
    })
  }, [enabled, isStale, lastUpdated, maxStaleMs, refresh, label, secondsSinceUpdate])

  // 注册到 visibilitychange 全局监听
  useEffect(() => {
    if (!enabled) return

    const checkAndRefresh = () => {
      const currentOptions = optionsRef.current
      const currentLastUpdated = currentOptions.lastUpdated
      const currentMaxStaleMs = currentOptions.maxStaleMs

      if (currentLastUpdated <= 0) return
      if (Date.now() - currentLastUpdated <= currentMaxStaleMs) return
      if (isRefreshingRef.current) return

      logger.info(`[useFreshData:${label}] visibilitychange 触发自动刷新`, {
        lastUpdated: currentLastUpdated,
        maxStaleMs: currentMaxStaleMs,
      })

      isRefreshingRef.current = true
      currentOptions.refresh().finally(() => {
        isRefreshingRef.current = false
      })
    }

    visibilityHandlers.add(checkAndRefresh)
    ensureVisibilityListener()

    return () => {
      visibilityHandlers.delete(checkAndRefresh)
    }
  }, [enabled, label])

  return {
    isStale,
    secondsSinceUpdate,
    forceRefresh,
  }
}

/* eslint-disable react-refresh/only-export-components */
import { createContext, useContext, useState, useCallback, useMemo, type ReactNode } from 'react'

export type ToastVariant = 'default' | 'success' | 'error' | 'warning' | 'info'

export interface Toast {
  id: string
  title?: string
  description?: string
  variant?: ToastVariant
  duration?: number
}

interface ToastContextValue {
  toasts: Toast[]
  toast: (toast: Omit<Toast, 'id'>) => void
  dismiss: (id: string) => void
}

const ToastContext = createContext<ToastContextValue | null>(null)

export function useToast() {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error('useToast must be used within <ToastProvider>')
  return ctx
}

export interface ToastProviderProps {
  children: ReactNode
}

export function ToastProvider({ children }: ToastProviderProps) {
  const [toasts, setToasts] = useState<Toast[]>([])

  const toast = useCallback((t: Omit<Toast, 'id'>) => {
    const id = Math.random().toString(36).slice(2)
    const newToast: Toast = { id, duration: 5000, ...t }
    setToasts((prev) => [...prev, newToast])

    if (newToast.duration && newToast.duration > 0) {
      setTimeout(() => {
        setToasts((prev) => prev.filter((item) => item.id !== id))
      }, newToast.duration)
    }
  }, [])

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((item) => item.id !== id))
  }, [])

  const value = useMemo(() => ({ toasts, toast, dismiss }), [toasts, toast, dismiss])

  return <ToastContext.Provider value={value}>{children}</ToastContext.Provider>
}

export { ToastContext }

/**
 * V9 统一错误类型定义
 *
 * @description
 * 集中定义 V9 项目中常见的错误子类，避免业务代码直接抛出匿名 Error。
 * 所有错误均以 V9Error 为基类，可通过 `err instanceof V9Error` 统一识别与日志分类。
 *
 * @module lib/errors
 * @created 2026-06-30 - G1 批次低风险优化（错误类型细分）
 */

/**
 * V9 错误基类
 *
 * 业务层、UI 层应当捕获此基类的子类，并通过 `error.category` / `error.code` 路由到
 * 不同的提示与上报通道。
 */
export class V9Error extends Error {
  /** 错误分类，用于日志与 UI 区分 */
  public readonly category: 'data' | 'network' | 'validation' | 'permission' | 'business' | 'system'
  /** 错误码，建议在 docs/10-glossary.md 维护统一注册表 */
  public readonly code: string
  /** 错误发生时间戳 */
  public readonly timestamp: number

  constructor(
    message: string,
    options: {
      category?: V9Error['category']
      code?: string
      cause?: unknown
    } = {},
  ) {
    super(message)
    this.name = 'V9Error'
    this.category = options.category ?? 'system'
    this.code = options.code ?? 'V9_UNKNOWN'
    this.timestamp = Date.now()
    if (options.cause !== undefined) {
      ;(this as Error & { cause?: unknown }).cause = options.cause
    }
  }
}

/**
 * 数据层错误（IndexedDB / DataBridge 写读失败）
 */
export class DataLayerError extends V9Error {
  constructor(message: string, code = 'DATA_LAYER_ERROR', cause?: unknown) {
    super(message, { category: 'data', code, cause })
    this.name = 'DataLayerError'
  }
}

/**
 * 股票不存在错误（业务层查找）
 */
export class StockNotFoundError extends V9Error {
  constructor(symbol: string) {
    super(`Stock not found: ${symbol}`, { category: 'business', code: 'STOCK_NOT_FOUND' })
    this.name = 'StockNotFoundError'
  }
}

/**
 * 重复股票错误
 */
export class DuplicateStockError extends V9Error {
  constructor(symbol: string) {
    super(`Stock already exists: ${symbol}`, { category: 'business', code: 'DUPLICATE_STOCK' })
    this.name = 'DuplicateStockError'
  }
}

/**
 * 信封/数据桥接错误（DataBridge 校验/分发失败）
 */
export class DataBridgeError extends V9Error {
  constructor(message: string, code = 'DATA_BRIDGE_ERROR', cause?: unknown) {
    super(message, { category: 'data', code, cause })
    this.name = 'DataBridgeError'
  }
}

/**
 * 权限/ACL 错误
 */
export class PermissionError extends V9Error {
  constructor(message: string, code = 'PERMISSION_DENIED') {
    super(message, { category: 'permission', code })
    this.name = 'PermissionError'
  }
}

/**
 * 输入校验错误（表单、payload 校验失败）
 */
export class ValidationError extends V9Error {
  public readonly field?: string
  constructor(message: string, field?: string) {
    super(message, { category: 'validation', code: field ? `INVALID_${field.toUpperCase()}` : 'VALIDATION_ERROR' })
    this.name = 'ValidationError'
    this.field = field
  }
}

/**
 * 网络层错误（fetcher / LLM 调用失败）
 */
export class NetworkError extends V9Error {
  public readonly status?: number
  constructor(message: string, status?: number, cause?: unknown) {
    super(message, { category: 'network', code: status ? `HTTP_${status}` : 'NETWORK_ERROR', cause })
    this.name = 'NetworkError'
    this.status = status
  }
}

/**
 * 业务规则错误（风控阻断、信号过滤等）
 */
export class BusinessRuleError extends V9Error {
  constructor(message: string, code = 'BUSINESS_RULE_VIOLATION') {
    super(message, { category: 'business', code })
    this.name = 'BusinessRuleError'
  }
}

/**
 * 类型守卫：判断对象是否为 V9Error 子类
 */
export function isV9Error(err: unknown): err is V9Error {
  return err instanceof V9Error
}

/**
 * 将任意异常安全转换为 V9Error。
 * - 已为 V9Error 子类 → 原样返回
 * - 已是 Error → 包装为 V9Error
 * - 其余值 → 包装为含 String() 描述的 V9Error
 */
export function toV9Error(err: unknown, fallbackCode = 'V9_UNKNOWN'): V9Error {
  if (isV9Error(err)) return err
  if (err instanceof Error) {
    return new V9Error(err.message, { cause: err, code: fallbackCode })
  }
  return new V9Error(typeof err === 'string' ? err : JSON.stringify(err), { code: fallbackCode })
}

import { getLogger } from '@/lib/logger'

const logger = getLogger()

type EventCallback = (payload: unknown) => void

class EventBus {
  private listeners = new Map<string, Set<EventCallback>>()

  on(event: string, callback: EventCallback): () => void {
    logger.debug(`[EventBus] on() called: event="${event}"`)

    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
      logger.debug(`[EventBus] Created new listener set for event: "${event}"`)
    }

    const prevCount = this.listeners.get(event)!.size
    this.listeners.get(event)!.add(callback)
    const newCount = this.listeners.get(event)!.size

    logger.info(`[EventBus] Subscribe: event="${event}", count=${prevCount}→${newCount}`)

    return () => {
      const wasPresent = this.listeners.get(event)?.has(callback)
      this.listeners.get(event)?.delete(callback)
      const remaining = this.listeners.get(event)?.size ?? 0

      if (wasPresent) {
        logger.info(`[EventBus] Unsubscribe: event="${event}", remaining=${remaining}`)
      }
    }
  }

  emit(event: string, payload?: unknown): void {
    const startTs = Date.now()
    logger.debug(`[EventBus] emit() called: event="${event}", hasPayload=${payload !== undefined}`)

    const callbacks = this.listeners.get(event)
    if (!callbacks) {
      logger.debug(`[EventBus] emit() skipped: no listeners for event "${event}"`)
      return
    }

    const callbackCount = callbacks.size
    logger.debug(`[EventBus] Emitting to ${callbackCount} listeners: event="${event}"`)

    let successCount = 0
    let errorCount = 0
    let listenerIndex = 0

    callbacks.forEach((cb) => {
      listenerIndex++
      try {
        cb(payload)
        successCount++
      } catch (err) {
        errorCount++
        logger.error(`[EventBus] Listener #${listenerIndex} error for event "${event}"`, { error: err })
      }
    })

    const duration = Date.now() - startTs
    if (duration > 10) {
      logger.warn(`[EventBus] emit() took ${duration}ms for event "${event}"`)
    }

    logger.info(`[EventBus] Emit completed: event="${event}", listeners=${callbackCount}, success=${successCount}, errors=${errorCount}`)
  }

  off(event: string, callback: EventCallback): void {
    logger.debug(`[EventBus] off() called: event="${event}"`)

    const callbacks = this.listeners.get(event)
    if (!callbacks) {
      logger.debug(`[EventBus] off() skipped: no listeners for event "${event}"`)
      return
    }

    const wasPresent = callbacks.has(callback)
    callbacks.delete(callback)
    const remaining = callbacks.size

    logger.info(`[EventBus] off(): event="${event}", removed=${wasPresent}, remaining=${remaining}`)
  }

  getStats() {
    const stats = {
      events: this.listeners.size,
      totalListeners: Array.from(this.listeners.values()).reduce((sum, set) => sum + set.size, 0),
      listenersPerEvent: Array.from(this.listeners.entries()).map(([event, set]) => ({ event, count: set.size })),
    }
    logger.debug(`[EventBus] getStats(): ${JSON.stringify(stats)}`)
    return stats
  }
}

export const eventBus = new EventBus()

/**
 * @module LocalStorageManager
 * @description 统一 localStorage 封装，支持命名空间隔离、JSON 序列化、TTL 过期、
 *              容量监控与批量操作。解决原生 localStorage 的以下痛点：
 *              - 无命名空间，key 容易冲突
 *              - 仅支持字符串，需手动序列化/反序列化
 *              - 无过期机制，数据永久残留
 *              - 无容量监控，超出配额静默失败
 *
 * v0.9.16 安全增强（audit-b4-4-security STOR-001 / STOR-003）：
 * - 新增 setEncrypted / getEncrypted 方法，使用 Web Crypto API (AES-GCM) 加密敏感字段
 * - 加密 key 派生自设备指纹（浏览器+origin），防止跨站攻击
 * - 加密失败时降级为不存储，避免明文回退
 */

import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 常量
// ============================================================

/** localStorage 标准容量上限 (5MB = 5,242,880 bytes) */
const STORAGE_MAX_BYTES = 5_242_880

/** 默认命名空间前缀分隔符 */
const NS_SEPARATOR = ':'

/** 默认过期时间（毫秒），0 表示永不过期 */
const DEFAULT_TTL = 0

// ============================================================
// 类型定义
// ============================================================

/** 存储条目包装结构 */
interface StorageEntry<T = unknown> {
  /** 命名空间 */
  ns: string
  /** 实际数据 */
  value: T
  /** 创建时间戳 (ms) */
  createdAt: number
  /** 过期时间戳 (ms)，0 表示永不过期 */
  expiresAt: number
  /** 数据版本号 */
  version: number
}

/** LocalStorageManager 配置选项 */
export interface LocalStorageOptions {
  /** 命名空间，用于 key 前缀隔离 */
  namespace?: string
  /** 默认 TTL 毫秒数，默认 0（永不过期） */
  defaultTTL?: number
  /** 容量警告阈值（0-1），默认 0.8（占用超过 80% 时发出警告） */
  capacityWarningThreshold?: number
}

/** 存储容量信息 */
export interface StorageCapacity {
  /** 已使用字节数 */
  usedBytes: number
  /** 总容量字节数 */
  totalBytes: number
  /** 使用率（0-1） */
  usageRatio: number
  /** 是否超过警告阈值 */
  isWarning: boolean
}

/** 命名空间信息 */
export interface NamespaceInfo {
  namespace: string
  keyCount: number
  totalBytes: number
  oldestEntry: string | null
  newestEntry: string | null
}

// ============================================================
// 工具函数
// ============================================================

/**
 * 计算字符串的 UTF-8 字节长度。
 */
function byteLength(str: string): number {
  // 使用 Blob API 精确计算，回退到估算
  try {
    return new Blob([str]).size
  } catch {
    // 回退：英文 1 字节，中文 3 字节，其他 2 字节
    let len = 0
    for (let i = 0; i < str.length; i++) {
      const code = str.charCodeAt(i)
      if (code < 0x80) len += 1
      else if (code < 0x800) len += 2
      else len += 3
    }
    return len
  }
}

// ============================================================
// LocalStorageManager 实现
// ============================================================

export class LocalStorageManager {
  private namespace: string
  private defaultTTL: number
  private capacityWarningThreshold: number

  constructor(options: LocalStorageOptions = {}) {
    this.namespace = options.namespace ?? 'app'
    this.defaultTTL = options.defaultTTL ?? DEFAULT_TTL
    this.capacityWarningThreshold = options.capacityWarningThreshold ?? 0.8

    logger.debug(`[LocalStorageManager:${this.namespace}] 初始化完成，TTL=${this.defaultTTL}ms, capacityThreshold=${this.capacityWarningThreshold}`)
  }

  // ============================================================
  // 公共 API：基础 CRUD
  // ============================================================

  /**
   * 读取存储值。
   * 自动检测过期，过期条目删除并返回 null。
   */
  get<T = unknown>(key: string): T | null {
    const fullKey = this.makeKey(key)
    const raw = localStorage.getItem(fullKey)

    if (raw === null) {
      return null
    }

    try {
      const entry = JSON.parse(raw) as StorageEntry<T>

      // 检查过期
      if (entry.expiresAt > 0 && Date.now() > entry.expiresAt) {
        localStorage.removeItem(fullKey)
        logger.debug(`[LocalStorageManager:${this.namespace}] EXPIRED: key="${key}"`)
        return null
      }

      return entry.value
    } catch (err) {
      logger.warn(`[LocalStorageManager:${this.namespace}] 反序列化失败: key="${key}"`, { error: err })
      // 损坏的数据直接删除
      localStorage.removeItem(fullKey)
      return null
    }
  }

  /**
   * 写入存储值。
   */
  set<T = unknown>(key: string, value: T, ttl?: number): void {
    const effectiveTTL = ttl ?? this.defaultTTL
    const entry: StorageEntry<T> = {
      ns: this.namespace,
      value,
      createdAt: Date.now(),
      expiresAt: effectiveTTL > 0 ? Date.now() + effectiveTTL : 0,
      version: 1,
    }

    const fullKey = this.makeKey(key)
    const raw = JSON.stringify(entry)

    try {
      localStorage.setItem(fullKey, raw)
      logger.debug(`[LocalStorageManager:${this.namespace}] SET: key="${key}", size=${byteLength(raw)}B, TTL=${effectiveTTL}ms`)

      // 写入后检查容量
      this.checkCapacity()
    } catch (err) {
      if (err instanceof DOMException && err.name === 'QuotaExceededError') {
        logger.error(`[LocalStorageManager:${this.namespace}] 存储配额已满，写入失败: key="${key}"`)
        throw new Error(`localStorage 配额已满，无法写入 key="${key}"。请清理过期数据或减少存储量。`)
      }
      throw err
    }
  }

  /**
   * 删除指定存储条目。
   */
  remove(key: string): void {
    const fullKey = this.makeKey(key)
    localStorage.removeItem(fullKey)
    logger.debug(`[LocalStorageManager:${this.namespace}] REMOVE: key="${key}"`)
  }

  // ============================================================
  // 公共 API：加密存储（v0.9.16 STOR-001）
  // ============================================================

  /**
   * 写入加密存储值。
   *
   * 使用 Web Crypto API (AES-GCM) 对 value 进行加密后存储。
   * 加密 key 派生自命名空间 + 浏览器 origin，避免跨站攻击。
   * 若 Web Crypto API 不可用（如非 HTTPS 环境），降级为不存储并抛出错误。
   *
   * @param key 存储 key
   * @param value 待加密的值
   * @param ttl 过期时间（毫秒）
   */
  async setEncrypted<T = unknown>(key: string, value: T, ttl?: number): Promise<void> {
    const cryptoKey = await getOrCreateCryptoKey(this.namespace)
    const plaintext = JSON.stringify(value)
    const iv = generateIv()

    const ciphertext = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv } as AesGcmParams,
      cryptoKey,
      new TextEncoder().encode(plaintext) as BufferSource,
    )

    const payload: EncryptedPayload = {
      __encrypted: true,
      iv: arrayBufferToBase64(iv),
      data: arrayBufferToBase64(ciphertext),
      createdAt: Date.now(),
      expiresAt: (ttl ?? this.defaultTTL) > 0 ? Date.now() + (ttl ?? this.defaultTTL) : 0,
      version: 1,
    }

    const fullKey = this.makeKey(key)
    const raw = JSON.stringify(payload)

    try {
      localStorage.setItem(fullKey, raw)
      logger.debug(`[LocalStorageManager:${this.namespace}] SET(encrypted): key="${key}", size=${byteLength(raw)}B`)
      this.checkCapacity()
    } catch (err) {
      if (err instanceof DOMException && err.name === 'QuotaExceededError') {
        logger.error(`[LocalStorageManager:${this.namespace}] 存储配额已满，加密写入失败: key="${key}"`)
        throw new Error(`localStorage 配额已满，无法写入 key="${key}"。`)
      }
      throw err
    }
  }

  /**
   * 读取加密存储值。
   *
   * 自动解密并返回原始值。若条目未加密、已过期或解密失败，返回 null。
   *
   * @param key 存储 key
   */
  async getEncrypted<T = unknown>(key: string): Promise<T | null> {
    const fullKey = this.makeKey(key)
    const raw = localStorage.getItem(fullKey)

    if (raw === null) return null

    try {
      const payload = JSON.parse(raw) as EncryptedPayload

      // 兼容旧版非加密条目：直接返回 null（不降级为明文读取，防止明文回退攻击）
      if (!payload.__encrypted) {
        logger.warn(`[LocalStorageManager:${this.namespace}] 检测到明文条目，已忽略: key="${key}"`)
        localStorage.removeItem(fullKey)
        return null
      }

      // 过期检查
      if (payload.expiresAt > 0 && Date.now() > payload.expiresAt) {
        localStorage.removeItem(fullKey)
        logger.debug(`[LocalStorageManager:${this.namespace}] EXPIRED(encrypted): key="${key}"`)
        return null
      }

      const cryptoKey = await getOrCreateCryptoKey(this.namespace)
      const iv = base64ToArrayBuffer(payload.iv)
      const ciphertext = base64ToArrayBuffer(payload.data)

      const plaintext = await crypto.subtle.decrypt(
        { name: 'AES-GCM', iv } as AesGcmParams,
        cryptoKey,
        ciphertext as BufferSource,
      )

      return JSON.parse(new TextDecoder().decode(plaintext)) as T
    } catch (err) {
      logger.warn(`[LocalStorageManager:${this.namespace}] 加密条目解密失败: key="${key}"`, { error: err })
      localStorage.removeItem(fullKey)
      return null
    }
  }

  /**
   * 检查指定 key 是否存在且未过期。
   */
  has(key: string): boolean {
    return this.get(key) !== null
  }

  /**
   * 获取当前命名空间下的所有 key 列表。
   */
  keys(): string[] {
    const prefix = this.getPrefix()
    const result: string[] = []

    for (let i = 0; i < localStorage.length; i++) {
      const fullKey = localStorage.key(i)
      if (fullKey && fullKey.startsWith(prefix)) {
        result.push(fullKey.slice(prefix.length))
      }
    }

    return result
  }

  // ============================================================
  // 公共 API：批量操作
  // ============================================================

  /**
   * 批量获取当前命名空间下的所有有效条目。
   */
  getAll<T = unknown>(): Record<string, T> {
    const result: Record<string, T> = {}
    const keys = this.keys()

    for (const key of keys) {
      const value = this.get<T>(key)
      if (value !== null) {
        result[key] = value
      }
    }

    return result
  }

  /**
   * 清除当前命名空间下的所有条目（包括过期条目）。
   */
  clearNamespace(): void {
    const keys = this.getAllKeysInNamespace()
    for (const fullKey of keys) {
      localStorage.removeItem(fullKey)
    }
    logger.info(`[LocalStorageManager:${this.namespace}] 已清除命名空间下 ${keys.length} 条数据`)
  }

  /**
   * 清除当前命名空间下的过期条目。
   * @returns 清理的条目数
   */
  purgeExpired(): number {
    const keys = this.keys()
    let count = 0

    for (const key of keys) {
      if (this.get(key) === null) {
        // get 方法内部已自动删除过期条目
        count++
      }
    }

    if (count > 0) {
      logger.debug(`[LocalStorageManager:${this.namespace}] 清理了 ${count} 条过期数据`)
    }
    return count
  }

  // ============================================================
  // 公共 API：容量监控
  // ============================================================

  /**
   * 获取当前存储容量信息。
   */
  getCapacity(): StorageCapacity {
    let usedBytes = 0

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key) {
        const value = localStorage.getItem(key)
        if (value) {
          usedBytes += byteLength(key) + byteLength(value)
        }
      }
    }

    const usageRatio = usedBytes / STORAGE_MAX_BYTES

    return {
      usedBytes,
      totalBytes: STORAGE_MAX_BYTES,
      usageRatio,
      isWarning: usageRatio >= this.capacityWarningThreshold,
    }
  }

  /**
   * 获取当前命名空间统计信息。
   */
  getNamespaceInfo(): NamespaceInfo {
    const keys = this.getAllKeysInNamespace()
    let totalBytes = 0
    let oldestEntry: string | null = null
    let newestEntry: string | null = null
    let oldestTime = Infinity
    let newestTime = 0

    for (const fullKey of keys) {
      const raw = localStorage.getItem(fullKey)
      if (raw) {
        totalBytes += byteLength(fullKey) + byteLength(raw)

        try {
          const entry = JSON.parse(raw) as StorageEntry
          if (entry.createdAt < oldestTime) {
            oldestTime = entry.createdAt
            oldestEntry = fullKey.slice(this.getPrefix().length)
          }
          if (entry.createdAt > newestTime) {
            newestTime = entry.createdAt
            newestEntry = fullKey.slice(this.getPrefix().length)
          }
        } catch {
          // 忽略解析失败
        }
      }
    }

    return {
      namespace: this.namespace,
      keyCount: keys.length,
      totalBytes,
      oldestEntry,
      newestEntry,
    }
  }

  // ============================================================
  // 静态方法：全局操作
  // ============================================================

  /**
   * 列出所有已知命名空间。
   */
  static listNamespaces(): string[] {
    const nsSet = new Set<string>()

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key) {
        const sepIndex = key.indexOf(NS_SEPARATOR)
        if (sepIndex > 0) {
          nsSet.add(key.slice(0, sepIndex))
        }
      }
    }

    return Array.from(nsSet).sort()
  }

  /**
   * 清除所有命名空间的数据。
   */
  static clearAll(): void {
    const count = localStorage.length
    localStorage.clear()
    logger.info(`[LocalStorageManager] 已清除全部 ${count} 条数据`)
  }

  /**
   * 获取全局容量信息。
   */
  static getGlobalCapacity(): StorageCapacity {
    let usedBytes = 0

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key) {
        const value = localStorage.getItem(key)
        if (value) {
          usedBytes += byteLength(key) + byteLength(value)
        }
      }
    }

    const usageRatio = usedBytes / STORAGE_MAX_BYTES

    return {
      usedBytes,
      totalBytes: STORAGE_MAX_BYTES,
      usageRatio,
      isWarning: usageRatio >= 0.8,
    }
  }

  // ============================================================
  // 私有方法
  // ============================================================

  /**
   * 拼接命名空间前缀与 key。
   */
  private makeKey(key: string): string {
    return `${this.getPrefix()}${key}`
  }

  /**
   * 获取命名空间前缀。
   */
  private getPrefix(): string {
    return `${this.namespace}${NS_SEPARATOR}`
  }

  /**
   * 获取当前命名空间下所有 key（含前缀的完整 key）。
   */
  private getAllKeysInNamespace(): string[] {
    const prefix = this.getPrefix()
    const result: string[] = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key && key.startsWith(prefix)) {
        result.push(key)
      }
    }

    return result
  }

  /**
   * 检查容量并在超过阈值时发出警告。
   */
  private checkCapacity(): void {
    const cap = this.getCapacity()
    if (cap.isWarning) {
      logger.warn(
        `[LocalStorageManager:${this.namespace}] 容量警告: ` +
        `已使用 ${(cap.usedBytes / 1024).toFixed(1)}KB / ${(cap.totalBytes / 1024).toFixed(0)}KB ` +
        `(${(cap.usageRatio * 100).toFixed(1)}%)`,
      )
    }
  }
}

// ============================================================
// 默认实例
// ============================================================

/** 默认 LocalStorageManager 实例（命名空间: app） */
export const defaultStorage = new LocalStorageManager({ namespace: 'app' })

/**
 * 创建命名空间隔离的 LocalStorageManager 实例。
 */
export function createStorage(namespace: string, options?: Omit<LocalStorageOptions, 'namespace'>): LocalStorageManager {
  return new LocalStorageManager({ ...options, namespace })
}

// ============================================================
// 加密存储辅助（v0.9.16 STOR-001）
// ============================================================

/** 加密条目的存储结构 */
interface EncryptedPayload {
  /** 标识为加密条目（区分明文旧版条目） */
  __encrypted: true
  /** Base64 编码的初始化向量 (12 bytes) */
  iv: string
  /** Base64 编码的密文 */
  data: string
  /** 创建时间戳 (ms) */
  createdAt: number
  /** 过期时间戳 (ms)，0 表示永不过期 */
  expiresAt: number
  /** 数据版本号 */
  version: number
}

/** CryptoKey 缓存（按命名空间） */
const cryptoKeyCache = new Map<string, CryptoKey>()

/**
 * 获取或创建指定命名空间的 AES-GCM CryptoKey。
 *
 * 密钥派生策略：
 * - 使用 PBKDF2 从命名空间 + origin 派生 256 位 AES key
 * - salt 固定（应用级），增加跨域攻击难度
 * - iterations=100000，符合 2026 年 OWASP 推荐
 *
 * @param namespace 命名空间
 */
async function getOrCreateCryptoKey(namespace: string): Promise<CryptoKey> {
  const cached = cryptoKeyCache.get(namespace)
  if (cached) return cached

  // 派生密钥的材料：命名空间 + 浏览器 origin
  const origin = typeof window !== 'undefined' ? window.location.origin : 'app'
  const keyMaterial = `${namespace}:${origin}`

  // 应用级 salt（不存储密钥，依赖 origin 隔离）
  const salt = new TextEncoder().encode('v9-local-storage-encryption-salt-v1')

  const baseKey = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(keyMaterial) as BufferSource,
    { name: 'PBKDF2' },
    false,
    ['deriveKey'],
  )

  const aesKey = await crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: salt as BufferSource, iterations: 100_000, hash: 'SHA-256' },
    baseKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  )

  cryptoKeyCache.set(namespace, aesKey)
  return aesKey
}

/** 生成 12 字节随机 IV（AES-GCM 推荐） */
function generateIv(): Uint8Array<ArrayBuffer> {
  const iv = new Uint8Array(12)
  crypto.getRandomValues(iv)
  return iv
}

/** ArrayBuffer → Base64 字符串 */
function arrayBufferToBase64(buffer: ArrayBuffer | Uint8Array): string {
  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer)
  const parts: string[] = new Array(bytes.byteLength)
  for (let i = 0; i < bytes.byteLength; i++) {
    parts[i] = String.fromCharCode(bytes[i]!)
  }
  return btoa(parts.join(''))
}

/** Base64 字符串 → ArrayBuffer */
function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binary = atob(base64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i)
  }
  return bytes.buffer
}

export interface LogContext {
  [key: string]: unknown
}

export type LogLevel = 'debug' | 'info' | 'warn' | 'error'

const LOG_LEVEL_PRIORITY: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
}

let globalLevel: LogLevel = 'debug'

function shouldLog(level: LogLevel): boolean {
  return LOG_LEVEL_PRIORITY[level] >= LOG_LEVEL_PRIORITY[globalLevel]
}

export function getLogger() {
  return {
    debug(message: string, context?: LogContext): void {
      if (shouldLog('debug')) {
        console.debug(`[DEBUG] ${message}`, context ?? '')
      }
    },
    info(message: string, context?: LogContext): void {
      if (shouldLog('info')) {
        console.log(`[INFO] ${message}`, context ?? '')
      }
    },
    warn(message: string, context?: LogContext): void {
      if (shouldLog('warn')) {
        console.warn(`[WARN] ${message}`, context ?? '')
      }
    },
    error(message: string, context?: LogContext): void {
      if (shouldLog('error')) {
        console.error(`[ERROR] ${message}`, context ?? '')
      }
    },
  }
}

export function setLogLevel(level: LogLevel): void {
  globalLevel = level
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]): string {
