/**
 * MCPBridge — MCP ↔ 现有架构适配层
 *
 * @description
 * 作为 MCP 架构与现有 DataBridge/Store 层之间的适配器，遵循 Strangler Fig 模式：
 * 1. 新代码通过 MCPClient 调用 MCP Server 的 Tool/Resource
 * 2. MCP Server 内部委托现有 Service 层执行
 * 3. Store 层数据通过 MCPBridge 同步到 MCP Resource
 * 4. 数据写入通过 DataBridge 保持一致性
 *
 * @module mcp/bridge/mcpBridge
 * @created 2026-07-04 - Phase 1 MCP 适配层建设
 */

import { getLogger } from '@/lib/logger'
import { MCPClientImpl } from '@/mcp/core/client'
import type { MCPClient, ToolResult, ResourceContent, PromptMessage } from '@/mcp/core/types'
import { mcpRegistry } from '@/mcp/core/registry'
import { mcpAuditLogger } from '@/mcp/core/mcpAuditLogger'

const logger = getLogger()

/** MCPBridge 单例 */
export class MCPBridge {
  private static instance: MCPBridge | null = null
  private client: MCPClientImpl

  private constructor() {
    this.client = new MCPClientImpl(mcpRegistry)
    logger.info('[MCPBridge] initialized')
  }

  /** 获取 MCPBridge 单例 */
  static getInstance(): MCPBridge {
    if (!MCPBridge.instance) {
      MCPBridge.instance = new MCPBridge()
    }
    return MCPBridge.instance
  }

  /** 获取 MCP Client（用于直接调用 Tool/Resource/Prompt） */
  getClient(): MCPClient {
    return this.client
  }

  /** 便捷方法：调用 Tool */
  async callTool(
    serverName: string,
    toolName: string,
    args: Record<string, unknown>,
  ): Promise<ToolResult> {
    const traceId = `mcp-${Date.now()}-${toolName}`
    const startTime = performance.now()

    try {
      const result = await this.client.callTool(serverName, toolName, args)
      const durationMs = performance.now() - startTime
      await mcpAuditLogger.logToolCall(serverName, toolName, args, result, traceId, durationMs)
      return result
    } catch (err) {
      const errorResult: ToolResult = {
        content: [{ type: 'text', text: err instanceof Error ? err.message : String(err) }],
        isError: true,
      }
      const durationMs = performance.now() - startTime
      await mcpAuditLogger.logToolCall(serverName, toolName, args, errorResult, traceId, durationMs)
      return errorResult
    }
  }

  /** 便捷方法：读取 Resource */
  async readResource(uri: string): Promise<ResourceContent> {
    return this.client.readResource(uri)
  }

  /** 便捷方法：获取 Prompt */
  async getPrompt(
    serverName: string,
    promptName: string,
    args: Record<string, string>,
  ): Promise<PromptMessage[]> {
    return this.client.getPrompt(serverName, promptName, args)
  }

  /** 列出所有工具（供 Agent 发现） */
  listAllTools() {
    return this.client.listAllTools()
  }

  /** 列出所有资源（供 Agent 发现） */
  listAllResources() {
    return this.client.listAllResources()
  }

  /** 列出所有 Prompt 模板（供 Agent 发现） */
  listAllPrompts() {
    return this.client.listAllPrompts()
  }

  /** 获取注册统计信息 */
  getStats() {
    return mcpRegistry.getStats()
  }
}

/** 全局 MCPBridge 单例 */
export const mcpBridge = MCPBridge.getInstance()

/**
 * @module mcp/core/elicitation
 * @description MCP Elicitation 管理器 — Server 向用户请求交互式输入
 * @created 2026-07-04
 */

import type { ElicitationRequest, ElicitationResponse } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 用户输入处理器类型 */
type ElicitationHandler = (request: ElicitationRequest) => Promise<ElicitationResponse>

/** Elicitation 管理器 — 单例模式 */
export class ElicitationManager {
  private handler: ElicitationHandler | null = null
  private pendingRequests = new Map<
    string,
    {
      resolve: (response: ElicitationResponse) => void
      reject: (error: Error) => void
      timeout: ReturnType<typeof setTimeout>
    }
  >()

  /** 注册用户输入处理器 */
  setHandler(handler: ElicitationHandler): void {
    this.handler = handler
    logger.info('[ElicitationManager] Handler registered')
  }

  /** 发起交互式请求 */
  async request(request: ElicitationRequest): Promise<ElicitationResponse> {
    const requestId = `elicitation-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
    logger.info('[ElicitationManager] Request initiated', { requestId, message: request.message })

    if (!this.handler) {
      logger.error('[ElicitationManager] No handler registered')
      throw new Error('Elicitation handler not configured')
    }

    const timeoutMs = request.timeout ?? 30000

    return new Promise<ElicitationResponse>((resolve, reject) => {
      const timeout = setTimeout(() => {
        this.pendingRequests.delete(requestId)
        logger.info('[ElicitationManager] Request timed out', { requestId })
        reject(new Error(`Elicitation request timed out after ${timeoutMs}ms`))
      }, timeoutMs)

      this.pendingRequests.set(requestId, { resolve, reject, timeout })

      this.handler!(request)
        .then((response) => {
          clearTimeout(timeout)
          this.pendingRequests.delete(requestId)
          logger.info('[ElicitationManager] Response received', { requestId, action: response.action })
          resolve(response)
        })
        .catch((error) => {
          clearTimeout(timeout)
          this.pendingRequests.delete(requestId)
          logger.error('[ElicitationManager] Handler error', { requestId, error: String(error) })
          reject(error instanceof Error ? error : new Error(String(error)))
        })
    })
  }

  /** 获取待处理请求数 */
  getPendingCount(): number {
    return this.pendingRequests.size
  }
}

export const elicitationManager = new ElicitationManager()

/**
 * MCPAuditLogger — MCP Tool 调用审计日志模块
 *
 * @description
 * 记录所有 MCP Tool 调用的审计信息，包括调用时间、工具名称、参数、结果、耗时。
 * 通过 DataBridge.forward() 将审计日志以信封协议写入 executionLogs 存储，
 * 实现 MCP 层与 DataBridge 统一审计入口的集成。
 *
 * @module mcp/core/mcpAuditLogger
 * @created 2026-07-05 - 批次F MCP-DataBridge 集成
 */

import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID } from '@/config/dbConfig'
import { generateId } from '@/data/db'
import type { ToolResult } from '@/mcp/core/types'

const logger = getLogger()

/**
 * MCP Tool 调用审计记录
 */
export interface MCPToolAuditRecord {
  /** 唯一标识 */
  id: string
  /** 调用时间戳（ms） */
  timestamp: number
  /** MCP Server 名称 */
  serverName: string
  /** Tool 名称 */
  toolName: string
  /** 调用参数 */
  args: Record<string, unknown>
  /** 调用结果摘要（截取前 500 字符） */
  resultSummary: string
  /** 是否出错 */
  isError: boolean
  /** 耗时（ms） */
  durationMs: number
  /** 追踪 ID */
  traceId: string
}

/**
 * MCP 审计日志管理器
 *
 * 负责将所有 MCP Tool 调用记录为审计日志，
 * 通过 DataBridge.forward() 信封协议写入 executionLogs 存储。
 */
export class MCPAuditLogger {
  private static instance: MCPAuditLogger | null = null

  private constructor() {
    logger.info('[MCPAuditLogger] initialized')
  }

  /** 获取 MCPAuditLogger 单例 */
  static getInstance(): MCPAuditLogger {
    if (!MCPAuditLogger.instance) {
      MCPAuditLogger.instance = new MCPAuditLogger()
    }
    return MCPAuditLogger.instance
  }

  /**
   * 记录一次 MCP Tool 调用的审计日志。
   *
   * 将审计记录封装入 StandardEnvelope，通过 DataBridge.forward() 写入 executionLogs。
   * 写入失败时仅记录错误日志，不抛出异常（审计日志不应阻断主流程）。
   *
   * @param serverName - MCP Server 名称
   * @param toolName - Tool 名称
   * @param args - 调用参数
   * @param result - 调用结果
   * @param traceId - 追踪 ID
   * @param durationMs - 耗时（ms）
   */
  async logToolCall(
    serverName: string,
    toolName: string,
    args: Record<string, unknown>,
    result: ToolResult,
    traceId: string,
    durationMs: number,
  ): Promise<void> {
    const auditStartTime = performance.now()

    try {
      const now = Date.now()
      const resultText = result.content
        .map((c) => c.text ?? '')
        .join('\n')
      const resultSummary = resultText.length > 500
        ? resultText.slice(0, 500) + '...'
        : resultText

      const auditRecord: MCPToolAuditRecord = {
        id: generateId(),
        timestamp: now,
        serverName,
        toolName,
        args,
        resultSummary,
        isError: result.isError ?? false,
        durationMs,
        traceId,
      }

      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.system,
          target: ENVELOPE_TARGET.executionLogs,
          action: ENVELOPE_ACTION.saveExecutionLog,
          traceId,
        },
        auditRecord,
      )

      await dataBridge.forward(envelope)

      const auditDuration = performance.now() - auditStartTime
      logger.info(`[MCPAuditLogger] audit log forwarded: ${serverName}/${toolName}`, {
        traceId,
        durationMs,
        isError: result.isError,
        auditWriteMs: Math.round(auditDuration),
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[MCPAuditLogger] failed to forward audit log', {
        error: message,
        serverName,
        toolName,
        traceId,
      })
    }
  }
}

/** 全局 MCPAuditLogger 单例 */
export const mcpAuditLogger = MCPAuditLogger.getInstance()

/**
 * @module mcp/core/progress
 * @description MCP Progress 追踪器 — 长时间运行任务的进度通知
 * @created 2026-07-04
 */

import type { ProgressNotification } from '@/types/modules/mcp.types'
import { notificationManager } from './notification'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 单次进度追踪上下文 */
interface ProgressContext {
  token: string
  total: number
  current: number
  message?: string
  startedAt: number
}

/** Progress 追踪器 — 单例模式 */
export class ProgressTracker {
  private tracks = new Map<string, ProgressContext>()

  /** 开始追踪一个新任务 */
  start(token: string, total: number, message?: string): void {
    const ctx: ProgressContext = {
      token,
      total,
      current: 0,
      message,
      startedAt: Date.now(),
    }
    this.tracks.set(token, ctx)
    logger.info('[ProgressTracker] Task started', { token, total, message })
    this.emit(token, 0, total, message)
  }

  /** 更新进度 */
  update(token: string, current: number, message?: string): void {
    const ctx = this.tracks.get(token)
    if (!ctx) {
      logger.info('[ProgressTracker] Unknown token, ignoring update', { token })
      return
    }
    ctx.current = Math.min(current, ctx.total)
    if (message) ctx.message = message
    this.emit(token, ctx.current, ctx.total, ctx.message)
  }

  /** 增量更新进度（+n） */
  increment(token: string, delta: number, message?: string): void {
    const ctx = this.tracks.get(token)
    if (!ctx) return
    this.update(token, ctx.current + delta, message)
  }

  /** 完成任务 */
  complete(token: string, message?: string): void {
    const ctx = this.tracks.get(token)
    if (!ctx) return
    this.update(token, ctx.total, message ?? '完成')
    const duration = Date.now() - ctx.startedAt
    logger.info('[ProgressTracker] Task completed', { token, duration: `${duration}ms` })
    this.tracks.delete(token)
  }

  /** 获取进度 */
  getProgress(token: string): ProgressContext | undefined {
    return this.tracks.get(token)
  }

  /** 获取所有活跃追踪 */
  getAllActive(): ProgressContext[] {
    return Array.from(this.tracks.values())
  }

  /** 发送进度通知 */
  private emit(token: string, progress: number, total: number, message?: string): void {
    const notification: ProgressNotification = {
      progressToken: token,
      progress,
      total,
      message,
    }
    notificationManager.emit(
      'notifications/progress',
      notification as unknown as Record<string, unknown>,
    )
  }
}

export const progressTracker = new ProgressTracker()

/**
 * MCP 全局注册中心
 *
 * @description
 * 管理所有 MCP Server 的注册、查找、启停。
 * 支持按优先级排序，按名称查找，支持启用/禁用。
 *
 * @module mcp/core/registry
 * @created 2026-07-04 - Phase 0 MCP 基础设施层建设
 */

import { getLogger } from '@/lib/logger'
import type { MCPServer, ServerRegistrationOptions, RegisteredServer } from '@/types/modules/mcp.types'

const logger = getLogger()

/** 优先级排序权重 */
const PRIORITY_ORDER: Record<ServerRegistrationOptions['priority'], number> = {
  high: 0,
  medium: 1,
  low: 2,
}

/** MCP 全局注册中心 —— 单例模式 */
export class MCPRegistry {
  /** 已注册的 Server 映射 */
  private servers: Map<string, RegisteredServer> = new Map()

  /** 注册 Server */
  register(server: MCPServer, options: ServerRegistrationOptions): void {
    const name = server.info.name

    if (this.servers.has(name)) {
      logger.warn(`[MCPRegistry] server already registered: ${name}, replacing`)
    }

    this.servers.set(name, {
      server,
      options: { ...options, enabled: options.enabled ?? true },
      registeredAt: Date.now(),
    })

    logger.info(`[MCPRegistry] register() server: ${name}`, {
      priority: options.priority,
      version: server.info.version,
      tools: server.listTools().length,
      resources: server.listResources().length,
      prompts: server.listPrompts().length,
    })

    // 发送工具列表变更通知
    import('./notification').then(({ notificationManager: nm }) => {
      nm.emit('notifications/tools/list_changed', { serverName: server.info.name })
    })
  }

  /** 注销 Server */
  unregister(serverName: string): boolean {
    const existed = this.servers.has(serverName)
    if (existed) {
      this.servers.delete(serverName)
      logger.info(`[MCPRegistry] unregister() server: ${serverName}`)

      // 发送工具列表变更通知
      import('./notification').then(({ notificationManager: nm }) => {
        nm.emit('notifications/tools/list_changed', { serverName })
      })
    }
    return existed
  }

  /** 获取指定 Server */
  getServer(serverName: string): RegisteredServer | undefined {
    return this.servers.get(serverName)
  }

  /** 列出所有已注册的 Server（按优先级排序） */
  listServers(): RegisteredServer[] {
    const entries = Array.from(this.servers.values())
    entries.sort((a, b) => PRIORITY_ORDER[a.options.priority] - PRIORITY_ORDER[b.options.priority])
    return entries
  }

  /** 启用/禁用 Server */
  setEnabled(serverName: string, enabled: boolean): boolean {
    const entry = this.servers.get(serverName)
    if (!entry) {
      logger.error(`[MCPRegistry] setEnabled() server not found: ${serverName}`)
      return false
    }
    entry.options.enabled = enabled
    logger.info(`[MCPRegistry] setEnabled() server: ${serverName}, enabled=${enabled}`)
    return true
  }

  /** 获取注册统计信息 */
  getStats(): { totalServers: number; enabledServers: number; totalTools: number; totalResources: number; totalPrompts: number } {
    const entries = Array.from(this.servers.values())
    const enabled = entries.filter((e) => e.options.enabled !== false)

    let totalTools = 0
    let totalResources = 0
    let totalPrompts = 0

    for (const entry of enabled) {
      totalTools += entry.server.listTools().length
      totalResources += entry.server.listResources().length
      totalPrompts += entry.server.listPrompts().length
    }

    return {
      totalServers: entries.length,
      enabledServers: enabled.length,
      totalTools,
      totalResources,
      totalPrompts,
    }
  }
}

/** 全局单例注册中心 */
export const mcpRegistry = new MCPRegistry()

/**
 * @module mcp/core/roots
 * @description MCP Roots 管理器 — 客户端声明可访问的目录范围，Server 据此限制文件访问
 * @created 2026-07-04
 */

import type { RootDescriptor, ListRootsResult } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** Roots 管理器 — 单例模式 */
export class RootsManager {
  private roots: RootDescriptor[] = []

  /** 设置允许访问的根目录列表 */
  setRoots(roots: RootDescriptor[]): void {
    this.roots = [...roots]
    logger.info('[RootsManager] Roots updated', { count: roots.length, roots: roots.map((r) => r.uri) })
  }

  /** 添加单个根目录 */
  addRoot(root: RootDescriptor): void {
    if (this.roots.some((r) => r.uri === root.uri)) {
      logger.info('[RootsManager] Root already exists, skipping', { uri: root.uri })
      return
    }
    this.roots.push(root)
    logger.info('[RootsManager] Root added', { uri: root.uri })
  }

  /** 移除单个根目录 */
  removeRoot(uri: string): boolean {
    const idx = this.roots.findIndex((r) => r.uri === uri)
    if (idx === -1) return false
    this.roots.splice(idx, 1)
    logger.info('[RootsManager] Root removed', { uri })
    return true
  }

  /** 列出所有根目录 */
  listRoots(): ListRootsResult {
    return { roots: [...this.roots] }
  }

  /** 检查 URI 是否在允许的根目录范围内 */
  isAllowed(uri: string): boolean {
    if (this.roots.length === 0) {
      return true
    }
    const allowed = this.roots.some((root) => uri.startsWith(root.uri))
    if (!allowed) {
      logger.info('[RootsManager] URI blocked', { uri })
    }
    return allowed
  }
}

export const rootsManager = new RootsManager()

/**
 * MCP Server 基类
 *
 * @description
 * 提供 MCPServer 接口的默认实现，内置 Tool/Resource/Prompt 的注册与查找。
 * 业务 Server 继承此类并重写 getTools/getResources/getPrompts 方法。
 *
 * @module mcp/core/server
 * @created 2026-07-04 - Phase 0 MCP 基础设施层建设
 */

import { getLogger } from '@/lib/logger'
import type {
  MCPServer,
  ServerInfo,
  ToolDescriptor,
  ToolResult,
  ResourceTemplate,
  ResourceContent,
  PromptTemplate,
  PromptMessage,
} from '@/types/modules/mcp.types'

const logger = getLogger()

/** MCP Server 基类 —— 提供默认的工具/资源/Prompt 管理 */
export abstract class MCPServerBase implements MCPServer {
  abstract readonly info: ServerInfo

  /** 工具缓存（按 name 索引） */
  private toolCache: Map<string, ToolDescriptor> | null = null

  /** 资源缓存（按 name 索引） */
  private resourceCache: Map<string, ResourceTemplate> | null = null

  /** Prompt 缓存（按 name 索引） */
  private promptCache: Map<string, PromptTemplate> | null = null

  // ============================================================
  // 子类重写方法
  // ============================================================

  /** 子类重写：返回工具列表 */
  protected getTools(): ToolDescriptor[] {
    return []
  }

  /** 子类重写：返回资源模板列表 */
  protected getResources(): ResourceTemplate[] {
    return []
  }

  /** 子类重写：返回 Prompt 模板列表 */
  protected getPrompts(): PromptTemplate[] {
    return []
  }

  // ============================================================
  // 公共接口实现
  // ============================================================

  listTools(): ToolDescriptor[] {
    if (this.toolCache === null) {
      const tools = this.getTools()
      this.toolCache = new Map(tools.map((t) => [t.name, t]))
      logger.info(`[MCPServer:${this.info.name}] listTools() loaded ${tools.length} tools`)
    }
    return Array.from(this.toolCache.values())
  }

  async callTool(name: string, args: Record<string, unknown>): Promise<ToolResult> {
    const startTime = performance.now()
    const tools = this.listTools()
    const tool = tools.find((t) => t.name === name)

    if (!tool) {
      logger.error(`[MCPServer:${this.info.name}] callTool() tool not found: ${name}`)
      return {
        content: [{ type: 'text', text: `Tool not found: ${name}` }],
        isError: true,
      }
    }

    // P0-2 安全修复：调用前校验参数 schema，防止非法参数注入
    const validationErrors = this.validateToolArgs(tool, args)
    if (validationErrors.length > 0) {
      logger.error(`[MCPServer:${this.info.name}] callTool() validation failed: ${name}`, {
        errors: validationErrors,
      })
      return {
        content: [{ type: 'text', text: `Invalid parameters: ${validationErrors.join('; ')}` }],
        isError: true,
      }
    }

    try {
      logger.info(`[MCPServer:${this.info.name}] callTool() executing: ${name}`, { args })
      const result = await tool.handler(args)
      const duration = performance.now() - startTime
      logger.info(`[MCPServer:${this.info.name}] callTool() completed: ${name}`, {
        durationMs: Math.round(duration),
        isError: result.isError ?? false,
      })
      return result
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.error(`[MCPServer:${this.info.name}] callTool() failed: ${name}`, { error: message })
      return {
        content: [{ type: 'text', text: `Tool execution error: ${message}` }],
        isError: true,
      }
    }
  }

  listResources(): ResourceTemplate[] {
    if (this.resourceCache === null) {
      const resources = this.getResources()
      this.resourceCache = new Map(resources.map((r) => [r.name, r]))
      logger.info(`[MCPServer:${this.info.name}] listResources() loaded ${resources.length} resources`)
    }
    return Array.from(this.resourceCache.values())
  }

  async readResource(uri: string): Promise<ResourceContent> {
    const resources = this.listResources()

    for (const resource of resources) {
      const regex = this.uriTemplateToRegex(resource.uriTemplate)
      if (regex.test(uri)) {
        try {
          logger.info(`[MCPServer:${this.info.name}] readResource() reading: ${uri}`)
          return await resource.resolver(uri)
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error)
          logger.error(`[MCPServer:${this.info.name}] readResource() failed: ${uri}`, { error: message })
          return {
            uri,
            mimeType: 'text/plain',
            text: `Resource read error: ${message}`,
          }
        }
      }
    }

    logger.error(`[MCPServer:${this.info.name}] readResource() not found: ${uri}`)
    return {
      uri,
      mimeType: 'text/plain',
      text: `Resource not found: ${uri}`,
    }
  }

  listPrompts(): PromptTemplate[] {
    if (this.promptCache === null) {
      const prompts = this.getPrompts()
      this.promptCache = new Map(prompts.map((p) => [p.name, p]))
      logger.info(`[MCPServer:${this.info.name}] listPrompts() loaded ${prompts.length} prompts`)
    }
    return Array.from(this.promptCache.values())
  }

  async getPrompt(name: string, args: Record<string, string>): Promise<PromptMessage[]> {
    const prompts = this.listPrompts()
    const prompt = prompts.find((p) => p.name === name)

    if (!prompt) {
      logger.error(`[MCPServer:${this.info.name}] getPrompt() not found: ${name}`)
      return [{ role: 'user', content: { type: 'text', text: `Prompt not found: ${name}` } }]
    }

    try {
      logger.info(`[MCPServer:${this.info.name}] getPrompt() generating: ${name}`, { args })
      return await prompt.generator(args)
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.error(`[MCPServer:${this.info.name}] getPrompt() failed: ${name}`, { error: message })
      return [{ role: 'user', content: { type: 'text', text: `Prompt generation error: ${message}` } }]
    }
  }

  // ============================================================
  // 工具方法
  // ============================================================

  /**
   * 校验工具调用参数是否符合 inputSchema 定义。
   * 检查项：必填字段、类型匹配、枚举值约束。
   *
   * @returns 错误信息数组，空数组表示校验通过
   */
  private validateToolArgs(
    tool: ToolDescriptor,
    args: Record<string, unknown>,
  ): string[] {
    const errors: string[] = []
    const schema = tool.inputSchema

    if (!schema || schema.type !== 'object' || !schema.properties) {
      return errors // 无 schema 定义时跳过校验（向后兼容）
    }

    // 检查必填字段
    for (const required of schema.required ?? []) {
      if (!(required in args)) {
        errors.push(`missing required parameter: "${required}"`)
      }
    }

    // 检查类型与枚举
    for (const [key, value] of Object.entries(args)) {
      const prop = schema.properties[key]
      if (!prop) continue // 未知参数不阻断（允许扩展）

      const actualType = Array.isArray(value) ? 'array' : typeof value
      if (value !== null && value !== undefined && actualType !== prop.type) {
        errors.push(`parameter "${key}" expected ${prop.type}, got ${actualType}`)
      }

      if (prop.enum && !prop.enum.includes(value as string)) {
        errors.push(`parameter "${key}" must be one of [${prop.enum.join(', ')}]`)
      }
    }

    return errors
  }

  /** 将 URI 模板转换为正则表达式 */
  private uriTemplateToRegex(template: string): RegExp {
    const escaped = template
      .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      .replace(/\\\{([^}]+)\\}/g, '([^/]+)')
    return new RegExp(`^${escaped}$`)
  }
}

/**
 * MCP 传输层 —— 进程内零拷贝传输实现
 *
 * @description
 * 同进程内的 MCP Server 调用使用 InProcessTransport，直接传递引用而非序列化，
 * 确保性能不退化。未来扩展跨进程调用时，可新增 JSONRPCTransport 实现。
 *
 * @module mcp/core/transport
 * @created 2026-07-04 - Phase 0 MCP 基础设施层建设
 */

import type { MCPTransport, MCPServer, NotificationMethod, SamplingRequest } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 进程内传输 —— 零拷贝，直接调用 Server 方法 */
export class InProcessTransport implements MCPTransport {
  private server: MCPServer
  private closed = false

  constructor(server: MCPServer) {
    this.server = server
    logger.info(`[InProcessTransport] created for server: ${server.info.name}`)
  }

  async sendRequest(method: string, params?: Record<string, unknown>): Promise<unknown> {
    if (this.closed) {
      throw new Error('Transport is closed')
    }

    const startTime = performance.now()

    switch (method) {
      case 'tools/list': {
        const tools = this.server.listTools()
        logger.info(`[InProcessTransport] tools/list returned ${tools.length} tools`)
        return { tools }
      }

      case 'tools/call': {
        if (!params || typeof params.name !== 'string') {
          throw new Error('Missing required param: name')
        }
        const args = (params.arguments as Record<string, unknown>) ?? {}
        const result = await this.server.callTool(params.name, args)
        const duration = performance.now() - startTime
        logger.info(`[InProcessTransport] tools/call ${params.name} completed in ${Math.round(duration)}ms`)
        return result
      }

      case 'resources/list': {
        const resources = this.server.listResources()
        return { resources }
      }

      case 'resources/read': {
        if (!params || typeof params.uri !== 'string') {
          throw new Error('Missing required param: uri')
        }
        return await this.server.readResource(params.uri)
      }

      case 'prompts/list': {
        const prompts = this.server.listPrompts()
        return { prompts }
      }

      case 'prompts/get': {
        if (!params || typeof params.name !== 'string') {
          throw new Error('Missing required param: name')
        }
        const args = (params.arguments as Record<string, string>) ?? {}
        return {
          messages: await this.server.getPrompt(params.name, args),
        }
      }

      case 'roots/list': {
        const { rootsManager: rm } = await import('./roots')
        return rm.listRoots()
      }

      case 'elicitation/request': {
        if (!params || typeof params.message !== 'string') {
          throw new Error('Missing required param: message')
        }
        const { elicitationManager: em } = await import('./elicitation')
        return em.request(params as unknown as import('@/types/modules/mcp.types').ElicitationRequest)
      }

      case 'sampling/createMessage': {
        const { samplingHandler } = await import('./sampling')
        return samplingHandler.createMessage(params as unknown as SamplingRequest)
      }

      default:
        throw new Error(`Unknown method: ${method}`)
    }
  }

  async sendNotification(method: string, params?: Record<string, unknown>): Promise<void> {
    const { notificationManager: nm } = await import('./notification')
    nm.emit(method as NotificationMethod, params)
  }

  close(): void {
    this.closed = true
    logger.info(`[InProcessTransport] closed for server: ${this.server.info.name}`)
  }
}

/**
 * MCP Server 配置驱动注册与热更新
 *
 * @description
 * 从 `src/config/mcpServerRegistry.ts` 读取 Server 清单，
 * 通过 import.meta.glob (eager) 同步加载模块并按配置自动注册到 MCPRegistry。
 *
 * 核心能力：
 *   - 副作用导入 `import '@/mcp/register'` → 同步全量注册（向后兼容）
 *   - `syncWithConfig()` → 增量同步（配置变更后调用，添加/移除 Server）
 *
 * @module mcp/register
 */

import { mcpRegistry } from '@/mcp/core/registry'
import { MCP_SERVER_REGISTRY, type MCPServerModule } from '@/config/mcpServerRegistry'
import { getLogger } from '@/lib/logger'
import type { MCPServer } from '@/types/modules/mcp.types'

const logger = getLogger()

// ============================================================
// Vite 静态模块扫描（构建时确定所有 Server 模块，eager 同步加载）
// ============================================================

/**
 * 使用 import.meta.glob (eager) 同步加载所有 Server 模块
 *
 * Vite 在构建时静态分析 glob 模式，将匹配文件打包。
 * eager: true 确保导入时所有模块已同步加载，可直接访问导出。
 */
const serverModules = import.meta.glob<MCPServerModule>(
  './servers/**/*.ts',
  { eager: true },
)

/**
 * 将配置中的 modulePath（@/别名路径）映射为 glob key（相对路径）
 *
 * 例：`@/mcp/servers/fetcher/dataFetcherServer` → `./servers/fetcher/dataFetcherServer.ts`
 */
function configPathToGlobKey(modulePath: string): string {
  return modulePath.replace(/^@\/mcp\//, './').replace(/\.ts$/, '') + '.ts'
}

/**
 * 从预加载模块中实例化 Server
 *
 * @param modulePath - 配置中的模块路径（@/别名格式）
 * @param exportName - 导出类名
 * @returns MCPServer 实例，加载失败返回 null
 */
function instantiateServer(
  modulePath: string,
  exportName: string,
): MCPServer | null {
  const globKey = configPathToGlobKey(modulePath)
  const mod = serverModules[globKey]

  if (!mod) {
    logger.error(`[MCP:register] module not found in glob: ${globKey}`, {
      originalPath: modulePath,
      availableKeys: Object.keys(serverModules),
    })
    return null
  }

  try {
    const ServerCtor = mod[exportName]
    if (typeof ServerCtor !== 'function') {
      logger.error(`[MCP:register] export "${exportName}" not found in ${globKey}`)
      return null
    }

    const instance = new ServerCtor() as MCPServer

    if (!instance.info || !instance.listTools) {
      logger.error(`[MCP:register] "${exportName}" does not implement MCPServer interface`)
      return null
    }

    return instance
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[MCP:register] failed to instantiate ${globKey}`, { error: message })
    return null
  }
}

// ============================================================
// 全量注册（同步）
// ============================================================

/**
 * 从配置清单全量注册所有 MCP Server
 *
 * 按配置顺序依次实例化并注册，跳过 enabled: false 的条目。
 * 使用 eager glob 确保同步完成，适合副作用导入。
 */
export function registerAllServers(): void {
  logger.info('[MCP:register] starting config-driven registration...', {
    totalEntries: MCP_SERVER_REGISTRY.length,
    enabledEntries: MCP_SERVER_REGISTRY.filter((e) => e.enabled).length,
    availableModules: Object.keys(serverModules).length,
  })

  for (const entry of MCP_SERVER_REGISTRY) {
    if (!entry.enabled) {
      logger.info(`[MCP:register] skipped (disabled): ${entry.name}`)
      continue
    }

    const server = instantiateServer(entry.modulePath, entry.exportName)
    if (server) {
      mcpRegistry.register(server, { priority: entry.priority })
    }
  }

  const stats = mcpRegistry.getStats()
  logger.info('[MCP:register] registration complete', stats)
}

// ============================================================
// 增量同步（热更新）
// ============================================================

/**
 * 增量同步：对比配置清单与当前 Registry，执行最小变更
 *
 * 操作逻辑：
 *   1. 配置中存在但 Registry 中不存在 → 新增注册
 *   2. Registry 中存在但配置中不存在 → 注销
 *   3. 配置中 enabled: false 但 Registry 中存在 → 注销
 *   4. 其余情况 → 跳过（不重复注册）
 *
 * @returns 同步结果摘要
 */
export function syncWithConfig(): SyncResult {
  const result: SyncResult = { added: [], removed: [], skipped: [], failed: [] }

  const configNames = new Set<string>()
  const registeredNames = new Set(
    mcpRegistry.listServers().map((rs) => rs.server.info.name),
  )

  // Step 1: 处理配置中的条目
  for (const entry of MCP_SERVER_REGISTRY) {
    configNames.add(entry.name)

    if (!entry.enabled) {
      // 配置中禁用但 Registry 中存在 → 注销
      if (registeredNames.has(entry.name)) {
        mcpRegistry.unregister(entry.name)
        result.removed.push(entry.name)
        logger.info(`[MCP:sync] disabled & unregistered: ${entry.name}`)
      }
      continue
    }

    if (registeredNames.has(entry.name)) {
      result.skipped.push(entry.name)
      continue
    }

    // 新增注册
    const server = instantiateServer(entry.modulePath, entry.exportName)
    if (server) {
      mcpRegistry.register(server, { priority: entry.priority })
      result.added.push(entry.name)
    } else {
      result.failed.push(entry.name)
    }
  }

  // Step 2: 注销 Registry 中存在但配置中不存在的 Server
  for (const name of registeredNames) {
    if (!configNames.has(name)) {
      mcpRegistry.unregister(name)
      result.removed.push(name)
      logger.info(`[MCP:sync] not in config & unregistered: ${name}`)
    }
  }

  logger.info('[MCP:sync] complete', {
    added: result.added.length,
    removed: result.removed.length,
    skipped: result.skipped.length,
    failed: result.failed.length,
  })

  return result
}

/** 增量同步结果 */
export interface SyncResult {
  /** 新增注册的 Server 名称 */
  added: string[]
  /** 注销的 Server 名称 */
  removed: string[]
  /** 已存在跳过的 Server 名称 */
  skipped: string[]
  /** 加载失败的 Server 名称 */
  failed: string[]
}

// ============================================================
// 自动注册（副作用导入兼容）
// ============================================================

/**
 * 副作用导入时自动触发全量注册
 * 保留与原 register.ts 的向后兼容：`import '@/mcp/register'`
 */
registerAllServers()

/**
 * @module mcp/servers/analysis
 * @description 分析引擎 MCP Server — 暴露个股分析、板块分析、筛选等工具
 * @created 2026-07-04
 */

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor, ResourceTemplate, PromptTemplate } from '@/mcp/core/types'
import { getLogger } from '@/lib/logger'
import { listStocks, listV6Scores } from '@/services/analysis/analysisService'
import { calculateAndSaveDefaultRotationScores } from '@/services/analysis/sectorAnalysisEngine'
import { runScreening } from '@/services/analysis/screeningEngine'

const logger = getLogger()

export class AnalysisServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'analysis',
    version: '1.0.0',
    description: '分析引擎 — 个股分析、板块分析、股票筛选',
    dependencies: ['scoring:v6', 'fetcher'],
  }

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'analyze_stock',
        description: '查询个股 V6 评分及基本信息',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码，如 000001' },
          },
          required: ['symbol'],
        },
        handler: async (args) => {
          const symbol = args.symbol as string
          logger.info('[AnalysisServer] analyze_stock called', { symbol })
          const [stocksResult, scoresResult] = await Promise.all([
            listStocks(),
            listV6Scores(),
          ])
          const stock = stocksResult.success && stocksResult.data
            ? stocksResult.data.find((s) => s.symbol === symbol)
            : null
          const scores = scoresResult.success && scoresResult.data
            ? scoresResult.data.filter((s) => s.symbol === symbol)
            : []
          const result = {
            symbol,
            stock,
            scores,
            scoreCount: scores.length,
          }
          return {
            content: [{ type: 'text', text: JSON.stringify(result) }],
          }
        },
      },
      {
        name: 'analyze_sector',
        description: '执行行业/板块轮动分析',
        inputSchema: {
          type: 'object',
          properties: {
            scoreDate: { type: 'string', description: '评分日期 (YYYY-MM-DD)，默认今天' },
          },
          required: [],
        },
        handler: async (args) => {
          logger.info('[AnalysisServer] analyze_sector called', {
            scoreDate: args.scoreDate as string | undefined,
          })
          const result = await calculateAndSaveDefaultRotationScores(
            args.scoreDate as string | undefined,
          )
          return {
            content: [{ type: 'text', text: JSON.stringify(result) }],
          }
        },
      },
      {
        name: 'screen_stocks',
        description: '按多因子条件筛选股票',
        inputSchema: {
          type: 'object',
          properties: {
            limit: { type: 'number', description: '返回数量上限', default: 20 },
          },
          required: [],
        },
        handler: async (_args) => {
          logger.info('[AnalysisServer] screen_stocks called')
          const result = await runScreening()
          return {
            content: [{ type: 'text', text: JSON.stringify(result) }],
          }
        },
      },
    ]
  }

  protected getResources(): ResourceTemplate[] {
    return [
      {
        uriTemplate: 'analysis://stock/{symbol}',
        name: '个股分析数据',
        description: '指定股票的 V6 评分及基本信息',
        mimeType: 'application/json',
        resolver: async (uri) => {
          const symbol = uri.split('/').pop() ?? ''
          const [stocksResult, scoresResult] = await Promise.all([
            listStocks(),
            listV6Scores(),
          ])
          const stock = stocksResult.success && stocksResult.data
            ? stocksResult.data.find((s) => s.symbol === symbol)
            : null
          const scores = scoresResult.success && scoresResult.data
            ? scoresResult.data.filter((s) => s.symbol === symbol)
            : []
          return {
            uri,
            mimeType: 'application/json',
            text: JSON.stringify({ symbol, stock, scores }),
          }
        },
      },
      {
        uriTemplate: 'analysis://sector/{scoreDate}',
        name: '板块分析数据',
        description: '指定日期的板块轮动分析结果',
        mimeType: 'application/json',
        resolver: async (uri) => {
          const scoreDate = uri.split('/').pop() ?? undefined
          const result = await calculateAndSaveDefaultRotationScores(scoreDate)
          return { uri, mimeType: 'application/json', text: JSON.stringify(result) }
        },
      },
    ]
  }

  protected getPrompts(): PromptTemplate[] {
    return [
      {
        name: 'stock_analysis',
        description: '个股分析报告生成模板',
        arguments: [
          { name: 'symbol', description: '股票代码', required: true },
        ],
        generator: async (args) => {
          return [{
            role: 'user',
            content: {
              type: 'text',
              text: `请对股票 ${args.symbol} 进行全面的投研分析，包括：评分概况、护城河评估、财务健康度、估值水平、情景推演、技术面筹码分析。`,
            },
          }]
        },
      },
    ]
  }
}

/**
 * @module mcp/servers/backtest
 * @description 回测引擎 MCP Server — 策略回测、绩效分析
 * @created 2026-07-04
 */

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor, ResourceTemplate } from '@/mcp/core/types'
import { getLogger } from '@/lib/logger'
import { BacktestEngine } from '@/services/backtest/BacktestEngine'
import type { BacktestStrategy } from '@/store/backtestStore'

const logger = getLogger()

const DEFAULT_BACKTEST_CONFIG = {
  initialCapital: 100000,
  commissionRate: 0.0003,
  slippage: 0.001,
  maxPositionPct: 0.3,
}

export class BacktestServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'backtest',
    version: '1.0.0',
    description: '回测引擎 — 策略回测、绩效分析、风险指标',
    dependencies: ['fetcher', 'scoring:v6'],
  }

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'run_backtest',
        description: '执行策略回测',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
            startDate: { type: 'string', description: '开始日期 (YYYY-MM-DD)' },
            endDate: { type: 'string', description: '结束日期 (YYYY-MM-DD)' },
            strategy: { type: 'string', description: '策略名称', default: 'v6_scoring' },
            initialCapital: { type: 'number', description: '初始资金', default: 100000 },
          },
          required: ['symbol', 'startDate', 'endDate'],
        },
        handler: async (args) => {
          logger.info('[BacktestServer] run_backtest called', { symbol: args.symbol as string })
          const engine = new BacktestEngine()
          const result = await engine.run({
            strategy: ((args.strategy as string) ?? 'composite') as BacktestStrategy,
            startDate: args.startDate as string,
            endDate: args.endDate as string,
            initialCapital: (args.initialCapital as number) ?? DEFAULT_BACKTEST_CONFIG.initialCapital,
            commissionRate: DEFAULT_BACKTEST_CONFIG.commissionRate,
            slippage: DEFAULT_BACKTEST_CONFIG.slippage,
            maxPositionPct: DEFAULT_BACKTEST_CONFIG.maxPositionPct,
          })
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
    ]
  }

  protected getResources(): ResourceTemplate[] {
    return [
      {
        uriTemplate: 'backtest://config',
        name: '回测默认配置',
        description: '回测引擎默认配置参数',
        mimeType: 'application/json',
        resolver: async (uri) => {
          return { uri, mimeType: 'application/json', text: JSON.stringify(DEFAULT_BACKTEST_CONFIG) }
        },
      },
    ]
  }
}

