/**
 * DataFetcherServer — 数据采集 MCP Server
 *
 * @description
 * 封装行情数据获取、K线数据采集、基础数据查询等数据采集能力。
 * 支持 AkShare（远程）和 Mock（本地）两种数据源，通过 DataSourceRegistry 自动切换。
 *
 * @module mcp/servers/fetcher/dataFetcherServer
 * @created 2026-07-04 - Phase 1 MCP 核心业务 Server 迁移
 */

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor, ResourceTemplate } from '@/mcp/core/types'
import { getLogger } from '@/lib/logger'
import {
  fetchStockBasic,
  fetchStocksBasic,
  fetchStockKline,
  refreshSymbol,
  checkFetcherHealth,
} from '@/services/fetcher/fetcherService'
import { DataSourceRegistry } from '@/services/fetcher/dataSourceRegistry'
import { AkshareProvider } from '@/services/fetcher/akshareProvider'
import { MockProvider } from '@/services/fetcher/mockProvider'
import type { DataSourceProvider } from '@/services/fetcher/types'

const logger = getLogger()

// ============================================================
// DataSourceRegistry 单例（Lazy 初始化，注册 AkShare + Mock providers）
// 修复 P0 类型错误：原代码引用不存在的 getDataSourceRegistry 工厂函数
// ============================================================

let _registry: DataSourceRegistry | null = null

function getDataSourceRegistry(): DataSourceRegistry {
  if (!_registry) {
    _registry = new DataSourceRegistry()
    _registry.register(new AkshareProvider())
    _registry.register(new MockProvider())
    logger.info('[fetcher] DataSourceRegistry initialized with AkShare + Mock providers')
  }
  return _registry
}

export class DataFetcherServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'fetcher',
    version: '1.0.0',
    description: '数据采集服务，支持 AkShare/Mock 数据源，提供行情、K线、基本面数据获取',
    dependencies: [],
  }

  // ============================================================
  // Tool 定义
  // ============================================================

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'fetch_stock_basic',
        description: '获取单只股票的基础信息（名称、价格、PE、PB、ROE、市值等）',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码，如 000001' },
          },
          required: ['symbol'],
        },
        handler: async (args) => {
          const symbol = args.symbol as string
          logger.info(`[fetcher] fetch_stock_basic: ${symbol}`)
          const result = await fetchStockBasic(symbol)
          return {
            content: [{ type: 'text', text: JSON.stringify(result, null, 2) }],
            isError: !result.success,
          }
        },
      },
      {
        name: 'fetch_stocks_basic',
        description: '批量获取多只股票的基础信息',
        inputSchema: {
          type: 'object',
          properties: {
            symbols: {
              type: 'array',
              description: '股票代码列表',
              items: { type: 'string' },
            },
          },
          required: ['symbols'],
        },
        handler: async (args) => {
          const symbols = args.symbols as string[]
          logger.info(`[fetcher] fetch_stocks_basic: ${symbols.length} symbols`)
          const result = await fetchStocksBasic(symbols)
          return {
            content: [{ type: 'text', text: JSON.stringify(result, null, 2) }],
            isError: !result.success,
          }
        },
      },
      {
        name: 'fetch_kline',
        description: '获取股票 K 线数据（日线/周线/月线，支持前复权/后复权）',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
            period: { type: 'string', enum: ['daily', 'weekly', 'monthly'], description: '周期', default: 'daily' },
            adjust: { type: 'string', enum: ['qfq', 'hfq', ''], description: '复权方式', default: 'qfq' },
            startDate: { type: 'string', description: '起始日期，格式 YYYY-MM-DD' },
            endDate: { type: 'string', description: '结束日期，格式 YYYY-MM-DD' },
          },
          required: ['symbol'],
        },
        handler: async (args) => {
          const symbol = args.symbol as string
          const options = {
            period: (args.period as 'daily' | 'weekly' | 'monthly') ?? 'daily',
            adjust: (args.adjust as 'qfq' | 'hfq' | '') ?? 'qfq',
            startDate: args.startDate as string | undefined,
            endDate: args.endDate as string | undefined,
          }
          logger.info(`[fetcher] fetch_kline: ${symbol}`, options)
          const result = await fetchStockKline(symbol, options)
          return {
            content: [{ type: 'text', text: JSON.stringify(result, null, 2) }],
            isError: !result.success,
          }
        },
      },
      {
        name: 'refresh_symbol',
        description: '刷新单只股票的全部数据（基础信息 + K线）',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
          },
          required: ['symbol'],
        },
        handler: async (args) => {
          const symbol = args.symbol as string
          logger.info(`[fetcher] refresh_symbol: ${symbol}`)
          const result = await refreshSymbol(symbol)
          return {
            content: [{ type: 'text', text: JSON.stringify(result, null, 2) }],
            isError: !result.success,
          }
        },
      },
      {
        name: 'health_check',
        description: '检查数据采集服务健康状态，返回各数据源状态',
        inputSchema: { type: 'object', properties: {} },
        handler: async () => {
          logger.info('[fetcher] health_check')
          const fetcherHealth = await checkFetcherHealth()
          const registry = getDataSourceRegistry()
          const providers = registry.getAllProviders()
          const providerStatuses = await Promise.all(
            providers.map(async (p: DataSourceProvider) => ({
              name: p.name,
              status: await p.healthCheck(),
            })),
          )
          return {
            content: [{
              type: 'text',
              text: JSON.stringify({ fetcher: fetcherHealth, providers: providerStatuses }, null, 2),
            }],
          }
        },
      },
    ]
  }

  // ============================================================
  // Resource 模板
  // ============================================================

  protected getResources(): ResourceTemplate[] {
    return [
      {
        uriTemplate: 'fetcher://{symbol}/basic',
        name: 'stock_basic',
        description: '股票基础信息',
        mimeType: 'application/json',
        resolver: async (uri) => {
          const symbol = uri.split('/')[2] ?? ''
          if (!symbol) {
            logger.warn('[fetcher] resource basic: missing symbol in URI', { uri })
          }
          logger.info(`[fetcher] resource: fetcher://${symbol}/basic`)
          const result = await fetchStockBasic(symbol)
          return {
            uri,
            mimeType: 'application/json',
            text: JSON.stringify(result),
          }
        },
      },
      {
        uriTemplate: 'fetcher://{symbol}/kline',
        name: 'stock_kline',
        description: '股票 K 线数据',
        mimeType: 'application/json',
        resolver: async (uri) => {
          const symbol = uri.split('/')[2] ?? ''
          if (!symbol) {
            logger.warn('[fetcher] resource kline: missing symbol in URI', { uri })
          }
          logger.info(`[fetcher] resource: fetcher://${symbol}/kline`)
          const result = await fetchStockKline(symbol, { period: 'daily', adjust: 'qfq' })
          return {
            uri,
            mimeType: 'application/json',
            text: JSON.stringify(result),
          }
        },
      },
      {
        uriTemplate: 'fetcher://health',
        name: 'health_status',
        description: '数据采集服务健康状态',
        mimeType: 'application/json',
        resolver: async (uri) => {
          const health = await checkFetcherHealth()
          const registry = getDataSourceRegistry()
          const providers = registry.getAllProviders()
          const providerStatuses = await Promise.all(
            providers.map(async (p: DataSourceProvider) => ({
              name: p.name,
              status: await p.healthCheck(),
            })),
          )
          return {
            uri,
            mimeType: 'application/json',
            text: JSON.stringify({ fetcher: health, providers: providerStatuses }),
          }
        },
      },
    ]
  }
}

/**
 * @module mcp/servers/input
 * @description 数据录入 MCP Server — 股票添加、搜索、股票池导入导出
 * @created 2026-07-05
 */

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'
import {
  addStock,
  addStockFromSearch,
  searchStocks,
  exportPool,
  importPool,
  listStocks,
} from '@/services/input/inputService'

const logger = getLogger()

export class InputServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'input',
    version: '1.0.0',
    description: '数据录入 — 股票添加、搜索、股票池导入导出',
    dependencies: ['fetcher'],
  }

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'add_stock',
        description: '添加股票到股票池',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
            name: { type: 'string', description: '股票名称' },
            poolId: { type: 'string', description: '目标股票池 ID（可选）' },
          },
          required: ['symbol', 'name'],
        },
        handler: async (args) => {
          logger.info('[InputServer] add_stock called', { symbol: args.symbol })
          const result = await addStock({
            symbol: args.symbol as string,
            name: args.name as string,
          })
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
      {
        name: 'search_stocks',
        description: '搜索股票',
        inputSchema: {
          type: 'object',
          properties: {
            query: { type: 'string', description: '搜索关键词（代码或名称）' },
          },
          required: ['query'],
        },
        handler: async (args) => {
          const query = args.query as string
          logger.info('[InputServer] search_stocks called', { query })
          const results = searchStocks(query)
          return { content: [{ type: 'text', text: JSON.stringify(results) }] }
        },
      },
      {
        name: 'add_stock_from_search',
        description: '从搜索结果添加股票',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
          },
          required: ['symbol'],
        },
        handler: async (args) => {
          const symbol = args.symbol as string
          logger.info('[InputServer] add_stock_from_search called', { symbol })
          const matches = searchStocks(symbol)
          const match = matches.find((m) => m.symbol === symbol) ?? matches[0]
          if (!match) {
            return { content: [{ type: 'text', text: JSON.stringify({ error: `未找到股票: ${symbol}` }) }] }
          }
          const result = await addStockFromSearch(match)
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
      {
        name: 'list_input_stocks',
        description: '列出已录入的股票',
        inputSchema: { type: 'object', properties: {} },
        handler: async () => {
          logger.info('[InputServer] list_input_stocks called')
          const result = await listStocks()
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
      {
        name: 'export_stock_pool',
        description: '导出股票池（按研究状态筛选）',
        inputSchema: {
          type: 'object',
          properties: {
            status: { type: 'string', description: '研究状态（可选，如 candidate/analyzed/invested）' },
          },
        },
        handler: async (args) => {
          // TODO: exportPool 接受 ResearchStatus 筛选，非 poolId；当前忽略 poolId 导出全量
          logger.info('[InputServer] export_stock_pool called', { status: args.status })
          const result = await exportPool()
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
      {
        name: 'import_stock_pool',
        description: '导入股票池',
        inputSchema: {
          type: 'object',
          properties: {
            payload: { type: 'object', description: '导入数据' },
          },
          required: ['payload'],
        },
        handler: async (args) => {
          logger.info('[InputServer] import_stock_pool called')
          const result = await importPool(args.payload as never)
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
    ]
  }
}

/**
