          }
          const result = await fetchHoldings(queryParams)
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
      {
        name: 'execute_trade_action',
        description: '执行交易操作（买入/卖出）',
        inputSchema: {
          type: 'object',
          properties: {
