  const setReportText = useIntelligentScoreStore((s) => s.setReportText)
  const setLlmConfig = useIntelligentScoreStore((s) => s.setLlmConfig)
  const setShowConfig = useIntelligentScoreStore((s) => s.setShowConfig)
