  )
}

import React, { useEffect } from 'react'
import { useParams } from 'react-router'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import { ScoreHistoryPanel } from '@/components/analysis/score/ScoreHistoryPanel'
import { useStockAnalysisStore } from '@/store/stockAnalysisStore'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

export default function StockAnalysisPage(): React.JSX.Element {
  const { symbol } = useParams<{ symbol?: string }>()

  // 从 Store 获取状态
  const stock = useStockAnalysisStore((s) => s.stock)
  const quotes = useStockAnalysisStore((s) => s.quotes)
  const score = useStockAnalysisStore((s) => s.v6Score)
  const scoreLoading = useStockAnalysisStore((s) => s.scoreLoading)

  // 从 Store 获取 actions
  const loadStockAnalysis = useStockAnalysisStore((s) => s.loadStockAnalysis)
  const refreshScore = useStockAnalysisStore((s) => s.refreshScore)

  // 监听 symbol 变化，加载数据
  useEffect(() => {
    if (!symbol) return

    logger.info('[StockAnalysisPage] symbol 变化，开始加载数据', { symbol })

    // 创建 AbortController 用于取消请求
    const controller = new AbortController()

    loadStockAnalysis(symbol, controller.signal).then(() => {
      if (!controller.signal.aborted) {
        logger.info('[StockAnalysisPage] 数据加载完成', { symbol })
      }
    }).catch((err) => {
      if (!controller.signal.aborted) {
        logger.error('[StockAnalysisPage] 数据加载失败', { symbol, error: err.message })
      }
    })

    return () => {
      logger.info('[StockAnalysisPage] 取消加载', { symbol })
      controller.abort()
    }
  }, [symbol, loadStockAnalysis])

  // 刷新评分
  const handleScore = async (): Promise<void> => {
    if (!symbol) return

    logger.info('[StockAnalysisPage] 开始刷新 V6 评分', { symbol })

    try {
      await refreshScore(symbol)
      logger.info('[StockAnalysisPage] V6 评分刷新完成', { symbol })
    } catch (err) {
      logger.error('[StockAnalysisPage] V6 评分刷新失败', { symbol, error: err instanceof Error ? err.message : String(err) })
    }
  }

  return (
    <div className="p-4">
      <Card>
        <CardHeader>
          <CardTitle>个股分析</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {stock ? (
            <>
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-bold">{stock.symbol}</h2>
                  <p className="text-muted-foreground">{stock.name}</p>
                </div>
                <Badge variant="outline">{stock.researchStatus}</Badge>
              </div>

              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                <div className="rounded-md border p-3">
                  <p className="text-xs text-muted-foreground">最新价</p>
                  <p className="text-lg font-semibold">
                    {stock.price?.toFixed(2) ?? '—'}
                  </p>
                </div>
                <div className="rounded-md border p-3">
                  <p className="text-xs text-muted-foreground">PE</p>
                  <p className="text-lg font-semibold">
                    {stock.pe?.toFixed(2) ?? '—'}
                  </p>
                </div>
                <div className="rounded-md border p-3">
                  <p className="text-xs text-muted-foreground">PB</p>
                  <p className="text-lg font-semibold">
                    {stock.pb?.toFixed(2) ?? '—'}
                  </p>
                </div>
                <div className="rounded-md border p-3">
                  <p className="text-xs text-muted-foreground">K线数据</p>
                  <p className="text-lg font-semibold">
                    {quotes ? `${quotes.history.length} 条` : '—'}
                  </p>
                </div>
              </div>

              {quotes?.latest && (
                <div className="text-sm text-muted-foreground">
                  最新 K线 {quotes.latest.date}：开 {quotes.latest.open.toFixed(2)} / 高{' '}
                  {quotes.latest.high.toFixed(2)} / 低 {quotes.latest.low.toFixed(2)} / 收{' '}
                  {quotes.latest.close.toFixed(2)}
                </div>
              )}

              {score ? (
                <div className="rounded-md bg-muted p-4">
                  <p className="text-lg font-semibold">
                    V6 评分: {score.score.toFixed(2)} / 5.0
                  </p>
                  <div className="mt-2 grid gap-2 sm:grid-cols-3">
                    {Object.entries(score.factors).map(([key, value]) => (
                      <div key={key} className="flex justify-between text-sm">
                        <span>{key}</span>
                        <span className="font-medium">{value.toFixed(2)}</span>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <p className="text-muted-foreground">暂无评分</p>
              )}

              <Button onClick={handleScore} disabled={scoreLoading}>
                {scoreLoading ? '评分中...' : '运行 V6 评分'}
              </Button>
            </>
          ) : (
            <p className="text-muted-foreground">
              {symbol ? `未找到 ${symbol}` : '请指定股票代码'}
            </p>
          )}
        </CardContent>
      </Card>

      {/* 评分历史面板 */}
      {stock && score && <ScoreHistoryPanel symbol={stock.symbol} />}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { Link } from 'react-router'
import { Target, RefreshCw, ChevronDown, ChevronUp, AlertCircle, CheckCircle, XCircle, Clock } from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import { Progress } from '@/components/ui/Progress'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
} from '@/components/ui/Breadcrumb'
import type { ValuePitScore } from '@/data/types'
import type { RotationSignal } from '@/services/scoring/rotationSignalDetector'
import { useValuePitStore, type ValuePitSectorResult } from '@/store/valuePitStore'
import { getLogger } from '@/lib/logger'
import { COLOR_SHADES, twText } from '@/constants/theme.tokens'

const logger = getLogger()

// ============================================================
// 常量
// ============================================================

const DIMENSION_LABELS: Record<string, string> = {
  catalyst: '催化确定性',
  valuation: '估值安全垫',
  chip: '筹码结构',
  rotation: '轮动位置',
  liquidity: '流动性',
  composite: '综合评分',
}

const DIMENSION_WEIGHTS: Record<string, string> = {
  catalyst: '30%',
  valuation: '25%',
  chip: '20%',
  rotation: '15%',
  liquidity: '10%',
  composite: '—',
}

const ACTION_CONFIG: Record<ValuePitScore['action'], { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline'; description: string }> = {
  immediate: { label: '建仓', variant: 'default', description: '评分达标，建议建仓' },
  probe: { label: '试探', variant: 'secondary', description: '接近达标，可小仓位试探' },
  wait: { label: '等待信号', variant: 'destructive', description: '等待轮动信号触发后再评估' },
  ignore: { label: '不建', variant: 'outline', description: '评分不足，暂不建仓' },
}

const STRENGTH_CONFIG: Record<RotationSignal['strength'], { label: string; color: string }> = {
  strong: { label: '强信号', color: twText('green', 600) },
  medium: { label: '中等信号', color: twText('yellow', 600) },
  weak: { label: '弱信号', color: twText('red', 600) },
}

// ============================================================
// 页面组件
// ============================================================

export default function ValuePitPage(): React.JSX.Element {
  // 从 Store 获取状态
  const combinedResults = useValuePitStore((s) => s.combinedResults)
  const loading = useValuePitStore((s) => s.loading)
  const error = useValuePitStore((s) => s.error)
  const runAnalysis = useValuePitStore((s) => s.runAnalysis)

  const [expandedSymbol, setExpandedSymbol] = useState<string | null>(null)

  useEffect(() => {
    logger.info('[ValuePitPage] 初始化，运行价值洼地分析')
    runAnalysis()
  }, [runAnalysis])

  const toggleExpand = (symbol: string) => {
    setExpandedSymbol((prev) => (prev === symbol ? null : symbol))
    logger.info(`[ValuePitPage] 切换展开: ${symbol} → ${expandedSymbol === symbol ? '收起' : '展开'}`)
  }

  // ============================================================
  // Loading 状态
  // ============================================================

  if (loading) {
    return (
      <div className="flex min-h-[400px] flex-col items-center justify-center space-y-4">
        <RefreshCw className="h-8 w-8 animate-spin text-muted-foreground" />
        <p className="text-sm text-muted-foreground">正在计算价值洼地评分...</p>
      </div>
    )
  }

  // ============================================================
  // Error 状态
  // ============================================================

  if (error) {
    return (
      <div className="flex min-h-[400px] flex-col items-center justify-center space-y-4">
        <AlertCircle className="h-8 w-8 text-destructive" />
        <p className="text-sm text-destructive">{error}</p>
        <Button variant="outline" onClick={runAnalysis}>
          <RefreshCw className="mr-2 h-4 w-4" />
          重试
        </Button>
      </div>
    )
  }

  // ============================================================
  // Empty 状态
  // ============================================================

  if (combinedResults.length === 0) {
    return (
      <div className="flex min-h-[400px] flex-col items-center justify-center space-y-4">
        <Target className="h-8 w-8 text-muted-foreground" />
        <p className="text-sm text-muted-foreground">暂无评分数据</p>
        <Button variant="outline" onClick={runAnalysis}>
          <RefreshCw className="mr-2 h-4 w-4" />
          刷新
        </Button>
      </div>
    )
  }

  // ============================================================
  // 正常渲染
  // ============================================================

  return (
    <div className="space-y-6 p-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/">首页</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/analysis">分析舱</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbPage>价值洼地策略</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">价值洼地策略</h1>
          <p className="text-muted-foreground">
            五维评分引擎 · 催化确定性 · 估值安全垫 · 筹码结构 · 轮动位置 · 流动性
          </p>
        </div>
        <Button variant="outline" onClick={runAnalysis} disabled={loading}>
          <RefreshCw className={`mr-2 h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
          刷新
        </Button>
      </div>

      {/* 板块列表 */}
      <div className="grid gap-4">
        {combinedResults.map(({ score, rotation }: ValuePitSectorResult) => {
          const isExpanded = expandedSymbol === score.symbol
          const actionCfg = ACTION_CONFIG[score.action]
          const strengthCfg = rotation.triggered ? STRENGTH_CONFIG[rotation.strength] : null
          const scoreColor =
            score.score >= 4 ? twText('green', 600) :
            score.score >= 3 ? twText('yellow', 600) :
            twText('red', 600)

          return (
            <Card key={score.symbol} className="transition-shadow hover:shadow-md">
              <CardHeader
                className="cursor-pointer pb-2"
                onClick={() => toggleExpand(score.symbol)}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-md bg-primary/10">
                      <Target className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                      <CardTitle className="text-base">{score.name}</CardTitle>
                      <CardDescription>{score.symbol}</CardDescription>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Badge variant={actionCfg.variant}>{actionCfg.label}</Badge>
                    <span className={`text-xl font-bold ${scoreColor}`}>
                      {score.score.toFixed(2)}
                    </span>
                    {isExpanded ? (
                      <ChevronUp className="h-4 w-4 text-muted-foreground" />
                    ) : (
                      <ChevronDown className="h-4 w-4 text-muted-foreground" />
                    )}
                  </div>
                </div>

                {/* 轮动信号徽章（列表行内） */}
                <div className="mt-2 flex items-center gap-2">
                  {rotation.triggered ? (
                    <Badge variant="default" className="text-xs">
                      <CheckCircle className="mr-1 h-3 w-3" />
                      轮动已触发
                      {strengthCfg && <span className={`ml-1 ${strengthCfg.color}`}>{strengthCfg.label}</span>}
                    </Badge>
                  ) : (
                    <Badge variant="outline" className="text-xs">
                      <Clock className="mr-1 h-3 w-3" />
                      轮动未触发
                    </Badge>
                  )}
                </div>
              </CardHeader>

              {isExpanded && (
                <CardContent className="space-y-4 pt-0">
                  {/* 五维评分条形图 */}
                  <div className="space-y-3">
                    {(Object.keys(score.dimensions) as Array<keyof typeof score.dimensions>).map((key) => (
                      <Progress
                        key={key}
                        value={score.dimensions[key] * 20}
                        label={`${DIMENSION_LABELS[key]} (${DIMENSION_WEIGHTS[key]})`}
                      />
                    ))}
                  </div>

                  {/* 轮动信号详情 */}
                  <div className="rounded-md border p-4">
                    <h4 className="mb-3 text-sm font-medium">轮动信号检测</h4>
                    <div className="grid grid-cols-3 gap-3">
                      <div className="flex items-center gap-2">
                        {rotation.conditions.volumeBreakthrough ? (
                          <CheckCircle className={`h-4 w-4 ${COLOR_SHADES.green[500]}`} />
                        ) : (
                          <XCircle className={`h-4 w-4 ${COLOR_SHADES.red[400]}`} />
                        )}
                        <span className="text-xs">成交量突破</span>
                      </div>
                      <div className="flex items-center gap-2">
                        {rotation.conditions.capitalInflow ? (
                          <CheckCircle className={`h-4 w-4 ${COLOR_SHADES.green[500]}`} />
                        ) : (
                          <XCircle className={`h-4 w-4 ${COLOR_SHADES.red[400]}`} />
                        )}
                        <span className="text-xs">资金净流入</span>
                      </div>
                      <div className="flex items-center gap-2">
                        {rotation.conditions.goldenCross ? (
                          <CheckCircle className={`h-4 w-4 ${COLOR_SHADES.green[500]}`} />
                        ) : (
                          <XCircle className={`h-4 w-4 ${COLOR_SHADES.red[400]}`} />
                        )}
                        <span className="text-xs">技术金叉</span>
                      </div>
                    </div>
                    {rotation.triggered && (
                      <p className="mt-3 text-xs text-muted-foreground">
                        检测时间: {new Date(rotation.detectedAt).toLocaleString('zh-CN')}
                      </p>
                    )}
                  </div>

                  {/* 建仓建议卡片 */}
                  <div
                    className={`rounded-md border p-4 ${
                      score.action === 'immediate' ? `${COLOR_SHADES.green[200]} ${COLOR_SHADES.green[50]}` :
                      score.action === 'wait' ? `${COLOR_SHADES.red[200]} ${COLOR_SHADES.red[50]}` :
                      `${COLOR_SHADES.yellow[200]} ${COLOR_SHADES.yellow[50]}`
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <Badge variant={actionCfg.variant}>{actionCfg.label}</Badge>
                      <span className="text-sm font-medium">{actionCfg.description}</span>
                    </div>
                    <p className="mt-2 text-xs text-muted-foreground">
                      综合评分 {score.score.toFixed(2)} / 5.0
                      · 生成时间 {new Date(score.calculatedAt).toLocaleString('zh-CN')}
                    </p>
                  </div>
                </CardContent>
              )}
            </Card>
          )
        })}
      </div>
    </div>
  )
}

import React, { useEffect, useState, useCallback } from 'react'
import { Link } from 'react-router'
import { Server, ToggleLeft, ToggleRight, Wrench, BookOpen, FileText, Play, Eye, EyeOff, RefreshCw } from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import {
  Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage,
} from '@/components/ui/Breadcrumb'
import { useMCPServerStore } from '@/store/mcpServerStore'
import { mcpRegistry } from '@/mcp/core/registry'
import { getLogger } from '@/lib/logger'
import { COLOR_TOKENS } from '@/constants/theme.tokens'

const logger = getLogger()

const PRIORITY_VARIANTS: Record<string, 'default' | 'secondary' | 'outline' | 'destructive' | 'success' | 'warning'> = {
  high: 'destructive',
  medium: 'warning',
  low: 'secondary',
}

export default function MCPServerDashboardPage(): React.JSX.Element {
  const store = useMCPServerStore()
  const [expandedServer, setExpandedServer] = useState<string | null>(null)
  const [selectedTool, setSelectedTool] = useState<string | null>(null)
  const [toolArgs, setToolArgs] = useState('{}')
  const [toolResult, setToolResult] = useState<string | null>(null)
  const [toolError, setToolError] = useState<string | null>(null)

  // 仅在挂载时拉取一次,使用 getState() 避免整个 store 引用变更触发死循环
  // (refreshServers 内 set() 产生新 state 引用 → [store] 依赖变更 → 重跑 → 无限循环)
  useEffect(() => {
    logger.info('[MCPServerDashboard] Mounted')
    void useMCPServerStore.getState().refreshServers()
    return () => {
      logger.info('[MCPServerDashboard] Unmounted')
    }
  }, [])

  const handleToggle = useCallback((name: string, enabled: boolean) => {
    store.toggleServer(name, enabled)
    logger.info('[MCPServerDashboard] Toggled server', { name, enabled })
  }, [store])

  const handleToolTest = useCallback(async (serverName: string, toolName: string) => {
    setToolResult(null)
    setToolError(null)
    try {
      const args = JSON.parse(toolArgs) as Record<string, unknown>
      const result = await mcpRegistry.getServer(serverName)?.server.callTool(toolName, args)
      if (result) {
        setToolResult(JSON.stringify(result, null, 2))
      }
    } catch (err) {
      setToolError(err instanceof Error ? err.message : String(err))
    }
  }, [toolArgs])

  const { servers, isLoading, error } = store

  return (
    <div className="space-y-6">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink asChild><Link to="/">首页</Link></BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbLink asChild><Link to="/command/hub">总控舱</Link></BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbPage>MCP Server 管理</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">MCP Server 管理</h1>
          <p className="text-muted-foreground">管理所有已注册的 MCP Server，查看工具、资源和 Prompt</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => store.refreshServers()}>
          <RefreshCw className="mr-2 h-4 w-4" />
          刷新
        </Button>
      </div>

      {isLoading && (
        <Card>
          <CardContent className="py-8 text-center text-muted-foreground">
            <RefreshCw className="h-8 w-8 mx-auto mb-2 animate-spin" />
            <p>加载中...</p>
          </CardContent>
        </Card>
      )}

      {error && (
        <Card className="border-destructive/50">
          <CardContent className="py-4">
            <p className="text-destructive">{error}</p>
          </CardContent>
        </Card>
      )}

      {!isLoading && !error && servers.length === 0 && (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-16 text-muted-foreground">
            <Server className="h-12 w-12 mb-3 opacity-30" />
            <p>暂无已注册的 MCP Server</p>
          </CardContent>
        </Card>
      )}

      <div className="space-y-4">
        {servers.map((server) => (
          <Card key={server.serverName}>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Server className="h-5 w-5 text-muted-foreground" />
                  <div>
                    <CardTitle className="text-lg flex items-center gap-2">
                      {server.serverName}
                      <Badge variant="outline" className="text-xs">v{server.version}</Badge>
                      <Badge variant={PRIORITY_VARIANTS[server.priority] ?? 'secondary'}>
                        {server.priority}
                      </Badge>
                    </CardTitle>
                    <CardDescription>{server.description}</CardDescription>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <div className="flex gap-3 text-sm text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <Wrench className="h-3 w-3" />{server.toolCount}
                    </span>
                    <span className="flex items-center gap-1">
                      <BookOpen className="h-3 w-3" />{server.resourceCount}
                    </span>
                    <span className="flex items-center gap-1">
                      <FileText className="h-3 w-3" />{server.promptCount}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleToggle(server.serverName, !server.enabled)}
                  >
                    {server.enabled ? (
                      <ToggleRight className={`h-5 w-5 ${COLOR_TOKENS.success.tailwind}`} />
                    ) : (
                      <ToggleLeft className="h-5 w-5 text-muted-foreground" />
                    )}
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setExpandedServer(
                      expandedServer === server.serverName ? null : server.serverName,
                    )}
                  >
                    {expandedServer === server.serverName ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </Button>
                </div>
              </div>
            </CardHeader>

            {expandedServer === server.serverName && (
              <CardContent className="border-t pt-4">
                <div className="space-y-4">
                  {server.dependencies.length > 0 && (
                    <div className="flex items-center gap-2 text-sm">
                      <span className="text-muted-foreground">依赖:</span>
                      {server.dependencies.map((dep) => (
                        <Badge key={dep} variant="outline" className="text-xs">{dep}</Badge>
                      ))}
                    </div>
                  )}

                  <div>
                    <h4 className="text-sm font-medium mb-2">Tools ({server.toolCount})</h4>
                    <div className="grid gap-2">
                      {mcpRegistry.getServer(server.serverName)?.server.listTools().map((tool) => (
                        <div key={tool.name} className="rounded border p-2 text-sm">
                          <div className="flex items-center justify-between">
                            <span className="font-mono text-xs font-medium">{tool.name}</span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => {
                                setSelectedTool(tool.name)
                                setToolArgs('{}')
                                setToolResult(null)
                                setToolError(null)
                              }}
                            >
                              <Play className="mr-1 h-3 w-3" />
                              测试
                            </Button>
                          </div>
                          <p className="text-muted-foreground text-xs mt-1">{tool.description}</p>

                          {selectedTool === tool.name && (
                            <div className="mt-3 pt-3 border-t space-y-2">
                              <textarea
                                className="w-full min-h-[60px] rounded border border-input bg-background px-2 py-1 text-xs font-mono"
                                value={toolArgs}
                                onChange={(e) => setToolArgs(e.target.value)}
                                placeholder="JSON arguments..."
                              />
                              <Button
                                size="sm"
                                onClick={() => handleToolTest(server.serverName, tool.name)}
                              >
                                <Play className="mr-1 h-3 w-3" />
                                执行
                              </Button>
                              {toolResult && (
                                <pre className="text-xs font-mono bg-muted p-2 rounded max-h-40 overflow-auto">{toolResult}</pre>
                              )}
                              {toolError && (
                                <p className="text-xs text-destructive">{toolError}</p>
                              )}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </CardContent>
            )}
          </Card>
        ))}
      </div>
    </div>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { Link } from 'react-router'
import { Play, RefreshCw, AlertCircle, CheckCircle2, Bot } from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import {
  Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage,
} from '@/components/ui/Breadcrumb'
import { useAgentStore } from '@/store/agentStore'
import { agentRuntime } from '@/agents/agentRuntime'
import { getAllAgentComponents } from '@/agents/agentComponentRegistry'
import { mcpRegistry } from '@/mcp/core/registry'
import { getLogger } from '@/lib/logger'
import { twBg, twText, twBorder } from '@/constants/theme.tokens'
import type { AgentTriggerPayload } from '@/types/modules/agent.types'

const logger = getLogger()

export default function AgentTriggerPage(): React.JSX.Element {
  const [selectedAgentId, setSelectedAgentId] = useState('')
  const [selectedServerName, setSelectedServerName] = useState('')
  const [selectedToolName, setSelectedToolName] = useState('')
  const [payloadJson, setPayloadJson] = useState('{}')
  const [timeout, setTimeout_] = useState(30000)
  const [isExecuting, setIsExecuting] = useState(false)
  const [result, setResult] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [payloadError, setPayloadError] = useState<string | null>(null)

  const agents = getAllAgentComponents()
  const servers = mcpRegistry.listServers()
  const selectedServer = servers.find((s) => s.server.info.name === selectedServerName)
  const tools = selectedServer?.server.listTools() ?? []
  const store = useAgentStore()

  useEffect(() => {
    logger.info('[AgentTriggerPage] Mounted')
    return () => {
      logger.info('[AgentTriggerPage] Unmounted')
    }
  }, [])

  const handleAgentChange = useCallback((agentId: string) => {
    setSelectedAgentId(agentId)
    const entry = getAllAgentComponents().find((a) => a.agentId === agentId)
    if (entry?.mcpServerName) {
      setSelectedServerName(entry.mcpServerName)
      if (entry.defaultToolName) {
        setSelectedToolName(entry.defaultToolName)
      }
    }
  }, [])

  const handleExecute = useCallback(async () => {
    setResult(null)
    setError(null)
    setIsExecuting(true)

    let parsedPayload: Record<string, unknown>
    try {
      parsedPayload = JSON.parse(payloadJson) as Record<string, unknown>
      setPayloadError(null)
    } catch {
      setPayloadError('JSON 格式无效')
      setIsExecuting(false)
      return
    }

    const payload: AgentTriggerPayload = {
      agentId: selectedAgentId,
      toolName: selectedToolName,
      serverName: selectedServerName,
      args: parsedPayload,
      timeout,
    }

    store.setTriggerPayload(payload)
    logger.info('[AgentTriggerPage] Executing trigger', {
      agentId: payload.agentId,
      toolName: payload.toolName,
      serverName: payload.serverName,
    })

    try {
      const task = await agentRuntime.execute(selectedAgentId, selectedToolName, parsedPayload, timeout)
      setResult(JSON.stringify(task, null, 2))
      logger.info('[AgentTriggerPage] Task completed', { taskId: task.id })
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      setError(errorMsg)
      logger.error('[AgentTriggerPage] Task failed', { error: errorMsg })
    } finally {
      setIsExecuting(false)
    }
  }, [selectedAgentId, selectedServerName, selectedToolName, payloadJson, timeout, store])

  return (
    <div className="space-y-6">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink asChild><Link to="/">首页</Link></BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbLink asChild><Link to="/command/hub">总控舱</Link></BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbLink asChild><Link to="/command/agents">智能体</Link></BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbPage>任务触发</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">任务触发</h1>
          <p className="text-muted-foreground">手动选择智能体并触发任务执行</p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>触发配置</CardTitle>
            <CardDescription>选择智能体、MCP Server 和 Tool 并配置参数</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">智能体</label>
              <select
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                value={selectedAgentId}
                onChange={(e) => handleAgentChange(e.target.value)}
              >
                <option value="">选择智能体...</option>
                {agents.map((a) => (
                  <option key={a.agentId} value={a.agentId}>
                    {a.displayName} ({a.agentId})
                  </option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">MCP Server</label>
              <select
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                value={selectedServerName}
                onChange={(e) => {
                  setSelectedServerName(e.target.value)
                  setSelectedToolName('')
                }}
              >
                <option value="">选择 Server...</option>
                {servers.map((s) => (
                  <option key={s.server.info.name} value={s.server.info.name}>
                    {s.server.info.name} v{s.server.info.version}
                  </option>
                ))}
              </select>
            </div>

            {selectedServerName && (
              <div className="space-y-2">
                <label className="text-sm font-medium">Tool</label>
                <select
                  className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={selectedToolName}
                  onChange={(e) => setSelectedToolName(e.target.value)}
                >
                  <option value="">选择 Tool...</option>
                  {tools.map((t) => (
                    <option key={t.name} value={t.name}>
                      {t.name} — {t.description}
                    </option>
                  ))}
                </select>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-sm font-medium">超时 (ms)</label>
              <Input
                type="number"
                value={timeout}
                onChange={(e) => setTimeout_(Number(e.target.value) || 30000)}
                min={1000}
                max={120000}
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Payload (JSON)</label>
              <textarea
                className="w-full min-h-[120px] rounded-md border border-input bg-background px-3 py-2 text-sm font-mono"
                value={payloadJson}
                onChange={(e) => {
                  setPayloadJson(e.target.value)
                  setPayloadError(null)
                }}
              />
              {payloadError && (
                <p className="text-sm text-destructive">{payloadError}</p>
              )}
            </div>

            <Button
              className="w-full"
              onClick={handleExecute}
              disabled={isExecuting || !selectedAgentId || !selectedToolName}
            >
              {isExecuting ? (
                <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Play className="mr-2 h-4 w-4" />
              )}
              {isExecuting ? '执行中...' : '执行任务'}
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>执行结果</CardTitle>
            <CardDescription>任务执行结果和错误信息</CardDescription>
          </CardHeader>
          <CardContent>
            {error && (
              <div className="rounded-md border border-destructive/50 bg-destructive/10 p-4">
                <div className="flex items-center gap-2 text-sm font-medium text-destructive">
                  <AlertCircle className="h-4 w-4" />
                  执行失败
                </div>
                <pre className="mt-2 text-sm font-mono text-destructive whitespace-pre-wrap">{error}</pre>
              </div>
            )}
            {result && (
              <div className={`rounded-md border ${twBorder('green', 500)}/50 ${twBg('green', 500)}/10 p-4`}>
                <div className={`flex items-center gap-2 text-sm font-medium ${twText('green', 600)}`}>
                  <CheckCircle2 className="h-4 w-4" />
                  执行成功
                </div>
                <pre className="mt-2 text-sm font-mono whitespace-pre-wrap overflow-auto max-h-96">{result}</pre>
              </div>
            )}
            {!result && !error && (
              <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
                <Bot className="h-12 w-12 mb-3 opacity-30" />
                <p>配置触发参数后点击执行</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

import { useEffect, useMemo } from 'react'
import { Link } from 'react-router'
import { FolderOpen, Search, BarChart3, Plus } from 'lucide-react'
import { useToast } from '@/hooks/useToast'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/Breadcrumb'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Badge } from '@/components/ui/Badge'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/components/ui/Tabs'
import { LocalDocCard } from '@/components/localDoc/LocalDocCard'
import { useLocalKnowledgeStore, type LocalKnowledgeTab } from '@/store/localKnowledgeStore'
import type { LocalDoc } from '@/data/types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

const CATEGORIES: LocalDoc['category'][] = [
  '研报',
  '财报',
  '行业分析',
  '新闻',
  '策略笔记',
  '其他',
]

export default function LocalKnowledgePage(): React.JSX.Element {
  const { toast } = useToast()

  // 从 Store 获取状态
  const activeTab = useLocalKnowledgeStore((s) => s.activeTab)
  const docs = useLocalKnowledgeStore((s) => s.docs)
  const symbolFilter = useLocalKnowledgeStore((s) => s.symbolFilter)
  const keyword = useLocalKnowledgeStore((s) => s.keyword)
  const searchResults = useLocalKnowledgeStore((s) => s.searchResults)
  const message = useLocalKnowledgeStore((s) => s.message)
  const loading = useLocalKnowledgeStore((s) => s.loading)
  const error = useLocalKnowledgeStore((s) => s.error)

  // 从 Store 获取 actions
  const setActiveTab = useLocalKnowledgeStore((s) => s.setActiveTab)
  const loadDocs = useLocalKnowledgeStore((s) => s.loadDocs)
  const searchDocs = useLocalKnowledgeStore((s) => s.searchDocs)
  const scanFolder = useLocalKnowledgeStore((s) => s.scanFolder)
  const importSampleDocs = useLocalKnowledgeStore((s) => s.importSampleDocs)
  const setSymbolFilter = useLocalKnowledgeStore((s) => s.setSymbolFilter)
  const setKeyword = useLocalKnowledgeStore((s) => s.setKeyword)

  // 监听 symbolFilter 变化，自动加载文档
  useEffect(() => {
    logger.info('[LocalKnowledgePage] symbolFilter 变化，加载文档', { symbolFilter })
    void loadDocs()
  }, [symbolFilter, loadDocs])

  // 监听 error 变化，显示 toast
  useEffect(() => {
    if (error) {
      toast({
        variant: 'error',
        title: '操作失败',
        description: error,
      })
    }
  }, [error, toast])

  const symbols = useMemo(() => {
    const set = new Set(docs.map((d) => d.symbol))
    return ['全部', ...Array.from(set).sort()]
  }, [docs])

  const handleImportSamples = async () => {
    logger.info('[LocalKnowledgePage] 导入示例文档')
    await importSampleDocs()
  }

  const handleScanFolder = async () => {
    logger.info('[LocalKnowledgePage] 扫描文件夹')
    await scanFolder()
  }

  const handleSearch = async () => {
    logger.info('[LocalKnowledgePage] 搜索文档', { keyword })
    await searchDocs(keyword)
  }

  const stats = useMemo(() => {
    const totalDocs = docs.length
    const uniqueStocks = new Set(docs.map((d) => d.symbol)).size
    const counts = CATEGORIES.map((category) => ({
      category,
      count: docs.filter((d) => d.category === category).length,
    }))
    return { totalDocs, uniqueStocks, counts }
  }, [docs])

  return (
    <div className="space-y-6">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/">首页</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/input/hub">输入舱</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>本地知识库</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">本地知识库</h1>
          <p className="text-muted-foreground">管理本地文档、研报、财报与策略笔记</p>
        </div>
        <Button variant="outline" size="sm" onClick={handleScanFolder} disabled={loading}>
          <FolderOpen className="mr-2 h-4 w-4" />
          导入文件夹
        </Button>
      </div>

      {message && (
        <div
          className="rounded-md border bg-muted px-4 py-3 text-sm text-muted-foreground"
          role="status"
        >
          {message}
        </div>
      )}

      <Tabs value={activeTab} onValueChange={(value) => setActiveTab(value as LocalKnowledgeTab)}>
        <TabsList>
          <TabsTrigger value="browse">浏览</TabsTrigger>
          <TabsTrigger value="search">搜索</TabsTrigger>
          <TabsTrigger value="stats">统计</TabsTrigger>
        </TabsList>

        <TabsContent value="browse" className="space-y-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-2">
              <label htmlFor="symbol-filter" className="text-sm font-medium">
                股票筛选
              </label>
              <select
                id="symbol-filter"
                value={symbolFilter}
                onChange={(e) => setSymbolFilter(e.target.value)}
                className="h-10 rounded-md border border-input bg-background px-3 py-2 text-sm"
              >
                {symbols.map((symbol) => (
                  <option key={symbol} value={symbol}>
                    {symbol}
                  </option>
                ))}
              </select>
            </div>
            <Button variant="secondary" size="sm" onClick={handleImportSamples} disabled={loading}>
              <Plus className="mr-2 h-4 w-4" />
              导入示例数据
            </Button>
          </div>

          {docs.length === 0 ? (
            <p className="text-sm text-muted-foreground">暂无文档，点击“导入示例数据”进行测试。</p>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {docs.map((doc) => (
                <LocalDocCard key={doc.id} doc={doc} />
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="search" className="space-y-4">
          <div className="flex items-center gap-2">
            <Input
              placeholder="输入关键词搜索文档、股票代码或标签"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  void handleSearch()
                }
              }}
            />
            <Button onClick={handleSearch} disabled={loading}>
              <Search className="mr-2 h-4 w-4" />
              搜索
            </Button>
          </div>

          {searchResults.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              {keyword ? '未找到匹配的文档' : '输入关键词后点击搜索'}
            </p>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {searchResults.map((doc) => (
                <LocalDocCard key={doc.id} doc={doc} />
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="stats" className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-muted-foreground">
                  文档总数
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-bold">{stats.totalDocs}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-muted-foreground">
                  涉及股票数
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-bold">{stats.uniqueStocks}</div>
              </CardContent>
            </Card>
            <Card className="sm:col-span-2">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-muted-foreground flex items-center gap-2">
                  <BarChart3 className="h-4 w-4" />
                  分类分布
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex flex-wrap gap-2">
                  {stats.counts.map(({ category, count }) => (
                    <Badge key={category} variant={count > 0 ? 'default' : 'outline'}>
                      {category}: {count}
                    </Badge>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  )
}

/**
 * @module SevenDimConfigPage
 * @description 七维采集配置页。
 *
 * 参考V6 Pro SevenDimCollectPage.tsx设计，适配V9架构：
 * - 5个策略模板卡片（价值/成长/防御/周期/全维度）
 * - 8个采集维度开关面板（含频率/数据源/存储策略）
 * - 全局参数配置（标的数/历史天数）
 * - 额度预估仪表盘
 * - 保存配置与执行采集操作
 *
 * @see V6 Pro: cockpit-app/src/pages/SevenDimCollectPage.tsx
 * @see V6 Pro: cockpit-app/src/components/collect/CollectParamPanel.tsx
 */

import { useMemo } from 'react'
import { Link } from 'react-router'
import { useSevenDimConfigStore } from '@/store/sevenDimConfigStore'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { getLogger } from '@/lib/logger'
import { COLOR_TOKENS, twBg } from '@/constants/theme.tokens'
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
} from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import { Switch } from '@/components/ui/Switch'
import { Select, SelectItem } from '@/components/ui/Select'
import { Input } from '@/components/ui/Input'
import { Label } from '@/components/ui/Label'
import { Progress } from '@/components/ui/Progress'
import { Separator } from '@/components/ui/Separator'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/Breadcrumb'
import {
  STRATEGY_TEMPLATES,
  DEFAULT_DIMENSIONS,
  FREQUENCY_LABELS,
  DATA_SOURCE_LABELS,
  STORAGE_TYPE_LABELS,
  IMPORTANCE_LABELS,
  IMPORTANCE_BADGE_VARIANT,
  DIMENSION_COLORS,
  GLOBAL_LIMITS,
  type StrategyTemplateId,
  type UpdateFrequency,
  type DataSourceType,
} from '@/config/collectConfig'

const logger = getLogger()

// ============================================================
// 策略模板颜色映射（引用 constants/theme.tokens，不硬编码颜色值）
// ============================================================

/** 策略模板 → 颜色 token 映射，用于卡片边框与高亮标识 */
const STRATEGY_COLOR_TOKEN: Record<StrategyTemplateId, keyof typeof COLOR_TOKENS> = {
  value: 'info',       // 价值投资 → 蓝色
  growth: 'success',   // 成长投资 → 绿色
  defense: 'warning',  // 防御策略 → 橙色
  cycle: 'purple',     // 周期轮动 → 紫色
  full: 'danger',      // 全维度 → 红色
}

// ============================================================
// 策略模板卡片
// ============================================================

interface StrategyCardProps {
  templateId: StrategyTemplateId
  name: string
  description: string
  dimensionCount: number
  isActive: boolean
  disabled: boolean
  onSelect: () => void
}

function StrategyCard({
  templateId,
  name,
  description,
  dimensionCount,
  isActive,
  disabled,
  onSelect,
}: StrategyCardProps) {
  const colorToken = COLOR_TOKENS[STRATEGY_COLOR_TOKEN[templateId]]
  return (
    <Card
      className={`cursor-pointer transition-all duration-200 ${
        isActive ? 'ring-2 ring-primary/20' : 'hover:shadow-md'
      } ${disabled ? 'pointer-events-none opacity-50' : ''}`}
      style={{ borderColor: colorToken.hex, borderWidth: isActive ? 2 : 1 }}
      onClick={onSelect}
    >
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span
              className="inline-block h-2.5 w-2.5 rounded-full"
              style={{ backgroundColor: colorToken.hex }}
            />
            <CardTitle className="text-base">{name}</CardTitle>
          </div>
          {isActive && <Badge>当前</Badge>}
        </div>
        <CardDescription className="text-xs">{description}</CardDescription>
      </CardHeader>
      <CardContent>
        <p className="text-sm text-muted-foreground">
          {dimensionCount} 个维度
        </p>
      </CardContent>
    </Card>
  )
}

// ============================================================
// 维度配置行
// ============================================================

interface DimensionRowProps {
  code: string
  name: string
  enabled: boolean
  frequency: UpdateFrequency
  sources: DataSourceType[]
  storageType: string
  importance: string
  fields: string[]
  disabled: boolean
  onToggle: () => void
  onFrequencyChange: (frequency: UpdateFrequency) => void
  onSourcesChange: (sources: DataSourceType[]) => void
}

function DimensionRow({
  code,
  name,
  enabled,
  frequency,
  sources,
  storageType,
  importance,
  fields,
  disabled,
  onToggle,
  onFrequencyChange,
  onSourcesChange,
}: DimensionRowProps) {
  const colorBar = DIMENSION_COLORS[code] ?? twBg('gray', 400)

  return (
    <div className="flex items-start gap-3 py-3 transition-all duration-200">
      {/* 维度色块 */}
      <div className={`mt-1 h-3 w-3 shrink-0 rounded-full transition-all duration-200 ${colorBar}`} />

      {/* 开关 */}
      <div className="mt-0.5 transition-all duration-200">
        <Switch
          checked={enabled}
          onChange={onToggle}
          disabled={disabled}
        />
      </div>

      {/* 维度信息 */}
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">{code} · {name}</span>
          <Badge variant={IMPORTANCE_BADGE_VARIANT[importance as keyof typeof IMPORTANCE_BADGE_VARIANT]}>
            {IMPORTANCE_LABELS[importance as keyof typeof IMPORTANCE_LABELS]}
          </Badge>
        </div>
        {enabled ? (
          <div className="mt-2 space-y-2">
            {/* 频率下拉 + 存储策略（静态） */}
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <span className="text-muted-foreground">频率</span>
              <Select
                value={frequency}
                disabled={disabled}
                onChange={(e) => onFrequencyChange(e.target.value as UpdateFrequency)}
                className="h-7 w-28 py-1 text-xs"
              >
                {(Object.keys(FREQUENCY_LABELS) as UpdateFrequency[]).map((freq) => (
                  <SelectItem key={freq} value={freq}>
                    {FREQUENCY_LABELS[freq]}
                  </SelectItem>
                ))}
              </Select>
              <span className="text-muted-foreground">·</span>
              <span className="text-muted-foreground">
                存储: {STORAGE_TYPE_LABELS[storageType as keyof typeof STORAGE_TYPE_LABELS]}
              </span>
            </div>
            {/* 数据源多选标签 */}
            <div className="flex flex-wrap items-center gap-1.5">
              <span className="text-xs text-muted-foreground">数据源</span>
              {(Object.keys(DATA_SOURCE_LABELS) as DataSourceType[]).map((src) => {
                const active = sources.includes(src)
                return (
                  <Badge
                    key={src}
                    variant={active ? 'default' : 'outline'}
                    className={
                      disabled
                        ? 'pointer-events-none opacity-50 text-[10px]'
                        : 'cursor-pointer text-[10px] hover:scale-105'
                    }
                    onClick={() => {
                      if (disabled) return
                      const next = active
                        ? sources.filter((s) => s !== src)
                        : [...sources, src]
                      onSourcesChange(next)
                    }}
                  >
                    {DATA_SOURCE_LABELS[src]}
                  </Badge>
                )
              })}
            </div>
          </div>
        ) : (
          <div className="mt-1 flex flex-wrap gap-2 text-xs text-muted-foreground">
            <span>频率: {FREQUENCY_LABELS[frequency]}</span>
            <span>·</span>
            <span>源: {sources.map((s) => DATA_SOURCE_LABELS[s as keyof typeof DATA_SOURCE_LABELS] ?? s).join(' > ')}</span>
            <span>·</span>
            <span>存储: {STORAGE_TYPE_LABELS[storageType as keyof typeof STORAGE_TYPE_LABELS]}</span>
          </div>
        )}
        {enabled && fields.length > 0 && (
          <div className="mt-1 flex flex-wrap gap-1">
            {fields.slice(0, 4).map((field) => (
              <span key={field} className="rounded bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground">
                {field}
              </span>
            ))}
            {fields.length > 4 && (
              <span className="text-[10px] text-muted-foreground">+{fields.length - 4}</span>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

// ============================================================
// 主页面
// ============================================================

export default function SevenDimConfigPage() {
  const store = useSevenDimConfigStore()

  logger.info('[SevenDimConfigPage] 渲染', {
    activeTemplate: store.activeTemplate,
    enabledCount: store.enabledCount(),
    isCollecting: store.isCollecting,
  })

  // 派生状态
  const enabledCount = store.enabledCount()
  const monthlyCalls = store.monthlyCallEstimate()
  const isDisabled = !store.isClickable()
  const tooltipText = store.tooltipText()
  // 额度使用率（基于月调用量 / 日上限×30）
  const quotaUsagePercent = useMemo(
    () => (GLOBAL_LIMITS.rateLimitPerDay > 0
      ? Math.min(100, Math.round((monthlyCalls / (GLOBAL_LIMITS.rateLimitPerDay * 30)) * 100))
      : 0),
    [monthlyCalls],
  )
  // 额度使用率颜色 token：低→蓝，中→琥珀，高→红
  const quotaColorToken = useMemo(() => {
    if (quotaUsagePercent >= 80) return COLOR_TOKENS.danger
    if (quotaUsagePercent >= 50) return COLOR_TOKENS.warning
    return COLOR_TOKENS.info
  }, [quotaUsagePercent])

  // 策略模板维度数映射
  const templateDimCounts = useMemo(() => {
    const map: Record<string, number> = {}
    for (const t of STRATEGY_TEMPLATES) {
      map[t.id] = t.dimensions.length
    }
    return map
  }, [])

  return (
    <ErrorBoundary>
      <div className="space-y-6 p-6">
        {/* 面包屑 */}
        <Breadcrumb>
          <BreadcrumbList>
            <BreadcrumbItem>
              <BreadcrumbLink asChild>
                <Link to="/">首页</Link>
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator />
            <BreadcrumbItem>
              <BreadcrumbLink asChild>
                <Link to="/input">输入舱</Link>
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator />
            <BreadcrumbItem>
              <BreadcrumbPage>七维采集配置</BreadcrumbPage>
            </BreadcrumbItem>
          </BreadcrumbList>
        </Breadcrumb>

        {/* 页面标题 */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold">七维采集配置</h1>
            <p className="mt-1 text-sm text-muted-foreground">
              采集维度 · 策略模板 · 额度预估 · 执行采集
            </p>
          </div>
          <Badge variant="outline">V9 新建</Badge>
        </div>

        {/* 错误提示 */}
        {store.error && (
          <Card className="border-destructive">
            <CardContent className="flex items-center justify-between py-3">
              <span className="text-sm text-destructive">{store.error}</span>
              <Button variant="ghost" size="sm" onClick={store.clearError}>
                关闭
              </Button>
            </CardContent>
          </Card>
        )}

        {/* 采集进度条 */}
        {store.isCollecting && (
          <Card>
            <CardContent className="py-4">
              <div className="mb-2 flex items-center justify-between">
                <span className="text-sm font-medium">采集中...</span>
                <span className="text-sm text-muted-foreground">{store.collectProgress}%</span>
              </div>
              <Progress value={store.collectProgress} />
            </CardContent>
          </Card>
        )}

        {/* 策略模板选择 */}
        <div>
          <h2 className="mb-3 text-base font-semibold">策略模板</h2>
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5">
            {STRATEGY_TEMPLATES.map((template) => (
              <StrategyCard
                key={template.id}
                templateId={template.id}
                name={template.name}
                description={template.description}
                dimensionCount={templateDimCounts[template.id] ?? 0}
                isActive={store.activeTemplate === template.id}
                disabled={isDisabled}
                onSelect={() => store.applyTemplate(template.id)}
              />
            ))}
          </div>
        </div>

        {/* 维度配置 + 参数面板 */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
          {/* 左侧：维度开关列表 */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle>采集维度</CardTitle>
                    <CardDescription>
                      已启用 {enabledCount} / {DEFAULT_DIMENSIONS.length} 个维度
                    </CardDescription>
                  </div>
                  <Badge variant="secondary">
                    {enabledCount} / {DEFAULT_DIMENSIONS.length}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent>
                <Separator />
                {store.dimensions.map((dim) => (
                  <DimensionRow
                    key={dim.code}
                    code={dim.code}
                    name={dim.name}
                    enabled={dim.enabled}
                    frequency={dim.frequency}
                    sources={dim.sources}
                    storageType={dim.storageType}
                    importance={dim.importance}
                    fields={dim.fields}
                    disabled={isDisabled}
                    onToggle={() => store.toggleDimension(dim.code)}
                    onFrequencyChange={(freq) => {
                      logger.info(`[SevenDimConfigPage] 维度 ${dim.code} 频率变更`, {
                        from: dim.frequency,
                        to: freq,
                      })
                      store.setDimensionFrequency(dim.code, freq)
                    }}
                    onSourcesChange={(nextSources) => {
                      logger.info(`[SevenDimConfigPage] 维度 ${dim.code} 数据源变更`, {
                        from: dim.sources,
                        to: nextSources,
                      })
                      store.setDimensionSources(dim.code, nextSources)
                    }}
                  />
                ))}
              </CardContent>
            </Card>
          </div>

          {/* 右侧：参数配置 + 额度预估 */}
          <div className="space-y-4">
            {/* 全局参数 */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base">全局参数</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="symbolCount">标的数量</Label>
                  <Input
                    id="symbolCount"
                    type="number"
                    min={1}
                    max={GLOBAL_LIMITS.maxSymbols}
                    value={store.symbolCount}
                    disabled={isDisabled}
                    onChange={(e) => store.setSymbolCount(Number(e.target.value) || 0)}
                  />
                  <p className="text-xs text-muted-foreground">
                    上限 {GLOBAL_LIMITS.maxSymbols}
                  </p>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="historyDays">历史天数</Label>
                  <Input
                    id="historyDays"
                    type="number"
                    min={1}
                    max={1000}
                    value={store.historyDays}
                    disabled={isDisabled}
                    onChange={(e) => store.setHistoryDays(Number(e.target.value) || 0)}
                  />
                </div>
              </CardContent>
            </Card>

            {/* 额度预估 */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base">额度预估</CardTitle>
                <CardDescription>基于当前配置的月调用估算</CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">月调用总量</span>
                  <span className="text-lg font-bold">{monthlyCalls.toLocaleString()}</span>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">日调用上限</span>
                  <span className="text-sm">{GLOBAL_LIMITS.rateLimitPerDay}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">小时调用上限</span>
                  <span className="text-sm">{GLOBAL_LIMITS.rateLimitPerHour}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">AKShare 额度</span>
                  <Badge variant="secondary">免费无限</Badge>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">额度使用率</span>
                  <span className="text-sm font-medium" style={{ color: quotaColorToken.hex }}>
                    {quotaUsagePercent}%
                  </span>
                </div>
                {/* 额度使用率可视化进度条 */}
                <div className="space-y-1">
                  <div className="h-2 w-full overflow-hidden rounded-full bg-secondary">
                    <div
                      className="h-full rounded-full transition-all duration-500"
                      style={{ width: `${quotaUsagePercent}%`, backgroundColor: quotaColorToken.hex }}
                    />
                  </div>
                  <p className="text-xs text-muted-foreground">
                    月调用 {monthlyCalls.toLocaleString()} / 日上限×30 {(GLOBAL_LIMITS.rateLimitPerDay * 30).toLocaleString()}
                  </p>
                </div>
              </CardContent>
            </Card>

            {/* 操作按钮 */}
            <div className="space-y-2">
              <Button
                className="w-full"
                onClick={() => store.runCollection()}
                disabled={isDisabled || enabledCount === 0}
              >
                {store.isCollecting ? '采集中...' : '开始采集'}
              </Button>
              <Button
                variant="outline"
                className="w-full"
                onClick={() => store.saveConfig()}
                disabled={isDisabled || !store.isDirty}
              >
                {store.isSaving ? '保存中...' : '保存配置'}
              </Button>
              <Button
                variant="ghost"
                className="w-full"
                onClick={() => store.reset()}
                disabled={isDisabled}
              >
                重置为默认
              </Button>
            </div>

            {/* 不可交互提示 */}
            {isDisabled && tooltipText && (
              <p className="text-center text-xs text-muted-foreground">{tooltipText}</p>
            )}
          </div>
        </div>
      </div>
    </ErrorBoundary>
  )
}

import { memo, useState, useEffect } from 'react'
import { Link } from 'react-router'
import { FileText, Download, RefreshCw, ArrowLeft } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import { Select, SelectItem } from '@/components/ui/Select'
import {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
} from '@/components/ui/Breadcrumb'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { useScoreDocStore } from '@/store/scoreDocStore'
import { useToast } from '@/hooks/useToast'
import { usePageGuard } from '@/hooks/usePageGuard'

interface ReportData {
  symbol: string
  version: number
  markdown: string
  generatedAt: string
}

export default memo(function ResearchReportPage(): React.JSX.Element {
  const [symbols, setSymbols] = useState<string[]>([])
  const [selectedSymbol, setSelectedSymbol] = useState('')
  const [reports, setReports] = useState<ReportData[]>([])
  const [loading, setLoading] = useState(false)
  const [generating, setGenerating] = useState(false)
  const { toast } = useToast()
  const { guardProps } = usePageGuard('research-report')
  const { loadStockSymbols, generateReport: generateReportFromStore } = useScoreDocStore()

  useEffect(() => {
    loadSymbols()
  }, [])

  const loadSymbols = async (): Promise<void> => {
    setLoading(true)
    try {
      const uniqueSymbols = await loadStockSymbols()
      setSymbols(uniqueSymbols)
    } catch (error) {
      toast({
        variant: 'error',
        title: '加载股票列表失败',
        description: error instanceof Error ? error.message : '未知错误',
      })
    } finally {
      setLoading(false)
    }
  }

  const generateReport = async (): Promise<void> => {
    if (!selectedSymbol) {
      toast({
        variant: 'error',
        title: '请选择股票',
        description: '请先选择一个股票再生成报告',
      })
      return
    }

    setGenerating(true)
    try {
      const report = await generateReportFromStore(selectedSymbol)
      const reportData: ReportData = {
        symbol: report.symbol,
        version: report.version,
        markdown: report.markdown,
        generatedAt: report.generatedAt,
      }
      setReports(prev => [reportData, ...prev])
      toast({
        title: '报告生成成功',
        description: `${selectedSymbol} V${report.version} 研究报告已生成`,
      })
    } catch (error) {
      toast({
        variant: 'error',
        title: '生成报告失败',
        description: error instanceof Error ? error.message : '未知错误',
      })
    } finally {
      setGenerating(false)
    }
  }

  const downloadReport = (report: ReportData): void => {
    const blob = new Blob([report.markdown], { type: 'text/markdown;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${report.symbol}_V${report.version}_研究报告_${new Date(report.generatedAt).toLocaleDateString('zh-CN')}.md`
    a.click()
    URL.revokeObjectURL(url)
    toast({
      title: '下载成功',
      description: `${report.symbol} 研究报告已下载`,
    })
  }

  return (
    <ErrorBoundary>
      <div className="space-y-6 p-4">
        <Breadcrumb>
          <BreadcrumbList>
            <BreadcrumbItem>
              <BreadcrumbLink asChild>
                <Link to="/">首页</Link>
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbItem>
              <BreadcrumbLink asChild>
                <Link to="/output">输出舱</Link>
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbItem>
              <BreadcrumbPage>研究报告</BreadcrumbPage>
            </BreadcrumbItem>
          </BreadcrumbList>
        </Breadcrumb>

        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">研究报告</h1>
            <p className="text-muted-foreground">基于评分文档生成个股研究报告</p>
          </div>
          <Button variant="outline" size="sm" asChild>
            <Link to="/output">
              <ArrowLeft className="mr-2 h-4 w-4" />
              返回
            </Link>
          </Button>
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              生成报告
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <label className="text-sm font-medium">选择股票</label>
                <Select
                  value={selectedSymbol}
                  onChange={(e) => setSelectedSymbol(e.target.value)}
                  disabled={loading || generating}
                >
                  <SelectItem value="">请选择股票</SelectItem>
                  {symbols.map(symbol => (
                    <SelectItem key={symbol} value={symbol}>
                      {symbol}
                    </SelectItem>
                  ))}
                </Select>
              </div>
              <div className="flex items-end">
                <Button
                  {...guardProps}
                  onClick={generateReport}
                  disabled={guardProps.disabled || !selectedSymbol || generating}
                  className="w-full"
                >
                  {generating ? (
                    <>
                      <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
                      生成中...
                    </>
                  ) : (
                    <>
                      <FileText className="mr-2 h-4 w-4" />
                      生成报告
                    </>
                  )}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        {reports.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>已生成报告</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {reports.map((report, index) => (
                <div key={index} className="rounded-lg border p-4 space-y-3">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <Badge variant="secondary">{report.symbol}</Badge>
                      <Badge variant="outline">V{report.version}</Badge>
                      <span className="text-sm text-muted-foreground">
                        {new Date(report.generatedAt).toLocaleString('zh-CN')}
                      </span>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      {...guardProps}
                      onClick={() => downloadReport(report)}
                      disabled={guardProps.disabled}
                    >
                      <Download className="mr-2 h-4 w-4" />
                      下载
                    </Button>
                  </div>
                  <div className="max-h-96 overflow-auto rounded-md bg-muted/50 p-4">
                    <pre className="text-xs whitespace-pre-wrap">{report.markdown}</pre>
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>
        )}
      </div>
    </ErrorBoundary>
  )
})

/**
 * @module HoldingsPage
 * @lifecycle @Route
 * @description 交易持仓与策略资产管理列表页。组装筛选区、数据表格、分页组件、交易确认弹窗。
 * 所有状态管理采用 useReducer + useCallback，确保数据流清晰可追溯。
 *
 * @compliance
 * - 所有颜色值从 @/constants/trade.constants 引用
 * - 所有枚举值从 @/constants/trade.constants 引用
 * - 所有字符串字面量从 @/constants/trade.constants 引用
 * - 组件内禁止出现 'BUY'、'CORE'、'#ef4444' 等硬编码
 */

import { useCallback, useEffect, useRef } from 'react'
import type React from 'react'
import { Link } from 'react-router'
import { FileText } from 'lucide-react'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
} from '@/components/ui/Breadcrumb'
import { useToast } from '@/hooks/useToast'
import HoldingsFilter from './components/HoldingsFilter'
import HoldingsTable from './components/HoldingsTable'
import Pagination from './components/Pagination'
import TradeModal from './components/TradeModal'
import { PAGINATION_DEFAULTS, HOLDING_ACTION } from '@/constants/trade.constants'
import type { HoldingItem } from '@/types/modules/trade.types'
import type { HoldingsQueryParams } from '@/types/modules/trade.types'
import type { HoldingAction } from '@/constants/trade.constants'
import { useHoldingsStore, buildHoldingsParams, initHoldingsStoreSubscriptions } from '@/store/holdingsStore'
import { usePageGuard } from '@/hooks/usePageGuard'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 组件
// ============================================================

export default function HoldingsPage(): React.JSX.Element {
  const {
    data, filter, pagination, loading, modal,
    setData, setPage, setPageSize, setLoading,
    openModal, closeModal, resetFilter, setFilter,
    fetchData, executeTrade, exportCSV,
  } = useHoldingsStore()
  const { toast } = useToast()
  const isMountedRef = useRef(true)
  const { guardProps } = usePageGuard('holdings')

  // 清理标记
  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
    }
  }, [])

  /** 初始化 DataBridge 订阅（组件卸载时自动清理） */
  useEffect(() => {
    return initHoldingsStoreSubscriptions()
  }, [])

  // 构建查询参数
  const buildParams = useCallback((): HoldingsQueryParams => {
    return buildHoldingsParams()
  }, [])

  // 加载数据
  const loadData = useCallback(async () => {
    const params = buildParams()
    logger.info('[HoldingsPage] 开始加载持仓数据', { params })
    setLoading({ isListLoading: true })
    try {
      const response = await fetchData(params)
      if (!isMountedRef.current) return

      if (response.code !== 200) {
        logger.warn('[HoldingsPage] 持仓数据加载返回异常code', {
          code: response.code,
          message: response.message,
        })
        toast({ title: '加载失败', description: response.message || '未知错误', variant: 'error' })
      }
    } catch (err) {
      if (!isMountedRef.current) return
      logger.error('[HoldingsPage] 持仓数据加载异常', {
        error: err instanceof Error ? err.message : String(err),
      })
      toast({
        title: '加载失败',
        description: err instanceof Error ? err.message : '网络请求异常',
        variant: 'error',
      })
    } finally {
      if (isMountedRef.current) {
        setLoading({ isListLoading: false })
      }
    }
  }, [buildParams, setData, setLoading, toast])

  // 初始加载 & 依赖变化时重新加载
  useEffect(() => {
    loadData()
  }, [loadData])

  // 筛选操作
  const handleSearch = useCallback(() => {
    logger.info('[HoldingsPage] 执行筛选搜索', { filter })
    setPage(PAGINATION_DEFAULTS.DEFAULT_PAGE)
    loadData()
  }, [loadData, filter, setPage])

  const handleReset = useCallback(() => {
    logger.info('[HoldingsPage] 重置筛选条件', { currentFilter: filter })
    resetFilter()
  }, [filter, resetFilter])

  // 分页操作
  const handlePageChange = useCallback((page: number) => {
    setPage(page)
  }, [setPage])

  const handlePageSizeChange = useCallback((pageSize: number) => {
    setPageSize(pageSize)
  }, [setPageSize])

  // 导出
  const handleExport = useCallback(async () => {
    const params = buildParams()
    logger.info('[HoldingsPage] 开始导出持仓数据', { params })
    setLoading({ isExporting: true })
    try {
      await exportCSV(params)
      logger.info('[HoldingsPage] 导出成功')
      toast({ title: '导出成功', description: '持仓数据已导出为 CSV 文件', variant: 'success' })
    } catch (err) {
      logger.error('[HoldingsPage] 导出失败', {
        error: err instanceof Error ? err.message : String(err),
      })
      toast({
        title: '导出失败',
        description: err instanceof Error ? err.message : '导出异常',
        variant: 'error',
      })
    } finally {
      if (isMountedRef.current) {
        setLoading({ isExporting: false })
      }
    }
  }, [buildParams, setLoading, toast])

  // 操作列点击
  const handleAction = useCallback(
    (item: HoldingItem, action: HoldingAction) => {
      openModal(item, action)
    },
    [openModal],
  )

  const handleCloseModal = useCallback(() => {
    closeModal()
  }, [closeModal])

  // 确认交易
  const handleConfirmTrade = useCallback(
    async (item: HoldingItem, action: HoldingAction, quantity: number) => {
      const tradeQuantity = action === HOLDING_ACTION.CLOSE_POSITION ? item.quantity : quantity
      logger.info('[HoldingsPage] 确认交易操作', {
        code: item.code,
        name: item.name,
        action,
        quantity: tradeQuantity,
        currentPrice: item.currentPrice,
        totalAmount: item.currentPrice * tradeQuantity,
      })
      setLoading({ isActionLoading: true })
      try {
        const response = await executeTrade({
          code: item.code,
          action,
          quantity: tradeQuantity,
        })

        if (response.success) {
          logger.info('[HoldingsPage] 交易操作成功', {
            code: item.code,
            action,
            message: response.message,
          })
          toast({ title: '操作成功', description: response.message, variant: 'success' })
          closeModal()
          await loadData()
        } else {
          logger.warn('[HoldingsPage] 交易操作失败', {
            code: item.code,
            action,
            message: response.message,
          })
          toast({ title: '操作失败', description: response.message, variant: 'error' })
        }
      } catch (err) {
        logger.error('[HoldingsPage] 交易操作异常', {
          code: item.code,
          action,
          error: err instanceof Error ? err.message : String(err),
        })
        toast({
          title: '操作异常',
          description: err instanceof Error ? err.message : '网络请求异常',
          variant: 'error',
        })
      } finally {
        if (isMountedRef.current) {
          setLoading({ isActionLoading: false })
        }
      }
    },
    [loadData, setLoading, closeModal, toast],
  )

  return (
    <div className="space-y-4">
      {/* 面包屑导航 */}
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/">首页</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/trading">交易舱</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbItem>
            <BreadcrumbPage>持仓管理</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      {/* 页面标题 */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">交易持仓管理</h1>
          <p className="text-sm text-muted-foreground">
            统一管理投资组合持仓，支持策略评分对比与资产配置全局视图
          </p>
        </div>
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <FileText className="h-4 w-4" />
          共 {pagination.total} 条持仓记录
        </div>
      </div>

      {/* 筛选区 */}
      <HoldingsFilter
        filter={filter}
        handlers={{
          onSearch: handleSearch,
          onReset: handleReset,
          onExport: handleExport,
          onUpdateFilter: setFilter,
        }}
        isExporting={loading.isExporting}
        disabled={guardProps.disabled}
      />

      {/* 数据表格 */}
      <HoldingsTable
        data={data}
        isLoading={loading.isListLoading}
        onAction={handleAction}
      />

      {/* 分页 */}
      <Pagination
        pagination={pagination}
        handlers={{
          onPageChange: handlePageChange,
          onPageSizeChange: handlePageSizeChange,
        }}
      />

      {/* 交易确认弹窗 */}
      <TradeModal
        modal={modal}
        isActionLoading={loading.isActionLoading}
        onClose={handleCloseModal}
        onConfirm={handleConfirmTrade}
      />
    </div>
  )
}

import { useEffect, useMemo } from 'react'
import { Link } from 'react-router'
import { Save, History, Camera } from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/Breadcrumb'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs'
import { StrategyGroupCard } from '@/components/strategy/StrategyGroupCard'
import { ChangeLogPanel } from '@/components/strategy/ChangeLogPanel'
import { useStrategySnapshotStore } from '@/store/strategySnapshotStore'
import { getLogger } from '@/lib/logger'
import { twBg } from '@/constants/theme.tokens'

const logger = getLogger()

const GROUP_CONFIG: Array<{ key: 'core' | 'hot' | 'value'; title: string; color: string }> = [
  { key: 'core', title: '核心稀缺', color: twBg('emerald', 500) },
  { key: 'hot', title: '热点动量', color: twBg('amber', 500) },
  { key: 'value', title: '价值洼地', color: twBg('blue', 500) },
]

export default function StrategySnapshotPage(): React.JSX.Element {
  // 从 Store 获取状态
  const activeTab = useStrategySnapshotStore((s) => s.activeTab)
  const stocks = useStrategySnapshotStore((s) => s.stocks)
  const v6Scores = useStrategySnapshotStore((s) => s.v6Scores)
  const rotationScores = useStrategySnapshotStore((s) => s.rotationScores)
  const items = useStrategySnapshotStore((s) => s.items)
  const snapshots = useStrategySnapshotStore((s) => s.snapshots)
  const selectedSnapshot = useStrategySnapshotStore((s) => s.selectedSnapshot)
  const loading = useStrategySnapshotStore((s) => s.loading)
  const saving = useStrategySnapshotStore((s) => s.saving)
  const error = useStrategySnapshotStore((s) => s.error)

  // 从 Store 获取 actions
  const setActiveTab = useStrategySnapshotStore((s) => s.setActiveTab)
  const loadCurrentStrategy = useStrategySnapshotStore((s) => s.loadCurrentStrategy)
  const loadHistorySnapshots = useStrategySnapshotStore((s) => s.loadHistorySnapshots)
  const saveSnapshot = useStrategySnapshotStore((s) => s.saveSnapshot)
  const selectSnapshot = useStrategySnapshotStore((s) => s.selectSnapshot)

  // 监听 activeTab 变化，加载对应数据
  useEffect(() => {
    logger.info('[StrategySnapshotPage] activeTab 切换', { activeTab })
    if (activeTab === 'current') {
      loadCurrentStrategy()
    } else if (activeTab === 'history') {
      loadHistorySnapshots()
    }
  }, [activeTab, loadCurrentStrategy, loadHistorySnapshots])

  // 构建分类后的 items（Store 中已经是分类后的结构）
  const groupedItems = useMemo(() => {
    logger.info('[StrategySnapshotPage] 构建分类数据', {
      core: items.core.length,
      hot: items.hot.length,
      value: items.value.length,
    })
    return items
  }, [items])

  // 保存快照处理
  async function handleSaveSnapshot() {
    logger.info('[StrategySnapshotPage] 开始保存快照', {
      stockCount: stocks.length,
      v6ScoreCount: v6Scores.length,
      rotationScoreCount: rotationScores.length,
      activeTab,
    })
    if (stocks.length === 0) {
      logger.warn('[StrategySnapshotPage] 跳过保存：股票池为空')
      return
    }
    await saveSnapshot('manual')
    logger.info('[StrategySnapshotPage] 快照保存完成')
  }

  // 选择快照处理
  function handleSelectSnapshot(id: string) {
    logger.info('[StrategySnapshotPage] 选择快照', { snapshotId: id })
    selectSnapshot(id)
  }

  return (
    <div className="space-y-6">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/">首页</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbLink asChild>
              <Link to="/trading">交易舱</Link>
            </BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>策略快照</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">策略快照</h1>
          <p className="text-muted-foreground">三策略分组快照、版本管理与变更追踪</p>
        </div>
        <Badge variant="secondary">V6 Pro</Badge>
      </div>

      <Tabs value={activeTab} onValueChange={(value) => setActiveTab(value as 'current' | 'history')}>
        <TabsList>
          <TabsTrigger value="current">当前策略</TabsTrigger>
          <TabsTrigger value="history">历史快照</TabsTrigger>
        </TabsList>

        <TabsContent value="current" className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="text-sm text-muted-foreground">
              股票 {stocks.length} / V6 评分 {v6Scores.length} / 轮动评分 {rotationScores.length}
            </div>
            <Button
              size="sm"
              onClick={handleSaveSnapshot}
              disabled={saving || stocks.length === 0}
              data-testid="save-snapshot-button"
            >
              <Save className="mr-2 h-4 w-4" />
              {saving ? '保存中...' : '保存当前快照'}
            </Button>
          </div>

          {error && <p className="text-sm text-destructive">{error}</p>}

          {loading ? (
            <p className="text-sm text-muted-foreground">加载中...</p>
          ) : (
            <div className="grid gap-4 md:grid-cols-3">
              {GROUP_CONFIG.map((group) => (
                <StrategyGroupCard
                  key={group.key}
                  title={group.title}
                  items={groupedItems[group.key]}
                  color={group.color}
                />
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="history" className="space-y-4">
          {error && <p className="text-sm text-destructive">{error}</p>}
          {loading ? (
            <p className="text-sm text-muted-foreground">加载中...</p>
          ) : (
            <div className="grid gap-4 lg:grid-cols-3">
              <Card className="lg:col-span-1">
                <CardHeader>
                  <div className="flex items-center gap-2">
                    <History className="h-4 w-4 text-muted-foreground" />
                    <CardTitle className="text-base">快照列表</CardTitle>
                  </div>
                  <CardDescription>最近 20 条策略快照</CardDescription>
                </CardHeader>
                <CardContent>
                  {snapshots.length === 0 ? (
                    <p className="text-sm text-muted-foreground">暂无历史快照</p>
                  ) : (
                    <ul className="space-y-2">
                      {snapshots.map((snapshot) => (
                        <li key={snapshot.id}>
                          <button
                            type="button"
                            onClick={() => handleSelectSnapshot(snapshot.id)}
                            className={`w-full rounded-md border p-3 text-left text-sm transition-colors hover:bg-accent ${
                              selectedSnapshot?.id === snapshot.id ? 'border-primary bg-primary/5' : ''
                            }`}
                            data-testid={`snapshot-item-${snapshot.id}`}
                          >
                            <div className="flex items-center justify-between">
                              <span className="font-medium">版本 {snapshot.version}</span>
                              <Badge variant="outline" className="text-xs">
                                {snapshot.trigger}
                              </Badge>
                            </div>
                            <div className="mt-1 text-xs text-muted-foreground">
                              {snapshot.date} {snapshot.time}
                            </div>
                          </button>
                        </li>
                      ))}
                    </ul>
                  )}
                </CardContent>
              </Card>

              <div className="space-y-4 lg:col-span-2">
                {selectedSnapshot ? (
                  <>
                    <Card>
                      <CardHeader>
                        <div className="flex items-center gap-2">
                          <Camera className="h-4 w-4 text-muted-foreground" />
                          <CardTitle className="text-base">快照详情</CardTitle>
                        </div>
                        <CardDescription>
                          版本 {selectedSnapshot.version} · {selectedSnapshot.date} {selectedSnapshot.time} · 触发器{' '}
                          {selectedSnapshot.trigger}
                        </CardDescription>
                      </CardHeader>
                      <CardContent>
                        <div className="grid gap-4 sm:grid-cols-3">
                          <div className="rounded-md border p-3 text-center">
                            <div className="text-2xl font-bold">{selectedSnapshot.core.count}</div>
                            <div className="text-xs text-muted-foreground">核心稀缺</div>
                          </div>
                          <div className="rounded-md border p-3 text-center">
                            <div className="text-2xl font-bold">{selectedSnapshot.hot.count}</div>
                            <div className="text-xs text-muted-foreground">热点动量</div>
                          </div>
                          <div className="rounded-md border p-3 text-center">
                            <div className="text-2xl font-bold">{selectedSnapshot.value.count}</div>
                            <div className="text-xs text-muted-foreground">价值洼地</div>
                          </div>
                        </div>
                        <div className="mt-4 text-xs text-muted-foreground">
                          股票 {selectedSnapshot.stockCount} / 评分 {selectedSnapshot.scoreCount} / 轮动{' '}
                          {selectedSnapshot.rotationCount}
                        </div>
                      </CardContent>
                    </Card>

                    <ChangeLogPanel snapshot={selectedSnapshot} />
                  </>
                ) : (
                  <Card>
                    <CardContent className="py-8 text-center text-sm text-muted-foreground">
                      选择左侧快照查看详情
                    </CardContent>
                  </Card>
                )}
              </div>
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  )
}

/**
 * @module HoldingsTable
 * @description 持仓数据表格组件。左侧固定证券代码/名称列，右侧固定操作列，盈亏列使用语义化颜色渲染。
 * 加载状态显示骨架屏，空数据显示空状态提示。
 * 所有颜色、列宽、固定配置从 @/constants/trade.constants 引用，禁止硬编码。
 */

import React from 'react'
import { TrendingDown, TrendingUp } from 'lucide-react'
import { Button } from '@/components/ui/Button'
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '@/components/ui/Table'
import { Skeleton } from '@/components/ui/Skeleton'
import { Badge } from '@/components/ui/Badge'
import {
  HOLDING_ACTION,
  HOLDING_ACTION_LABELS,
  STRATEGY_TYPE_LABELS,
  STRATEGY_TYPE_COLORS,
  getPnlColorClass,
  getPnlBgClass,
  SKELETON_ROW_COUNT,
  SKELETON_COLUMNS,
} from '@/constants/trade.constants'
import type { HoldingItem } from '@/types/modules/trade.types'
import type { HoldingAction } from '@/constants/trade.constants'

interface HoldingsTableProps {
  /** 持仓数据列表 */
  data: HoldingItem[]
  /** 是否加载中 */
  isLoading: boolean
  /** 操作列点击回调 */
  onAction: (item: HoldingItem, action: HoldingAction) => void
}

function formatNumber(value: number, decimals = 2): string {
  return value.toFixed(decimals)
}

function formatPercent(value: number): string {
  const sign = value >= 0 ? '+' : ''
  return `${sign}${value.toFixed(2)}%`
}

/** 骨架屏行 */
function SkeletonRow(): React.JSX.Element {
  return (
    <TableRow>
      {SKELETON_COLUMNS.map((col, idx) => (
        <TableCell key={idx}>
          <Skeleton className={`h-5 ${col.width}`} />
        </TableCell>
      ))}
    </TableRow>
  )
}

/** 空数据状态 */
function EmptyState(): React.JSX.Element {
  return (
    <TableRow>
      <td colSpan={9} className="h-48 text-center p-4 align-middle">
        <div className="flex flex-col items-center justify-center gap-2 text-muted-foreground">
          <svg className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
          </svg>
          <p className="text-sm">暂无持仓数据</p>
          <p className="text-xs">调整筛选条件或添加持仓后重试</p>
        </div>
      </td>
    </TableRow>
  )
}

export default function HoldingsTable({
  data,
  isLoading,
  onAction,
}: HoldingsTableProps): React.JSX.Element {
  return (
    <div className="overflow-x-auto rounded-md border">
      <Table>
        <TableHeader>
          <TableRow>
            {/* 左侧固定列：证券代码 */}
            <TableHead className="sticky left-0 z-10 bg-background min-w-[100px]">
              证券代码
            </TableHead>
            {/* 左侧固定列：证券名称 */}
            <TableHead className="sticky left-[100px] z-10 bg-background min-w-[120px]">
              证券名称
            </TableHead>
            <TableHead className="text-right">持仓数量</TableHead>
            <TableHead className="text-right">当前价格</TableHead>
            <TableHead className="text-right">成本价</TableHead>
            <TableHead className="text-right">浮动盈亏</TableHead>
            <TableHead className="text-right">市值占比</TableHead>
            <TableHead>策略类型</TableHead>
            {/* 右侧固定列：操作 */}
            <TableHead className="sticky right-0 z-10 bg-background text-center min-w-[140px]">
              操作
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {isLoading ? (
            Array.from({ length: SKELETON_ROW_COUNT }).map((_, i) => (
              <SkeletonRow key={i} />
            ))
          ) : data.length === 0 ? (
            <EmptyState />
          ) : (
            data.map((item) => {
              const pnlColorClass = getPnlColorClass(item.floatingPnl)
              const pnlBgClass = getPnlBgClass(item.floatingPnl)
              const strategyConfig = STRATEGY_TYPE_COLORS[item.strategyType]

              return (
                <TableRow key={item.code}>
                  {/* 左侧固定列 */}
                  <TableCell className="sticky left-0 z-10 bg-background font-mono text-sm">
                    {item.code}
                  </TableCell>
                  <TableCell className="sticky left-[100px] z-10 bg-background font-medium">
                    {item.name}
                  </TableCell>
                  <TableCell className="text-right tabular-nums">
                    {formatNumber(item.quantity, 0)}
                  </TableCell>
                  <TableCell className="text-right tabular-nums">
                    {formatNumber(item.currentPrice)}
                  </TableCell>
                  <TableCell className="text-right tabular-nums">
                    {formatNumber(item.avgCost)}
                  </TableCell>
                  {/* 浮动盈亏：语义化颜色 */}
                  <TableCell className={`text-right tabular-nums ${pnlBgClass}`}>
                    <div className="flex items-center justify-end gap-1">
                      {item.floatingPnl > 0 ? (
                        <TrendingUp className="h-3.5 w-3.5" />
                      ) : item.floatingPnl < 0 ? (
                        <TrendingDown className="h-3.5 w-3.5" />
                      ) : null}
                      <span className={pnlColorClass}>
                        {formatPercent(item.floatingPnlPercent)}
                      </span>
                      <span className={`text-xs ${pnlColorClass}`}>
                        ({formatNumber(item.floatingPnl)})
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="text-right tabular-nums">
                    {formatPercent(item.marketValueRatio * 100)}
                  </TableCell>
                  {/* 策略类型标签 */}
                  <TableCell>
                    {strategyConfig ? (
                      <Badge
                        variant="outline"
                        className={`${strategyConfig.bg} ${strategyConfig.text} ${strategyConfig.border}`}
                      >
                        {STRATEGY_TYPE_LABELS[item.strategyType]}
                      </Badge>
                    ) : (
                      <span className="text-sm text-muted-foreground">-</span>
                    )}
                  </TableCell>
                  {/* 右侧固定列 */}
                  <TableCell className="sticky right-0 z-10 bg-background">
                    <div className="flex items-center justify-center gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => onAction(item, HOLDING_ACTION.ADD_POSITION)}
                        className="h-7 text-xs"
                      >
                        {HOLDING_ACTION_LABELS[HOLDING_ACTION.ADD_POSITION]}
                      </Button>
                      <Button
                        variant="danger"
                        size="sm"
                        onClick={() => onAction(item, HOLDING_ACTION.CLOSE_POSITION)}
                        className="h-7 text-xs"
                      >
                        {HOLDING_ACTION_LABELS[HOLDING_ACTION.CLOSE_POSITION]}
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              )
            })
          )}
        </TableBody>
      </Table>
    </div>
  )
}

/**
 * @module Pagination
 * @description 标准后台分页组件。支持每页条数切换、页码跳转、前后翻页。
 * 所有配置值从 @/constants/trade.constants 引用，禁止硬编码。
 */

import React, { useCallback, useState } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { Button } from '@/components/ui/Button'
import { Select } from '@/components/ui/Select'
import {
  PAGINATION_DEFAULTS,
  PAGINATION_MAX_VISIBLE,
} from '@/constants/trade.constants'
import type { PaginationState, PaginationHandlers } from '@/types/modules/trade.types'

interface PaginationProps {
  /** 分页状态 */
  pagination: PaginationState
  /** 分页操作回调 */
  handlers: PaginationHandlers
}

export default function Pagination({ pagination, handlers }: PaginationProps): React.JSX.Element {
  const { page, pageSize, total } = pagination
  const { onPageChange, onPageSizeChange } = handlers
  const [jumpValue, setJumpValue] = useState('')

  const totalPages = Math.max(1, Math.ceil(total / pageSize))

  /** 计算可见页码范围 */
  const getVisiblePages = useCallback((): number[] => {
    const half = Math.floor(PAGINATION_MAX_VISIBLE / 2)
    let start = Math.max(1, page - half)
    const end = Math.min(totalPages, start + PAGINATION_MAX_VISIBLE - 1)
    if (end - start + 1 < PAGINATION_MAX_VISIBLE) {
      start = Math.max(1, end - PAGINATION_MAX_VISIBLE + 1)
    }
    return Array.from({ length: end - start + 1 }, (_, i) => start + i)
  }, [page, totalPages])

  const handleJump = useCallback(() => {
    const target = parseInt(jumpValue, 10)
    if (isNaN(target) || target < 1 || target > totalPages) return
    onPageChange(target)
    setJumpValue('')
  }, [jumpValue, totalPages, onPageChange])

  const handleJumpKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') handleJump()
    },
    [handleJump],
  )

  const visiblePages = getVisiblePages()

  return (
    <div className="flex items-center justify-between border-t px-2 py-3">
      {/* 左侧：总条数 + 每页条数 */}
      <div className="flex items-center gap-4">
        <span className="text-sm text-muted-foreground">
          共 {total} 条
        </span>
        <div className="flex items-center gap-2">
          <span className="text-sm text-muted-foreground">每页</span>
          <Select
            aria-label="每页显示条数"
            value={String(pageSize)}
            onChange={(e) => onPageSizeChange(Number((e.target as HTMLSelectElement).value))}
            className="h-8 w-20"
          >
            {PAGINATION_DEFAULTS.PAGE_SIZE_OPTIONS.map((size) => (
              <option key={size} value={String(size)}>
                {size}
              </option>
            ))}
          </Select>
          <span className="text-sm text-muted-foreground">条</span>
        </div>
      </div>

      {/* 右侧：翻页控制 */}
      <div className="flex items-center gap-1">
        {/* 上一页 */}
        <Button
          variant="ghost"
          size="sm"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
          className="h-8 w-8 p-0"
        >
          <ChevronLeft className="h-4 w-4" />
        </Button>

        {/* 页码 */}
        {visiblePages.map((p) => (
          <Button
            key={p}
            variant={p === page ? 'primary' : 'ghost'}
            size="sm"
            onClick={() => onPageChange(p)}
            className="h-8 w-8 p-0 text-sm"
          >
            {p}
          </Button>
        ))}

        {/* 下一页 */}
        <Button
          variant="ghost"
          size="sm"
          disabled={page >= totalPages}
          onClick={() => onPageChange(page + 1)}
          className="h-8 w-8 p-0"
        >
          <ChevronRight className="h-4 w-4" />
        </Button>

        {/* 跳转 */}
        <div className="ml-3 flex items-center gap-1">
          <span className="text-sm text-muted-foreground">跳至</span>
          <input
            type="text"
            value={jumpValue}
            onChange={(e) => setJumpValue(e.target.value.replace(/\D/g, ''))}
            onKeyDown={handleJumpKeyDown}
            placeholder="..."
            aria-label="跳转到页码"
            className="h-8 w-12 rounded-md border border-input bg-background px-2 text-center text-sm"
          />
          <Button
            variant="outline"
            size="sm"
            onClick={handleJump}
            className="h-8 px-2 text-xs"
