/**
 * 虚拟滚动持仓表格组件
 * 当数据量超过 VIRTUALIZATION_THRESHOLD (100条) 时自动启用虚拟滚动
 */
export function VirtualizedHoldingsTable({
  data,
  isLoading,
  onAction,
}: VirtualizedHoldingsTableProps): React.JSX.Element {
  const parentRef = useRef<HTMLDivElement>(null)

  // 根据数据量决定是否启用虚拟滚动
  const useVirtual = data.length > VIRTUALIZATION_THRESHOLD

  const virtualizer = useVirtualizer({
    count: data.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 48, // 每行高度
    overscan: 5, // 预渲染行数
  })

  // 加载状态
  if (isLoading) {
    return (
      <div className="overflow-hidden rounded-md border">
        <TableHeader />
        <div>
          {Array.from({ length: 10 }).map((_, i) => (
            <SkeletonRow key={i} />
          ))}
        </div>
      </div>
    )
  }

  // 空数据状态
  if (data.length === 0) {
    return (
      <div className="overflow-hidden rounded-md border">
        <TableHeader />
        <EmptyState />
      </div>
    )
  }

  // 小数据量：直接渲染（避免虚拟滚动开销）
  if (!useVirtual) {
    return (
      <div className="overflow-hidden rounded-md border">
        <TableHeader />
        <div>
          {data.map((item) => (
            <HoldingsRow key={item.code} holding={item} onAction={onAction} />
          ))}
        </div>
      </div>
    )
  }

  // 大数据量：虚拟滚动渲染
  return (
    <div className="overflow-hidden rounded-md border">
      <TableHeader />
      <div
        ref={parentRef}
        className="h-[500px] overflow-auto"
        style={CONTAIN_STRICT_STYLE}
      >
        <div
          style={{
            height: `${virtualizer.getTotalSize()}px`,
            width: '100%',
            position: 'relative',
          }}
        >
          {virtualizer.getVirtualItems().map((virtualRow) => {
            const holding = data[virtualRow.index]
            if (!holding) return null
            return (
              <div
                key={virtualRow.key}
                data-index={virtualRow.index}
                ref={virtualizer.measureElement}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  transform: `translateY(${virtualRow.start}px)`,
                }}
              >
                <HoldingsRow holding={holding} onAction={onAction} />
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

export default VirtualizedHoldingsTable

