/**
 * scoreTrendService - 多周期评分趋势聚合服务
 *
 * 为行业评分（V4）与智能评分（个股）提供按周/月/季度的趋势数据聚合，
 * 所有标签、阈值均来自配置与类型，组件层零硬编码。
 */

import { dataLayer } from '@/data/dataLayer'
import { getLogger } from '@/lib/logger'
import type { ScoreTrendPeriod } from '@/types/modules/score.types'
import { MS_PER_DAY } from '@/config/mathConstants'

const logger = getLogger()

export type { ScoreTrendPeriod }
export type ScoreTrendEntityType = 'industry' | 'stock'

export interface ScoreTrendPoint {
  /** 周期标签，如 2026-W27 / 2026-07 / 2026-Q3 */
  period: string
  /** 综合评分平均值 */
  composite: number
  /** 参与聚合的样本数 */
  count: number
  /** 各维度平均分 */
  dimensions: Record<string, number>
}

export interface ScoreTrendData {
  entityId: string
  entityType: ScoreTrendEntityType
  period: ScoreTrendPeriod
  points: ScoreTrendPoint[]
}

interface DimensionLike {
  name: string
  score: number | null | undefined
}

interface Bucket {
  label: string
  compositeSum: number
  compositeCount: number
  dimensions: Map<string, { sum: number; count: number }>
}

function getISOWeek(date: Date): number {
  const tmp = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
  const dayNum = tmp.getUTCDay() || 7
  tmp.setUTCDate(tmp.getUTCDate() + 4 - dayNum)
  const yearStart = new Date(Date.UTC(tmp.getUTCFullYear(), 0, 1))
  return Math.ceil((((tmp.getTime() - yearStart.getTime()) / MS_PER_DAY) + 1) / 7)
}

function getISOWeekYear(date: Date): number {
  const tmp = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
  const dayNum = tmp.getUTCDay() || 7
  tmp.setUTCDate(tmp.getUTCDate() + 4 - dayNum)
  return tmp.getUTCFullYear()
}

export function formatPeriodLabel(date: Date, period: ScoreTrendPeriod): string {
  if (period === 'week') {
    const year = getISOWeekYear(date)
    const week = String(getISOWeek(date)).padStart(2, '0')
    return `${year}-W${week}`
  }

  if (period === 'month') {
    const year = date.getFullYear()
    const month = String(date.getMonth() + 1).padStart(2, '0')
    return `${year}-${month}`
  }

  const year = date.getFullYear()
  const quarter = Math.floor(date.getMonth() / 3) + 1
  return `${year}-Q${quarter}`
}

export function aggregateScoresByPeriod<T>(
  items: T[],
  period: ScoreTrendPeriod,
  getDate: (item: T) => Date,
  getScore: (item: T) => number | null | undefined,
  getDimensions?: (item: T) => DimensionLike[],
): ScoreTrendPoint[] {
  const buckets = new Map<string, Bucket>()

  for (const item of items) {
    const date = getDate(item)
    if (Number.isNaN(date.getTime())) {
      logger.warn('aggregateScoresByPeriod: 跳过无效日期项')
      continue
    }

    const label = formatPeriodLabel(date, period)
    let bucket = buckets.get(label)
    if (!bucket) {
      bucket = { label, compositeSum: 0, compositeCount: 0, dimensions: new Map() }
      buckets.set(label, bucket)
    }

    const score = getScore(item)
    if (typeof score === 'number' && Number.isFinite(score)) {
      bucket.compositeSum += score
      bucket.compositeCount += 1
    }

    if (getDimensions) {
      for (const dim of getDimensions(item)) {
        if (!dim || !dim.name) continue
        const s = dim.score
        if (typeof s !== 'number' || !Number.isFinite(s)) continue
        let entry = bucket.dimensions.get(dim.name)
        if (!entry) {
          entry = { sum: 0, count: 0 }
          bucket.dimensions.set(dim.name, entry)
        }
        entry.sum += s
        entry.count += 1
      }
    }
  }

  const sortedLabels = Array.from(buckets.keys()).sort()
  return sortedLabels.map((label) => {
    const bucket = buckets.get(label)!
    const composite = bucket.compositeCount > 0
      ? Number((bucket.compositeSum / bucket.compositeCount).toFixed(2))
      : 0

    const dimensions: Record<string, number> = {}
    for (const [name, entry] of bucket.dimensions.entries()) {
      dimensions[name] = entry.count > 0
        ? Number((entry.sum / entry.count).toFixed(2))
        : 0
    }

    return {
      period: label,
      composite,
      count: bucket.compositeCount,
      dimensions,
    }
  })
}

export async function loadIndustryScoreTrend(
  code: string,
  period: ScoreTrendPeriod,
): Promise<{ success: true; data: ScoreTrendData } | { success: false; error: string }> {
  try {
    const scores = await dataLayer.industryScores.listByCode(code)
    const points = aggregateScoresByPeriod(
      scores,
      period,
      (s) => new Date(s.scoredAt),
      (s) => s.overallScore,
      (s) => s.dimensionScores,
    )

    return {
      success: true,
      data: { entityId: code, entityType: 'industry', period, points },
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`loadIndustryScoreTrend 失败: ${message}`, { err, code, period })
    return { success: false, error: message }
  }
}

export async function loadStockScoreTrend(
  symbol: string,
  period: ScoreTrendPeriod,
): Promise<{ success: true; data: ScoreTrendData } | { success: false; error: string }> {
  try {
    const scores = await dataLayer.intelligentScores.listBySymbol(symbol)
    const points = aggregateScoresByPeriod(
      scores,
      period,
      (s) => new Date(s.scoredAt),
      (s) => s.overallScore,
      (s) => s.dimensionScores,
    )

    return {
      success: true,
      data: { entityId: symbol, entityType: 'stock', period, points },
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`loadStockScoreTrend 失败: ${message}`, { err, symbol, period })
    return { success: false, error: message }
  }
}

import { RESEARCH_STATUS, type ResearchStatus } from '@/config/dbConfig'
import { getDefaultScreeningConfig } from '@/config/screeningConfig'
import { dataLayer } from '@/data/dataLayer'
import type { DataLayerResult, Stock } from '@/data/types'
import { transitionStock } from '@/services/stockpool/stockpoolService'

export interface ScreeningResult {
  promotedToScreened: string[]
  promotedToDeepDive: string[]
  errors: string[]
}

function isQualityOk(
  stock: Stock,
  required: { basic?: boolean; kline?: boolean; finance?: boolean },
): boolean {
  const q = stock.dataQuality
  if (!q) return false
  if (required.basic && !q.basic) return false
  if (required.kline && !q.kline) return false
  if (required.finance && !q.finance) return false
  return true
}

async function canPromoteToScreened(stock: Stock): Promise<boolean> {
  if (stock.researchStatus !== RESEARCH_STATUS.candidate) return false

  const config = getDefaultScreeningConfig()
  const qualityOk = isQualityOk(stock, {
    basic: config.thresholds.requireBasicForScreened,
    kline: config.thresholds.requireKlineForScreened,
  })
  if (!qualityOk) return false

  const v6 = await dataLayer.v6Scores.get(stock.symbol)
  if (!v6) return false

  return v6.score >= config.thresholds.minV6ScoreForScreened
}

async function canPromoteToDeepDive(stock: Stock): Promise<boolean> {
  if (stock.researchStatus !== RESEARCH_STATUS.screened) return false

  const config = getDefaultScreeningConfig()
  const qualityOk = isQualityOk(stock, {
    basic: true,
    kline: true,
    finance: config.thresholds.requireFinanceForDeepDive,
  })
  if (!qualityOk) return false

  const v6 = await dataLayer.v6Scores.get(stock.symbol)
  const intelligent = await dataLayer.intelligentScores.getLatestBySymbol(stock.symbol)

  const v6Ok = v6 !== undefined && v6.score >= config.thresholds.minV6ScoreForDeepDive
  const intelligentOk =
    intelligent !== undefined &&
    intelligent.overallScore !== null &&
    intelligent.overallScore >= config.thresholds.minIntelligentScoreForDeepDive

  return v6Ok || intelligentOk
}

async function tryPromote(
  stock: Stock,
  toStatus: ResearchStatus,
  eligibility: (s: Stock) => Promise<boolean>,
  result: ScreeningResult,
  targetKey: 'promotedToScreened' | 'promotedToDeepDive',
): Promise<void> {
  const ok = await eligibility(stock)
  if (!ok) return

  const transitionResult = await transitionStock(stock.symbol, toStatus)
  if (transitionResult.success) {
    result[targetKey].push(stock.symbol)
  } else {
    result.errors.push(`${stock.symbol}: ${transitionResult.error ?? '流转失败'}`)
  }
}

/**
 * 对全量股票池运行筛选规则
 *
 * 按以下顺序执行：
 * 1. candidate → screened
 * 2. screened → deepDive
 */
export async function runScreening(): Promise<DataLayerResult<ScreeningResult>> {
  const result: ScreeningResult = {
    promotedToScreened: [],
    promotedToDeepDive: [],
    errors: [],
  }

  try {
    const candidates = await dataLayer.stocks.listByStatus(RESEARCH_STATUS.candidate)
    for (const stock of candidates) {
      await tryPromote(stock, RESEARCH_STATUS.screened, canPromoteToScreened, result, 'promotedToScreened')
    }

    const screened = await dataLayer.stocks.listByStatus(RESEARCH_STATUS.screened)
    for (const stock of screened) {
      await tryPromote(stock, RESEARCH_STATUS.deepDive, canPromoteToDeepDive, result, 'promotedToDeepDive')
    }

    return { success: true, data: result }
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

/**
 * 对单只股票执行即时筛选
 *
 * 仅当股票处于 candidate 或 screened 时可能晋升；其他状态无动作。
 */
export async function screenSingleStock(symbol: string): Promise<DataLayerResult<ScreeningResult>> {
  const result: ScreeningResult = {
    promotedToScreened: [],
    promotedToDeepDive: [],
    errors: [],
  }

  try {
    const stock = await dataLayer.stocks.get(symbol)
    if (!stock) {
      return { success: false, error: `股票不存在: ${symbol}` }
    }

    if (stock.researchStatus === RESEARCH_STATUS.candidate) {
      await tryPromote(stock, RESEARCH_STATUS.screened, canPromoteToScreened, result, 'promotedToScreened')
    } else if (stock.researchStatus === RESEARCH_STATUS.screened) {
      await tryPromote(stock, RESEARCH_STATUS.deepDive, canPromoteToDeepDive, result, 'promotedToDeepDive')
    }

    return { success: true, data: result }
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

