  quantity: number
  date: string
  commission: number
}

export interface VirtualPosition {
  symbol: string
  quantity: number
  avgCost: number
  currentPrice: number
  marketValue: number
  unrealizedPnL: number
}

export interface BacktestEngineResult {
  trades: VirtualOrder[]
  positions: VirtualPosition[]
  dailyValues: { date: string; totalValue: number; cash: number }[]
  metrics: BacktestResult
}

interface BacktestEvent {
  symbol: string
  direction: 'buy' | 'sell'
  date: string
  price: number
  confidence: number
  source: 'signal' | 'order'
  strategy?: string
}

interface InternalPosition {
  quantity: number
  avgCost: number
}

// ============================================================
// 回测引擎
// ============================================================

export class BacktestEngine {
  /**
   * 执行回测。
   */
  async run(config: BacktestEngineConfig): Promise<BacktestEngineResult> {
    logger.info('[BacktestEngine] 开始回测', {
      strategy: config.strategy,
      startDate: config.startDate,
      endDate: config.endDate,
      initialCapital: config.initialCapital,
    })

    // 1. 加载信号/订单事件
    const events = await this._loadEvents(config)
    if (events.length === 0) {
      logger.warn('[BacktestEngine] 未找到任何信号/订单，返回空结果')
      return this._emptyResult(config)
    }

    // 2. 预加载行情数据
    const quotesCache = await this._preloadQuotes(events)

    // 3. 初始化状态
    let cash = config.initialCapital
    const positions = new Map<string, InternalPosition>()
    const trades: VirtualOrder[] = []
    const dailyValues: { date: string; totalValue: number; cash: number }[] = []

    // 4. 按日期分组事件
    const eventsByDate = this._groupEventsByDate(events)

    // 5. 生成日期序列并逐日执行
    const dateList = this._generateDateRange(config.startDate, config.endDate)

    for (const date of dateList) {
      const dayEvents = eventsByDate.get(date) ?? []

      // 先处理卖出，释放现金
      const sellEvents = dayEvents.filter((e) => e.direction === 'sell')
      const buyEvents = dayEvents.filter((e) => e.direction === 'buy')

      for (const evt of sellEvents) {
        const price = this._getPriceForDate(evt.symbol, date, quotesCache) ?? evt.price
        if (price <= 0) continue

        const qty = this._calculateSellQuantity(evt.symbol, positions)
        if (qty <= 0) continue

        const order = this._executeVirtualSell(evt.symbol, price, qty, date, config)
        trades.push(order)
        cash = cash + order.quantity * order.price - order.commission

        const pos = positions.get(evt.symbol)
        if (pos) {
          const remaining = pos.quantity - order.quantity
          if (remaining <= 0) {
            positions.delete(evt.symbol)
          } else {
            positions.set(evt.symbol, { quantity: remaining, avgCost: pos.avgCost })
          }
        }
      }

      for (const evt of buyEvents) {
        const price = this._getPriceForDate(evt.symbol, date, quotesCache) ?? evt.price
        if (price <= 0) continue

        const portfolioValue = this._calculatePortfolioValue(cash, positions, date, quotesCache)
        const qty = this._calculatePositionSize(evt, cash, portfolioValue, positions, config)
        if (qty <= 0) continue

        const order = this._executeVirtualBuy(evt.symbol, price, qty, date, config)
        const totalCost = order.quantity * order.price + order.commission
        if (totalCost > cash) continue

        trades.push(order)
        cash = cash - totalCost

        const pos = positions.get(evt.symbol) ?? { quantity: 0, avgCost: 0 }
        const newQty = pos.quantity + order.quantity
        const newAvgCost =
          newQty > 0
            ? (pos.quantity * pos.avgCost + order.quantity * order.price) / newQty
            : 0
        positions.set(evt.symbol, { quantity: newQty, avgCost: newAvgCost })
      }

      // 6. 记录当日收盘净值
      const dayTotalValue = this._calculatePortfolioValue(cash, positions, date, quotesCache)
      dailyValues.push({ date, totalValue: dayTotalValue, cash })
    }

    // 7. 计算绩效指标
    const metrics = this._calculateMetrics(dailyValues, trades, config)

    // 8. 构建最终持仓
    const virtualPositions = this._buildVirtualPositions(positions, config.endDate, quotesCache)

    // 9. 将持仓与净值序列一并注入 metrics，供 backtestStore 导出使用（避免重复计算）
    metrics.positions = virtualPositions
    metrics.dailyValues = dailyValues

    logger.info('[BacktestEngine] 回测完成', {
      tradeCount: trades.length,
      finalValue: dailyValues[dailyValues.length - 1]?.totalValue ?? config.initialCapital,
      totalReturn: metrics.totalReturn,
    })

    return { trades, positions: virtualPositions, dailyValues, metrics }
  }

  // ============================================================
  // 信号加载
  // ============================================================

  private async _loadEvents(config: BacktestEngineConfig): Promise<BacktestEvent[]> {
    const startTs = new Date(config.startDate).getTime()
    const endTsEod = new Date(config.endDate)
    endTsEod.setHours(23, 59, 59, MS_END_OF_DAY)
    const endTs = endTsEod.getTime()

    // 1. 从 signals 获取策略信号
    const signalEvents = await this._loadSignalEvents(config, startTs, endTs)

    // 2. 若信号不足，用 orders 补充
    if (signalEvents.length < MIN_SIGNAL_EVENTS_FOR_COMBINE) {
      const orderEvents = await this._loadOrderEvents(config, startTs, endTs)
      const combined = this._mergeEvents(signalEvents, orderEvents)
      return combined.sort((a, b) => a.date.localeCompare(b.date))
    }

    return signalEvents.sort((a, b) => a.date.localeCompare(b.date))
  }

  private async _loadSignalEvents(
    config: BacktestEngineConfig,
    startTs: number,
    endTs: number,
  ): Promise<BacktestEvent[]> {
    let signals: Signal[] = []
    try {
      signals = await dataLayer.signals.list()
    } catch {
      logger.warn('[BacktestEngine] 读取 signals 失败')
      return []
    }

    const filtered = signals.filter((s) => {
      const ts = s.createdAt ?? 0
      if (ts < startTs || ts > endTs) return false
      if (s.direction !== 'buy' && s.direction !== 'sell') return false
      if (config.strategy === 'hot_sector') return s.strategy === 'hot-sector'
      if (config.strategy === 'value_pit') return s.strategy === 'value-pit'
      return true // composite 或 strategy 未匹配时全保留
    })

    // 预加载行情用于定价
    const quotesCache = new Map<string, DailyQuotes>()
    for (const s of filtered) {
      if (!quotesCache.has(s.symbol)) {
        const q = await dataLayer.dailyQuotes.get(s.symbol)
        if (q) quotesCache.set(s.symbol, q)
      }
    }

    return filtered
      .map((s) => {
        const date = new Date(s.createdAt ?? Date.now()).toISOString().slice(0, 10)
        const quotes = quotesCache.get(s.symbol)
        const price = this._getPriceForDate(s.symbol, date, quotesCache) ?? quotes?.latest.close ?? 0
        return {
          symbol: s.symbol,
          direction: s.direction as 'buy' | 'sell',
          date,
          price,
          confidence: s.confidence,
          source: 'signal' as const,
          strategy: s.strategy,
        }
      })
      .filter((e) => e.price > 0)
  }

  private async _loadOrderEvents(
    _config: BacktestEngineConfig,
    startTs: number,
    endTs: number,
  ): Promise<BacktestEvent[]> {
    let orders: Order[] = []
    try {
      orders = await dataLayer.orders.list()
    } catch {
      logger.warn('[BacktestEngine] 读取 orders 失败')
      return []
    }

    const filtered = orders.filter((o) => {
      const ts = o.createdAt ?? 0
      return ts >= startTs && ts <= endTs && (o.direction === 'buy' || o.direction === 'sell')
    })

    return filtered.map((o) => ({
      symbol: o.symbol,
      direction: o.direction as 'buy' | 'sell',
      date: new Date(o.createdAt ?? Date.now()).toISOString().slice(0, 10),
      price: o.price,
      confidence: 0.5,
      source: 'order' as const,
      strategy: undefined,
    }))
  }

  private _mergeEvents(signals: BacktestEvent[], orders: BacktestEvent[]): BacktestEvent[] {
    const seen = new Set<string>()
    const merged: BacktestEvent[] = []

    for (const e of signals) {
      const key = `${e.date}-${e.symbol}-${e.direction}`
      if (!seen.has(key)) {
        seen.add(key)
        merged.push(e)
      }
    }

    for (const e of orders) {
      const key = `${e.date}-${e.symbol}-${e.direction}`
      if (!seen.has(key)) {
        seen.add(key)
        merged.push(e)
      }
    }

    return merged
  }

  private _groupEventsByDate(events: BacktestEvent[]): Map<string, BacktestEvent[]> {
    const map = new Map<string, BacktestEvent[]>()
    for (const e of events) {
      const list = map.get(e.date) ?? []
      list.push(e)
      map.set(e.date, list)
    }
    return map
  }

  // ============================================================
  // 行情数据
  // ============================================================

  private async _preloadQuotes(events: BacktestEvent[]): Promise<Map<string, DailyQuotes>> {
    const cache = new Map<string, DailyQuotes>()
    const symbols = new Set(events.map((e) => e.symbol))
    for (const sym of symbols) {
      const q = await dataLayer.dailyQuotes.get(sym)
      if (q) cache.set(sym, q)
    }
    return cache
  }

  private _getPriceForDate(
    symbol: string,
    date: string,
    cache: Map<string, DailyQuotes>,
  ): number | undefined {
    const quotes = cache.get(symbol)
    if (!quotes) return undefined
    const bar = quotes.history.find((b) => b.date === date)
    if (bar) return bar.close
    // 若历史无该日，回退到最新价（适用于信号日期在最新价附近）
    return quotes.latest.close
  }

  // ============================================================
  // 日期工具
  // ============================================================

  private _generateDateRange(startDate: string, endDate: string): string[] {
    const dates: string[] = []
    const start = new Date(startDate)
    const end = new Date(endDate)
    const curr = new Date(start)

    while (curr <= end) {
      // 跳过周末（简化：仅周六日）
      const day = curr.getDay()
      if (day !== 0 && day !== 6) {
        dates.push(curr.toISOString().slice(0, 10))
      }
      curr.setDate(curr.getDate() + 1)
    }

    return dates
  }

  // ============================================================
  // 仓位与执行
  // ============================================================

  /**
   * 计算买入数量。
   * 复用 positionSizer，并叠加 maxPositionPct 约束。
   */
  private _calculatePositionSize(
    event: BacktestEvent,
    cash: number,
    portfolioValue: number,
    positions: Map<string, InternalPosition>,
    config: BacktestEngineConfig,
  ): number {
    if (event.direction !== 'buy' || event.price <= 0 || portfolioValue <= 0) {
      return 0
    }

    const holding = positions.get(event.symbol) ?? { quantity: 0, avgCost: 0 }
    const holdingValue = holding.quantity * event.price
    const totalPositionValue = Array.from(positions.entries()).reduce((sum, [, pos]) => {
      return sum + pos.quantity * event.price
    }, 0)

    const sizing = calculatePosition({
      direction: 'buy',
      price: event.price,
      portfolioValue,
      currentHoldingShares: holding.quantity,
      currentHoldingValue: holdingValue,
      currentTotalPositionValue: totalPositionValue,
    })

    if (sizing.action !== 'buy' || sizing.targetShares <= 0) {
      return 0
    }

    let targetShares = sizing.targetShares

    // 叠加 maxPositionPct 约束（回测专用）
    const maxSingleValue = config.maxPositionPct * portfolioValue
    const afterBuyValue = (holding.quantity + targetShares) * event.price
    if (afterBuyValue > maxSingleValue) {
      const maxShares = Math.floor(maxSingleValue / event.price)
      targetShares = Math.max(0, maxShares - holding.quantity)
    }

    // 检查现金是否足够（含手续费）
    const execPrice = event.price * (1 + config.slippage)
    const maxAffordable = Math.floor(
      cash / (execPrice * (1 + config.commissionRate)),
    )
    targetShares = Math.min(targetShares, maxAffordable)

    return targetShares > 0 ? targetShares : 0
  }

  private _calculateSellQuantity(
    symbol: string,
    positions: Map<string, InternalPosition>,
  ): number {
    const pos = positions.get(symbol)
    return pos && pos.quantity > 0 ? pos.quantity : 0
  }

  private _executeVirtualBuy(
    symbol: string,
    price: number,
    quantity: number,
    date: string,
    config: BacktestEngineConfig,
  ): VirtualOrder {
    const execPrice = price * (1 + config.slippage)
    const grossValue = quantity * execPrice
    const commission = grossValue * config.commissionRate

    return {
      id: `bt-${generateId()}`,
      symbol,
      direction: 'buy',
      price: Math.round(execPrice * 100) / 100,
      quantity,
      date,
      commission: Math.round(commission * 100) / 100,
    }
  }

  private _executeVirtualSell(
    symbol: string,
    price: number,
    quantity: number,
    date: string,
    config: BacktestEngineConfig,
  ): VirtualOrder {
    const execPrice = price * (1 - config.slippage)
    const grossValue = quantity * execPrice
    const commission = grossValue * config.commissionRate

    return {
      id: `bt-${generateId()}`,
      symbol,
      direction: 'sell',
      price: Math.round(execPrice * 100) / 100,
      quantity,
      date,
      commission: Math.round(commission * 100) / 100,
    }
  }

  // ============================================================
  // 组合估值
  // ============================================================

  private _calculatePortfolioValue(
    cash: number,
    positions: Map<string, InternalPosition>,
    date: string,
    quotesCache: Map<string, DailyQuotes>,
  ): number {
    let marketValue = 0
    for (const [symbol, pos] of positions) {
      const price = this._getPriceForDate(symbol, date, quotesCache) ?? pos.avgCost
      marketValue += pos.quantity * price
    }
    return cash + marketValue
  }

  private _buildVirtualPositions(
    positions: Map<string, InternalPosition>,
    endDate: string,
    quotesCache: Map<string, DailyQuotes>,
  ): VirtualPosition[] {
    return Array.from(positions.entries()).map(([symbol, pos]) => {
      const price = this._getPriceForDate(symbol, endDate, quotesCache) ?? pos.avgCost
      const mv = pos.quantity * price
      const cost = pos.quantity * pos.avgCost
      return {
        symbol,
        quantity: pos.quantity,
        avgCost: Math.round(pos.avgCost * 100) / 100,
        currentPrice: Math.round(price * 100) / 100,
        marketValue: Math.round(mv * 100) / 100,
        unrealizedPnL: Math.round((mv - cost) * 100) / 100,
      }
    })
  }

  // ============================================================
  // 绩效指标
  // ============================================================

  private _calculateMetrics(
    dailyValues: { date: string; totalValue: number; cash: number }[],
    trades: VirtualOrder[],
    config: BacktestEngineConfig,
  ): BacktestResult {
    const DAYS_PER_YEAR = TRADING_DAYS_PER_YEAR
    const RISK_FREE_RATE = 0.03

    // 净值曲线（归一化）
    const pnlCurve = dailyValues.map((d) =>
      config.initialCapital > 0 ? d.totalValue / config.initialCapital : 1,
    )

    if (pnlCurve.length === 0) {
      return this._emptyMetrics(config)
    }

    const finalValue = pnlCurve[pnlCurve.length - 1]!
    const totalReturn = (finalValue - 1) * 100

    const totalDays = dailyValues.length
    const years = totalDays / DAYS_PER_YEAR
    const annualizedReturn =
      years > 0 ? (Math.pow(finalValue, 1 / years) - 1) * 100 : 0

    // 最大回撤
    let peak = 1.0
    let maxDrawdownVal = 0
    for (const v of pnlCurve) {
      if (v > peak) peak = v
      const dd = (peak - v) / peak
      if (dd > maxDrawdownVal) maxDrawdownVal = dd
    }

    // 夏普比率
    const dailyReturns: number[] = []
    for (let i = 1; i < pnlCurve.length; i++) {
      dailyReturns.push(pnlCurve[i]! / pnlCurve[i - 1]! - 1)
    }
    const meanDailyReturn =
      dailyReturns.length > 0
        ? dailyReturns.reduce((a, b) => a + b, 0) / dailyReturns.length
        : 0
    const stdDailyReturn =
      dailyReturns.length > 0
        ? Math.sqrt(
            dailyReturns.reduce((sum, r) => sum + (r - meanDailyReturn) ** 2, 0) /
              dailyReturns.length,
          )
        : 0
    const sharpeRatio =
      stdDailyReturn > 0
        ? (meanDailyReturn * DAYS_PER_YEAR - RISK_FREE_RATE) /
          (stdDailyReturn * Math.sqrt(DAYS_PER_YEAR))
        : 0

    // 交易盈亏统计（基于每笔卖出与其持仓成本的对比）
    const backtestTrades = this._buildBacktestTrades(trades, config)
    const profitTrades = backtestTrades.filter((t) => t.pnlPct > 0)
    const lossTrades = backtestTrades.filter((t) => t.pnlPct < 0)
    const tradeCount = backtestTrades.length
    const winRate = tradeCount > 0 ? (profitTrades.length / tradeCount) * 100 : 0
    const avgProfit =
      profitTrades.length > 0
        ? profitTrades.reduce((a, t) => a + t.pnlPct, 0) / profitTrades.length
        : 0
    const avgLoss =
      lossTrades.length > 0
        ? lossTrades.reduce((a, t) => a + t.pnlPct, 0) / lossTrades.length
        : 0

    return {
      totalReturn: Math.round(totalReturn * 100) / 100,
      annualizedReturn: Math.round(annualizedReturn * 100) / 100,
      maxDrawdown: Math.round(maxDrawdownVal * 10000) / 100,
      sharpeRatio: Math.round(sharpeRatio * 100) / 100,
      winRate: Math.round(winRate * 100) / 100,
      tradeCount,
      profitTrades: profitTrades.length,
      lossTrades: lossTrades.length,
      avgProfit: Math.round(avgProfit * 100) / 100,
      avgLoss: Math.round(avgLoss * 100) / 100,
      pnlCurve,
      trades: backtestTrades,
    }
  }

  /**
   * 将 VirtualOrder 序列转换为 BacktestTrade，计算每笔交易的盈亏。
   * 采用平均成本法：买入记录成本，卖出时按 avgCost 计算实现盈亏。
   */
  private _buildBacktestTrades(
    trades: VirtualOrder[],
    _config: BacktestEngineConfig,
  ): BacktestTrade[] {
    const result: BacktestTrade[] = []
    const avgCosts = new Map<string, number>() // symbol -> avgCost
    const quantities = new Map<string, number>() // symbol -> 当前持仓

    for (const t of trades) {
      if (t.direction === 'buy') {
        const prevQty = quantities.get(t.symbol) ?? 0
        const prevCost = avgCosts.get(t.symbol) ?? 0
        const newQty = prevQty + t.quantity
        const newAvgCost =
          newQty > 0 ? (prevQty * prevCost + t.quantity * t.price) / newQty : 0

        quantities.set(t.symbol, newQty)
        avgCosts.set(t.symbol, newAvgCost)

        result.push({
          symbol: t.symbol,
          direction: 'buy',
          price: t.price,
          quantity: t.quantity,
          date: t.date,
          pnl: 0,
          pnlPct: 0,
          reason: '策略信号买入',
        })
      } else {
        const qty = quantities.get(t.symbol) ?? 0
        const avgCost = avgCosts.get(t.symbol) ?? 0
        const sellQty = Math.min(t.quantity, qty)
        if (sellQty <= 0) continue

        const grossPnL = (t.price - avgCost) * sellQty - t.commission
        const pnlPct = avgCost > 0 ? ((t.price - avgCost) / avgCost) * 100 : 0

        result.push({
          symbol: t.symbol,
          direction: 'sell',
          price: t.price,
          quantity: sellQty,
          date: t.date,
          pnl: Math.round(grossPnL * 100) / 100,
          pnlPct: Math.round(pnlPct * 100) / 100,
          reason: '策略信号卖出',
        })

        const remaining = qty - sellQty
        if (remaining <= 0) {
          quantities.delete(t.symbol)
          avgCosts.delete(t.symbol)
        } else {
          quantities.set(t.symbol, remaining)
        }
      }
    }

    return result
  }

  private _emptyResult(config: BacktestEngineConfig): BacktestEngineResult {
    return {
      trades: [],
      positions: [],
      dailyValues: [],
      metrics: this._emptyMetrics(config),
    }
  }

  private _emptyMetrics(_config: BacktestEngineConfig): BacktestResult {
    return {
      totalReturn: 0,
      annualizedReturn: 0,
      maxDrawdown: 0,
      sharpeRatio: 0,
      winRate: 0,
      tradeCount: 0,
      profitTrades: 0,
      lossTrades: 0,
      avgProfit: 0,
      avgLoss: 0,
      pnlCurve: [1.0],
      trades: [],
    }
  }
}

import { getLogger } from '@/lib/logger'
import { toSafeNumber, toSafeOptionalNumber, toSafeString } from '@/lib/safeCoerce'
import type {
  RawMarketData,
  MarketData,
  MarketIndexData,
  SectorHeatmapData,
  FundFlowData,
  SentimentData,
  WatchlistData,
  PortfolioData,
  TradeReviewData,
  AnalysisScores,
  ModelComparison,
  StockPool,
  ChatHistory,
  StockPoolItem,
  ChatMessage,
  HotSectorData,
  ValuePitData,
} from '@/types/modules/widget.types'
import { FUND_FLOW_NAMES } from '@/constants/cockpit.constants'

const logger = getLogger()

/**
 * 市场数据适配器
 * @description 将不同来源（Mock/REST/WebSocket）的原始数据，统一映射为标准化的 MarketData 接口
 * @remarks 当数据源切换时，只需更换 Collector，无需修改 Adapter 和界面层
 */
export class MarketDataAdapter {
  /**
   * 适配单条原始数据
   * @param rawData 原始市场数据
   * @returns 标准化的市场数据片段
   */
  adapt(rawData: RawMarketData): Partial<MarketData> {
    logger.debug(`[MarketDataAdapter] 适配数据: type=${rawData.dataType}, source=${rawData.source}`)

    switch (rawData.dataType) {
      case 'indices':
        return { indices: this.adaptIndices(rawData.payload) }
      case 'sectors':
        return { sectors: this.adaptSectors(rawData.payload) }
      case 'fundFlow':
        return { fundFlows: this.adaptFundFlows(rawData.payload) }
      case 'sentiment':
        return { sentiment: this.adaptSentiment(rawData.payload) }
      case 'watchlist':
        return { watchlist: this.adaptWatchlist(rawData.payload) }
      case 'portfolio':
        return { portfolio: this.adaptPortfolio(rawData.payload) }
      case 'tradeReview':
        return { tradeReview: this.adaptTradeReview(rawData.payload) }
      // ============================================================
      // 新增金融业务数据适配
      // ============================================================
      case 'analysisScores':
        return { analysisScores: this.adaptAnalysisScores(rawData.payload) }
      case 'modelComparison':
        return { modelComparison: this.adaptModelComparison(rawData.payload) }
      case 'stockPool':
        return { stockPool: this.adaptStockPool(rawData.payload) }
      case 'chatHistory':
        return { chatHistory: this.adaptChatHistory(rawData.payload) }
      case 'hotSectors':
        return { hotSectors: this.adaptHotSectors(rawData.payload) }
      case 'valuePit':
        return { valuePit: this.adaptValuePit(rawData.payload) }
      default:
        logger.warn(`[MarketDataAdapter] 未知的数据类型: ${String(rawData.dataType)}`)
        return {}
    }
  }

  /**
   * 合并多个适配后的数据片段为完整的 MarketData
   * @param partials 数据片段数组
   */
  merge(...partials: Partial<MarketData>[]): MarketData {
    const merged: MarketData = {
      timestamp: Date.now(),
      indices: [],
      sectors: [],
      fundFlows: [],
      sentiment: this.getDefaultSentiment(),
      watchlist: [],
      portfolio: this.getDefaultPortfolio(),
      tradeReview: this.getDefaultTradeReview(),
      // 新增金融业务数据默认值
      analysisScores: this.getDefaultAnalysisScores(),
      modelComparison: this.getDefaultModelComparison(),
      stockPool: this.getDefaultStockPool(),
      chatHistory: this.getDefaultChatHistory(),
      hotSectors: [],
      valuePit: [],
    }

    for (const partial of partials) {
      if (partial.indices) merged.indices = partial.indices
      if (partial.sectors) merged.sectors = partial.sectors
      if (partial.fundFlows) merged.fundFlows = partial.fundFlows
      if (partial.sentiment) merged.sentiment = partial.sentiment
      if (partial.watchlist) merged.watchlist = partial.watchlist
      if (partial.portfolio) merged.portfolio = partial.portfolio
      if (partial.tradeReview) merged.tradeReview = partial.tradeReview
      // 新增金融业务数据合并
      if (partial.analysisScores) merged.analysisScores = partial.analysisScores
      if (partial.modelComparison) merged.modelComparison = partial.modelComparison
      if (partial.stockPool) merged.stockPool = partial.stockPool
      if (partial.chatHistory) merged.chatHistory = partial.chatHistory
      if (partial.hotSectors) merged.hotSectors = partial.hotSectors
      if (partial.valuePit) merged.valuePit = partial.valuePit
    }

    return merged
  }

  // ============================================================
  // 私有适配方法（原有）
  // ============================================================

  private adaptIndices(payload: unknown): MarketIndexData[] {
    if (!Array.isArray(payload)) {
      logger.warn('[MarketDataAdapter] indices payload 不是数组')
      return []
    }

    return payload.map((item) => ({
      code: toSafeString(item.code ?? item.symbol),
      name: toSafeString(item.name ?? item.shortName),
      price: toSafeNumber(item.price ?? item.value ?? item.current ?? 0),
      change: toSafeNumber(item.change ?? 0),
      changePercent: toSafeNumber(item.changePercent ?? item.change_percent ?? item.pctChange ?? 0),
      high: toSafeOptionalNumber(item.high),
      low: toSafeOptionalNumber(item.low),
      volume: item.volume != null ? toSafeString(item.volume) : undefined,
    }))
  }

  private adaptSectors(payload: unknown): SectorHeatmapData[] {
    if (!Array.isArray(payload)) {
      logger.warn('[MarketDataAdapter] sectors payload 不是数组')
      return []
    }

    return payload.map((item) => ({
      name: toSafeString(item.name ?? item.sectorName),
      code: toSafeString(item.code ?? item.sectorCode),
      changePercent: toSafeNumber(item.changePercent ?? item.change_percent ?? item.pctChange ?? 0),
      turnover: item.turnover != null ? toSafeString(item.turnover) : undefined,
    }))
  }

  private adaptFundFlows(payload: unknown): FundFlowData[] {
    if (!Array.isArray(payload)) {
      logger.warn('[MarketDataAdapter] fundFlows payload 不是数组')
      return []
    }

    return payload.map((item) => ({
      type: toSafeString(item.type),
      name: toSafeString(item.name ?? FUND_FLOW_NAMES[item.type]),
      value: toSafeNumber(item.value ?? item.netInflow ?? 0),
      unit: toSafeString(item.unit, '亿'),
    }))
  }

  private adaptSentiment(payload: unknown): SentimentData {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] sentiment payload 不是对象')
      return this.getDefaultSentiment()
    }

    const p = payload as Record<string, unknown>

    return {
      fearGreedIndex: toSafeNumber(p.fearGreedIndex ?? p.fear_greed_index ?? p.fgi ?? 50),
      fearGreedLabel: toSafeString(p.fearGreedLabel ?? p.fear_greed_label, '中性'),
      totalStocks: toSafeNumber(p.totalStocks ?? p.total_stocks ?? p.total ?? 0),
      up: toSafeNumber(p.up ?? p.rise ?? 0),
      down: toSafeNumber(p.down ?? p.fall ?? 0),
      flat: toSafeNumber(p.flat ?? p.unchanged ?? 0),
      limitUp: toSafeNumber(p.limitUp ?? p.limit_up ?? p.limitRise ?? 0),
      limitDown: toSafeNumber(p.limitDown ?? p.limit_down ?? p.limitFall ?? 0),
    }
  }

  private adaptWatchlist(payload: unknown): WatchlistData[] {
    if (!Array.isArray(payload)) {
      logger.warn('[MarketDataAdapter] watchlist payload 不是数组')
      return []
    }

    return payload.map((item) => ({
      name: toSafeString(item.name ?? item.stockName),
      code: toSafeString(item.code ?? item.symbol),
      price: toSafeNumber(item.price ?? item.currentPrice ?? item.current ?? 0),
      changePercent: toSafeNumber(item.changePercent ?? item.change_percent ?? item.pctChange ?? 0),
    }))
  }

  private adaptPortfolio(payload: unknown): PortfolioData {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] portfolio payload 不是对象')
      return this.getDefaultPortfolio()
    }

    const p = payload as Record<string, unknown>

    return {
      totalAssets: toSafeString(p.totalAssets ?? p.total_assets, '0'),
      availableFunds: toSafeString(p.availableFunds ?? p.available_funds, '0'),
      todayPnL: toSafeString(p.todayPnL ?? p.today_pnl ?? p.todayProfit, '0'),
      todayPnLPercent: toSafeNumber(p.todayPnLPercent ?? p.today_pnl_percent ?? p.todayProfitPct ?? 0),
      totalPnL: toSafeString(p.totalPnL ?? p.total_pnl ?? p.totalProfit, '0'),
      totalPnLPercent: toSafeNumber(p.totalPnLPercent ?? p.total_pnl_percent ?? p.totalProfitPct ?? 0),
      holdings: toSafeNumber(p.holdings ?? p.holdingCount ?? p.positionCount ?? 0),
      holdingsList: Array.isArray(p.holdingsList) ? p.holdingsList : [],
      rebalancePlan: Array.isArray(p.rebalancePlan) ? p.rebalancePlan : [],
    }
  }

  private adaptTradeReview(payload: unknown): TradeReviewData {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] tradeReview payload 不是对象')
      return this.getDefaultTradeReview()
    }

    const p = payload as Record<string, unknown>

    return {
      totalTrades: toSafeNumber(p.totalTrades ?? p.total_trades ?? p.total ?? 0),
      profitable: toSafeNumber(p.profitable ?? p.profitCount ?? 0),
      losing: toSafeNumber(p.losing ?? p.lossCount ?? 0),
      winRate: toSafeNumber(p.winRate ?? p.win_rate ?? p.winPct ?? 0),
      profitLossRatio: toSafeNumber(p.profitLossRatio ?? p.profit_loss_ratio ?? p.plRatio ?? 0),
      disciplineScore: toSafeNumber(p.disciplineScore ?? p.discipline_score ?? p.score ?? 0),
    }
  }

  // ============================================================
  // 新增金融业务适配方法
  // ============================================================

  /**
   * 适配投资画像 / KAI 评分数据
   * @remarks 支持字段别名，便于接入不同量化服务返回的 JSON 结构
   */
  private adaptAnalysisScores(payload: unknown): AnalysisScores {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] analysisScores payload 不是对象')
      return this.getDefaultAnalysisScores()
    }

    const p = payload as Record<string, unknown>

    return {
      profile: this.adaptProfile(p.profile ?? p.userProfile ?? {}),
      kai: this.adaptKaiScore(p.kai ?? p.score ?? {}),
    }
  }

  private adaptProfile(payload: unknown): AnalysisScores['profile'] {
    if (!payload || typeof payload !== 'object') {
      return { tags: [], metrics: [] }
    }

    const p = payload as Record<string, unknown>
    const metrics = Array.isArray(p.metrics) ? p.metrics : []

    return {
      tags: Array.isArray(p.tags) ? p.tags.map((t) => toSafeString(t)) : [],
      metrics: metrics.map((item) => ({
        name: toSafeString(item.name),
        score: toSafeNumber(item.score ?? 0),
        description: item.description != null ? toSafeString(item.description) : undefined,
        icon: item.icon != null ? toSafeString(item.icon) : undefined,
      })),
    }
  }

  private adaptKaiScore(payload: unknown): AnalysisScores['kai'] {
    if (!payload || typeof payload !== 'object') {
      return this.getDefaultAnalysisScores().kai
    }

    const p = payload as Record<string, unknown>
    const dimensions = Array.isArray(p.dimensions) ? p.dimensions : []
    const detailDistribution = Array.isArray(p.detailDistribution) ? p.detailDistribution : []

    return {
      totalScore: toSafeNumber(p.totalScore ?? p.total_score ?? p.score ?? 0),
      sentiment: toSafeNumber(p.sentiment ?? 0),
      trend: toSafeNumber(p.trend ?? 0),
      flow: toSafeNumber(p.flow ?? 0),
      dimensions: dimensions.map((item) => ({
        name: toSafeString(item.name),
        score: toSafeNumber(item.score ?? 0),
        weight: toSafeNumber(item.weight ?? 0),
        status: toSafeString(item.status),
        color: toSafeString(item.color, 'bg-blue-500'),
      })),
      detailDistribution: detailDistribution.map((item) => ({
        dimensionName: toSafeString(item.dimensionName ?? item.dimension_name),
        itemName: toSafeString(item.itemName ?? item.item_name),
        score: toSafeNumber(item.score ?? 0),
        weight: toSafeNumber(item.weight ?? 0),
        color: toSafeString(item.color, 'bg-blue-500'),
      })),
    }
  }

  /**
   * 适配 AI 大模型对比数据
   */
  private adaptModelComparison(payload: unknown): ModelComparison {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] modelComparison payload 不是对象')
      return this.getDefaultModelComparison()
    }

    const p = payload as Record<string, unknown>
    const dimensions = Array.isArray(p.dimensions) ? p.dimensions : []

    return {
      leftModel: this.adaptModelInfo(p.leftModel ?? p.left_model ?? p.modelA ?? {}),
      rightModel: this.adaptModelInfo(p.rightModel ?? p.right_model ?? p.modelB ?? {}),
      dimensions: dimensions.map((item) => ({
        name: toSafeString(item.name),
        leftScore: toSafeNumber(item.leftScore ?? item.left_score ?? item.scoreA ?? 0),
        rightScore: toSafeNumber(item.rightScore ?? item.right_score ?? item.scoreB ?? 0),
        weight: toSafeNumber(item.weight ?? 0),
      })),
      riskHint: toSafeString(p.riskHint ?? p.risk_hint ?? p.risk),
    }
  }

  private adaptModelInfo(payload: unknown): ModelComparison['leftModel'] {
    if (!payload || typeof payload !== 'object') {
      return { id: '', name: '', version: '', score: 0 }
    }

    const p = payload as Record<string, unknown>
    return {
      id: toSafeString(p.id),
      name: toSafeString(p.name),
      version: toSafeString(p.version),
      score: toSafeNumber(p.score ?? 0),
    }
  }

  /**
   * 适配股票池数据
   */
  private adaptStockPool(payload: unknown): StockPool {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] stockPool payload 不是对象')
      return this.getDefaultStockPool()
    }

    const p = payload as Record<string, unknown>
    const stocks = Array.isArray(p.stocks) ? p.stocks : []

    return {
      stocks: stocks.map((item) => this.adaptStockPoolItem(item)),
      total: toSafeNumber(p.total ?? stocks.length),
      page: toSafeNumber(p.page ?? 1),
      pageSize: toSafeNumber(p.pageSize ?? p.page_size ?? p.limit ?? 10),
    }
  }

  private adaptStockPoolItem(item: unknown): StockPoolItem {
    const it = item as Record<string, unknown>
    return {
      code: toSafeString(it.code ?? it.symbol),
      name: toSafeString(it.name ?? it.stockName),
      price: toSafeNumber(it.price ?? it.currentPrice ?? it.current ?? 0),
      changePercent: toSafeNumber(it.changePercent ?? it.change_percent ?? it.pctChange ?? 0),
      turnover: toSafeString(it.turnover),
      turnoverRate: toSafeString(it.turnoverRate ?? it.turnover_rate),
      statusColor: toSafeString(it.statusColor ?? it.status_color, 'bg-gray-400'),
      statusLabel: toSafeString(it.statusLabel ?? it.status_label),
    }
  }

  /**
   * 适配聊天历史数据
   */
  private adaptChatHistory(payload: unknown): ChatHistory {
    if (!payload || typeof payload !== 'object') {
      logger.warn('[MarketDataAdapter] chatHistory payload 不是对象')
      return this.getDefaultChatHistory()
    }

    const p = payload as Record<string, unknown>
    const messages = Array.isArray(p.messages) ? p.messages : []

    return {
      target: toSafeString(p.target),
      targetType: (p.targetType ?? p.target_type ?? 'stock') as ChatHistory['targetType'],
      messages: messages.map((item) => this.adaptChatMessage(item)),
    }
  }

  private adaptChatMessage(item: unknown): ChatMessage {
    const it = item as Record<string, unknown>
    return {
      id: toSafeString(it.id),
      role: (it.role ?? 'assistant') as ChatMessage['role'],
      content: toSafeString(it.content),
      timestamp: toSafeNumber(it.timestamp ?? it.ts ?? Date.now()),
    }
  }

  // ============================================================
  // 默认值方法
  // ============================================================

  private getDefaultSentiment(): SentimentData {
    return {
      fearGreedIndex: 50,
      fearGreedLabel: '中性',
      totalStocks: 0,
      up: 0,
      down: 0,
      flat: 0,
      limitUp: 0,
      limitDown: 0,
    }
  }

  private getDefaultPortfolio(): PortfolioData {
    return {
      totalAssets: '0',
      availableFunds: '0',
      todayPnL: '0',
      todayPnLPercent: 0,
      totalPnL: '0',
      totalPnLPercent: 0,
      holdings: 0,
      holdingsList: [],
      rebalancePlan: [],
    }
  }

  private getDefaultTradeReview(): TradeReviewData {
    return {
      totalTrades: 0,
      profitable: 0,
      losing: 0,
      winRate: 0,
      profitLossRatio: 0,
      disciplineScore: 0,
    }
  }

  private getDefaultAnalysisScores(): AnalysisScores {
    return {
      profile: { tags: [], metrics: [] },
      kai: {
        totalScore: 0,
        sentiment: 0,
        trend: 0,
        flow: 0,
        dimensions: [],
        detailDistribution: [],
      },
    }
  }

  private getDefaultModelComparison(): ModelComparison {
    return {
      leftModel: { id: '', name: '', version: '', score: 0 },
      rightModel: { id: '', name: '', version: '', score: 0 },
      dimensions: [],
      riskHint: '',
    }
  }

  private getDefaultStockPool(): StockPool {
    return {
      stocks: [],
      total: 0,
      page: 1,
      pageSize: 10,
    }
  }

  private getDefaultChatHistory(): ChatHistory {
    return {
      target: '',
      targetType: 'stock',
      messages: [],
    }
  }

  private adaptHotSectors(payload: unknown): HotSectorData[] {
    if (!Array.isArray(payload)) {
      logger.warn('[MarketDataAdapter] hotSectors payload 不是数组')
      return []
    }

    return payload.map((item) => {
      const dims = {
        momentum: toSafeNumber(item.dimensions?.momentum ?? 0),
        sentiment: toSafeNumber(item.dimensions?.sentiment ?? 0),
        technical: toSafeNumber(item.dimensions?.technical ?? 0),
        valuation: toSafeNumber(item.dimensions?.valuation ?? 0),
      }
      return {
        symbol: toSafeString(item.symbol),
        name: toSafeString(item.name),
        score: toSafeNumber(item.score ?? 0),
        action: (item.action ?? 'ignore') as HotSectorData['action'],
        dimensions: {
          ...dims,
          composite: (dims.momentum + dims.sentiment + dims.technical + dims.valuation) / 4,
        },
      }
    })
  }

  private adaptValuePit(payload: unknown): ValuePitData[] {
    if (!Array.isArray(payload)) {
      logger.warn('[MarketDataAdapter] valuePit payload 不是数组')
      return []
    }

    return payload.map((item) => {
      const dims = {
        catalyst: toSafeNumber(item.dimensions?.catalyst ?? 0),
        valuation: toSafeNumber(item.dimensions?.valuation ?? 0),
        chip: toSafeNumber(item.dimensions?.chip ?? 0),
        rotation: toSafeNumber(item.dimensions?.rotation ?? 0),
        liquidity: toSafeNumber(item.dimensions?.liquidity ?? 0),
      }
      return {
        symbol: toSafeString(item.symbol),
        name: toSafeString(item.name),
        score: toSafeNumber(item.score ?? 0),
        action: (item.action ?? 'ignore') as ValuePitData['action'],
        rotationSignal: Boolean(item.rotationSignal ?? false),
        dimensions: {
          ...dims,
          composite: (dims.catalyst + dims.valuation + dims.chip + dims.rotation + dims.liquidity) / 5,
        },
      }
    })
  }
}

export const marketDataAdapter = new MarketDataAdapter()

import { getLogger } from '@/lib/logger'
import type {
  CollectionTask,
  CollectionTaskStatus,
  DataSourceConfig,
  CollectionResultCallback,
} from '@/types/modules/widget.types'
import { DATA_SOURCE_TYPE } from '@/constants/cockpit.constants'
import { BaseCollector } from './collectors/BaseCollector'
import { MockCollector } from './collectors/MockCollector'
import { RestCollector } from './collectors/RestCollector'
import { WebSocketCollector } from './collectors/WebSocketCollector'

const logger = getLogger()

/**
 * 采集任务调度器
 * @description 负责单个 Widget 数据采集任务的注册、启动、停止、错误状态管理
 * @remarks 支持自动定时轮询，页面销毁时自动清理定时器防止内存泄漏
 */
export class TaskScheduler {
  private tasks = new Map<string, CollectionTask>()
  private timers = new Map<string, ReturnType<typeof setInterval>>()
  private collectors = new Map<string, BaseCollector>()
  private listeners = new Set<CollectionResultCallback>()
  private taskCounter = 0

  /**
   * 注册采集任务
   * @param widgetId Widget ID
   * @param instanceId 实例 ID
   * @param dataSource 数据源配置
   * @returns 任务 ID
   */
  registerTask(widgetId: string, instanceId: string, dataSource: DataSourceConfig): string {
    this.taskCounter++
    const taskId = `task_${widgetId}_${instanceId}_${this.taskCounter}`

    const task: CollectionTask = {
      taskId,
      widgetId,
      instanceId,
      dataSource,
      status: 'pending',
      runCount: 0,
      successCount: 0,
      failCount: 0,
    }

    this.tasks.set(taskId, task)
    logger.info(`[TaskScheduler] 任务注册成功: ${taskId}, widgetId=${widgetId}, type=${dataSource.type}, mode=${dataSource.mode}`)

    return taskId
  }

  /**
   * 启动采集任务
   * @param taskId 任务 ID
   */
  async startTask(taskId: string): Promise<void> {
    const task = this.tasks.get(taskId)
    if (!task) {
      logger.error(`[TaskScheduler] 启动失败: 任务 ${taskId} 未找到`)
      return
    }

    if (task.status === 'running') {
      logger.warn(`[TaskScheduler] 任务 ${taskId} 已在运行中`)
      return
    }

    const { dataSource } = task

    // 根据数据源类型创建对应的采集器
    const collector = this.getOrCreateCollector(dataSource.type)
    this.collectors.set(taskId, collector)

    task.status = 'running'
    logger.info(`[TaskScheduler] 任务启动: ${taskId}, mode=${dataSource.mode}`)

    if (dataSource.mode === 'polling') {
      // 立即执行一次
      await this.executeTask(taskId)

      // 设置定时轮询
      const timer = setInterval(() => {
        this.executeTask(taskId).catch((err) => {
          logger.error(`[TaskScheduler] 轮询执行失败: ${taskId}`, { error: err })
        })
      }, dataSource.interval)

      this.timers.set(taskId, timer)
    } else if (dataSource.mode === 'once') {
      // 只执行一次
      await this.executeTask(taskId)
      task.status = 'completed'
    } else if (dataSource.mode === 'streaming') {
      // 流式采集（WebSocket）
      logger.info(`[TaskScheduler] 流式采集模式: ${taskId}`)
      await this.executeTask(taskId)
    }
  }

  /**
   * 停止采集任务
   * @param taskId 任务 ID
   */
  stopTask(taskId: string): void {
    const task = this.tasks.get(taskId)
    if (!task) return

    // 清除定时器
    const timer = this.timers.get(taskId)
    if (timer) {
      clearInterval(timer)
      this.timers.delete(taskId)
      logger.info(`[TaskScheduler] 定时器已清除: ${taskId}`)
    }

    // 取消采集器
    const collector = this.collectors.get(taskId)
    if (collector) {
      collector.cancel()
      this.collectors.delete(taskId)
    }

    task.status = 'paused'
    logger.info(`[TaskScheduler] 任务已停止: ${taskId}`)
  }

  /**
   * 注销采集任务
   * @param taskId 任务 ID
   */
  unregisterTask(taskId: string): void {
    this.stopTask(taskId)
    this.tasks.delete(taskId)
    logger.info(`[TaskScheduler] 任务已注销: ${taskId}`)
  }

  /**
   * 订阅采集结果
   * @param callback 结果回调函数
   * @returns 取消订阅函数
   */
  subscribe(callback: CollectionResultCallback): () => void {
    this.listeners.add(callback)
    logger.debug(`[TaskScheduler] 结果监听器已添加, 总数=${this.listeners.size}`)

    return () => {
      this.listeners.delete(callback)
      logger.debug(`[TaskScheduler] 结果监听器已移除, 总数=${this.listeners.size}`)
    }
  }

  /**
   * 获取任务状态
   * @param taskId 任务 ID
   */
  getTaskStatus(taskId: string): CollectionTaskStatus | undefined {
    return this.tasks.get(taskId)?.status
  }

  /**
   * 获取所有任务统计
   */
  getAllTasks(): CollectionTask[] {
    return Array.from(this.tasks.values())
  }

  /**
   * 清理所有任务（页面销毁时调用）
   * @remarks 防止内存泄漏的关键方法
   */
  dispose(): void {
    logger.info('[TaskScheduler] 正在清理所有任务...')

    // 停止所有定时器
    this.timers.forEach((timer, taskId) => {
      clearInterval(timer)
      logger.debug(`[TaskScheduler] 定时器已清除: ${taskId}`)
    })
    this.timers.clear()

    // 取消所有采集器
    this.collectors.forEach((collector, taskId) => {
      collector.cancel()
      logger.debug(`[TaskScheduler] 采集器已取消: ${taskId}`)
    })
    this.collectors.clear()

    // 清空任务
    this.tasks.clear()

    // 清空监听器
    this.listeners.clear()

    logger.info('[TaskScheduler] 所有任务已清理完毕')
  }

  /**
   * 执行单次采集任务
   * @param taskId 任务 ID
   */
  private async executeTask(taskId: string): Promise<void> {
    const task = this.tasks.get(taskId)
    if (!task || task.status !== 'running') return

    const collector = this.collectors.get(taskId)
    if (!collector) return

    task.lastRun = Date.now()
    task.runCount++

    try {
      const rawData = await collector.collectWithRetry(task.dataSource)
      task.successCount++
      task.nextRun = Date.now() + task.dataSource.interval

      // 通知所有监听器
      this.listeners.forEach((listener) => {
        try {
          listener(taskId, rawData)
        } catch (err) {
          logger.error('[TaskScheduler] 监听器执行失败', { error: err })
        }
      })
    } catch (error) {
      task.failCount++
      task.status = 'error'
      task.error = error instanceof Error ? error.message : String(error)

      logger.error(`[TaskScheduler] 任务执行失败: ${taskId}`, { error })

      // 通知监听器错误
      this.listeners.forEach((listener) => {
        try {
          listener(taskId, null, error instanceof Error ? error : new Error(String(error)))
        } catch (err) {
          logger.error('[TaskScheduler] 错误监听器执行失败', { error: err })
        }
      })
    }
  }

  /**
   * 获取或创建采集器
   * @param type 数据源类型
   */
  private getOrCreateCollector(type: string): BaseCollector {
    switch (type) {
      case DATA_SOURCE_TYPE.MOCK:
        return new MockCollector()
      case DATA_SOURCE_TYPE.REST:
        return new RestCollector()
      case DATA_SOURCE_TYPE.WEBSOCKET:
        return new WebSocketCollector()
      default:
        logger.warn(`[TaskScheduler] 未知的数据源类型: ${type}, 使用 MockCollector`)
        return new MockCollector()
    }
  }
}

