import { getLogger } from '@/lib/logger'
import { BaseCollector } from './BaseCollector'
import type { RawMarketData, DataSourceConfig } from '@/types/modules/widget.types'
import { MOCK_COLLECTOR_CONFIG } from '@/constants/cockpit.constants'
import {
  mockMarketIndices,
  mockSectorData,
  mockFundFlows,
  mockMarketSentiment,
  mockWatchlist,
  mockPortfolioStats,
  mockTradeReview,
} from '@/cockpit/data/mockDataProvider'
import { MockStockAnalysisProvider } from '@/services/stock-analysis/mockStockAnalysisProvider'

const logger = getLogger()

/**
 * Mock 数据采集器
 * @description 生成随机模拟数据，支持模拟延迟和随机波动
 * @remarks 当环境变量 VITE_DATA_SOURCE_TYPE=mock 时启用
 */
export class MockCollector extends BaseCollector {
  constructor() {
    super()
  }

  /**
   * 执行 Mock 数据采集
   * @param dataSource 数据源配置（通过 endpoint 区分数据类型）
   */
  async collect(dataSource: DataSourceConfig): Promise<RawMarketData> {
    const { endpoint = '' } = dataSource

    // 模拟网络延迟
    const delay = this.getRandomDelay()
    logger.debug(`[MockCollector] 模拟延迟 ${delay}ms`)
    await this.delay(delay)

    // 根据 endpoint 路由到对应的数据生成器
    if (endpoint.includes('indices')) {
      return this.wrapData('indices', this.generateIndicesData(), 'mock')
    }
    if (endpoint.includes('sectors')) {
      return this.wrapData('sectors', this.generateSectorsData(), 'mock')
    }
    if (endpoint.includes('fund-flow')) {
      return this.wrapData('fundFlow', this.generateFundFlowData(), 'mock')
    }
    if (endpoint.includes('sentiment')) {
      return this.wrapData('sentiment', this.generateSentimentData(), 'mock')
    }
    if (endpoint.includes('watchlist')) {
      return this.wrapData('watchlist', this.generateWatchlistData(), 'mock')
    }
    if (endpoint.includes('portfolio')) {
      return this.wrapData('portfolio', this.generatePortfolioData(), 'mock')
    }
    if (endpoint.includes('trade-review')) {
      return this.wrapData('tradeReview', this.generateTradeReviewData(), 'mock')
    }
    // ============================================================
    // 新增股票分析业务 Mock 路由
    // @remarks 生产环境切换为 REST/WebSocket Collector 后，以下路由由真实 API 接管
    // ============================================================
    if (endpoint.includes('stock-analysis/profile') || endpoint.includes('stock-analysis/kai')) {
      const scores = await MockStockAnalysisProvider.getAnalysisScores()
      return this.wrapData('analysisScores', scores, 'mock')
    }
    if (endpoint.includes('stock-analysis/compare')) {
      const comparison = await MockStockAnalysisProvider.getModelComparison()
      return this.wrapData('modelComparison', comparison, 'mock')
    }
    if (endpoint.includes('stock-analysis/pool')) {
      const pool = await MockStockAnalysisProvider.getStockPool()
      return this.wrapData('stockPool', pool, 'mock')
    }
    if (endpoint.includes('stock-analysis/chat')) {
      const chat = await MockStockAnalysisProvider.getChatHistory()
      return this.wrapData('chatHistory', chat, 'mock')
    }
    if (endpoint.includes('strategy/hot-sectors')) {
      const hotSectors = await MockStockAnalysisProvider.getHotSectors()
      return this.wrapData('hotSectors', hotSectors, 'mock')
    }
    if (endpoint.includes('strategy/value-pit')) {
      const valuePit = await MockStockAnalysisProvider.getValuePit()
      return this.wrapData('valuePit', valuePit, 'mock')
    }

    throw new Error(`[MockCollector] 未知的 endpoint: ${endpoint}`)
  }

  /**
   * 生成随机延迟
   */
  private getRandomDelay(): number {
    const { MIN_DELAY, MAX_DELAY } = MOCK_COLLECTOR_CONFIG
    return Math.floor(Math.random() * (MAX_DELAY - MIN_DELAY + 1)) + MIN_DELAY
  }

  /**
   * 生成波动后的指数数据
   */
  private generateIndicesData() {
    const { PRICE_FLUCTUATION } = MOCK_COLLECTOR_CONFIG
    return mockMarketIndices.map((item) => ({
      ...item,
      value: this.fluctuate(item.value, PRICE_FLUCTUATION),
      change: this.fluctuate(item.change, PRICE_FLUCTUATION),
      changePercent: this.fluctuate(item.changePercent, PRICE_FLUCTUATION),
    }))
  }

  /**
   * 生成波动后的板块数据
   */
  private generateSectorsData() {
    const { PRICE_FLUCTUATION } = MOCK_COLLECTOR_CONFIG
    return mockSectorData.map((item) => ({
      ...item,
      changePercent: this.fluctuate(item.changePercent, PRICE_FLUCTUATION),
    }))
  }

  /**
   * 生成波动后的资金流向数据
   */
  private generateFundFlowData() {
    const { PRICE_FLUCTUATION } = MOCK_COLLECTOR_CONFIG
    return mockFundFlows.map((item) => ({
      ...item,
      value: this.fluctuate(item.value, PRICE_FLUCTUATION),
    }))
  }

  /**
   * 生成波动后的市场情绪数据
   */
  private generateSentimentData() {
    const { PRICE_FLUCTUATION } = MOCK_COLLECTOR_CONFIG
    return {
      ...mockMarketSentiment,
      fearGreedIndex: Math.max(0, Math.min(100, Math.floor(this.fluctuate(mockMarketSentiment.fearGreedIndex, 0.05)))),
      up: Math.max(0, Math.floor(this.fluctuate(mockMarketSentiment.up, PRICE_FLUCTUATION))),
      down: Math.max(0, Math.floor(this.fluctuate(mockMarketSentiment.down, PRICE_FLUCTUATION))),
    }
  }

  /**
   * 生成波动后的自选股数据
   */
  private generateWatchlistData() {
    const { PRICE_FLUCTUATION } = MOCK_COLLECTOR_CONFIG
    return mockWatchlist.map((item) => ({
      ...item,
      price: this.fluctuate(item.price, PRICE_FLUCTUATION),
      changePercent: this.fluctuate(item.changePercent, PRICE_FLUCTUATION),
    }))
  }

  /**
   * 生成持仓概览数据（变化较小）
   */
  private generatePortfolioData() {
    return mockPortfolioStats
  }

  /**
   * 生成交易复盘数据（静态）
   */
  private generateTradeReviewData() {
    return mockTradeReview
  }

  /**
   * 数值波动工具
   * @param value 原始值
   * @param range 波动范围（0-1）
   */
  private fluctuate(value: number, range: number): number {
    const factor = 1 + (Math.random() - 0.5) * 2 * range
    return Number((value * factor).toFixed(2))
  }
}

import { getLogger } from '@/lib/logger'
import { BaseCollector } from './BaseCollector'
import type { RawMarketData, DataSourceConfig, CollectorConfig } from '@/types/modules/widget.types'
import { REST_COLLECTOR_CONFIG } from '@/constants/cockpit.constants'

const logger = getLogger()

/**
 * REST API 数据采集器
 * @description 通过 HTTP 轮询获取数据，支持 GET/POST 请求
 * @remarks 当环境变量 VITE_DATA_SOURCE_TYPE=rest 时启用
 */
export class RestCollector extends BaseCollector {
  private baseUrl: string

  constructor(config?: Partial<CollectorConfig>) {
    super(config)
    this.baseUrl = REST_COLLECTOR_CONFIG.BASE_URL
  }

  /**
   * 执行 REST API 数据采集
   * @param dataSource 数据源配置
   */
  async collect(dataSource: DataSourceConfig): Promise<RawMarketData> {
    const { endpoint = '' } = dataSource
    const url = `${this.baseUrl}${endpoint}`

    logger.debug(`[RestCollector] 请求 API: ${url}`)

    const signal = this.abortController?.signal

    const response = await fetch(url, {
      method: 'GET',
      headers: {
        ...REST_COLLECTOR_CONFIG.DEFAULT_HEADERS,
        ...this.config.headers,
      },
      signal,
    })

    if (!response.ok) {
      throw new Error(`[RestCollector] HTTP ${response.status}: ${response.statusText}`)
    }

    const rawData = await response.json()
    logger.debug(`[RestCollector] 数据获取成功: ${url}`)

    // 根据 endpoint 推断数据类型
    const dataType = this.inferDataType(endpoint)

    return this.wrapData(dataType, rawData, 'rest')
  }

  /**
   * 发送 POST 请求（用于需要请求体的场景）
   * @param dataSource 数据源配置
   * @param body 请求体
   */
  async collectPost(dataSource: DataSourceConfig, body?: Record<string, unknown>): Promise<RawMarketData> {
    const { endpoint = '' } = dataSource
    const url = `${this.baseUrl}${endpoint}`

    logger.debug(`[RestCollector] POST 请求: ${url}`)

    const signal = this.abortController?.signal

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        ...REST_COLLECTOR_CONFIG.DEFAULT_HEADERS,
        ...this.config.headers,
      },
      body: body ? JSON.stringify(body) : undefined,
      signal,
    })

    if (!response.ok) {
      throw new Error(`[RestCollector] HTTP ${response.status}: ${response.statusText}`)
    }

    const rawData = await response.json()
    const dataType = this.inferDataType(endpoint)

    return this.wrapData(dataType, rawData, 'rest')
  }

  /**
   * 根据 endpoint 推断数据类型
   * @param endpoint API 端点
   */
  private inferDataType(endpoint: string): RawMarketData['dataType'] {
    if (endpoint.includes('indices')) return 'indices'
    if (endpoint.includes('sectors')) return 'sectors'
    if (endpoint.includes('fund-flow')) return 'fundFlow'
    if (endpoint.includes('sentiment')) return 'sentiment'
    if (endpoint.includes('watchlist')) return 'watchlist'
    if (endpoint.includes('portfolio')) return 'portfolio'
    if (endpoint.includes('trade-review')) return 'tradeReview'
    return 'indices'
  }
}

import { getLogger } from '@/lib/logger'
import { BaseCollector } from './BaseCollector'
import type { RawMarketData, DataSourceConfig, CollectorConfig } from '@/types/modules/widget.types'
import { WEBSOCKET_COLLECTOR_CONFIG } from '@/constants/cockpit.constants'

const logger = getLogger()

/**
 * WebSocket 数据采集器
 * @description 用于长连接实时推流，支持自动重连
 * @remarks 当环境变量 VITE_DATA_SOURCE_TYPE=websocket 时启用
 * @todo 内部逻辑可根据实际 WebSocket 服务端协议补充实现
 */
export class WebSocketCollector extends BaseCollector {
  private ws: WebSocket | null = null
  private reconnectCount = 0
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private messageQueue: string[] = []
  private onMessageCallback: ((data: RawMarketData) => void) | null = null

  constructor(config?: Partial<CollectorConfig>) {
    super(config)
  }

  /**
   * 执行 WebSocket 连接（预留扩展接口）
   * @param dataSource 数据源配置
   * @remarks 当前为预留接口，内部逻辑待后续补充
   */
  async collect(dataSource: DataSourceConfig): Promise<RawMarketData> {
    const { endpoint = '' } = dataSource
    logger.info(`[WebSocketCollector] 初始化连接: ${WEBSOCKET_COLLECTOR_CONFIG.WS_URL}${endpoint}`)

    // 预留：建立 WebSocket 连接
    // this.connect(endpoint)

    // 返回占位数据（实际应通过消息回调推送）
    return this.wrapData('indices', { message: 'WebSocket 连接预留接口' }, 'websocket')
  }

  /**
   * 建立 WebSocket 连接
   * @param endpoint 端点路径
   */
  connect(endpoint: string): void {
    const url = `${WEBSOCKET_COLLECTOR_CONFIG.WS_URL}${endpoint}`

    try {
      this.ws = new WebSocket(url)

      this.ws.onopen = () => {
        logger.info(`[WebSocketCollector] 连接成功: ${url}`)
        this.reconnectCount = 0
        this.flushMessageQueue()
      }

      this.ws.onmessage = (event) => {
        try {
          const rawData = JSON.parse(event.data as string)
          const dataType = this.inferDataType(endpoint)
          const wrappedData = this.wrapData(dataType, rawData, 'websocket')
          this.onMessageCallback?.(wrappedData)
        } catch (error) {
          logger.error('[WebSocketCollector] 消息解析失败', { error })
        }
      }

      this.ws.onclose = () => {
        logger.warn('[WebSocketCollector] 连接关闭')
        this.handleReconnect(endpoint)
      }

      this.ws.onerror = (error) => {
        logger.error('[WebSocketCollector] 连接错误', { error })
      }
    } catch (error) {
      logger.error(`[WebSocketCollector] 连接失败: ${url}`, { error })
      this.handleReconnect(endpoint)
    }
  }

  /**
   * 断开 WebSocket 连接
   */
  disconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    if (this.ws) {
      this.ws.close()
      this.ws = null
    }
    logger.info('[WebSocketCollector] 连接已断开')
  }

  /**
   * 发送消息
   * @param message 消息内容
   */
  send(message: string): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(message)
    } else {
      this.messageQueue.push(message)
    }
  }

  /**
   * 设置消息接收回调
   * @param callback 回调函数
   */
  onMessage(callback: (data: RawMarketData) => void): void {
    this.onMessageCallback = callback
  }

  /**
   * 处理重连逻辑
   * @param endpoint 端点路径
   */
  private handleReconnect(endpoint: string): void {
    const { RECONNECT_INTERVAL, MAX_RECONNECT_COUNT } = WEBSOCKET_COLLECTOR_CONFIG

    if (this.reconnectCount < MAX_RECONNECT_COUNT) {
      this.reconnectCount++
      logger.info(`[WebSocketCollector] ${RECONNECT_INTERVAL}ms 后重连 (${this.reconnectCount}/${MAX_RECONNECT_COUNT})`)

      this.reconnectTimer = setTimeout(() => {
        this.connect(endpoint)
      }, RECONNECT_INTERVAL)
    } else {
      logger.error('[WebSocketCollector] 已达到最大重连次数')
    }
  }

  /**
   * 刷新消息队列
   */
  private flushMessageQueue(): void {
    while (this.messageQueue.length > 0 && this.ws?.readyState === WebSocket.OPEN) {
      const message = this.messageQueue.shift()
      if (message) this.ws.send(message)
    }
  }

  /**
   * 根据 endpoint 推断数据类型
   * @param endpoint 端点路径
   */
  private inferDataType(endpoint: string): RawMarketData['dataType'] {
    if (endpoint.includes('indices')) return 'indices'
    if (endpoint.includes('sectors')) return 'sectors'
    if (endpoint.includes('fund-flow')) return 'fundFlow'
    if (endpoint.includes('sentiment')) return 'sentiment'
    if (endpoint.includes('watchlist')) return 'watchlist'
    if (endpoint.includes('portfolio')) return 'portfolio'
    if (endpoint.includes('trade-review')) return 'tradeReview'
    return 'indices'
  }

  /**
   * 取消采集（断开连接）
   */
  override cancel(): void {
    this.disconnect()
    super.cancel()
  }
}

/**
