        { id: 1, symbol: '600000', reportType: MISSING_REPORT_TYPE.RESEARCH, severity: MISSING_REPORT_SEVERITY.CRITICAL, reason: '缺少研报', detectedAt: 4_000, retryCount: 0, createdAt: 4_000 },
      ])
      const result = await listBySeverity(MISSING_REPORT_SEVERITY.CRITICAL)
      expect(result).toHaveLength(1)
      expect(result[0]!.severity).toBe(MISSING_REPORT_SEVERITY.CRITICAL)
    })
  })

  describe('listUnresolved', () => {
    it('returns only unresolved reports under retry limit', async () => {
      vi.mocked(missingReportStore.list).mockResolvedValue([
        { id: 1, symbol: '600000', reportType: MISSING_REPORT_TYPE.RESEARCH, severity: 'medium', reason: 'r1', detectedAt: 1, resolvedAt: undefined, retryCount: 0 },
        { id: 2, symbol: '600001', reportType: MISSING_REPORT_TYPE.EARNINGS, severity: 'high', reason: 'r2', detectedAt: 2, resolvedAt: 3, retryCount: 0 },
      ] as any)
      const result = await listUnresolved()
      expect(result).toHaveLength(1)
      expect(result[0]!.id).toBe(1)
    })
  })

  describe('incrementRetry', () => {
    it('increments retry count for a report', async () => {
      vi.mocked(missingReportStore.incrementRetry).mockResolvedValue({ success: true, data: {} as any })
      const result = await incrementRetry(1)
      expect(result).toBeDefined()
      expect(missingReportStore.incrementRetry).toHaveBeenCalledWith(1)
    })

    it('returns undefined when increment fails', async () => {
      vi.mocked(missingReportStore.incrementRetry).mockResolvedValue({ success: false, error: 'db_error' })
      const result = await incrementRetry(1)
      expect(result).toBeUndefined()
    })
  })

  describe('clear', () => {
    it('returns count of resolved reports to clear', async () => {
      vi.mocked(missingReportStore.list).mockResolvedValue([
        { id: 1, symbol: '600000', reportType: MISSING_REPORT_TYPE.RESEARCH, severity: 'medium', reason: 'r1', detectedAt: 1, resolvedAt: 5, retryCount: 0 },
        { id: 2, symbol: '600001', reportType: MISSING_REPORT_TYPE.EARNINGS, severity: 'high', reason: 'r2', detectedAt: 2, resolvedAt: undefined, retryCount: 0 },
      ] as any)
      const count = await clear()
      expect(count).toBe(1)
    })

    it('filters by symbol when provided', async () => {
      vi.mocked(missingReportStore.list).mockResolvedValue([
        { id: 1, symbol: '600000', reportType: MISSING_REPORT_TYPE.RESEARCH, severity: 'medium', reason: 'r1', detectedAt: 1, resolvedAt: 5, retryCount: 0 },
        { id: 2, symbol: '600001', reportType: MISSING_REPORT_TYPE.EARNINGS, severity: 'high', reason: 'r2', detectedAt: 2, resolvedAt: 6, retryCount: 0 },
      ] as any)
      const count = await clear('600000')
      expect(count).toBe(1)
    })
  })

  describe('detector enabled state', () => {
    it('setDetectorEnabled updates state', () => {
      setDetectorEnabled(false)
      expect(isDetectorEnabled()).toBe(false)
      setDetectorEnabled(true)
      expect(isDetectorEnabled()).toBe(true)
    })
  })
})

/**
 * @module missingReportDetector
 * @description 缺失报告检测器：在采集/计算过程中登记数据缺失报告，支持去重与重试。
 *
 * 职责：
 *   - detect(symbol, reportType, reason, options): 检测并登记缺失报告（自动去重）
 *   - listBySymbol(symbol): 查询某股票的全部缺失报告
 *   - listBySeverity(severity): 按严重度查询
 *   - clear(symbol?): 清理已解决的缺失报告
 *   - incrementRetry(id): 增加重试次数
 */

import { getLogger } from '@/lib/logger'
import { missingReportStore } from '@/data/dataLayer'
import type { MissingReport } from '@/data/types'
import {
  MISSING_REPORT_TYPE,
  MISSING_REPORT_SEVERITY,
  DEFAULT_MAX_RETRY_COUNT,
  DEFAULT_MISSING_REPORT_ENABLED,
  type MissingReportType,
  type MissingReportSeverity,
} from '@/constants/execution.constants'
import { checkMissingReportFreshness } from '@/core/freshnessGuard'

const logger = getLogger()

/** 全局开关：是否启用缺失报告检测（初始关闭） */
let detectorEnabled = DEFAULT_MISSING_REPORT_ENABLED

/** 设置检测器启用状态 */
export function setDetectorEnabled(enabled: boolean): void {
  detectorEnabled = enabled
  logger.info(`[missingReportDetector] detectorEnabled = ${enabled}`)
}

/** 查询检测器启用状态 */
export function isDetectorEnabled(): boolean {
  return detectorEnabled
}

export interface DetectOptions {
  now?: number
  severity?: MissingReportSeverity
  enabled?: boolean
}

/**
 * 检测并登记缺失报告。
 * - 当全局开关关闭且 options.enabled 未指定时，跳过登记。
 * - 当同一 (symbol, reportType) 已存在未解决报告时，跳过登记（去重）。
 */
export async function detect(
  symbol: string,
  reportType: MissingReportType,
  reason: string,
  options: DetectOptions = {},
): Promise<MissingReport | undefined> {
  const now = options.now ?? Date.now()
  const severity = options.severity ?? MISSING_REPORT_SEVERITY.MEDIUM
  const enabled = options.enabled ?? detectorEnabled

  if (!enabled) {
    logger.debug(`[missingReportDetector] detect skipped (disabled): symbol="${symbol}" type="${reportType}"`)
    return undefined
  }

  try {
    // Freshness 校验：检测时间必须晚于当前时间减去一个合理窗口（防止回填）
    checkMissingReportFreshness(now, now, symbol)

    // 去重：检查是否已存在未解决的同类报告
    const existing = await missingReportStore.listBySymbol(symbol)
    const duplicate = existing.find((r) => r.reportType === reportType && r.resolvedAt === undefined)
    if (duplicate) {
      logger.info(`[missingReportDetector] detect skipped (duplicate): symbol="${symbol}" type="${reportType}"`, {
        existingId: duplicate.id,
      })
      return undefined
    }

    const report: Omit<MissingReport, 'id'> = {
      symbol,
      reportType,
      severity,
      reason,
      detectedAt: now,
      retryCount: 0,
      createdAt: now,
    }

    const result = await missingReportStore.report(report)
    if (!result.success) {
      logger.error(`[missingReportDetector] detect save failed: ${result.error}`, { symbol, reportType })
      return undefined
    }

    logger.info(`[missingReportDetector] detect success: symbol="${symbol}" type="${reportType}" severity="${severity}"`)
    return result.data
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[missingReportDetector] detect error: ${message}`, { symbol, reportType })
    return undefined
  }
}

/**
 * 查询某股票的全部缺失报告。
 */
export async function listBySymbol(symbol: string): Promise<MissingReport[]> {
  try {
    return await missingReportStore.listBySymbol(symbol)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[missingReportDetector] listBySymbol error: ${message}`, { symbol })
    return []
  }
}

/**
 * 按严重度查询缺失报告。
 */
export async function listBySeverity(severity: MissingReportSeverity): Promise<MissingReport[]> {
  try {
    return await missingReportStore.listBySeverity(severity)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[missingReportDetector] listBySeverity error: ${message}`, { severity })
    return []
  }
}

/**
 * 查询所有未解决的缺失报告。
 */
export async function listUnresolved(): Promise<MissingReport[]> {
  try {
    const all = await missingReportStore.list()
    return all.filter((r) => r.resolvedAt === undefined && r.retryCount < DEFAULT_MAX_RETRY_COUNT)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[missingReportDetector] listUnresolved error: ${message}`)
    return []
  }
}

/**
 * 增加重试次数。当重试次数达到上限时自动标记为已解决。
 */
export async function incrementRetry(id: number, _options: { now?: number } = {}): Promise<MissingReport | undefined> {
  try {
    const result = await missingReportStore.incrementRetry(id)
    if (!result.success) {
      logger.error(`[missingReportDetector] incrementRetry failed: ${result.error}`, { id })
      return undefined
    }

    logger.info(`[missingReportDetector] incrementRetry success: id="${id}"`)
    return result.data
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[missingReportDetector] incrementRetry error: ${message}`, { id })
    return undefined
  }
}

/**
 * 清理已解决的缺失报告。若提供 symbol，则仅清理该股票的报告。
 */
export async function clear(symbol?: string): Promise<number> {
  try {
    const all = await missingReportStore.list()
    const toClear = all.filter((r) => {
      if (r.resolvedAt === undefined) return false
      return symbol ? r.symbol === symbol : true
    })

    // 注意：dataLayer 未提供批量删除，这里仅返回待清理数量，实际删除由调用方逐条处理
    logger.info(`[missingReportDetector] clear: ${toClear.length} resolved reports`, { symbol })
    return toClear.length
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[missingReportDetector] clear error: ${message}`, { symbol })
    return 0
  }
}

export const missingReportDetector = {
  detect,
  listBySymbol,
  listBySeverity,
  listUnresolved,
  incrementRetry,
  clear,
  setDetectorEnabled,
  isDetectorEnabled,
}

