/**
 * @module executionPlanService
 * @description 执行计划服务：基于交易信号创建执行计划，管理阶段流转与取消。
 *
 * 职责：
 *   - createPlan(signal): 基于信号创建执行计划
 *   - listPlans(symbol?): 查询执行计划列表
 *   - updatePhase(planId, nextPhase): 按状态机推进阶段
 *   - cancelPlan(planId): 取消执行计划
 *
 * 依赖：dataLayer.executionPlans / dataLayer.executionLogs / dataFreshnessGuard
 */

import { getLogger } from '@/lib/logger'
import { executionPlanStore } from '@/data/dataLayer'
import type { ExecutionPlan, Signal } from '@/data/types'
import {
  EXECUTION_PHASE,
  PHASE_TRANSITIONS,
  PHASE_LOG_ACTION,
  DEFAULT_CONFIDENCE_THRESHOLD,
  DEFAULT_MAX_POSITION_PCT,
  DEFAULT_ACCOUNT_TYPE,
} from '@/constants/execution.constants'
import { checkExecutionPlanFreshness } from '@/core/freshnessGuard'
import { executionLogService } from './executionLogService'

const logger = getLogger()

export interface CreatePlanOptions {
  now?: number
  confidenceThreshold?: number
  maxPositionPct?: number
  accountType?: ExecutionPlan['accountType']
}

export interface UpdatePhaseOptions {
  now?: number
  actor?: string
}

/**
 * 基于交易信号创建执行计划。
 * 当信号置信度低于阈值时返回 undefined。
 */
export async function createPlan(signal: Signal, options: CreatePlanOptions = {}): Promise<ExecutionPlan | undefined> {
  const now = options.now ?? Date.now()
  const confidenceThreshold = options.confidenceThreshold ?? DEFAULT_CONFIDENCE_THRESHOLD
  const maxPositionPct = options.maxPositionPct ?? DEFAULT_MAX_POSITION_PCT
  const accountType = options.accountType ?? DEFAULT_ACCOUNT_TYPE as ExecutionPlan['accountType']

  try {
    if (signal.confidence < confidenceThreshold) {
      logger.info(
        `[executionPlanService] createPlan skipped: signal confidence ${signal.confidence} < threshold ${confidenceThreshold}`,
        { symbol: signal.symbol, signalId: signal.id },
      )
      return undefined
    }

    const plan: ExecutionPlan = {
      id: `plan_${signal.id}_${now}`,
      signalId: signal.id,
      symbol: signal.symbol,
      name: signal.symbol,
      direction: signal.direction === 'sell' ? 'sell' : 'buy',
      phase: EXECUTION_PHASE.PLAN,
      quantity: 0,
      targetPrice: 0,
      rationale: signal.rationale,
      confidence: signal.confidence,
      riskChecks: [],
      sizing: {
        quantity: 0,
        positionPct: Math.min(maxPositionPct, signal.confidence),
        reason: `基于信号 ${signal.id} 自动生成`,
      },
      accountType,
      createdAt: now,
    }

    // Freshness 校验：执行计划创建时间必须晚于信号创建时间
    checkExecutionPlanFreshness(plan.createdAt, signal.createdAt, plan.id)

    const result = await executionPlanStore.save(plan)
    if (!result.success) {
      logger.error(`[executionPlanService] createPlan save failed: ${result.error}`, { signalId: signal.id })
      return undefined
    }

    // 写入创建日志
    await executionLogService.writeLog(plan, PHASE_LOG_ACTION[EXECUTION_PHASE.PLAN], { now, actor: 'system' })

    logger.info(`[executionPlanService] createPlan success: planId="${plan.id}"`, {
      symbol: plan.symbol,
      phase: plan.phase,
      confidence: plan.confidence,
    })
    return plan
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[executionPlanService] createPlan error: ${message}`, { signalId: signal.id })
    return undefined
  }
}

/**
 * 查询执行计划列表。
 * @param symbol 可选，按 symbol 过滤
 */
export async function listPlans(symbol?: string): Promise<ExecutionPlan[]> {
  try {
    const all = await executionPlanStore.getAll()
    if (!symbol) {
      return all
    }
    return all.filter((p) => p.symbol === symbol)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[executionPlanService] listPlans error: ${message}`, { symbol })
    return []
  }
}

/**
 * 按状态机推进执行计划阶段。
 * 若 nextPhase 不在当前阶段允许的下一个阶段列表中，则拒绝推进。
 */
export async function updatePhase(
  planId: string,
  nextPhase: ExecutionPlan['phase'],
  options: UpdatePhaseOptions = {},
): Promise<ExecutionPlan | undefined> {
  const now = options.now ?? Date.now()
  const actor = options.actor ?? 'system'

  try {
    const plan = await executionPlanStore.get(planId)
    if (!plan) {
      logger.warn(`[executionPlanService] updatePhase plan not found: planId="${planId}"`)
      return undefined
    }

    const allowed = PHASE_TRANSITIONS[plan.phase]
    if (!allowed.includes(nextPhase)) {
      logger.warn(
        `[executionPlanService] updatePhase rejected: ${plan.phase} → ${nextPhase} not allowed (planId="${planId}")`,
      )
      return undefined
    }

    const updated: ExecutionPlan = { ...plan, phase: nextPhase }
    if (nextPhase === EXECUTION_PHASE.CONFIRMED) {
      updated.confirmedAt = now
    } else if (nextPhase === EXECUTION_PHASE.EXECUTED) {
      updated.executedAt = now
    } else if (nextPhase === EXECUTION_PHASE.REVIEWED) {
      updated.reviewedAt = now
    }

    const result = await executionPlanStore.save(updated)
    if (!result.success) {
      logger.error(`[executionPlanService] updatePhase save failed: ${result.error}`, { planId })
      return undefined
    }

    // 写入阶段流转日志
    await executionLogService.writeLog(updated, PHASE_LOG_ACTION[nextPhase], { now, actor })

    logger.info(`[executionPlanService] updatePhase success: ${plan.phase} → ${nextPhase} (planId="${planId}")`, {
      actor,
    })
    return updated
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[executionPlanService] updatePhase error: ${message}`, { planId })
    return undefined
  }
}

/**
 * 取消执行计划。仅当当前阶段允许转移到 cancelled 时才可取消。
 */
export async function cancelPlan(planId: string, options: UpdatePhaseOptions = {}): Promise<ExecutionPlan | undefined> {
  const now = options.now ?? Date.now()
  const actor = options.actor ?? 'system'

  try {
    const plan = await executionPlanStore.get(planId)
    if (!plan) {
      logger.warn(`[executionPlanService] cancelPlan plan not found: planId="${planId}"`)
      return undefined
    }

    const allowed = PHASE_TRANSITIONS[plan.phase]
    if (!allowed.includes(EXECUTION_PHASE.CANCELLED)) {
      logger.warn(
        `[executionPlanService] cancelPlan rejected: ${plan.phase} → cancelled not allowed (planId="${planId}")`,
      )
      return undefined
    }

    const updated: ExecutionPlan = { ...plan, phase: EXECUTION_PHASE.CANCELLED }
    const result = await executionPlanStore.save(updated)
    if (!result.success) {
      logger.error(`[executionPlanService] cancelPlan save failed: ${result.error}`, { planId })
      return undefined
    }

    await executionLogService.writeLog(updated, PHASE_LOG_ACTION[EXECUTION_PHASE.CANCELLED], { now, actor })

    logger.info(`[executionPlanService] cancelPlan success: planId="${planId}"`, { actor })
    return updated
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[executionPlanService] cancelPlan error: ${message}`, { planId })
    return undefined
  }
}

/**
 * 查询孤儿执行计划：关联的信号已被删除的计划。
 */
export async function getOrphanPlans(): Promise<ExecutionPlan[]> {
  try {
    const all = await executionPlanStore.getAll()
    // 信号存在性由调用方检查，这里仅返回非终态的计划
    const terminalPhases: ExecutionPlan['phase'][] = [EXECUTION_PHASE.EXECUTED, EXECUTION_PHASE.CANCELLED, EXECUTION_PHASE.REVIEWED]
    return all.filter((p) => !terminalPhases.includes(p.phase))
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[executionPlanService] getOrphanPlans error: ${message}`)
    return []
  }
}

export const executionPlanService = {
  createPlan,
  listPlans,
  updatePhase,
  cancelPlan,
  getOrphanPlans,
}

/**
 * @module backtestExportService
 * @description DA-006 回测报告导出服务。
 * 数据仅读取 backtestStore（BacktestResult + BacktestConfig），禁止重复计算回测结果。
 * PDF / Excel 第三方库采用动态导入（import()），仅在导出触发时加载，减少主包体积。
 */

import type {
  BacktestConfig,
  BacktestResult,
  BacktestTrade,
  BacktestDailyValue,
  BacktestExcelSheets,
  BacktestExportConfig,
  BacktestExportResult,
  BacktestPosition,
  BacktestReportMeta,
} from '@/types/modules/backtest.types'
import {
  BACKTEST_STRATEGY_LABELS,
  BACKTEST_EXCEL_SHEETS,
  BACKTEST_EXPORT_FILENAME,
  PDF_TITLE_FONT_SIZE,
  PDF_SUMMARY_FONT_SIZE,
  PDF_SECTION_FONT_SIZE,
  PDF_TABLE_FONT_SIZE,
  PDF_MARGIN_LEFT,
  PDF_TITLE_START_Y,
  PDF_SUMMARY_START_Y,
  PDF_SUMMARY_LINE_HEIGHT,
  PDF_TABLE_HEADER_COLOR,
  PDF_SECTION_SPACING,
  PDF_MAX_TRADE_ROWS,
} from '@/constants/backtest.constants'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 百分比转换基数 */
const PERCENT_BASE = 100

/** 百分比显示小数位 */
const PERCENT_DECIMAL_PLACES = 2

/** Excel MIME 类型 */
const EXCEL_MIME_TYPE = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'

// ============================================================
// 元数据构建
// ============================================================

/** 构建报告元数据 */
export function buildReportMeta(config: BacktestConfig): BacktestReportMeta {
  return {
    strategy: BACKTEST_STRATEGY_LABELS[config.strategy],
    startDate: config.startDate,
    endDate: config.endDate,
    initialCapital: config.initialCapital,
    generatedAt: new Date().toISOString(),
  }
}

// ============================================================
// 格式化辅助
// ============================================================

/** 格式化百分比（入参为 0-1 小数，输出带 % 的字符串） */
function formatPercent(value: number): string {
  return `${(value * PERCENT_BASE).toFixed(PERCENT_DECIMAL_PLACES)}%`
}

// ============================================================
// Excel 多 Sheet 数据构建
// ============================================================

/** 构建 Excel 多 Sheet 数据 */
export function buildExcelSheets(
  result: BacktestResult,
  meta: BacktestReportMeta,
): BacktestExcelSheets {
  const positions: BacktestPosition[] = result.positions ?? []
  const dailyValues: BacktestDailyValue[] = result.dailyValues ?? []

  const summary: Array<Record<string, string | number>> = [
    { 项目: '策略', 值: meta.strategy },
    { 项目: '回测区间', 值: `${meta.startDate} ~ ${meta.endDate}` },
    { 项目: '初始资金', 值: meta.initialCapital },
    { 项目: '总收益', 值: formatPercent(result.totalReturn / PERCENT_BASE) },
    { 项目: '年化收益', 值: formatPercent(result.annualizedReturn / PERCENT_BASE) },
    { 项目: '最大回撤', 值: formatPercent(result.maxDrawdown / PERCENT_BASE) },
    { 项目: '夏普比率', 值: result.sharpeRatio },
    { 项目: '胜率', 值: formatPercent(result.winRate / PERCENT_BASE) },
    { 项目: '交易次数', 值: result.tradeCount },
    { 项目: '盈利笔数', 值: result.profitTrades },
    { 项目: '亏损笔数', 值: result.lossTrades },
    { 项目: '平均盈利', 值: formatPercent(result.avgProfit / PERCENT_BASE) },
    { 项目: '平均亏损', 值: formatPercent(result.avgLoss / PERCENT_BASE) },
    { 项目: '生成时间', 值: meta.generatedAt },
  ]

  const positionsSheet: Array<Record<string, string | number>> = positions.map(
    (p: BacktestPosition) => ({
      标的: p.symbol,
      持仓数量: p.quantity,
      平均成本: p.avgCost,
      当前价格: p.currentPrice,
      市值: p.marketValue,
      浮动盈亏: p.unrealizedPnL,
    }),
  )

  const tradesSheet: Array<Record<string, string | number>> = result.trades.map(
    (t: BacktestTrade) => ({
      日期: t.date,
      标的: t.symbol,
      方向: t.direction === 'buy' ? '买入' : '卖出',
      价格: t.price,
      数量: t.quantity,
      盈亏: t.pnl,
      盈亏比例: formatPercent(t.pnlPct / PERCENT_BASE),
      原因: t.reason,
    }),
  )

  const dailyValuesSheet: Array<Record<string, string | number>> = dailyValues.map(
    (d: BacktestDailyValue, index: number) => ({
      日期: d.date,
      总资产: d.totalValue,
      现金: d.cash,
      净值: result.pnlCurve[index] ?? 1,
    }),
  )

  return {
    summary,
    positions: positionsSheet,
    trades: tradesSheet,
    dailyValues: dailyValuesSheet,
  }
}

// ============================================================
// 文件名构建
// ============================================================

/** 生成带日期的文件名 */
function buildFilename(format: 'pdf' | 'excel', meta: BacktestReportMeta): string {
  const dateStr = meta.generatedAt.slice(0, 10).replace(/-/g, '')
  const ext = format === 'pdf' ? '.pdf' : '.xlsx'
  return `${BACKTEST_EXPORT_FILENAME}_${dateStr}${ext}`
}

// ============================================================
// Excel 导出
// ============================================================

/** 导出 Excel 文件 */
async function exportExcel(
  sheets: BacktestExcelSheets,
  meta: BacktestReportMeta,
): Promise<BacktestExportResult> {
  try {
    const XLSX = await import('xlsx')
    const wb = XLSX.utils.book_new()

    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(sheets.summary),
      BACKTEST_EXCEL_SHEETS.summary,
    )
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(sheets.positions),
      BACKTEST_EXCEL_SHEETS.positions,
    )
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(sheets.trades),
      BACKTEST_EXCEL_SHEETS.trades,
    )
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(sheets.dailyValues),
      BACKTEST_EXCEL_SHEETS.dailyValues,
    )

    const buffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' })
    const blob = new Blob([buffer], { type: EXCEL_MIME_TYPE })
    const filename = buildFilename('excel', meta)

    logger.info('[backtestExportService] Excel 导出成功', { filename })
    return { success: true, filename, blob }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    logger.error('[backtestExportService] Excel 导出失败', { error: msg })
    return { success: false, filename: '', error: msg }
  }
}

// ============================================================
// PDF 导出
// ============================================================

/** 导出 PDF 文件 */
async function exportPdf(
  sheets: BacktestExcelSheets,
  meta: BacktestReportMeta,
): Promise<BacktestExportResult> {
  try {
    const { jsPDF } = await import('jspdf')
    const autoTable = (await import('jspdf-autotable')).default

    const doc = new jsPDF()

    // 标题
    doc.setFontSize(PDF_TITLE_FONT_SIZE)
    doc.text(BACKTEST_EXPORT_FILENAME, PDF_MARGIN_LEFT, PDF_TITLE_START_Y)

    // 摘要文本
    doc.setFontSize(PDF_SUMMARY_FONT_SIZE)
    let y = PDF_SUMMARY_START_Y
    for (const row of sheets.summary) {
      doc.text(`${row['项目']}: ${row['值']}`, PDF_MARGIN_LEFT, y)
      y += PDF_SUMMARY_LINE_HEIGHT
    }

    // 持仓表
    y += PDF_SECTION_SPACING
    doc.setFontSize(PDF_SECTION_FONT_SIZE)
    doc.text(BACKTEST_EXCEL_SHEETS.positions, PDF_MARGIN_LEFT, y)
    autoTable(doc, {
      startY: y + PDF_SECTION_SPACING,
      head: [['标的', '持仓数量', '平均成本', '当前价格', '市值', '浮动盈亏']],
      body: sheets.positions.map((p) => [
        String(p['标的'] ?? ''),
        Number(p['持仓数量'] ?? 0),
        Number(p['平均成本'] ?? 0),
        Number(p['当前价格'] ?? 0),
        Number(p['市值'] ?? 0),
        Number(p['浮动盈亏'] ?? 0),
      ]) as Array<Array<string | number>>,
      styles: { fontSize: PDF_TABLE_FONT_SIZE },
      headStyles: { fillColor: [...PDF_TABLE_HEADER_COLOR] },
    })

    // 交易明细表（限制行数避免 PDF 溢出）
    y += PDF_SECTION_SPACING + 60
    doc.setFontSize(PDF_SECTION_FONT_SIZE)
    doc.text(BACKTEST_EXCEL_SHEETS.trades, PDF_MARGIN_LEFT, y)
    const tradesRows = sheets.trades.slice(0, PDF_MAX_TRADE_ROWS)
    autoTable(doc, {
      startY: y + PDF_SECTION_SPACING,
      head: [['日期', '标的', '方向', '价格', '数量', '盈亏', '盈亏比例', '原因']],
      body: tradesRows.map((t) => [
        String(t['日期'] ?? ''),
        String(t['标的'] ?? ''),
        String(t['方向'] ?? ''),
        Number(t['价格'] ?? 0),
        Number(t['数量'] ?? 0),
        Number(t['盈亏'] ?? 0),
        String(t['盈亏比例'] ?? ''),
        String(t['原因'] ?? ''),
      ]) as Array<Array<string | number>>,
      styles: { fontSize: PDF_TABLE_FONT_SIZE },
      headStyles: { fillColor: [...PDF_TABLE_HEADER_COLOR] },
    })

    // 净值序列表
    y += PDF_SECTION_SPACING + 100
    doc.setFontSize(PDF_SECTION_FONT_SIZE)
    doc.text(BACKTEST_EXCEL_SHEETS.dailyValues, PDF_MARGIN_LEFT, y)
    autoTable(doc, {
      startY: y + PDF_SECTION_SPACING,
      head: [['日期', '总资产', '现金', '净值']],
      body: sheets.dailyValues.map((d) => [
        String(d['日期'] ?? ''),
        Number(d['总资产'] ?? 0),
        Number(d['现金'] ?? 0),
        Number(d['净值'] ?? 0),
      ]) as Array<Array<string | number>>,
      styles: { fontSize: PDF_TABLE_FONT_SIZE },
      headStyles: { fillColor: [...PDF_TABLE_HEADER_COLOR] },
    })

    const blob = doc.output('blob')
    const filename = buildFilename('pdf', meta)

    logger.info('[backtestExportService] PDF 导出成功', { filename })
    return { success: true, filename, blob }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    logger.error('[backtestExportService] PDF 导出失败', { error: msg })
    return { success: false, filename: '', error: msg }
  }
}

// ============================================================
// 统一导出入口
// ============================================================

/** 导出回测报告（支持 PDF / Excel） */
export async function exportBacktestReport(
  result: BacktestResult,
  config: BacktestConfig,
  options: BacktestExportConfig,
): Promise<BacktestExportResult> {
  try {
    const meta = buildReportMeta(config)
    const sheets = buildExcelSheets(result, meta)

    if (options.format === 'excel') {
      return await exportExcel(sheets, meta)
    }
    return await exportPdf(sheets, meta)
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    logger.error('[backtestExportService] 导出失败', { error: msg })
    return { success: false, filename: '', error: msg }
  }
}

/**
 * 操作反馈闭环服务
 *
 * 提供统一的操作反馈机制，包括：
 * - 操作状态记录（成功/失败/进行中）
 * - 反馈消息推送（通过 eventBus）
 * - 操作历史查询
 * - 错误重试机制
 *
 * 变更记录：
 * - v1.0.0 (2026-06-27): 初始版本，实现基础反馈闭环
 */

import { eventBus } from '@/lib/eventBus'
import { getLogger } from '@/lib/logger'
import type { DataLayerResult } from '@/data/types'

const logger = getLogger()

/**
 * 反馈事件类型
 */
export type FeedbackEventType =
  | 'OPERATION_STARTED'
  | 'OPERATION_SUCCESS'
  | 'OPERATION_FAILED'
  | 'OPERATION_RETRY'
  | 'OPERATION_CANCELLED'

/**
 * 反馈级别
 */
export type FeedbackLevel = 'info' | 'success' | 'warning' | 'error'

/**
 * 反馈消息
 */
export interface FeedbackMessage {
  /** 操作 ID */
  operationId: string
  /** 操作类型 */
  operationType: string
  /** 操作目标 */
  target?: string
  /** 事件类型 */
  eventType: FeedbackEventType
  /** 反馈级别 */
  level: FeedbackLevel
  /** 消息内容 */
  message: string
  /** 时间戳 */
  timestamp: number
  /** 错误详情（失败时） */
  error?: string
  /** 重试次数 */
  retryCount?: number
  /** 元数据 */
  metadata?: Record<string, unknown>
}

/**
 * 操作记录
 */
export interface OperationRecord {
  operationId: string
  operationType: string
  target?: string
  status: 'started' | 'success' | 'failed' | 'retrying' | 'cancelled'
  message: string
  startTime: number
  endTime?: number
  retryCount: number
  error?: string
  metadata?: Record<string, unknown>
}

/**
 * 反馈监听器
 */
export type FeedbackListener = (message: FeedbackMessage) => void

/**
 * 全局操作记录（内存存储）
 */
const operationRecords: Map<string, OperationRecord> = new Map()

/**
 * 反馈监听器集合
 */
const feedbackListeners: Set<FeedbackListener> = new Set()

/**
 * 生成操作 ID
 */
function generateOperationId(operationType: string): string {
  return `${operationType}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

/**
 * 发布反馈消息
 */
function publishFeedback(message: FeedbackMessage): void {
  // 通过 eventBus 发布
  eventBus.emit('FEEDBACK_MESSAGE', message)

  // 通知监听器
  feedbackListeners.forEach((listener) => {
    try {
      listener(message)
    } catch (err) {
      logger.error('[FeedbackService] 监听器回调失败', { error: err })
    }
  })

  logger.info('[FeedbackService] 反馈消息已发布', {
    operationId: message.operationId,
    eventType: message.eventType,
    level: message.level,
  })
}

/**
 * 开始操作
 */
export function startOperation(
  operationType: string,
  options?: {
    target?: string
    message?: string
    metadata?: Record<string, unknown>
  },
): string {
  const operationId = generateOperationId(operationType)
  const message = options?.message ?? `${operationType} 操作开始`

  const record: OperationRecord = {
    operationId,
    operationType,
    target: options?.target,
    status: 'started',
    message,
    startTime: Date.now(),
    retryCount: 0,
    metadata: options?.metadata,
  }

  operationRecords.set(operationId, record)

  publishFeedback({
    operationId,
    operationType,
    target: options?.target,
    eventType: 'OPERATION_STARTED',
    level: 'info',
    message,
    timestamp: Date.now(),
    metadata: options?.metadata,
  })

  return operationId
}

/**
 * 操作成功
 */
export function succeedOperation(
  operationId: string,
  options?: {
    message?: string
    metadata?: Record<string, unknown>
  },
): void {
  const record = operationRecords.get(operationId)
  if (!record) {
    logger.warn('[FeedbackService] 操作记录不存在', { operationId })
    return
  }

  const message = options?.message ?? `${record.operationType} 操作成功`

  record.status = 'success'
  record.endTime = Date.now()
  record.message = message
  record.metadata = { ...record.metadata, ...options?.metadata }

  publishFeedback({
    operationId,
    operationType: record.operationType,
    target: record.target,
    eventType: 'OPERATION_SUCCESS',
    level: 'success',
    message,
    timestamp: Date.now(),
    metadata: record.metadata,
  })
}

/**
 * 操作失败
 */
export function failOperation(
  operationId: string,
  error: string,
  options?: {
    message?: string
    metadata?: Record<string, unknown>
  },
): void {
  const record = operationRecords.get(operationId)
  if (!record) {
    logger.warn('[FeedbackService] 操作记录不存在', { operationId })
    return
  }

  const message = options?.message ?? `${record.operationType} 操作失败`

  record.status = 'failed'
  record.endTime = Date.now()
  record.error = error
  record.message = message
  record.metadata = { ...record.metadata, ...options?.metadata }

  publishFeedback({
    operationId,
    operationType: record.operationType,
    target: record.target,
    eventType: 'OPERATION_FAILED',
    level: 'error',
    message,
    timestamp: Date.now(),
    error,
    retryCount: record.retryCount,
    metadata: record.metadata,
  })
}

/**
 * 重试操作
 */
export function retryOperation(
  operationId: string,
  options?: {
    message?: string
    metadata?: Record<string, unknown>
  },
): void {
  const record = operationRecords.get(operationId)
  if (!record) {
    logger.warn('[FeedbackService] 操作记录不存在', { operationId })
    return
  }

  record.retryCount++
  record.status = 'retrying'
  const message = options?.message ?? `${record.operationType} 操作重试（第${record.retryCount}次）`

  publishFeedback({
    operationId,
    operationType: record.operationType,
    target: record.target,
    eventType: 'OPERATION_RETRY',
    level: 'warning',
    message,
    timestamp: Date.now(),
    retryCount: record.retryCount,
    metadata: { ...record.metadata, ...options?.metadata },
  })
}

/**
 * 取消操作
 */
export function cancelOperation(
  operationId: string,
  options?: {
    message?: string
    metadata?: Record<string, unknown>
  },
): void {
  const record = operationRecords.get(operationId)
  if (!record) {
    logger.warn('[FeedbackService] 操作记录不存在', { operationId })
    return
  }

  const message = options?.message ?? `${record.operationType} 操作已取消`

  record.status = 'cancelled'
  record.endTime = Date.now()
  record.message = message
  record.metadata = { ...record.metadata, ...options?.metadata }

  publishFeedback({
    operationId,
    operationType: record.operationType,
    target: record.target,
    eventType: 'OPERATION_CANCELLED',
    level: 'warning',
    message,
    timestamp: Date.now(),
    metadata: record.metadata,
  })
}

/**
 * 包装异步操作（自动反馈）
 */
export async function wrapOperation<T>(
  operationType: string,
  operation: () => Promise<DataLayerResult<T>>,
  options?: {
    target?: string
    startMessage?: string
    successMessage?: string
    failMessage?: string
    maxRetries?: number
    metadata?: Record<string, unknown>
  },
): Promise<DataLayerResult<T>> {
  const operationId = startOperation(operationType, {
    target: options?.target,
    message: options?.startMessage,
    metadata: options?.metadata,
  })

  const maxRetries = options?.maxRetries ?? 0

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const result = await operation()

      if (result.success) {
        succeedOperation(operationId, {
          message: options?.successMessage,
          metadata: { result: result.data },
        })
        return result
      }

      if (attempt < maxRetries) {
        retryOperation(operationId, { message: `重试第 ${attempt + 1} 次` })
        continue
      }

      failOperation(operationId, result.error ?? '操作失败', {
        message: options?.failMessage,
      })
      return result
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err)

      if (attempt < maxRetries) {
        retryOperation(operationId, { message: `重试第 ${attempt + 1} 次` })
        continue
      }

      failOperation(operationId, error, {
        message: options?.failMessage,
      })
      return { success: false, error }
    }
  }

  return { success: false, error: '重试次数耗尽' }
}

/**
 * 添加反馈监听器
 */
export function addFeedbackListener(listener: FeedbackListener): () => void {
  feedbackListeners.add(listener)
  return () => feedbackListeners.delete(listener)
}

/**
 * 获取操作记录
 */
export function getOperationRecord(operationId: string): OperationRecord | undefined {
  return operationRecords.get(operationId)
}

/**
 * 获取所有操作记录
 */
export function getAllOperationRecords(): OperationRecord[] {
  return Array.from(operationRecords.values())
}

/**
 * 清除操作记录
 */
export function clearOperationRecords(): void {
  operationRecords.clear()
  logger.info('[FeedbackService] 操作记录已清除')
}

