/**
 * 将 AKShare / Python 服务返回的基础数据转换为 V9 Stock 更新对象
 *
 * 注意：
 * - 不修改 symbol 与 researchStatus 等本地字段，仅更新来自外部数据源的可变字段。
 * - source 标记为 akshare，dataVersion 由调用方递增。
 */
export function adaptBasicDataToStock(
  symbol: string,
  data: CollectBasicData,
  _existing?: Stock,
): Partial<Stock> {
  const update: Partial<Stock> = {
    symbol,
    source: DATA_SOURCE.akshare,
    updatedAt: Date.now(),
  }

  if (data.name !== undefined && data.name.trim().length > 0) {
    update.name = data.name.trim()
  }
  if (data.price !== undefined && !Number.isNaN(data.price)) {
    update.price = data.price
  }
  if (data.pe !== undefined && !Number.isNaN(data.pe)) {
    update.pe = data.pe
  }
  if (data.pb !== undefined && !Number.isNaN(data.pb)) {
    update.pb = data.pb
  }
  if (data.roe !== undefined && !Number.isNaN(data.roe)) {
    update.roe = data.roe
  }
  if (data.market_cap !== undefined && !Number.isNaN(data.market_cap)) {
    update.marketCap = data.market_cap
  }

  return update
}

function isValidKlineBar(bar: unknown): bar is KlineBar {
  if (!bar || typeof bar !== 'object') return false
  const b = bar as Record<string, unknown>
  return (
    typeof b.date === 'string' &&
    typeof b.open === 'number' &&
    typeof b.high === 'number' &&
    typeof b.low === 'number' &&
    typeof b.close === 'number' &&
    typeof b.volume === 'number' &&
    typeof b.amount === 'number'
  )
}

/**
 * 将 AKShare / Python 服务返回的 K线数据转换为 V9 DailyQuotes
 */
export function adaptKlineDataToDailyQuotes(
  symbol: string,
  data: CollectKlineData,
  period = 'daily',
  adjust = 'qfq',
): DailyQuotes | null {
  const history = (data.history ?? []).filter(isValidKlineBar)
  const latest = data.latest && isValidKlineBar(data.latest) ? data.latest : history[history.length - 1]

  if (!latest) {
    return null
  }

  return {
    symbol,
    latest,
    history,
    period,
    adjust,
    updatedAt: Date.now(),
  }
}

/**
 * 判断 Stock 是否已包含可用于评分的真实基础数据
 */
export function hasRealBasicData(stock: Stock): boolean {
  return (
    stock.price !== undefined &&
    stock.pe !== undefined &&
    stock.pb !== undefined &&
    stock.roe !== undefined &&
    stock.marketCap !== undefined
  )
}

/**
 * 判断 DailyQuotes 是否包含足够历史用于动量/波动/流动性计算
 */
export function hasEnoughHistory(quotes: DailyQuotes | undefined, minBars = 20): boolean {
  return quotes !== undefined && quotes.history.length >= minBars && quotes.latest !== undefined
}

// HTTP 错误分类
export enum HttpErrorType {
  NETWORK_ERROR = 'NETWORK_ERROR',        // 网络断开/超时
  TIMEOUT = 'TIMEOUT',                    // 请求超时
  UNAUTHORIZED = 'UNAUTHORIZED',          // 401 未授权
  FORBIDDEN = 'FORBIDDEN',               // 403 禁止
  NOT_FOUND = 'NOT_FOUND',               // 404 未找到
  RATE_LIMITED = 'RATE_LIMITED',         // 429 限流
  SERVER_ERROR = 'SERVER_ERROR',           // 5xx 服务器错误
  UNKNOWN = 'UNKNOWN',                   // 未知错误
}

// HTTP 错误类
export class HttpError extends Error {
  constructor(
    message: string,
    public readonly type: HttpErrorType,
    public readonly statusCode?: number,
    public readonly url?: string,
  ) {
    super(message)
    this.name = 'HttpError'
  }
}

// 错误码到类型的映射
export function getHttpErrorType(statusCode: number): HttpErrorType {
  if (statusCode === 401) return HttpErrorType.UNAUTHORIZED
  if (statusCode === 403) return HttpErrorType.FORBIDDEN
  if (statusCode === 404) return HttpErrorType.NOT_FOUND
  if (statusCode === 429) return HttpErrorType.RATE_LIMITED
  if (statusCode >= 500) return HttpErrorType.SERVER_ERROR
  return HttpErrorType.UNKNOWN
}

import { HttpError, HttpErrorType, getHttpErrorType } from './fetcherErrors'

// 拦截器配置
export interface InterceptorConfig {
  // 最大重试次数
  maxRetries: number
  // 初始重试延迟（毫秒）
  baseDelay: number
  // 最大重试延迟（毫秒）
  maxDelay: number
  // 是否在 5xx 时重试
  retryOnServerError: boolean
  // 是否在 429 时重试
  retryOnRateLimit: boolean
  // 是否在网络错误时重试
  retryOnNetworkError: boolean
  // 401 回调（用于跳转登录）
  onUnauthorized?: () => void
  // 403 回调（用于显示无权限）
  onForbidden?: () => void
}

const DEFAULT_CONFIG: InterceptorConfig = {
  maxRetries: 3,
  baseDelay: 1000,
  maxDelay: 10000,
  retryOnServerError: true,
  retryOnRateLimit: true,
  retryOnNetworkError: true,
  onUnauthorized: undefined,
  onForbidden: undefined,
}

// 指数退避计算
export function calculateBackoff(attempt: number, baseDelay: number, maxDelay: number): number {
  const delay = Math.min(baseDelay * Math.pow(2, attempt), maxDelay)
  // 添加随机抖动 ±20%
  const jitter = delay * 0.2 * (Math.random() - 0.5)
  return Math.floor(delay + jitter)
}

// 全局拦截器实例
let globalConfig: InterceptorConfig = { ...DEFAULT_CONFIG }

export function setInterceptorConfig(config: Partial<InterceptorConfig>): void {
  globalConfig = { ...globalConfig, ...config }
}

export function getInterceptorConfig(): InterceptorConfig {
  return { ...globalConfig }
}

// 错误判断
function shouldRetry(error: HttpError, config: InterceptorConfig, attempt: number): boolean {
  if (attempt >= config.maxRetries) return false
  if (error.type === HttpErrorType.UNAUTHORIZED) return false  // 401 不重试
  if (error.type === HttpErrorType.FORBIDDEN) return false   // 403 不重试
  if (error.type === HttpErrorType.NOT_FOUND) return false    // 404 不重试
  if (error.type === HttpErrorType.RATE_LIMITED && config.retryOnRateLimit) return true
  if (error.type === HttpErrorType.SERVER_ERROR && config.retryOnServerError) return true
  if (error.type === HttpErrorType.NETWORK_ERROR && config.retryOnNetworkError) return true
  if (error.type === HttpErrorType.TIMEOUT && config.retryOnNetworkError) return true
  return false
}

// 全局 fetch 包装函数
export async function interceptedFetch(
  input: RequestInfo | URL,
  init?: RequestInit,
): Promise<Response> {
  const config = getInterceptorConfig()
  const url = typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url
  let lastError: HttpError | null = null

  for (let attempt = 0; attempt <= config.maxRetries; attempt++) {
    try {
      const controller = new AbortController()
      const timeout = setTimeout(() => controller.abort(), 30000)  // 30s 超时

      const response = await fetch(input, {
        ...init,
        signal: controller.signal,
      })

      clearTimeout(timeout)

      // 处理 HTTP 错误状态码
      if (!response.ok) {
        const errorType = getHttpErrorType(response.status)
        const error = new HttpError(
          `HTTP ${response.status}: ${response.statusText}`,
          errorType,
          response.status,
          url,
        )

        // 触发特殊回调
        if (errorType === HttpErrorType.UNAUTHORIZED && config.onUnauthorized) {
          config.onUnauthorized()
        }
        if (errorType === HttpErrorType.FORBIDDEN && config.onForbidden) {
          config.onForbidden()
        }

        // 判断是否重试
        if (shouldRetry(error, config, attempt)) {
          lastError = error
          const delay = calculateBackoff(attempt, config.baseDelay, config.maxDelay)
          await new Promise(resolve => setTimeout(resolve, delay))
          continue
        }

        throw error
      }

      return response

    } catch (err) {
      if (err instanceof HttpError) {
        throw err
      }

      // 网络错误（fetch 抛出）
      const isAbort = err instanceof DOMException && err.name === 'AbortException'
      const errorType = isAbort ? HttpErrorType.TIMEOUT : HttpErrorType.NETWORK_ERROR
      const error = new HttpError(
        isAbort ? '请求超时' : '网络连接失败',
        errorType,
        undefined,
        url,
      )

      if (shouldRetry(error, config, attempt)) {
        lastError = error
        const delay = calculateBackoff(attempt, config.baseDelay, config.maxDelay)
        await new Promise(resolve => setTimeout(resolve, delay))
        continue
      }

      throw error
    }
  }

  throw lastError || new HttpError('请求失败', HttpErrorType.UNKNOWN, undefined, url)
}

/**
 * 数据采集调度器（简化版）
 *
 * 当前实现仅提供手动触发与事件触发能力；定时调度与时间分层在 P2 阶段逐步补齐。
 */

import { getDefaultFetcherConfig, type FetcherFrequency } from '@/config/fetcherConfig'
import { getLogger } from '@/lib/logger'
import { fetchStockBasic, fetchStockKline } from './fetcherService'

const logger = getLogger()

export interface FetcherSchedulerState {
  isRunning: boolean
  currentSymbol: string | null
  lastRunAt: number | null
}

class FetcherScheduler {
  private state: FetcherSchedulerState = {
    isRunning: false,
    currentSymbol: null,
    lastRunAt: null,
  }

  getState(): FetcherSchedulerState {
    return { ...this.state }
  }

  /**
   * 手动触发单只股票基础数据采集
   */
  async runManual(symbol: string): Promise<void> {
    if (this.state.isRunning) {
      logger.warn('[fetcherScheduler] 已有采集任务执行中，跳过')
      return
    }

    this.state.isRunning = true
    this.state.currentSymbol = symbol

    try {
      const result = await fetchStockBasic(symbol)
      if (!result.success) {
        logger.error('[fetcherScheduler] 手动采集失败', { symbol, error: result.error })
      } else {
        logger.info('[fetcherScheduler] 手动采集成功', { symbol })
      }
    } finally {
      this.state.isRunning = false
      this.state.currentSymbol = null
      this.state.lastRunAt = Date.now()
    }
  }

  /**
   * 手动触发单只股票 K线采集
   */
  async runKline(symbol: string): Promise<void> {
    if (this.state.isRunning) {
      logger.warn('[fetcherScheduler] 已有采集任务执行中，跳过')
      return
    }

    this.state.isRunning = true
    this.state.currentSymbol = symbol

    try {
      const result = await fetchStockKline(symbol)
      if (!result.success) {
        logger.error('[fetcherScheduler] K线采集失败', { symbol, error: result.error })
      } else {
        logger.info('[fetcherScheduler] K线采集成功', { symbol })
      }
    } finally {
      this.state.isRunning = false
      this.state.currentSymbol = null
      this.state.lastRunAt = Date.now()
    }
  }

  /**
   * 事件触发：新增股票后自动拉取基础数据与 K线
   */
  async onSymbolAdded(symbol: string): Promise<void> {
    const config = getDefaultFetcherConfig()
    const basicDim = config.dimensions.find((d) => d.code === '01')
    const klineDim = config.dimensions.find((d) => d.code === '02')

    if (basicDim?.enabled) {
      await this.runManual(symbol)
    }
    if (klineDim?.enabled) {
      await this.runKline(symbol)
    }
  }
}

let globalScheduler: FetcherScheduler | null = null

export function getFetcherScheduler(): FetcherScheduler {
  if (!globalScheduler) {
    globalScheduler = new FetcherScheduler()
  }
  return globalScheduler
}

export function resetFetcherScheduler(): void {
  globalScheduler = null
}

