/**
 * 将 dataLayer 的 Stock 适配为引擎 StockBasicData
 *
 * 仅提取引擎关心的基础字段；缺失字段保持 undefined，由各层计算器自行降级。
 */
export function stockToBasicData(stock: Stock): StockBasicData {
