/**
 * 获取单个数据源的完整状态
 * @param key 数据源 key
 */
export function useDataSource(key: MarketDataSourceKey): DataSourceEntry {
  return useMarketDataStore((state) => state.dataSources[key]) ?? {
    data: undefined,
    loading: false,
    error: null,
    lastUpdated: 0,
  }
}

/**
 * 获取单个数据源的数据（跳过 loading/error）
 * @param key 数据源 key
 * @template T 预期的数据类型，默认为 Partial&lt;MarketData&gt;
