/** 获取 Top N 评分 */
export function topScores(limit: number = 5): ValuePitScore[] {
  const { scores } = useValuePitStore.getState()
  return scores.slice(0, limit)
}

/** 获取建仓候选列表 */
export function buildCandidates(): ValuePitScore[] {
  const { scores } = useValuePitStore.getState()
  return scores.filter((s) => s.action === 'immediate')
}

/** 获取等待信号列表 */
export function waitSignalList(): ValuePitScore[] {
  const { scores } = useValuePitStore.getState()
  return scores.filter((s) => s.action === 'wait')
}

/**
 * 无障碍（Accessibility）工具
 * v0.9.11 P2-A11Y
 * 标准：WCAG 2.1 Level AA
 */

import type React from 'react'

// 生成唯一 ID（用于 aria-labelledby/aria-describedby）
let idCounter = 0
export function generateId(prefix = 'a11y'): string {
  return `${prefix}-${++idCounter}`
}

// 键盘导航助手
export const KEYS = {
  ENTER: 'Enter',
  SPACE: ' ',
  ESCAPE: 'Escape',
  TAB: 'Tab',
  ARROW_UP: 'ArrowUp',
  ARROW_DOWN: 'ArrowDown',
  ARROW_LEFT: 'ArrowLeft',
  ARROW_RIGHT: 'ArrowRight',
  HOME: 'Home',
  END: 'End',
} as const

export type KeyType = (typeof KEYS)[keyof typeof KEYS]

// 处理键盘事件（回车/空格触发点击）
export function handleKeyboardActivation(handler: () => void) {
  return (e: React.KeyboardEvent) => {
    if (e.key === KEYS.ENTER || e.key === KEYS.SPACE) {
      e.preventDefault()
      handler()
    }
  }
}

// 处理 Escape 键
export function handleEscapeKey(handler: () => void) {
  return (e: React.KeyboardEvent) => {
    if (e.key === KEYS.ESCAPE) {
      e.preventDefault()
      handler()
    }
  }
}

// 判断是否为交互元素
export function isInteractiveElement(tag: string): boolean {
  const interactiveTags = ['button', 'a', 'input', 'select', 'textarea', 'details', 'menuitem']
  return interactiveTags.includes(tag.toLowerCase())
}

// 获取可聚焦元素选择器列表
export const FOCUSABLE_SELECTORS = [
  'button:not([disabled])',
  'a[href]',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
  '[contenteditable="true"]',
].join(', ')

// 检查元素是否可聚焦
export function isFocusable(element: HTMLElement): boolean {
  if (element.hasAttribute('disabled') && element.tagName !== 'A') {
    return false
  }
  if (element.getAttribute('aria-hidden') === 'true') {
    return false
  }
  const tabIndex = element.getAttribute('tabindex')
  if (tabIndex !== null && parseInt(tabIndex, 10) < 0) {
    return false
  }
  return true
}

// Live Region 助手（用于屏幕阅读器公告）
export function announceToScreenReader(
  message: string,
  priority: 'polite' | 'assertive' = 'polite',
  containerId = 'sr-announcer',
) {
  let announcer = document.getElementById(containerId)
  if (!announcer) {
    announcer = document.createElement('div')
    announcer.id = containerId
    announcer.setAttribute('aria-live', priority)
    announcer.setAttribute('aria-atomic', 'true')
    announcer.className = 'sr-only'
    announcer.style.cssText =
      'position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;'
    document.body.appendChild(announcer)
  }

  // 清空并重新设置以触发动画
  announcer.textContent = ''
  setTimeout(() => {
    announcer!.textContent = message
  }, 100)
}

// 组合 label 和 description 的 aria 属性
export interface AriaDescribedByProps {
  labelId?: string
  descriptionId?: string
  errorId?: string
}

export function getAriaDescribedByIds({ labelId, descriptionId, errorId }: AriaDescribedByProps): string | undefined {
  const ids = [labelId, descriptionId, errorId].filter(Boolean) as string[]
  return ids.length > 0 ? ids.join(' ') : undefined
}

// 为表单字段生成无障碍属性
export function getFieldAriaProps(
  fieldId: string,
  options: {
    required?: boolean
    hasError?: boolean
    errorMessage?: string
    describedById?: string
  } = {},
) {
  const describedByIds: string[] = []

  if (options.describedById) {
    describedByIds.push(options.describedById)
  }

  if (options.hasError && options.errorMessage) {
    const errorId = `${fieldId}-error`
    describedByIds.push(errorId)
  }

  return {
    id: fieldId,
    'aria-labelledby': `${fieldId}-label`,
    'aria-describedby': describedByIds.length > 0 ? describedByIds.join(' ') : undefined,
    'aria-required': options.required,
    'aria-invalid': options.hasError,
  }
}

// 焦点管理：聚焦到元素
export function focusElement(element: HTMLElement | null | undefined) {
  if (element) {
    element.focus()
    // 如果是 input，选择所有文本
    if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
      element.select()
    }
  }
}

// 焦点管理：聚焦到第一个可聚焦元素
export function focusFirst(container: HTMLElement | null) {
  if (!container) return
  const focusable = container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTORS)
  focusElement(focusable[0])
}

// 焦点管理：聚焦到最后一个可聚焦元素
export function focusLast(container: HTMLElement | null) {
  if (!container) return
  const focusable = container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTORS)
  focusElement(focusable[focusable.length - 1])
}

// 减少运动偏好检测
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined') return false
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

// 高对比度模式检测
export function prefersHighContrast(): boolean {
  if (typeof window === 'undefined') return false
  return window.matchMedia('(prefers-contrast: more)').matches
}

/**
 * 数据验证工具
 * v0.9.11 P2-DATA
 * 用途：确保数据流入符合数据类型和范围约束
 *
 * v0.9.16 安全增强（audit-b4-4-security）：
 * - 新增 LLM 配置字段格式校验（VAL-001）
 * - 新增股票代码严格校验（A股/港股/美股）（VAL-003）
 * - 新增 URL 协议白名单校验（XSS-003）
 * - 新增 API Key 脱敏函数（LEAK-004）
 */

// ============================================================
// 股票代码相关验证
// ============================================================

/** A股代码：6位数字（含 SH/SZ/BJ 交易所） */
const A_SHARE_CODE_REGEX = /^\d{6}$/

/** 港股代码：5位数字 */
const HK_SHARE_CODE_REGEX = /^\d{5}$/

/** 美股代码：1-5 位字母或 1-4 位字母 + .O/.N/.A 后缀 */
const US_SHARE_CODE_REGEX = /^[A-Z]{1,5}(?:\.[A-Z]{1,2})?$/

/** 股票代码格式验证（6位数字，兼容 A 股） */
export function isValidStockCode(code: string): boolean {
  return A_SHARE_CODE_REGEX.test(code)
}

/** 股票代码格式化（补零） */
export function formatStockCode(code: string | number): string {
  return String(code).padStart(6, '0')
}

/**
 * 严格的股票代码格式校验，支持 A 股 / 港股 / 美股。
 *
 * @param code 股票代码
 * @param market 市场类型，未指定时仅校验 A 股 6 位数字
 * @returns 是否合法
 */
export function isValidStockCodeStrict(
  code: string,
  market?: 'A' | 'HK' | 'US',
): boolean {
  if (typeof code !== 'string' || code.length === 0) return false
  const trimmed = code.trim()

  switch (market) {
    case 'A':
      return A_SHARE_CODE_REGEX.test(trimmed)
    case 'HK':
      return HK_SHARE_CODE_REGEX.test(trimmed)
    case 'US':
      return US_SHARE_CODE_REGEX.test(trimmed.toUpperCase())
    default:
      // 默认仅校验 A 股 6 位数字
      return A_SHARE_CODE_REGEX.test(trimmed)
  }
}

/**
 * 验证带交易所后缀的股票代码（如 600519.SH、00700.HK、AAPL.US）。
 */
export function isValidSymbolWithExchange(symbol: string): boolean {
  if (typeof symbol !== 'string' || symbol.length === 0) return false
  // 格式：CODE.EXCHANGE，如 600519.SH、000001.SZ、00700.HK
  return /^\d{6}\.(SH|SZ|BJ)$/i.test(symbol.trim())
}

// ============================================================
// 数值范围验证
// ============================================================

/** 百分比范围验证（0-100） */
export function isValidPercent(value: number): boolean {
  return value >= 0 && value <= 100
}

/** 评分范围验证（0-100） */
export function isValidScore(value: number): boolean {
  return value >= 0 && value <= 100
}

/** 价格正数验证 */
export function isValidPrice(value: number): boolean {
  return value > 0 && isFinite(value)
}

/** 空值处理 */
export function safeValue<T>(value: T | null | undefined, fallback: T): T {
  return value ?? fallback
}

/**
 * 安全数字解析：返回有效数字或默认值，过滤 NaN/Infinity。
 *
 * @param value 原始值（string/number）
 * @param fallback 默认值
 * @param min 最小值（可选）
 * @param max 最大值（可选）
 */
export function safeParseNumber(
  value: unknown,
  fallback: number,
  min?: number,
  max?: number,
): number {
  if (value === null || value === undefined || value === '') return fallback
  const num = typeof value === 'number' ? value : Number(value)
  if (!isFinite(num) || isNaN(num)) return fallback
  if (min !== undefined && num < min) return min
  if (max !== undefined && num > max) return max
  return num
}

// ============================================================
// LLM 配置校验（VAL-001 / XSS-003）
// ============================================================

/** 允许的 URL 协议白名单 */
const ALLOWED_URL_PROTOCOLS = ['http:', 'https:']

/** 危险的 URL 协议黑名单（明确禁止） */
const DANGEROUS_URL_PROTOCOLS = ['javascript:', 'data:', 'vbscript:', 'file:']

/**
 * 验证 LLM baseURL 是否为合法 URL 且协议在白名单内。
 *
 * - 必须是合法 URL
 * - 协议必须为 http: 或 https:
 * - 禁止 javascript:、data:、vbscript: 等危险协议
 * - 开发环境允许 http://localhost
 *
 * @param baseURL 待校验的 baseURL
 */
export function isValidLlmBaseURL(baseURL: string): boolean {
  if (typeof baseURL !== 'string' || baseURL.trim().length === 0) return false

  const trimmed = baseURL.trim()

  // 明确拒绝危险协议
  const lower = trimmed.toLowerCase()
  if (DANGEROUS_URL_PROTOCOLS.some((p) => lower.startsWith(p))) {
    return false
  }

  try {
    const url = new URL(trimmed)
    if (!ALLOWED_URL_PROTOCOLS.includes(url.protocol)) {
      return false
    }
    return true
  } catch {
    return false
  }
}

/**
 * 验证 LLM API Key 格式。
 *
 * 规则：
 * - 长度 8-256
 * - 仅允许字母、数字、连字符、下划线、点
 * - 不包含空白字符、引号、尖括号
 *
 * @param apiKey 待校验的 API Key
 */
export function isValidLlmApiKey(apiKey: string): boolean {
  if (typeof apiKey !== 'string' || apiKey.length === 0) return false
  const trimmed = apiKey.trim()
  if (trimmed.length < 8 || trimmed.length > 256) return false
  // 仅允许字母、数字、连字符、下划线、点、斜杠（部分厂商 key 包含）
  return /^[A-Za-z0-9._\-/]+$/.test(trimmed)
}

/**
 * 验证 LLM 模型名称格式。
 *
 * 规则：
 * - 长度 1-128
 * - 仅允许字母、数字、连字符、下划线、点、斜杠、冒号
 *
 * @param model 待校验的模型名称
 */
export function isValidLlmModel(model: string): boolean {
  if (typeof model !== 'string' || model.length === 0) return false
  const trimmed = model.trim()
  if (trimmed.length < 1 || trimmed.length > 128) return false
  return /^[A-Za-z0-9._\-/:]+$/.test(trimmed)
}

// ============================================================
// 敏感信息脱敏（LEAK-004）
// ============================================================

/**
 * 对 API Key 进行脱敏显示。
 *
 * 规则：
 * - 长度 ≤ 8：全部替换为 ****
 * - 长度 > 8：保留前 4 位 + **** + 后 4 位
 *
 * @param apiKey 原 API Key
 * @returns 脱敏后的字符串
 */
export function maskApiKey(apiKey: string): string {
  if (typeof apiKey !== 'string' || apiKey.length === 0) return '(empty)'
  if (apiKey.length <= 8) return '****'
  return `${apiKey.slice(0, 4)}****${apiKey.slice(-4)}`
}

/**
 * 对 token 进行脱敏显示。
 *
 * @param token 原 token
 * @returns 脱敏后的字符串
 */
export function maskToken(token: string): string {
  if (typeof token !== 'string' || token.length === 0) return '(empty)'
  if (token.length <= 8) return '****'
  return `${token.slice(0, 4)}****${token.slice(-4)}`
}

/**
 * 敏感字段名集合（小写匹配）。
 * 用于日志上下文的自动脱敏。
 */
export const SENSITIVE_FIELD_NAMES = [
  'apikey',
  'api_key',
  'api-key',
  'token',
  'accesstoken',
  'access_token',
  'refreshtoken',
  'refresh_token',
  'password',
  'passwd',
  'pwd',
  'secret',
  'authorization',
  'auth',
  'cookie',
  'session',
  'sessionid',
  'session_id',
] as const

/**
 * 判断字段名是否为敏感字段（大小写不敏感）。
 */
export function isSensitiveField(fieldName: string): boolean {
  if (typeof fieldName !== 'string') return false
  const lower = fieldName.toLowerCase()
  return SENSITIVE_FIELD_NAMES.some((sensitive) => lower === sensitive || lower.includes(sensitive))
}

/**
 * 对任意对象进行脱敏处理，递归遍历所有字段。
 *
 * @param obj 原始对象
 * @param maxDepth 最大递归深度（默认 5）
 * @returns 脱敏后的新对象（不修改原对象）
 */
export function sanitizeObject<T>(obj: T, maxDepth = 5): T {
  if (maxDepth < 0 || obj === null || obj === undefined) return obj

  if (typeof obj === 'string') {
    return obj as unknown as T
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => sanitizeObject(item, maxDepth - 1)) as unknown as T
  }

  if (typeof obj === 'object') {
    const result: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
      if (isSensitiveField(key) && typeof value === 'string') {
        result[key] = maskApiKey(value)
      } else if (typeof value === 'object' && value !== null) {
        result[key] = sanitizeObject(value, maxDepth - 1)
      } else {
        result[key] = value
      }
    }
    return result as unknown as T
  }

  return obj
}

/**
 * 金融数值精度工具
 * v0.9.11 P2-TS002
 * 用途：统一处理股票价格、涨跌幅、百分比等数值的精度控制
 */

// 小数位精度常量
export const PRECISION = {
  PRICE: 2,       // 股票价格：2位小数
  CHANGE: 2,      // 涨跌额：2位小数
  CHANGE_RATE: 2, // 涨跌幅：2位小数（百分比）
  PERCENT: 1,     // 百分比：1位小数
  VOLUME: 0,      // 成交量：整数
  AMOUNT: 2,      // 成交额：2位小数
} as const

/**
 * 格式化价格（自动处理精度）
 * @param value 数值
 * @param decimals 小数位数，默认2位
 * @returns 格式化后的价格字符串，无效值返回 '--'
 */
export function formatPrice(value: number | undefined | null, decimals = PRECISION.PRICE): string {
  if (value == null || isNaN(value)) return '--'
  return value.toFixed(decimals)
}

/**
 * 格式化涨跌幅（%）
 * @param value 涨跌幅数值（如 5.23 表示 5.23%）
 * @returns 带正负号和百分号的字符串，无效值返回 '--'
 */
export function formatChangeRate(value: number | undefined | null): string {
  if (value == null || isNaN(value)) return '--'
  const sign = value >= 0 ? '+' : ''
  return `${sign}${value.toFixed(PRECISION.CHANGE_RATE)}%`
}

/**
 * 格式化涨跌额
 * @param value 涨跌额数值
 * @returns 带正负号的字符串，无效值返回 '--'
 */
export function formatChange(value: number | undefined | null): string {
  if (value == null || isNaN(value)) return '--'
  const sign = value >= 0 ? '+' : ''
  return `${sign}${value.toFixed(PRECISION.CHANGE)}`
}

/**
 * 格式化成交量（万/亿单位）
 * @param value 成交量数值
 * @param unit 显示单位，'auto'自动选择，'wan'万，'yi'亿
 * @returns 格式化后的成交量字符串
 */
export function formatVolume(value: number | undefined | null, unit: 'auto' | 'wan' | 'yi' = 'auto'): string {
  if (value == null || isNaN(value)) return '--'

  if (unit === 'wan' || (unit === 'auto' && value < 100000000)) {
    const wan = value / 10000
    return `${wan.toFixed(PRECISION.VOLUME)}万`
  }

  const yi = value / 100000000
  return `${yi.toFixed(2)}亿`
}

/**
 * 格式化成交额（万/亿单位）
 * @param value 成交额数值（元）
 * @param unit 显示单位，'auto'自动选择，'wan'万，'yi'亿
 * @returns 格式化后的成交额字符串
 */
export function formatAmount(value: number | undefined | null, unit: 'auto' | 'wan' | 'yi' = 'auto'): string {
  if (value == null || isNaN(value)) return '--'

  if (unit === 'wan' || (unit === 'auto' && value < 100000000)) {
    const wan = value / 10000
    return `${wan.toFixed(PRECISION.AMOUNT)}万`
  }

  const yi = value / 100000000
  return `${yi.toFixed(PRECISION.AMOUNT)}亿`
}

/**
 * 格式化百分比
 * @param value 0-1之间的小数或数值
 * @param decimals 小数位数
 * @returns 带百分号的字符串
 */
export function formatPercent(value: number | undefined | null, decimals = PRECISION.PERCENT): string {
  if (value == null || isNaN(value)) return '--'
  // 如果值大于1，假设是百分比形式（如 50 表示 50%）
  const percentValue = value > 1 ? value : value * 100
  return `${percentValue.toFixed(decimals)}%`
}

/**
 * 安全数组索引访问（配合 noUncheckedIndexedAccess）
 * @param arr 数组
 * @param index 索引
 * @param fallback 越界时的默认值
 * @returns 数组元素或默认值
 */
export function safeArrayGet<T>(arr: T[], index: number): T | undefined
export function safeArrayGet<T>(arr: T[], index: number, fallback: T): T
export function safeArrayGet<T>(arr: T[], index: number, fallback?: T): T | undefined {
  return arr[index] ?? fallback
}

/**
 * 安全获取数组第一个元素（配合 noUncheckedIndexedAccess）
 * @param arr 数组
 * @returns 第一个元素或 undefined
 */
export function safeFirst<T>(arr: T[]): T | undefined {
  return arr[0]
}

/**
 * 安全获取数组最后一个元素（配合 noUncheckedIndexedAccess）
 * @param arr 数组
 * @returns 最后一个元素或 undefined
 */
export function safeLast<T>(arr: T[]): T | undefined {
  return arr[arr.length - 1]
}

/**
 * 安全获取对象属性（链式访问）
 * @param obj 对象
 * @param keyPath 属性路径，如 'a.b.c'
 * @param fallback 默认值
 * @returns 属性值或默认值
 */
export function safeGet<T>(obj: Record<string, unknown> | null | undefined, keyPath: string, fallback: T): T {
  if (obj == null) return fallback

  const keys = keyPath.split('.')
  let current: unknown = obj

  for (const key of keys) {
    if (current == null || typeof current !== 'object') return fallback
    current = (current as Record<string, unknown>)[key]
  }

  return (current as T) ?? fallback
}

/**
 * 补充：金融数值格式化
 * v0.9.11 P2-DATA003
 */

// 大数格式化（万/亿）
export function formatLargeNumber(value: number | undefined | null, _unit = '万'): string {
  if (value == null || isNaN(value)) return '--'
  if (Math.abs(value) >= 100000000) {
    return `${(value / 100000000).toFixed(2)}亿`
  }
  if (Math.abs(value) >= 10000) {
    return `${(value / 10000).toFixed(2)}万`
  }
  return value.toFixed(2)
}

// 涨跌幅颜色（配合 COLOR_TOKENS）
export function getChangeColor(value: number): 'up' | 'down' | 'neutral' {
  if (value > 0) return 'up'
  if (value < 0) return 'down'
  return 'neutral'
}

// 格式化市值
export function formatMarketCap(value: number | undefined | null): string {
  return formatLargeNumber(value, '万')
}

// 格式化成交量
export function formatShares(value: number | undefined | null): string {
  if (value == null || isNaN(value)) return '--'
  return formatLargeNumber(value, '股')
}

/**
 * 统一时间处理工具
 * v0.9.11 P2-DATA001
 * 规范：所有时间戳以 UTC 存储，显示时转换至 Asia/Shanghai (UTC+8)
 * 库：dayjs + utc 插件 + timezone 插件
 */
import * as dayjs from 'dayjs'
import utc from 'dayjs/plugin/utc'
import timezone from 'dayjs/plugin/timezone'
import relativeTime from 'dayjs/plugin/relativeTime'
import isSameOrBefore from 'dayjs/plugin/isSameOrBefore'
import isSameOrAfter from 'dayjs/plugin/isSameOrAfter'
import isBetween from 'dayjs/plugin/isBetween'
import 'dayjs/locale/zh-cn'

// 注册插件
dayjs.extend(utc)
dayjs.extend(timezone)
dayjs.extend(relativeTime)
dayjs.extend(isSameOrBefore)
dayjs.extend(isSameOrAfter)
dayjs.extend(isBetween)

// 默认时区
const DEFAULT_TIMEZONE = 'Asia/Shanghai'
dayjs.locale('zh-cn')

/**
 * 获取当前时间戳（毫秒，UTC）
 */
export function now(): number {
  return Date.now()
}

/**
 * 格式化时间（UTC → Asia/Shanghai）
 */
export function formatTime(
  timestamp: number | string | Date | undefined | null,
  format = 'YYYY-MM-DD HH:mm:ss',
): string {
  if (!timestamp) return '--'
  return dayjs(timestamp).tz(DEFAULT_TIMEZONE).format(format)
}

/**
 * 格式化日期（无时间）
 */
export function formatDate(
  timestamp: number | string | Date | undefined | null,
  format = 'YYYY-MM-DD',
): string {
  return formatTime(timestamp, format)
}

/**
 * 格式化相对时间（如"3分钟前"）
 */
export function formatRelativeTime(timestamp: number | string | Date | undefined | null): string {
  if (!timestamp) return '--'
  return dayjs(timestamp).tz(DEFAULT_TIMEZONE).fromNow()
}

/**
 * 判断是否在今天
 */
export function isToday(timestamp: number | string | Date | undefined | null): boolean {
  if (!timestamp) return false
  return dayjs(timestamp).tz(DEFAULT_TIMEZONE).isSame(dayjs().tz(DEFAULT_TIMEZONE), 'day')
}

/**
 * 判断是否在指定日期范围
 */
export function isInRange(
  timestamp: number | string | Date | undefined | null,
  start: number | string | Date,
  end: number | string | Date,
): boolean {
  if (!timestamp) return false
  return dayjs(timestamp).tz(DEFAULT_TIMEZONE).isBetween(start, end, 'day', '[]')
}

/**
 * 解析日期字符串（兼容多种格式）
 */
export function parseTime(value: string | number | Date): dayjs.Dayjs | null {
  const d = dayjs(value)
  return d.isValid() ? d : null
}

/**
 * 格式化股票交易日（格式：09:30:00）
 */
export function formatTradeTime(timestamp: number | string | Date | undefined | null): string {
  return formatTime(timestamp, 'HH:mm:ss')
}

